                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>श्रुतो हितोपदेशोऽयं पाटवं संस्कृतोक्तिषु । वाचां सर्वत्र वैचित्र्यं नीतिविद्यां ददाति च ॥०.२॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>श्रुतः हितोपदेशः अयं पाटवं संस्कृत-उक्तिषु । वाचां सर्वत्र वैचित्र्यं नीति-विद्यां ददाति च ॥०.२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अयं हितोपदेशः श्रुतः। संस्कृत-उक्तिषु पाटवं च सर्वत्र वाचां वैचित्र्यं ददाति। नीति-विद्यां च (ददाति) ॥०.२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अयं = मया वक्ष्यमाणः; श्रुतः हितोपदेशः = ग्रन्थविशेषः; संस्कृत-उक्तिषु = संस्कृतभाषणादिषु; पाटवं = कौशलम्; सर्वत्र = सर्वविषयेषु; वाचां वैचित्र्यं = नानाविधोक्ति-चातुर्यम्; नीति-विद्यां = राजनीतिं, व्यवहारकौशलं च; ददाति = (अत्र) शिक्षयति ॥०.२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मया वक्ष्यमाणः हितोपदेशः संस्कृतभाषाप्रावीण्यं, सर्वविषयेषु चातुर्यं, राजनीतिं व्यवहारज्ञानं च ददाति ॥०.२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>यह हितोपदेश नामक ग्रन्थ पढनेवालों को संस्कृत बोलने में कुशलता देता है, और सब विषयों में नाना भाषाओं में बोलनेकी नाना प्रकार की सुन्दर-सुन्दर रीतियाँ सिखाता है और नीति-विद्या भी सिखाता है ॥२॥</td>
                        </tr>
                    
                    
