                        <button id="anvayasmall03" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '03')">अन्वयः</button>
                        <button id="pratismall03" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '03')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall03" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '03')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall03" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '03')">हिन्द्यर्थः</button>
                        <button id="audiosmall03" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '03')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अजरामरवत् प्राज्ञो विद्यामर्थं च चिन्तयेत् । गृहीत इव केशेषु मृत्युना धर्ममाचरेत् ॥०.३॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अजर-अमर-वत् प्राज्ञः विद्याम् अर्थं च चिन्तयेत् । गृहीतः इव केशेषु मृत्युना धर्मम् आचरेत् ॥०.३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्राज्ञः अजर-अमर-वत् विद्याम् अर्थं च चिन्तयेत्। मृत्युना केशेषु गृहीतः इव धर्मम् आचरेत् ॥०.३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्राज्ञः = विद्वान्; अजर-अमर-वत् = जरा-मरण-वर्जितम् आत्मानं मन्यमान इव; विद्याम् = धर्मशास्त्रादिकं, कलाकलापविज्ञानं, ज्ञानं च; अर्थं च = धनं च; चिन्तयेत् = अभ्यसेत्, उपार्जयेत् च; मृत्युना केशेषु गृहीतः इव = कालकवलितम् इव आत्मानं पश्यन्; धर्मम्; आचरेत् = सेवेत, पालयेत् च ॥०.३॥॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विद्वान् जरामरणरहितः इव शास्त्रविद्यामभ्यसेत्। (आजीवनं शास्त्राध्ययनं कुर्यात्।) मृत्युदेवः केशान् गृहीत्वा तिष्ठति (मरणकालः आसन्नः, अत्यन्तं निकटे अस्ति) इति मत्वा धर्माचरणं कुर्यात् ॥०.३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बुद्धिमान् मनुष्य को चाहिए कि अपने (आत्मा) को अजर व अमर समझकर विद्या तथा धन को कमावे । परन्तु धर्माचरण के समय तो मृत्यु को अपने शिर पर बैठी ही समझे ॥०.३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.3.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="04" class="total">
                    <div>
                        <button id="moolamsmall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '04')">मूलम्</button>
                        <button id="padasmall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '04')">पदविभागः</button>
                        <button id="anvayasmall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '04')">अन्वयः</button>
                        <button id="pratismall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '04')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '04')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '04')">हिन्द्यर्थः</button>
                        <button id="audiosmall04" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '04')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सर्वद्रव्येषु विद्यैव द्रव्यमाहुरनुत्तमम् । अहार्यत्वादनर्घत्वादक्षयत्वाच्च सर्वदा ॥०.४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सर्व-द्रव्येषु विद्या एव द्रव्यम् आहुः अनुत्तमम् । अहार्यत्वाद् अनर्घत्वाद् अक्षयत्वात् च सर्वदा ॥०.४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सर्वदा (अन्येन केनापि) अहार्यत्वाद्, अनर्घत्वाद्, अक्षयत्वात् च सर्व-द्रव्येषु विद्या एव अनुत्तमम् द्रव्यम् (इति विद्वांसः) आहुः ॥०.४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सर्वदा; (अन्येन केनापि) अहार्यत्वाद् = हर्तुम् अशक्यत्वात्; अनर्घत्वाद् = बहुमूल्यत्वात्; अक्षयत्वात् च = दानादिना अपि अक्षीयमाणत्वात्; सर्व-द्रव्येषु = सर्वसाधनोपेक्षया; विद्या एव; अनुत्तमम् = सर्वश्रेष्ठम्; द्रव्यम् = धनं; आहुः ॥०.४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सर्वकालेषु सर्वधनेषु विद्या एव सर्वश्रेष्ठं धनम् इति विद्वद्वचनम्। यतः– तत् अन्यैः हर्तुं न शक्यते। बहुमूल्या वर्तते। कदापि क्षयं न याति ॥०.४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>संसार के सब द्रव्यों से उत्तम धन विद्या ही है। क्यों कि न यह चुराई जा सकती है, न इसका कोई मोल ही लगा सकता है और न इसका कभी क्षय (नाश, घटना) ही हो सकता है ॥०.४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.4.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="05" class="total">
                    <div>
                        <button id="moolamsmall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '05')">मूलम्</button>
                        <button id="padasmall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '05')">पदविभागः</button>
                        <button id="anvayasmall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '05')">अन्वयः</button>
                        <button id="pratismall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '05')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '05')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '05')">हिन्द्यर्थः</button>
                        <button id="audiosmall05" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '05')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>संयोजयति विद्यैव नीचगापि नरं सरित् । समुद्रमिव दुर्धर्षं नृपं भाग्यमतः परम् ॥०.५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>संयोजयति विद्या एव नीचगा अपि नरं सरित् । समुद्रम् इव दुर्धर्षं नृपं भाग्यम् अतः परम् ॥०.५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नीचगा अपि सरित् समुद्रम् (यथा संयोजयति) इव विद्या एव (नीचगा अपि) दुर्धर्षं नरं नृपं संयोजयति। अतः परं भाग्यम् (प्रमाणम्) ॥०.५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नीचगा अपि = निम्नगा अपि; सरित् = नदी; समुद्रम् इव; विद्या; एव = केवलं; (नीचगा अपि = नीचजनस्था अपि) दुर्धर्षं = दुरासदं, दुष्प्रापं, दुर्लभदर्शनं; नृपं = राजानं; नरं संयोजयति = तेन सह पुरुषं सङ्गमयति। अतः परं = तेन सह समागमानन्तरं; भाग्यम् = भाग्यानुसारेण (ततो धनरत्नादीनां लाभः) ॥०.५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नदी यथा निम्नस्थानात् गच्छन्ती अपि समुद्रं गच्छति, तथैव विद्या नीचजनमपि- राज्ञः सङ्गतिं नयति। तदुपरि यथा दैवानुकूलता, तथा घटते (राज्ञा यत् प्राप्तव्यं लब्धव्यं वा तत् प्राप्नोति।) ॥०.५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जैसे नदी नीचे बहनेवाली भी है तो भी स्वाश्रितों को वह समुद्र से मिला देती है, उसी प्रकार यदि विद्या नीच के पास भी होवे तो भी वह विद्या उस मनुप्य को दुर्धर्ष राजा तक पतुँचा देती है । इसके बाद उस मनुष्य का जैसा भाग्य होता है, वैसा ही उसे राजा से लाभ होता है ॥०.५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.5.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="06" class="total">
                    <div>
                        <button id="moolamsmall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '06')">मूलम्</button>
                        <button id="padasmall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '06')">पदविभागः</button>
                        <button id="anvayasmall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '06')">अन्वयः</button>
                        <button id="pratismall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '06')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '06')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '06')">हिन्द्यर्थः</button>
                        <button id="audiosmall06" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '06')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>विद्या ददाति विनयं विनयाद् याति पात्रताम् । पात्रत्वात् धनमाप्नोति धनाद् धर्मं ततः सुखम् ॥०.६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्या ददाति विनयं विनयाद् याति पात्रताम् । पात्रत्वात् धनम् आप्नोति धनाद् धर्मं ततः सुखम् ॥०.६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विद्या विनयं ददाति। विनयाद् पात्रतां याति । पात्रत्वात् धनम् आप्नोति। धनाद् धर्मं (आप्नोति) ततः सुखम् (चाप्नोति) ॥०.६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विद्या; विनयं = सौजन्यं; ददाति; विनयाद्; पात्रताम् = योग्यताम्; याति = तत्स्थितिं लभते; पात्रत्वात्; धनम्; आप्नोति ; धनाद्; धर्मं; ततः; सुखम्; (चाप्नोति) ॥०.६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(विद्यैव सर्वसुखसाधनम् इत्याशयः)। विद्यावान् विनयं प्राप्य, तेन पात्रत्वं लभते। पात्रभूतः सज्जनो धनं प्राप्नोति, धनात् धर्मोपार्जनं शक्यं कर्तुम्। ततः सुखं च सम्प्राप्नोति ॥०.६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और विद्या नम्रता देती है, नम्रता से मनुष्य पात्र ( योग्य) बनता है। पात्रता ( योग्यता) से धन मिलता है, धन से धर्म प्राप्त हो सकता है, और धर्म से सुख प्राप्त होता है ॥०.६ ॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.6.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="07" class="total">
                    <div>
                        <button id="moolamsmall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '07')">मूलम्</button>
                        <button id="padasmall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '07')">पदविभागः</button>
                        <button id="anvayasmall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '07')">अन्वयः</button>
                        <button id="pratismall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '07')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '07')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '07')">हिन्द्यर्थः</button>
                        <button id="audiosmall07" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '07')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>विद्या शस्त्रं च शास्त्रं च द्वे विद्ये प्रतिपत्तये । आद्या हास्याय वृद्धत्वे द्वितीयाद्रियते सदा ॥०.७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्या शस्त्रं च शास्त्रं च द्वे विद्ये प्रतिपत्तये । आद्या हास्याय वृद्धत्वे द्वितीया आद्रियते सदा ॥०.७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>(मनुष्यस्य) प्रतिपत्तये, शस्त्रं विद्या च शास्त्रं (विद्या) च द्वे विद्ये (प्रसिद्धे)। आद्या वृद्धत्वे हास्याय। द्वितीया (लोके) सदा आद्रियते ॥०.७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्रतिपत्तये = ज्ञानाय, यशोलाभाय च; शस्त्रं विद्या = धनुर्वेदादि; शास्त्रं (विद्या) च द्वे विद्ये; आद्या = प्रथमा ; वृद्धत्वे = वृद्धावस्थायां, बलक्षये; हास्याय = उपहासप्रदा; द्वितीया = शास्त्रविद्या; (लोके) सदा; आद्रियते = पूज्यते ॥०.७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्यस्य ज्ञानार्जनाय, यशसे च द्वे विद्ये स्तः- शस्त्रविद्या, शास्त्रविद्या चेति। शस्त्रविद्यया गते वयसि न कोऽपि लाभः (शारीरिक-बलाभावात्)। किन्तु शास्त्रविद्यया जनः आजीवनं पूज्यते लोके (वृद्धोऽपि सन् विद्यां न त्यजति, अत्यागेन अपहासत्वमपि न याति।) ॥०.७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>विद्या दो प्रकार की है। एक शस्त्रविद्या और दूसरी शास्त्रविद्या । दोनों विद्याओंसे ही लोक में प्रतिष्ठा होती है । परन्तु पहिली विद्या (शस्त्रविद्या) वृद्धावस्था में हँसी कराती है, परन्तु दूसरी (शास्त्र) विद्या का तो सदा ही आदर होता है ॥०.७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.7.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="08" class="total">
                    <div>
                        <button id="moolamsmall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '08')">मूलम्</button>
                        <button id="padasmall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '08')">पदविभागः</button>
                        <button id="anvayasmall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '08')">अन्वयः</button>
                        <button id="pratismall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '08')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '08')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '08')">हिन्द्यर्थः</button>
                        <button id="audiosmall08" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '08')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यन्नवे भाजने लग्नः संस्कारो नान्यथा भवेत् । कथाच्छलेन बालानां नीतिस्तदिह कथ्यते ॥०.८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यत् नवे भाजने लग्नः संस्कारः न अन्यथा भवेत् । कथा-छलेन बालानां नीतिः तद् इह कथ्यते ॥०.८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यत्, नवे भाजने लग्नः संस्कारः अन्यथा न भवेत्, तद् इह कथा-छलेन बालानां नीतिः (मया) कथ्यते ॥०.८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यत् = यस्मात् कारणात्; नवे = नवीने, अपक्वे बाले; भाजने = पात्रे, पुंसि च; लग्नः = संसक्तः; संस्कारः = गुणाधानम्; अन्यथा न भवेत् = दूरीभवेत्; तद् = तस्मात् कारणात्; इह = हितोपदेशे; कथा-छलेन = काककूर्मादीनाम् आख्यानकानां व्याजेन; बालानां = बालोपदेशार्थं; नीतिः = राजनीतिः व्यवहारनीतिश्च; कथ्यते = मया निबध्यते ॥०.८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नवीने पात्रे परिवेषितं (?) भोजनं यथा न नश्यति, तथैव नववयस्केषु बालकेषु निक्षिप्तः संस्कारः नैव विनश्यति। अतः (हितोपदेश)कथामाध्यमेन नीतिव्यवहारादीनां ज्ञानं बालकान् उपदिशामि ॥०.८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>नवीन पात्र में तथा छोटे-छोटे बालको में स्थपित किया हुआ (दिया हुआ) संस्कार व शिक्षण आदि कभी नष्ट नहीं होता है, इस लिये इस ग्रन्थ में कथा के बहाने से मैं बालकों के लिए नीतिशास्त्र का सार निकाल कर कहता हूँ ॥०.८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.8.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="010" class="total">
                    <div>
                        <button id="moolamsmall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '010')">मूलम्</button>
                        <button id="padasmall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '010')">पदविभागः</button>
                        <button id="anvayasmall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '010')">अन्वयः</button>
                        <button id="pratismall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '010')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '010')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '010')">हिन्द्यर्थः</button>
                        <button id="audiosmall010" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '010')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अनेकसंशयोच्छेदि परोक्षार्थस्य दर्शकम् । सर्वस्य लोचनं शास्त्रं यस्य नास्त्यन्ध एव सः ॥०.१०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अनेक-संशय-उच्छेदि परोक्ष-अर्थस्य दर्शकम् । सर्वस्य लोचनं शास्त्रं यस्य नास्ति अन्धः एव सः ॥०.१०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अनेक-संशय-उच्छेदि, परोक्ष-अर्थस्य दर्शकम्, सर्वस्य लोचनं (च यत्) शास्त्रं (तत्) यस्य (पुंसः) नास्ति, सः अन्धः एव ॥०.१०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अनेक-संशय-उच्छेदि ~ अनेकान् संशयान् उच्छिनत्ति तच्छीलम् = नाना-वितर्क-विनाशकम्; परोक्ष-अर्थस्य = अतीत-अनागतादि-अर्थस्य; दर्शकम् = बोधकम्; सर्वस्य लोचनं = लोचनम् इव मार्गदर्शकम्; शास्त्रं यस्य (पुंसः) नास्ति, सः; अन्धः = लोचनविकलः; एव; ॥०.१०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सकलान् सन्देहान् अपाकुर्वत्, अप्रत्यक्षस्य, निगूढस्यार्थस्य च दर्शकं यत् शास्त्रं, तत् सर्वेषां नयनमिव विलसति। यस्य मनुष्यस्य शास्त्रज्ञानं नास्ति, सः दृष्टिहीन एव ॥०.१०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सब प्रकार के संशय को दूर करने वाला, तथा परोक्ष वस्तुओंको भी प्रत्यक्ष करानेवाला शास्त्र ही सबका सच्चा नेत्र है, और जिसके पास वह शास्त्र रूपी नेत्र नहीं है, वह मनुष्य अन्धे के समान है ॥०.१०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.10.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="011" class="total">
                    <div>
                        <button id="moolamsmall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '011')">मूलम्</button>
                        <button id="padasmall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '011')">पदविभागः</button>
                        <button id="anvayasmall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '011')">अन्वयः</button>
                        <button id="pratismall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '011')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '011')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '011')">हिन्द्यर्थः</button>
                        <button id="audiosmall011" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '011')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यौवनं धनसम्पत्तिः प्रभुत्वमविवेकिता । एकैकमप्यनर्थाय किमु यत्र चतुष्टयम् ॥०.११॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यौवनं धन-सम्पत्तिः प्रभुत्वम् अविवेकिता । एकैकम् अपि अनर्थाय किमु यत्र चतुष्टयम् ॥०.११॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यौवनं, धन-सम्पत्तिः, प्रभुत्वम्, अविवेकिता - (अत्र) एकैकम् अपि (पुंसाम्) अनर्थाय (भवति)। यत्र चतुष्टयम् (तत्र) किमु (अनर्थस्य विषये वक्तव्यम्?) ॥०.११॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यौवनं = युवावस्था; धन-सम्पत्तिः = वित्तसमृद्धिः; प्रभुत्वम् = ऐश्वर्यम्, अधिकारः; अविवेकिता = विचार-वैकल्यम्, मूढता; एकैकम् अपि (पुंसां); अनर्थाय = विपत्कारकं भवति; यत्र = यस्मिन् पुंसि; चतुष्टयम् (तत्र); किमु = किं वा वक्तव्यम्; ॥०.११॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>युवावस्था, वित्तसमृद्धिः, अधिकारस्थानं, अविवेकः- इत्येतेषु गुणस्थितिषु प्रत्येकं (अन्यजनेभ्यः) आपत्करं भवति। यदि कस्मिंश्चित् पुरुषे सर्वाणि मिलित्वा विद्यन्ते, तर्हि अनर्थकत्वस्य किं विशेषतया वक्तव्यं भवति? तदवश्यमेव आपत्स्थानं भवति </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>युवावस्था, धनसम्पत्ति, प्रभुत्व, अज्ञानता- इन चारों में एक भी जहाँ वस्तु हो वहाँ अनर्थ (जिस मनुष्य में) ही प्रायः होता है । फिर जहाँ ये चारों एकत्र हो, वहाँ की तो बात ही क्या है? ॥०.११॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.11.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="012" class="total">
                    <div>
                        <button id="moolamsmall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '012')">मूलम्</button>
                        <button id="padasmall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '012')">पदविभागः</button>
                        <button id="anvayasmall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '012')">अन्वयः</button>
                        <button id="pratismall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '012')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '012')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '012')">हिन्द्यर्थः</button>
                        <button id="audiosmall012" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '012')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>कोऽर्थः पुत्रेण जातेन यो न विद्वान् न धार्मिकः । काणेन चक्षुषा किं वा चक्षुः पीडैव केवलम् ॥०.१२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः अर्थः पुत्रेण जातेन यः न विद्वान् न धार्मिकः । काणेन चक्षुषा किं वा चक्षुः पीडा एव केवलम् ॥०.१२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः (पुत्रः) विद्वान् न (भवति) धार्मिकः न (वर्तते) (तेन) पुत्रेण जातेन कः अर्थः (प्रयोजनम्) ? (अत्र उदाहरणम्-) काणेन चक्षुषा किं वा (प्रयोजनम्?) चक्षुः पीडा एव केवलं (भवति) ॥०.१२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यः = पुत्रः; न विद्वान् न धार्मिकः = धर्माचरणप्रवणः; (तेन) पुत्रेण जातेन = उत्पन्नेनापि; कः अर्थः = किं प्रयोजनम्?; काणेन = दर्शनशक्तिशून्येन; एकचक्षुर्युक्तः (काणत्वञ्च चक्षुरिन्द्रियशून्यैकगोलकवत्त्वम्); चक्षुषा = नेत्रेण; किं वा = किं नु फलं, न किमपि फलं; चक्षुः-पीडा एव = शारीरिकव्यथा; केवलम् = मात्रम्; ॥०.१२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः सुतः विद्वत्त्वं न धारयति, धर्मं वा नाचरति, सः सम्भूय अपि न कस्यापि प्रयोजनं कारयति। अस्योदाहरणमेवम्– दर्शनशक्तिहीन-गोलरूपेणाक्ष्णा वस्तुदर्शनं न शक्यते। केवलं तत्व्यथां कारयति, न कस्याप्युपयोगाय भवति ॥०.१२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उस पुत्र के उत्पन्न होने से क्या लाभ है, जो न विद्वान् है और न धार्मिक ही । क्यों कि कानी आँख से कोई लाभ नहीं होता, वह तो केवल पीडा ही देने के लिये होती है ॥०.१२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.12.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="013" class="total">
                    <div>
                        <button id="moolamsmall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '013')">मूलम्</button>
                        <button id="padasmall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '013')">पदविभागः</button>
                        <button id="anvayasmall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '013')">अन्वयः</button>
                        <button id="pratismall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '013')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '013')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '013')">हिन्द्यर्थः</button>
                        <button id="audiosmall013" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '013')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अजातमृतमूर्खाणां वरमाद्यौ न चान्तिमः । सकृद्दुःखकरावाद्यावन्तिमस्तु पदे पदे ॥०.१३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अजात-मृत-मूर्खाणां वरम् आद्यौ न च अन्तिमः । सकृद्-दुःख-करौ आद्यौ अन्तिमः तु पदे पदे ॥०.१३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अजात-मृत-मूर्खाणां (इति त्रिविधानां पुत्राणां मध्ये) वरम् आद्यौ (द्वौ) न च अन्तिमः (मूर्खः)। सकृद् दुःख-करौ आद्यौ अन्तिमः तु पदे पदे (दुःख-करः) ॥०.१३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अजातः = अनुत्पन्नः; मृतः = उत्पन्नोऽपि विगतप्राणः; मूर्खः = मूढः, जडः; वरम् = श्रेष्ठौ; आद्यौ = अजात-मृतौ; न च अन्तिमः = न मूर्खः; सकृद्-दुःख-करौ = एकवारमेव दुःखं दत्तः; आद्यौ = अजात-मृतौ; अन्तिमः = मूर्खः; तु पदे पदे = सर्वदा, यावज्जीवम् ॥०.१३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अनुत्पन्नपुत्रः मृतपुत्रः वा एकवारमेव दुःखं ददाति। मूर्खपुत्रस्तु आजन्ममरणं दुःखयति। अतः अनुत्पन्न-मृत-पुत्रौ मूर्खपुत्रात् वरम् ॥०.१३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो उत्पन्न ही नहीं हुआ है (अजात), अथवा उत्पन्न होकर मर गया है (मृत), और मूर्ख - इन तीनों में से पहले दो तो कुछ अच्छे हैं, परन्तु अन्तिम (मूर्ख) पुत्र तो कभी अच्छा नहीं है, क्यों कि प्रथम दो पुत्र तो एकही बार दुःख देते हैं, परन्तु अन्तिम (मूर्ख) तो सदा दुःखदाई होता है ॥०.१३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.13.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="014" class="total">
                    <div>
                        <button id="moolamsmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '014')">मूलम्</button>
                        <button id="padasmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '014')">पदविभागः</button>
                        <button id="anvayasmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '014')">अन्वयः</button>
                        <button id="pratismall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '014')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '014')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '014')">हिन्द्यर्थः</button>
                        <button id="audiosmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '014')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वरं गर्भस्रावो वरमृतुषु नैवाभिगमनं वरं जातः प्रेतो वरमपि च कन्यैव जनिता । वरं वन्ध्या भार्या वरमपि च गर्भेषु वसति- र्न वाविद्वान् रूपद्रविणगुणयुक्तोऽपि तनयः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरं गर्भ-स्रावः। वरम् ऋतुषु न एव अभिगमनम्। वरं जातः प्रेतः। वरम् अपि च कन्या एव जनिता । वरं वन्ध्या भार्या। वरम् अपि च गर्भेषु वसतिः। न वा अविद्वान् रूप-द्रविण-गुण-युक्तः अपि तनयः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गर्भ-स्रावः वरम्। ऋतुषु न एव अभिगमनम् वरम् । जातः प्रेतः वरम्। अपि च कन्या एव जनिता वरम्। वन्ध्या भार्या वरम् । अपि च गर्भेषु वसतिः वरम् । अविद्वान् रूप-द्रविण-गुण-युक्तः अपि तनयः न वा (वरम्)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गर्भ-स्रावः =गर्भपातः; वरम् = ईषत् श्रेष्ठः; ऋतुषु = भार्यायाः ऋतुकाले; न एव; अभिगमनम् = उपसर्पणम्; वरम् । जातः प्रेतः = मृतः; वरम्। अपि च; कन्या एव जनिता वरम्। वन्ध्या = सन्तानजनने असमर्था; भार्या वरम् । अपि च; गर्भेषु = कुक्षौ एव; वसतिः = निवासः; वरम् । अविद्वान् = मूर्खः; रूप-द्रविण-गुण-युक्तः = सुन्दरः, धनवान्, सकलसद्गुणयुक्तः; अपि तनयः = पुत्रः; न वा (वरम्)॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>रूपसद्गुणयुक्तोपि सन् मूर्खपुत्रः यदि जायते, तत्तुलनायां किं किं श्रेष्ठमिति वदति– गर्भपातः, भार्यासङ्गमवर्जनं, मृतशिशुजननं, कन्याजननं, पत्न्याः शिशुजननाशक्तता, कुक्षावेव पिण्डस्य वासः–एतानि सर्वाणि श्रेष्ठानि मूर्खसुतस्य जननात् इति॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और चाहे गर्भपात हो जाए श्रथवा पुत्रोत्पत्ति के लिए ऋतुकाल में स्त्री के पास गमन ही न किया जाए, या जन्मता ही पुत्र मर जाए या कन्या हो उत्पन्न हो, या सन्तान गर्भ में हो रहे, गर्भ से बाहर उत्पन्न ही न हो, यह सब ठकि है, पर मूर्ख पुत्र यदि सुन्दर भी हो तो भी वह ठकि नहीं है ॥०.१४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.14.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="014" class="total">
                    <div>
                        <button id="moolamsmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '014')">मूलम्</button>
                        <button id="padasmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '014')">पदविभागः</button>
                        <button id="anvayasmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '014')">अन्वयः</button>
                        <button id="pratismall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '014')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '014')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '014')">हिन्द्यर्थः</button>
                        <button id="audiosmall014" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '014')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td></td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स जातो येन जातेन याति वंशः समुन्नतिम् । परिवर्तिनि संसारे मृतः को वा न जायते ॥०.१४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>येन जातेन वंशः समुन्नतिं याति, सः (वस्तुतः) जातः । परिवर्तिनि संसारे कः वा मृतः? (कः वा) न जायते? ॥०.१४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>येन जातेन = यस्य जन्मना; वंशः = आत्मकुलं; समुन्नतिं = ख्यातिं, औन्नत्यं च; याति = भजते, प्राप्नोति; सः; जातः = सुजातः; परिवर्तिनि = परिवर्तनशीले; संसारे = अनादौ अस्मिन् जगति; को वा न मृतः? को वा न जायते? ॥०.१४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य जन्मना कुलं (कुटुम्बः) औन्नत्यं प्राप्नोति, सः पुत्रः जातः इति वक्तुं शक्यते। अन्ये जीवाः बहवो संसारेऽस्मिन् जीवन्ति, म्रियन्ते च। [कोटिशो जीवाः अस्मिन् जगति प्रत्यहमुद्यन्ते, विलीयन्ते च, स एव तु सुजन्मा धन्यजीवितो यस्य जन्मना स्वकुलं महीयते इत्याशयः] ॥०.१४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और इस जगत् में उसी का जन्म लेना सफल है, जिसके जन्म से अपने वंश और जाति की उन्नति होती है । अन्यथा (इस तरह तो) इस परिवर्तनशील संसार में कौन नहीं जीता और मरता है ॥०.१४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.14.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="015" class="total">
                    <div>
                        <button id="moolamsmall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '015')">मूलम्</button>
                        <button id="padasmall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '015')">पदविभागः</button>
                        <button id="anvayasmall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '015')">अन्वयः</button>
                        <button id="pratismall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '015')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '015')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '015')">हिन्द्यर्थः</button>
                        <button id="audiosmall015" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '015')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>गुणिगणगणनारम्भे न पतति कठिनी सुसम्भ्रमाद् यस्य । तेनाम्बा यदि सुतिनी वद वन्ध्या कीदृशी भवति ? ॥०.१५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गुणि-गण-गणना आरम्भे न पतति कठिनी सुसम्भ्रमाद् यस्य । तेन अम्बा यदि सुतिनी वद वन्ध्या कीदृशी भवति ? ॥०.१५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुणि-गण-गणना-आरम्भे सुसम्भ्रमाद् यस्य कठिनी न पतति । तेन अम्बा यदि सुतिनी, वन्ध्या कीदृशी भवति, (इति) वद ? ॥०.१५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गुणि-गण-गणना-आरम्भे ~ गुणिनां गणाः तेषां गणनायाः आरम्भे = विदुषां सङ्घाः, तेषां प्रारम्भावसरे ; सुसम्भ्रमाद् = सहसैव ; यस्य = यस्य पुंसो नामनि ; कठिनी = लेखनसाधनम् (=पेंसिल्) ; न पतति = (अत्र) लेखाधारे काष्ठपट्टे, पत्रादौ वा तन्नामोल्लेखार्थं न झटिति प्रसरति ; तेन अम्बा = माता ; यदि = यदा ; सुतिनी = पुत्रवती ; वन्ध्या = पुत्रहीना, अपुत्रा स्त्री ; कीदृशी = का ; भवति = भण्यते ; (इति) वद = कथय तावत् ; ॥०.१५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विद्वत्सङ्घानां गणनायाः प्रारम्भावसरे सहसैव यस्य लेखकस्य कठिनी कस्यचित् पुरुषस्य नामलेखनाय लेखनपत्रे न पतति, यदि तत्पुरुषस्य माता पुत्रवती इति उच्यते, तर्हि का वा स्त्री वन्ध्या इति कथ्येत? गुणिसमवाये यस्य पुंसः शोभनं यशो वर्तते, स एव, सुजन्मेति हृदयम्। सैव तु खलु वन्ध्या ॥०.१५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>गुणियों की गिनती के आरम्भ में जिसके नाम पर सबसे पहले सहसा लोगों की कलम न उठे, उस पुरुष के जन्म से भी यदि उसकी माता पुत्र-वती कहलावे, तो कहो वन्ध्या किसे कहेंगे? [जिसे अपने सद्गुणों के कारण लोग नहीं पहचानते, ऐसे पुत्र का होना ना होने के समान है।] ॥०.१५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.15.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="016" class="total">
                    <div>
                        <button id="moolamsmall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '016')">मूलम्</button>
                        <button id="padasmall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '016')">पदविभागः</button>
                        <button id="anvayasmall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '016')">अन्वयः</button>
                        <button id="pratismall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '016')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '016')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '016')">हिन्द्यर्थः</button>
                        <button id="audiosmall016" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '016')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दाने तपसि शौर्ये च यस्य न प्रथितं यशः । विद्यायामर्थलाभे च मातुरुच्चार एव सः ॥०.१६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दाने तपसि शौर्ये च यस्य न प्रथितं यशः । विद्यायाम् अर्थलाभे च मातुः उच्चारः एव सः ॥०.१६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दाने तपसि शौर्ये च विद्यायाम् अर्थलाभे च यस्य यशः न प्रथितं, सः मातुः उच्चारः एव ॥०.१६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दाने = धनादिवितरणे ; तपसि = धर्माचरणादौ ; शौर्ये = वीरत्वे ; विद्यायाम् = ज्ञाने ; अर्थलाभे = धनोपार्जने ; यस्य = पुंसः ; यशः = कीर्तिः ; न प्रथितं = न प्रसृतम् ; सः ; मातुः = जनन्याः ; उच्चारः = विष्टा, मलं ; एव = मात्रम् ॥०.१६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धनादिवितरणे, धर्माचरणादौ, वीरत्वे, ज्ञाने, धनोपार्जने यस्य पुंसः कीर्तिः न प्रसृतम्, सः जनन्याः विष्ठामात्रम् । नासौ पुत्रः केषामपि उपयोगाय भवति। तस्य जन्म वृथा भवतीति अभिप्रायः ॥०.१६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिस मनुष्य का मन-दान, तपस्या, वीरता, विद्या तथा धनोपार्जन मे न लगा, वह मनुष्य केवल माता के मल के समान है ॥०.१६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.16.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="017" class="total">
                    <div>
                        <button id="moolamsmall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '017')">मूलम्</button>
                        <button id="padasmall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '017')">पदविभागः</button>
                        <button id="anvayasmall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '017')">अन्वयः</button>
                        <button id="pratismall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '017')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '017')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '017')">हिन्द्यर्थः</button>
                        <button id="audiosmall017" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '017')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वरमेको गुणी पुत्रो न च मूर्खशतान्यपि । एकश्चन्द्रस्तमो हन्ति न च तारागणोऽपि च ॥०.१७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरम् एकः गुणी पुत्रः न च मूर्ख-शतानि अपि । एकः चन्द्रः तमः हन्ति न च तारा-गणः अपि च ॥०.१७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>एकः अपि गुणी पुत्रः वरम्। (किन्तु) मूर्ख-शतानि न च। एकः चन्द्रः तमः हन्ति। तारा-गणः अपि न च ॥०.१७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>एकः अपि ; गुणी = सुगुणसंयुक्तः ; पुत्रः = सुतः ; वरम् = श्रेष्ठः ; (किन्तु) न च ; मूर्ख-शतानि = जड-मन्दपुत्राणां शतमपि ; एकः चन्द्रः ; तमः = अन्धकारं ; हन्ति = नाशयति ; न च तारा-गणः अपि च = नक्षत्रकोटीरपि ॥०.१७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गुणवता पुत्रेण एकेनापि अलम्। यदि एकशतं पुत्राः अपि मन्दबुद्धयः भवन्तु, तेन न कोऽपि लाभः। यथा– रात्रौ चन्द्रः एक एव अन्धकारं अपनेतुं समर्थः। असङ्ख्यकानि नक्षत्राणि मिलित्वा अपि कान्तिं न कुर्वन्ति ॥०.१७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सौ मूर्ख पुत्रों की अपेक्षा एक ही पुत्र गुणी हो तो भी अच्छा है। बहुत से तारागणों से अन्धकार दूर नहीं होता है, पर चन्द्रमा अकेला ही उसे दूर कर देता है ॥०.१७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.17.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="018" class="total">
                    <div>
                        <button id="moolamsmall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '018')">मूलम्</button>
                        <button id="padasmall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '018')">पदविभागः</button>
                        <button id="anvayasmall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '018')">अन्वयः</button>
                        <button id="pratismall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '018')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '018')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '018')">हिन्द्यर्थः</button>
                        <button id="audiosmall018" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '018')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पुण्यतीर्थे कृतं येन तपः क्वाप्यतिदुष्करम् । तस्य पुत्रो भवेद् वश्यः समृद्धो धार्मिकः सुधीः ॥०.१८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पुण्य-तीर्थे कृतं येन तपः क्व-अपि अति-दुष्करम् । तस्य पुत्रः भवेद् वश्यः समृद्धः धार्मिकः सुधीः ॥०.१८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>येन क्वापि पुण्य-तीर्थे अति-दुष्करं तपः कृतं, तस्य पुत्रः वश्यः, समृद्धः, धार्मिकः, सुधीः च भवेत् ॥०.१८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>येन क्वापि पुण्य-तीर्थे = महाक्षेत्रे ; कृतं ; अति-दुष्करं = कठिनं ; तपः ; तस्य = (पुण्यात्मनः) ; पुत्रः ; वश्यः = वशंवदः ; समृद्धः = गुणगण-अलङ्कृकृतः, धनी च ; धार्मिकः = धर्मात्मा ; सुधीः = विद्वान्, विनीतश्च ; भवेत् = स्यात् ॥०.१८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>येन पित्रा कुत्रचित् महापुण्यस्थले अतिकठिनं तपः आचरितं, तस्य एव नियतः, सम्पन्नः, धर्मानुष्ठानपरः, धीशाली च पुत्रो भवेत्। (अतिमहतस्तपसः फलमेतद्यत्पुत्रो विद्वान् विनीतश्च भवतीति भावः।) ॥०.१८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिस मनुष्य ने किसी पुण्यतीर्थं में कठिन तपस्या की है, उसीका पुत्र आज्ञाकारी, समृद्ध, धार्मिक तथा विद्वान् होता है ॥०.१८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.18.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="019" class="total">
                    <div>
                        <button id="moolamsmall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '019')">मूलम्</button>
                        <button id="padasmall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '019')">पदविभागः</button>
                        <button id="anvayasmall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '019')">अन्वयः</button>
                        <button id="pratismall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '019')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '019')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '019')">हिन्द्यर्थः</button>
                        <button id="audiosmall019" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '019')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अर्थागमो नित्यमरोगिता च प्रिया च भार्या प्रियवादिनी च । वश्यश्च पुत्रोऽर्थकरी च विद्या षड् जीवलोकस्य सुखानि राजन् ॥०.१९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अर्थ-आगमः नित्यम् अरोगिता च प्रिया च भार्या प्रिय-वादिनी च । वश्यः च पुत्रः अर्थकरी च विद्या षड् जीव-लोकस्य सुखानि राजन् ॥०.१९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>राजन्, १) नित्यम् अर्थ-आगमः, २) अरोगिता च, ३) प्रिय-वादिनी (भार्या), ४) प्रिया च भार्या, ५) वश्यः च पुत्रः, ६) अर्थकरी विद्या (एतानि) षड् जीव-लोकस्य सुखानि च ॥०.१९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>राजन् = हे युधिष्ठिर, नित्यं = (अत्र) निर्बाधः ; अर्थ-आगमः = धनप्राप्तिः ; अरोगिता च = शरीरसौख्यं, स्वास्थ्यम् ; प्रिय-वादिनी = मधुरभाषिणी ; प्रिया =हृद्या ; भार्या = पत्नी ; वश्यः = अनुकूलः ; पुत्रः ; अर्थकरी = धनकरी ; विद्या ; एतानि षट् जीव-लोकस्य = मानवलोकस्य ; सुखानि = सुखकारकाणि ॥०.१९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे राजन्, निराघात-धनप्राप्तिः, शरीरस्वास्थ्यं, मधुरं वदन्ती, प्रियतमा च पत्नी, आज्ञाकारी पुत्रः, धनप्रापयित्री विद्या च– एतानि षट् मानवलोके सुखकराणि इति मन्यन्ते ॥०.१९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हे राजन्! संसार में केवल छे ही सुख हैं- १. नित्य धनप्राप्ति, २. आरोग्यता, ३. प्रियतमा भार्या, ४. मधुर बोलने वाली स्त्री, ५. आज्ञाकारी पुत्र, तथा ६. धन देनेवाली विद्या ॥०.१९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.19.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="020" class="total">
                    <div>
                        <button id="moolamsmall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '020')">मूलम्</button>
                        <button id="padasmall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '020')">पदविभागः</button>
                        <button id="anvayasmall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '020')">अन्वयः</button>
                        <button id="pratismall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '020')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '020')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '020')">हिन्द्यर्थः</button>
                        <button id="audiosmall020" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '020')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>को धन्यो बहुभिः पुत्रैः कुशूलापूरणाढकैः । वरमेकः कुलालम्बी यत्र विश्रूयते पिता ॥०.२०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः धन्यः बहुभिः पुत्रैः कुशूल-आपूरण-आढकैः । वरम् एकः कुल-आलम्बी यत्र विश्रूयते पिता ॥०.२०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कुशूल-आपूरण-आढकैः कः धन्यः बहुभिः पुत्रैः एकः कुल-आलम्बी वरम् । यत्र पिता विश्रूयते ॥०.२०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कुशूल-आपूरण-आढकैः = धान्य-कोष्ठक-पूरण-असमर्थैः आढकपात्रैः इव [कुशूलं- = धान्यावपनम्- आढकम्- = आढकपरिमितम् धान्यपात्रम् (अढाई सेर का) ]; = स्वल्पाशयैः तुच्छैः ; बहुभिः पुत्रैरपि ; कः धन्यः = कः पुण्यवान् ; एकः कुल-आलम्बी = येन कुल आलम्ब्यते ; वरम् = श्रेष्ठः ; यत्र = यस्मिन् पुत्रे जाते ; पिता = जनकः ; विश्रूयते = लोके महीयते ; ॥०.२०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कः पुमान् अल्पाशयैः पुत्रैः सुकृती इति लोके विश्रूयते? यः पुत्रः कुलं धरति, यस्य जातेन कुलस्य आलम्बनं भवति, स एव पुत्रत्वार्हः ; तेनैव पिता जगति कीर्तिं विन्दति। (अथवा अन्ये तु– खरीवाहादिपरिमितैः, आढकपरिमितैः च पुत्रस्थानीयधान्यादिभिः कः धनी इति गण्यते? कुशूलादिमितेनापि धान्यराशिना न कोपि धन्यतां लभते। एकेन कुलदीपकेन- रत्नादिना, कौस्तुभमणिना सागर इव- पिता धनी श्रेष्ठश्च भवति– इत्यर्थमाहुः) ॥०.२०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अन्न की कोटी (ओवरी, कोठला) को भरने में असमर्थ आढकपात्रों (अढैया, पसेरी आदि नाप के पात्रों) के समान बहुत से पुत्रों से क्या लाभ है, वंश की सहायता करनेवाला तो एक ही पुत्र अच्छा है, जिससे पिता की प्रसिद्धि और प्रशंसा होती हो ॥०.२० ॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.20.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="021" class="total">
                    <div>
                        <button id="moolamsmall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '021')">मूलम्</button>
                        <button id="padasmall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '021')">पदविभागः</button>
                        <button id="anvayasmall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '021')">अन्वयः</button>
                        <button id="pratismall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '021')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '021')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '021')">हिन्द्यर्थः</button>
                        <button id="audiosmall021" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '021')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>ऋणकर्ता पिता शत्रुर्माता च व्यभिचारिणी । भार्या रूपवती शत्रुः पुत्रः शत्रुरपण्डितः ॥०.२१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>ऋण-कर्ता पिता शत्रुः माता च व्यभिचारिणी । भार्या रूपवती शत्रुः पुत्रः शत्रुः अपण्डितः ॥०.२१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पिता ऋण-कर्ता शत्रुः। माता च व्यभिचारिणी (शत्रुः) । भार्या रूपवती शत्रुः । पुत्रः अपण्डितः शत्रुः ॥०.२१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पिता = जनकः ; ऋण-कर्ता = यः पुनः पुनः अन्येभ्यः ऋणं स्वीकृत्य जीवति ; शत्रुः = अयशोहेतुत्वात् शत्रुरिव ; माता = जननी ; व्यभिचारिणी = परपुरुषरता ; भार्या = पत्नी ; रूपवती = सुन्दरी ; शत्रुः = विवाद-ईर्ष्यादि-हेतुत्वात् शत्रुरिव ; पुत्रः = सुतः ; अपण्डितः = मूर्खः ; शत्रुः = मनस्तापहेतुत्वात् शत्रुरिव ; ॥०.२१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य पिता ऋणं करोति, सः पुत्रस्य शत्रुरिव भवति (तस्य पुत्रेणैव तदृण-प्रत्यर्पणधुर्याः भारवहनत्वात्) । माता च नैकपतिव्रता (समाजे ज्ञातिषु चाकीर्तिकरत्वात्) शत्रुः भवति। सुन्दरी पत्नी तु (सर्वजनैः आकृष्टा, दृश्या च भूत्वा, पत्युर्मनसि ईर्ष्यादिदुर्भावान् जनयतीति कारणेन) शत्रुर्भवति। पुत्रस्तु विद्याहीनः, मूर्खश्च (कुलस्योद्गमे अयोग्यः सन्) शत्रुः भवति ॥०.२१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>ऋण करने वाला पिता शत्रुतुल्य है, व्यभिचारिणी माता शत्रुतुल्य है, रूपवती स्त्री भी शत्रुतुल्य है और मूर्ख पुत्र भी शत्रुतुल्य है ॥०.२१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.21.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="022" class="total">
                    <div>
                        <button id="moolamsmall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '022')">मूलम्</button>
                        <button id="padasmall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '022')">पदविभागः</button>
                        <button id="anvayasmall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '022')">अन्वयः</button>
                        <button id="pratismall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '022')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '022')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '022')">हिन्द्यर्थः</button>
                        <button id="audiosmall022" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '022')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अनभ्यासे विषं विद्या अजीर्णे भोजनं विषम् । विषं सभा दरिद्रस्य वृद्धस्य तरुणी विषम् ॥०.२२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अनभ्यासे विषं विद्या अजीर्णे भोजनं विषम् । विषं सभा दरिद्रस्य वृद्धस्य तरुणी विषम् ॥०.२२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अनभ्यासे (सति) विद्या विषम् (इव) । अजीर्णे भोजनं विषम् । दरिद्रस्य सभा विषम् । वृद्धस्य तरुणी विषम् ॥०.२२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अनभ्यासे (सति) = पुनःपुनरनुशीलनाभावे, पौनःपुन्येन करणाभावे ; विद्या = ज्ञानं ; विषं = अपमानस्थानत्वात् विषवद् दुःखप्रदा ; अजीर्णे = कुक्षौ अपक्वे आहारे (सति) ; भोजनं = अन्नं ; विषम् = जीवितापहारकत्वात् विषवद् दुःखप्रदम् ; दरिद्रस्य = धनहीनस्य, निर्धनस्य ; सभा = सदः, परिषद् ; विषं = सन्तापजनकत्वात् विषवद् दुःखप्रदा ; वृद्धस्य = विगतयौवनस्य ; तरुणी = युवा स्त्री ; विषम् = अयोग्यत्वात् विषवद् दुःखप्रदा ; ॥०.२२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अभ्यासाभावे विद्या हानिकरी भवति । (आवृत्त्यभावे नरः अधिगतविद्योऽपि सन् आवश्यकतायां सत्यां तां नोपयोक्तुं पारयेत् । अतः तस्य विद्यावत्त्वमेव शङ्क्यते जनैः ।) (उदरे जीर्णमभूत्वा यदान्नं यथातथं तिष्ठेत्, तदा अस्वास्थ्यं जनयति । अतः) अपाके खाद्यं विषं भवति । (धनाभावे उत्तमवस्त्रादीनां राहित्यात् जनसमूहेषु अपमानमनुभवेदिति) अकिञ्चनस्य सदः विषतुल्यं भवति । (तरुण्या सह सम्पर्कः यौवने सुख-सन्तानादिकारकं भवति । तदनावश्यकत्वात् शरीरशैथिल्याच्च) वयोऽधिकस्य स्त्रीसम्पर्कः विषं (अनारोग्यकरः) भवति ॥०.२२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>विना अभ्यास के विद्या भी विष है, अजीर्ण होने पर भोजन भी विष है दरिद्र मनुष्य केलिए सभी संसार ही विष तुल्य है और वृद्ध पुरुष के लिए उसकी युवती स्त्री भी विष के समान ही है ॥०.२२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.22.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="023" class="total">
                    <div>
                        <button id="moolamsmall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '023')">मूलम्</button>
                        <button id="padasmall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '023')">पदविभागः</button>
                        <button id="anvayasmall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '023')">अन्वयः</button>
                        <button id="pratismall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '023')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '023')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '023')">हिन्द्यर्थः</button>
                        <button id="audiosmall023" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '023')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यस्य कस्य प्रसूतोऽपि गुणवान् पूज्यते नरः । धनुर्वंशविशुद्धोऽपि निर्गुणः किं करिष्यति ॥०.२३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्य कस्य प्रसूतः अपि गुणवान् पूज्यते नरः । धनुः वंश-विशुद्धः अपि निर्गुणः किं करिष्यति ॥०.२३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुणवान् नरः, यस्य कस्य प्रसूतः अपि, पूज्यते । वंश-विशुद्धः अपि धनुः (चेत्) निर्गुणः, किं करिष्यति? ॥०.२३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य कस्य = अज्ञातकुलशीलस्य, अकुलीनस्यापि ; प्रसूतः = तत उत्पन्नः ; अपि ; गुणवान् = गुणी, सद्गुणसम्पन्नः, (अथवा धनुषः पक्षे) तन्तुयुतः, मौर्वीयुतः च ; नरः ; पूज्यते = सत्क्रियते, आद्रियते ; वंश-विशुद्धः अपि = श्रेष्ठवंशनिर्मितमपि ; धनुः = कोदण्डं ; निर्गुणः = गुणशून्यं, ज्यारहितम् ; किं करिष्यति = किं लक्ष्यं हन्तुं समर्थो भवति? ॥०.२३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सामान्यपुरुषात् उत्पन्नोऽपि (कुलवैशिष्ट्यरहितः, वंशविशुद्धरहितोऽपि यावत् ) नरः यदि सद्गुणसम्पन्नः तर्हि सर्वैः आद्रियते। (अस्यैव वाक्यस्य समर्थनाय उदाहरणं दीयते।) उत्तमकोटिधनुः अपि यदि ज्यारहितं, तर्हि न किमपि लक्ष्यं भेत्तुं उपयुज्यते। (ज्या इत्यस्य गुण इति पर्यायशब्दः। अतः श्लेषः पुरुषेऽपि अनुवर्तते। श्रेष्ठवंशे जातोऽपि सन् पुरुषः गुणहीनः अर्थरहितः भवति) ॥०.२३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>गुणी मनुष्य चाहे किसी कुल में उत्पन्न हो, सर्वत्र पूजित ही होता है, परन्तु यदि अच्छे कुल में उत्पन्न होकर भी मनुष्य निर्गुण हो, तो वह क्या कर सकता है, किस काम का है? जैसे धनुष अच्छे बाँस का बना होने पर भी यदि उस में गुण (तात या डोरो) न हो तो वह क्या काम कर सकता है? कुछ भी नहीं । यहाँ वंश शब्द के दो अर्थ हैं, बांस और कुल ॥०.२३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.23.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="024" class="total">
                    <div>
                        <button id="moolamsmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '024')">मूलम्</button>
                        <button id="padasmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '024')">पदविभागः</button>
                        <button id="anvayasmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '024')">अन्वयः</button>
                        <button id="pratismall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '024')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '024')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '024')">हिन्द्यर्थः</button>
                        <button id="audiosmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '024')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>हा हा पुत्रक नाधीतं गतास्वेतासु रात्रिषु । तेन त्वं विदुषां मध्ये पङ्के गौरिव सीदसि ॥०.२४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>हा हा पुत्रक, न अधीतं गतासु एतासु रात्रिषु । तेन त्वं विदुषां मध्ये पङ्के गौः इव सीदसि ॥०.२४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पुत्रक, हा हा! एतासु रात्रिषु गतासु न अधीतम् । तेन विदुषां मध्ये पङ्के गौः इव त्वं सीदसि ॥०.२४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पुत्रक = हे पुत्र (सम्बोधनम्) ; हा हा = धिक्, अहो, (दुःखकरं) ; एतासु रात्रिषु गतासु = वृथा-अपयातासु रात्रिसमयेषु (दिनसामान्यार्थे) ; न अधीतं = शास्त्रं न अभ्यस्तम्, ज्ञानं न सम्प्राप्तम् ; तेन = कालयापनेन, अनध्ययनेन च ; विदुषां = पण्डितानां, विद्यावतां ; मध्ये = सभायां, पुरतः ; पङ्के = कर्दमे ; गौः इव = जन्तुविशेष-सदृशः ; त्वं सीदसि = क्लेशमनुभवसि, विषण्णो, आकुलो भवसि ॥०.२४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे सुत, धिक्। त्वं एतावन्ति नक्तंदिनानि विना विद्याभ्यासं व्यर्थं कालमपनीतवान्। अतः त्वं इदानीं विद्वज्जनसम्मुखं यथा पङ्के पतितः गौः, तथा खिन्नः भवसि ॥०.२४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हे पुत्र! खेद है कि तुमने बाल्यकालकी बीती हुई रात्रियों में कुछ नहीं पढा, इसीलिए विद्वानों की मण्डली में आज तुम्हारी यह दशा हो रही है, जो दशा कीचड़ में फँसी हुई गाय की होती है ॥०.२४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.24.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="024" class="total">
                    <div>
                        <button id="moolamsmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '024')">मूलम्</button>
                        <button id="padasmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '024')">पदविभागः</button>
                        <button id="anvayasmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '024')">अन्वयः</button>
                        <button id="pratismall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '024')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '024')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '024')">हिन्द्यर्थः</button>
                        <button id="audiosmall024" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '024')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आहारनिद्राभयमैथुनञ्च सामान्यमेतत् पशुभिर्नराणाम् । धर्मो हि तेषामधिको विशेषो धर्मेण हीनाः पशुभिः समानाः ॥०.२५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आहार-निद्रा-भय-मैथुनञ्च सामान्यम् एतत् पशुभिः नराणाम् । धर्मः हि तेषां अधिकः विशेषः धर्मेण हीनाः पशुभिः समानाः ॥०.२५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आहार-निद्रा-भय-मैथुनञ्च एतत् नराणाम् पशुभिः सामान्यम् । हि तेषां धर्मः अधिकः विशेषः । धर्मेण हीनाः पशुभिः समानाः ॥०.२५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आहार-निद्रा-भय-मैथुनञ्च ~ आहारश्च, निद्रा च, भयञ्च, मैथुनं च = रतिश्च, एषां समाहारः ~ आहार-निद्राभयमैथुनम् । एतत् ; नराणां = पुंसां ; पशुभिः = गवादिभिः पशुभिः ; सामान्यं= तुल्यम् एव ; हि = यतः ; तेषां = नराणाम् ; धर्मः = विद्या-विनय-धर्माचारादिः एव ; अधिकः = असदृशः, अतिरिक्तः अंशः, तत्र अवर्तमानः ; विशेषः = भेदकः ; धर्मेण हीनाः = रहिताः नरास्तु ; पशुभिः समानाः = पशुतुल्या एव इत्यर्थः ॥०.२५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अन्नादनं, शयनं, प्राणभीतिः, रतीच्छा च चतुष्पादजन्तूनां मनुष्याणां च समानधर्माः भवन्ति। तयोः द्वयोः धर्माचरणमेव भेदः। नराणां धर्मः अतिरिक्ततया विशेषांशो भवति। ये पुरुषाः धर्माचरणरहिताः ते पशुसदृशाः भवन्ति ॥०.२५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>भोजन, नींद, भय और मैथुन- ये चार बातें तो मनुष्यों और पशुओं में समान ही हैं। मनुष्य में केवल धर्म (गुण) ही अधिक है, इस लिए धर्महीन (विद्या विनय आदि गुणों से रहित) मनुष्य पशु के ही समान है ॥०.२५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.24.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="026" class="total">
                    <div>
                        <button id="moolamsmall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '026')">मूलम्</button>
                        <button id="padasmall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '026')">पदविभागः</button>
                        <button id="anvayasmall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '026')">अन्वयः</button>
                        <button id="pratismall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '026')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '026')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '026')">हिन्द्यर्थः</button>
                        <button id="audiosmall026" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '026')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धर्मार्थकाममोक्षाणां यस्यैकोऽपि न विद्यते । अजागलस्तनस्येव तस्य जन्म निरर्थकम् ॥०.२६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धर्म-अर्थ-काम-मोक्षाणां यस्य एकः अपि न विद्यते । अजा-गल-स्तनस्य इव तस्य जन्म निरर्थकम् ॥०.२६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य धर्म-अर्थ-काम-मोक्षाणां एकः अपि न विद्यते, तस्य जन्म अजा-गल-स्तनस्य इव निरर्थकम् ॥०.२६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य = यस्य पुंसः ; धर्म-अर्थ-काम-मोक्षाणां = धर्मार्थ-काम-मोक्षाख्य-पुरुषार्थ-चतुष्टयस्य मध्ये ; एकोऽपि ; पुरुषार्थः = धर्मादिरूपो ; न विद्यते = (ध्येयत्वेन) न भवति ; तस्य = तस्य पुंसः ; अजागलस्तनस्य इव = अजा-गल-स्थित-स्तन-वत् लम्बमान-चर्म-खण्डस्य इव ; जन्म = जननं ; निरर्थकं = निष्फलमेव ; ॥०.२६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य पुरुषस्य पुरुषार्थ-चतुष्टयस्य मध्ये एकः अपि पुरुषार्थः धर्मो अर्थो कामो मोक्षो वा न विद्यते, तस्य धर्मादीनसेवमानस्य पुंसः दुग्धादि-रहित-बर्कर-गलचर्म-खण्डमिव वृथैव जन्म इत्याशयः ॥०.२६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि-धर्म अर्थ, काम, मोक्ष-इन चारों में से जिसके पास एक भी नहीं है, उस मनुष्य का जन्म वैसे ही व्यर्थ है, जैसे बकरी के गले का स्तन (चमड़ेकी स्तनाकार लम्बी थैली) ॥०.२६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.26.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="027" class="total">
                    <div>
                        <button id="moolamsmall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '027')">मूलम्</button>
                        <button id="padasmall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '027')">पदविभागः</button>
                        <button id="anvayasmall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '027')">अन्वयः</button>
                        <button id="pratismall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '027')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '027')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '027')">हिन्द्यर्थः</button>
                        <button id="audiosmall027" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '027')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आयुः कर्म च वित्तं च विद्या निधनमेव च । पञ्चैतानि हि सृज्यन्ते गर्भस्थस्यैव देहिनः ॥०.२७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आयुः कर्म च वित्तं च विद्या निधनम् एव च । पञ्च एतानि हि सृज्यन्ते गर्भस्थस्य एव देहिनः ॥०.२७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आयुः कर्म च वित्तं च विद्या निधनम् एव च– एतानि पञ्च हि गर्भस्थस्य एव देहिनः सृज्यन्ते ॥०.२७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आयुः = जीवितकालः ; कर्म = जीविकासाधनं कर्म, शुभाशुभमाचरणं वा ; वित्तं = धनम् ; विद्या ; निधनं = मृत्युः ; एतानि पञ्च ; गर्भस्थस्य = मातुः कुक्षिस्थस्यैव ; देहिनः = प्राणिनः, जीविनः, शरीरिणः ; सृज्यन्ते = कल्प्यन्ते ॥०.२७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शरीरिणः पञ्च विषयाः– १. जीवनपरिमाणं, २. पोषणाय वृत्तिः शुभाशुभकार्याणि वा, ३. आर्थिकस्थितिः, ४. ज्ञानं, ५. मरणसमयश्च– सर्वे जन्मनः पूर्वं गर्भे स्थिते एव निर्धृताः भवन्ति। (कोऽपि एतेषामभावस्य कारणं प्रयत्नलोप इति वक्तुं न शक्नोति। प्राणिनः मातृगर्भस्थितेः पूर्वमेव तस्य पूर्वजन्मनः कर्म अनुसृत्य आयुःप्रमाणादिकं निर्दिश्यते। अनेन निष्कर्षेण, स्थितौ परिणामः नितराम् असम्भव इति कथितुं न शक्यते। अभ्यासप्रयत्नाभ्यां तत्र कर्म-धन-विद्याविषयेषु लाभो भवेत्। यदि लाभो न दृश्येत, तर्हि शुचा न कार्या इत्येवास्य श्लोकस्यार्थः।) ॥०.२७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कुछ लोग जो कहा करते हैं कि- जब मनुष्य गर्भ में रहता है तभी उसकी आयु, कर्म (व्यवसाय, धन, विद्या कौर मृत्युका समय- ये (चार वस्तु) निश्चित हो जाते हैं ॥०.२७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.27.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="028" class="total">
                    <div>
                        <button id="moolamsmall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '028')">मूलम्</button>
                        <button id="padasmall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '028')">पदविभागः</button>
                        <button id="anvayasmall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '028')">अन्वयः</button>
                        <button id="pratismall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '028')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '028')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '028')">हिन्द्यर्थः</button>
                        <button id="audiosmall028" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '028')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अवश्यं भाविनो भावा भवन्ति महतामपि । नग्नत्वं नीलकण्ठस्य महाहिशयनं हरेः ॥०.२८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अवश्यं भाविनः भावाः भवन्ति महताम् अपि । नग्नत्वं नीलकण्ठस्य महा-अहि-शयनं हरेः ॥०.२८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>महताम् अपि भावाः अवश्यं भाविनः भवन्ति । नीलकण्ठस्य नग्नत्वं, हरेः महा-अहि-शयनं (चात्र प्रमाणम्) ॥०.२८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>महतामपि = महात्मानामपि ; भावाः = भवितव्यानि ; अवश्यं भाविनः = निश्चयेन भवमानाः घटनाः ; नीलकण्ठस्य = शिवस्य ; नग्नत्वं = दिगम्बरत्वम् ; हरेः = विष्णोः, महाहिशयनं = शेषशय्या ॥०.२८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये घटनाः नूनं भवमानाः भवन्ति, ते (न केवलं सामान्यानाम् अपि तु) महापुरुषाणामपि जीवने घटन्ते एव। (यद्यपि जगद्रक्षकौ, तथापि तयोः भाग्यमेवं भवति येन) शिवस्य तु दिगम्बरत्वं, विष्णोस्तु शेषे शय्या (परिकल्पिते स्तः) ॥०.२८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो बात अवश्य हाने वाली है, वह तो अवश्य ही होती है, उसको तो कोई भी नहीं हटा सकता है। इसमें शिवजी का नग्न रहना और विष्णु का शेषनाग का शय्या पर सोना ही प्रमाण है । अर्थात् यद्यपि ये दोनों संसार के प्रभु हैं, तथापि इनके प्रारब्ध में यही बिडम्बना लिखी है ॥०.२८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.28.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="029" class="total">
                    <div>
                        <button id="moolamsmall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '029')">मूलम्</button>
                        <button id="padasmall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '029')">पदविभागः</button>
                        <button id="anvayasmall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '029')">अन्वयः</button>
                        <button id="pratismall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '029')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '029')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '029')">हिन्द्यर्थः</button>
                        <button id="audiosmall029" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '029')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यदभावि न तद् भावि भावि चेन्न तदन्यथा । इति चिन्ताविषघ्नोऽयमगदः किं न पीयते ॥०.२९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् अभावि न तद् भावि भावि चेद् न तद् अन्यथा । इति चिन्ता-विषघ्नः अयम् अगदः किं न पीयते ॥०.२९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् अभावि, न तद् भावि ; भावि चेद् तद् न अन्यथा इति चिन्ता-विषघ्नः अयम् अगदः किं न पीयते ॥०.२९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यत् = सुखादि ; अभावि = न भावि ; तत् न भावि = न भवितुं न शक्यते ; चेत् = यदि ; भावि = सुखदुःखादिकं भावि, तत् = भाविसुखादि ; न अन्यया = न दूरीकर्तुं शक्यम् ; इति = इत्ययं ; चिन्ता एव विषं, तद्-हन्ति इति चिन्ताविषघ्नः = चिन्ताविषापहारी ; अगदः = औषधं, किं न = कुतो न ; पीयते = सेव्यते ॥०.२९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यद्भावि, तत्तु विना प्रयत्नमपि भवति। यन्न भावि तत् प्रयत्न-सहस्रेणापि न सम्भवति। अतः अलं चिन्तया इति-- चिन्तानाम विषं हरन् विचार-औषधः जनैः किमर्थं न सेव्यते? अर्थात्- यद्भावि तद्भविष्यत्येव ; यच्च न भावि तन्न भविष्यत्येव, दैवाधीनमेव सर्वम् ; तत्र किं वृथा चिन्तया आयासेन च - इत्याशयः ॥०.२९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो बात नहीं होने वाली है, वह कभी नहीं होगी और जो होने वाली है, वह किसी प्रकार मिट नहीं सकती है इस विचाररूपी औषध को- जो कि सब चिन्ताओं को नाश करनेवाली है लोग क्यों नहीं पीते हैं? ॥०.२९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.29.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="030" class="total">
                    <div>
                        <button id="moolamsmall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '030')">मूलम्</button>
                        <button id="padasmall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '030')">पदविभागः</button>
                        <button id="anvayasmall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '030')">अन्वयः</button>
                        <button id="pratismall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '030')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '030')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '030')">हिन्द्यर्थः</button>
                        <button id="audiosmall030" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '030')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न दैवमपि सञ्चिन्त्य त्यजेदुद्योगमात्मनः । अनुद्योगेन तैलानि तिलेभ्यो नाप्तुमर्हति ॥०.३०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न दैवम् अपि सञ्चिन्त्य त्यजेद् उद्योगम् आत्मनः । अनुद्योगेन तैलानि तिलेभ्यः न आप्तुम् अर्हति ॥०.३०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दैवम् अपि सञ्चिन्त्य आत्मनः उद्योगं न त्यजेद् । (अत्रोदाहरणम्) अनुद्योगेन तिलेभ्यः तैलानि आप्तुं न अर्हति ॥०.३०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>देवम् अपि = दैवम् अस्ति इति, भाग्यम् (तदेव सर्वकार्यसाधकमिति) ; सञ्चिन्त्य = विभाव्य, चिन्तयित्वा ; आत्मनः = आत्माधीनम् ; उद्योगं = पुरुषार्थं ; (यत् स्वयं कर्तुं शक्यते तत्) न त्यजेत् ; (यतः) अनुद्योगेन = उद्योगविकलेन, आलस्येन वा ; (गृहकोणस्थितेभ्योऽपि तैलपूर्णेभ्योऽपि) तिलेभ्यः ; तैलानि ; आप्तुं = प्राप्तुं ; न अर्हति = योग्यो न भवति ॥०.३०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>भाग्यमस्ति इति चिन्तयित्वा स्वस्य हस्ते यदस्ति, तत् प्रयत्नं न त्यक्तव्यम् । प्रयत्नं विना तिलेषु सत्सु अपि तैलं न प्राप्नोति। (उद्योगाऽभावे हि गृहकोणस्थतिलेभ्योऽपि तैललाभो न भवति, किं पुनरभ्युदयसम्पत्तिसुखादिलाभः । एवञ्च दैवस्य आशां विहाय, पुरुषेण उद्योगोऽवश्यं विधेय इत्यर्थः) ॥०.३०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बुद्धिमान् मनुष्य को अपना उद्योग कभी नहीं छोड़ना चाहिए । क्योंकि विना उद्योग के किये तो तिल से तेल भी नहीं निकल सकता है ॥०.३०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.30.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="031" class="total">
                    <div>
                        <button id="moolamsmall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '031')">मूलम्</button>
                        <button id="padasmall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '031')">पदविभागः</button>
                        <button id="anvayasmall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '031')">अन्वयः</button>
                        <button id="pratismall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '031')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '031')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '031')">हिन्द्यर्थः</button>
                        <button id="audiosmall031" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '031')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उद्योगिनं पुरुषसिंहमुपैति लक्ष्मीः दैवेन देयमिति कापुरुषा वदन्ति । दैवं निहत्य कुरु पौरुषमात्मशक्त्या यत्ने कृते यदि न सिध्यति कोऽत्र दोषः ॥०.३१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उद्योगिनं पुरुष-सिंहम् उपैति लक्ष्मीः दैवेन देयम् इति कापुरुषाः वदन्ति । दैवं निहत्य कुरु पौरुषम् आत्म-शक्त्या यत्ने कृते यदि न सिध्यति कः अत्र दोषः ॥०.३१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उद्योगिनं पुरुष-सिंहम् लक्ष्मीः उपैति । कापुरुषाः ‘दैवेन देयम्’ इति वदन्ति । दैवं निहत्य, आत्म-शक्त्या पौरुषं कुरु । यत्ने कृते यदि न सिध्यति कः अत्र दोषः ॥०.३१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उद्योगिनम् = प्रयत्नशीलं ; पुरुषसिंहं = (~पुरुषः सिंह इव, पुरुषसिंहस्तं) सिंहवद् विक्रमशालिनं पुरुषश्रेष्ठम् ; लक्ष्मीः = धनं, सम्पत्तिः, सफलता, जयः ; स्वयमेव = स्वत एव ; उपैति = आगच्छति ; कापुरुषाः = उद्योगशक्तिशून्याः, भयशीलाः, कातरा एव, न शूराः ; ‘दैवेन देयम्’ इति = ‘भाग्येन एव दीयते (सर्वं सुखं दुःखं वे’ति) ; वदन्ति = कथयन्ति ; दैवम् = भाग्यं, अदृष्टं ; निहत्य = तन्मुखप्रेक्षितां विहाय, तदुपेक्ष्येति वा ; पौरुषम् = उद्योगं ; कुरु ; यत्ने = उद्योगे ; कृते सति ; यदि = चेत् ; कार्यं न सिध्यति (तर्हि अस्मिन्विषये) ; कः = को वा पुंसः ; दोषः = अपकर्षकारकं ; (नैव कश्चिद्दोष इत्यर्थः) । यद्वा-अत्र = यत्ने एव कः = कोऽपि दोषः = त्रुटिरस्तीति विभाव्यम्, अन्यथा बलवति यत्ने सति अवश्यमेव कार्यं भवत्येवेत्यवधेयमित्यन्ये व्याचक्षते ॥०.३१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः प्रयत्नशीलः सिंहवत् विक्रमशाली पुरुषः, सः सफलत्वं प्राप्नोति। भयशीलिनः तु ‘भाग्येनैव दीयते’ इति ब्रुवन्ति। अतः भाग्यमुपेक्ष्य, प्रयत्नं कुरु। यदि यत्नं कृत्वा अपि फलं न प्राप्यते, तर्हि न कोऽपि दोषस्तत्र। अथवा, यदि न प्राप्यते फलं, तर्हि ‘यत्ने को दोषः?’ इति चिन्तनीयम् ॥०.३१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी-उद्योगशील पुरुषसिंह के पास स्वयं ही लक्ष्मी आती है । 'धन भाग्य से ही मिलता है' यह तो कायर पुरुष ही कहा करते हैं । इसलिये मनुष्य को भाग्य का भरोसा छोड़कर अपनी शक्ति के अनुसार उद्योग करना चाहिये, यदि उद्योग करने पर भी कार्य की सिद्धि न होने तो इस उद्योग में क्या दोष है। इसका विचार करो । अर्थात्- देखो कि तुमारे इस उद्योग में क्या त्रुटि है, न कि उद्योग को ही छोड दो ॥०.३१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.31.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="032" class="total">
                    <div>
                        <button id="moolamsmall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '032')">मूलम्</button>
                        <button id="padasmall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '032')">पदविभागः</button>
                        <button id="anvayasmall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '032')">अन्वयः</button>
                        <button id="pratismall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '032')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '032')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '032')">हिन्द्यर्थः</button>
                        <button id="audiosmall032" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '032')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यथा ह्येकेन चक्रेण न रथस्य गतिर्भवेत् । तथा पुरुषकारेण विना दैवं न सिद्ध्यति ॥०.३२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यथा हि एकेन चक्रेण न रथस्य गतिः भवेत् । तथा पुरुषकारेण विना दैवं न सिद्ध्यति ॥०.३२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यथा हि एकेन चक्रेण रथस्य गतिः न भवेत् । तथा पुरुषकारेण विना दैवं न सिद्ध्यति ॥०.३२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यथा = येन प्रकारेण ; एकेन ; चक्रेण = रथाङ्गेन ; रथस्य ; गतिः = अग्रे चलनं ; न भवेत् = न भवति ; एवं = तथैव ; पुरुषकारेण = मानवप्रयत्नेन, सहायभूतेन पौरुषेण ; विना ; दैवम् = केवलम् अदृष्टं ; न सिध्यति = नैव फलतीत्यर्थः ॥०.३२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा रथः द्वयोः चक्रयोः चलति, एकेन चक्रेण नाग्रे गन्तुं पारयति, तथैव मनुष्यस्य प्रयत्नेन विना केवलं भाग्येन कार्यं न सिद्ध्यति ॥०.३२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जैसे एक चक्र से रथ नहीं चल सकता है, उसी प्रकार उद्योग के विना केवल भाग्य से ही सिद्धि नहीं हो सकती है ॥०.३२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.32.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="033" class="total">
                    <div>
                        <button id="moolamsmall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '033')">मूलम्</button>
                        <button id="padasmall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '033')">पदविभागः</button>
                        <button id="anvayasmall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '033')">अन्वयः</button>
                        <button id="pratismall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '033')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '033')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '033')">हिन्द्यर्थः</button>
                        <button id="audiosmall033" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '033')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पूर्वजन्मकृतं कर्म तद् दैवमिति कथ्यते । तस्मात् पुरुषकारेण यत्नं कुर्यादतन्द्रितः ॥०.३३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पूर्व-जन्म-कृतं कर्म तद् दैवम् इति कथ्यते । तस्मात् पुरुषकारेण यत्नं कुर्याद् अतन्द्रितः ॥०.३३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पूर्व-जन्म-कृतं कर्म तद् दैवम् इति कथ्यते । तस्मात् पुरुषकारेण अतन्द्रितः यत्नं कुर्याद् ॥०.३३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पूर्वजन्मनि = गते जन्मकाले ; कृतं यत्कर्म = आचरितानि कार्याणि ; तत् = तदेव ; दैवमिति कथ्यते = ‘दैवपदवाच्यम्, इतोऽन्यद्दैवं नाम किञ्चिदपि नास्ति ; तस्मात् = पुरुषकारेण विना दैवस्य सिद्धेरभावात् ; पुरुषकारेण = पुरुषार्थमास्थाय, प्रयत्नं कृत्वा ; अतन्द्रितः = आलस्यवर्जितः, सावधानः सन् ; पुमान् = पुरुषः, मनुष्यः ; यत्नं कुर्यात् = उद्यमं कुर्यात् ॥०.३३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गते जन्मनि यद्यदाचरितं कर्म वर्तते, तदेव अस्मिन् जन्मनि भाग्यरूपेण परिणमति। अतः (पूर्वकाले वा भवतु) प्रयत्नेनैव भाग्यस्यापि कल्पितत्वात्, सावधानो भूत्वा प्रयत्नः अवश्यं करणीयः ॥०.३३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>पूर्वजन्म में किया हुआ कर्म ही दूसरे जन्म में भाग्य कहा जाता है । इसलिये मनुष्य को पुरुषार्थं (उद्योग, कर्म) करना ही चाहिए ॥०.३३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.33.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="034" class="total">
                    <div>
                        <button id="moolamsmall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '034')">मूलम्</button>
                        <button id="padasmall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '034')">पदविभागः</button>
                        <button id="anvayasmall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '034')">अन्वयः</button>
                        <button id="pratismall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '034')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '034')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '034')">हिन्द्यर्थः</button>
                        <button id="audiosmall034" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '034')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यथा मृत्पिण्डतः कर्ता कुरुते यद् यदिच्छति । एवमात्मकृतं कर्म मानवः प्रतिपद्यते ॥०.३४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यथा मृत्पिण्डतः कर्ता कुरुते यद् यद् इच्छति । एवम् आत्मकृतं कर्म मानवः प्रतिपद्यते ॥०.३४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यथा मृत्पिण्डतः कर्ता यद् यद् इच्छति (तत्तत्) कुरुते । एवम् मानवः आत्मकृतं कर्म प्रतिपद्यते ॥०.३४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यथा मृत्पिण्डतः = मृत्तिकासंघेन ; कर्ता = (अत्र) कुलालः ; यद्यत् = शरावोदञ्चन-घटादिकम् ; इच्छति = कर्तुं वाञ्छति ; तत्तत्-कुरुते = स्वप्रयत्नेन सम्पादयति ; एवं = पूर्वोपपादितया रीत्या ; मानवः = कर्ता ; आत्मकृतमेव = स्वयमाचरितम् ; कर्म = कर्मफलम् ; धटादिकञ्च ; प्रतिपद्यते = लभते, प्राप्नोति ॥०.३४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा कुलालः मृत्तिकामुपयुज्य यद्वस्तु आवश्यकं तत् निर्माति, (कार्येषु उपयुनक्ति च) तथा मनुष्योऽपि स्वयमाचरितस्य कर्मणः एव फलं भुनक्ति ॥०.३४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जैसे कुम्हार मिट्टी के पिण्ड से जो जो वस्तु चाहता है, अपनी इच्छा के अनुसार बनाता है, उसी प्रकार मनुष्य अपने किये हुए कर्म के अनुसार ही फल पाता है ॥०.३४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.34.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="035" class="total">
                    <div>
                        <button id="moolamsmall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '035')">मूलम्</button>
                        <button id="padasmall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '035')">पदविभागः</button>
                        <button id="anvayasmall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '035')">अन्वयः</button>
                        <button id="pratismall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '035')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '035')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '035')">हिन्द्यर्थः</button>
                        <button id="audiosmall035" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '035')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>काकतालीयवत् प्राप्तं दृष्ट्वापि निधिमग्रतः । न स्वयं दैवमादत्ते पुरुषार्थमपेक्षते ॥०.३५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>काक-तालीय-वत् प्राप्तं दृष्ट्वा अपि निधिम् अग्रतः । न स्वयं दैवम् आदत्ते पुरुषार्थम् अपेक्षते ॥०.३५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>काक-तालीय-वत् प्राप्तं निधिम् अग्रतः दृष्ट्वा अपि दैवं स्वयं न आदत्ते । पुरुषार्थम् अपेक्षते ॥०.३५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>काकस्य आगमनमिव, तालस्य पतनमिव-काकतालं, काकतालमिव ~ काकतालीयं = सहसा उपनतम् ; तद्वत् = काकतालीयवत् = काकागमनेन तालपतनवद्, कस्मात्, दैववशात् ; प्राप्तं = लब्धं, निधिम् = शेवधिम् = (खजाने को) ; अग्रतः = पुरतः, दृष्ट्वापि ; दैवं = भाग्यं ; स्वयम् = स्वतः ; न आदत्ते = न गृह्णाति ; किन्तु-- आदाने-पुरुषार्थे = हस्तचालनादिकं पुरुषव्यापारम् ; अपेक्षते = आश्रयते एव ; सहायमपेक्षते एव ॥०.३५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>काकतालीयमिव (कस्यचित् मनुष्यस्य) पुरतः पतितं धनमपि भाग्येन न गृह्णाति । तदर्थमपि प्रयत्न अपेक्ष्यते ॥०.३५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>काकतालीय न्याय से (अर्थात् अकस्मात्, भाग्य से) सामने प्राप्त हुए धन को भी उठाकर रखने में पुरुषार्थ की जरूरत रहती ही है ॥०.३५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.35.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="036" class="total">
                    <div>
                        <button id="moolamsmall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '036')">मूलम्</button>
                        <button id="padasmall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '036')">पदविभागः</button>
                        <button id="anvayasmall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '036')">अन्वयः</button>
                        <button id="pratismall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '036')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '036')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '036')">हिन्द्यर्थः</button>
                        <button id="audiosmall036" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '036')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उद्यमेन हि सिध्यन्ति कार्याणि न मनोरथैः । न हि सुप्तस्य सिंहस्य प्रविशन्ति मुखे मृगाः ॥०.३६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उद्यमेन हि सिध्यन्ति कार्याणि न मनोरथैः । न हि सुप्तस्य सिंहस्य प्रविशन्ति मुखे मृगाः ॥०.३६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उद्यमेन हि कार्याणि सिध्यन्ति। मनोरथैः न। सुप्तस्य सिंहस्य मुखे मृगाः न हि प्रविशन्ति ॥०.३६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उद्यमेन = उद्योगेन, प्रयत्नेन ; सिध्यन्ति = सफलानि भवन्ति ; कार्याणि = उद्दिष्टानि कर्माणि ; मनोरथैः = कामनाभिः ; हि = यतः ; सुप्तस्य = शयितस्य (बुभुक्षितस्यापि) ; सिंहस्य ; मुखे= वदने ; मृगाः = पशवः ; न प्रविशन्ति = आहारो न भवन्ति ; ॥०.३६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>आकाङ्क्षितैः, 'ममेदं भवतु' 'सिध्यतु ममेद'मित्यादि-मनोरथमात्रेण कर्माणि न सम्पद्यन्ते । सिंहः यदा शेते, तदा (स क्षुदा पीडित इति कृत्वा स्वयमेवागत्य) जन्तवः तस्य मुखान्ते (अन्नं भूत्वा) न प्रविशन्ति ।किन्तु तदर्थं सिंहोऽपि यत्नं करोति । एवमेव सर्वैरपि यत्नो विधेयः ॥०.३६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योंकि- कार्य की सिद्धि उद्योग से ही होती है, केवल इच्छामात्र से नहीं । क्योंकि सोये हुये भूखे सिंह के मुख में मृग स्वयं नहीं चले जाते हैं, किन्तु उसको भी शिकार पकड़ने के लिए यत्न करना ही होता है ॥०.३६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.36.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="037" class="total">
                    <div>
                        <button id="moolamsmall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '037')">मूलम्</button>
                        <button id="padasmall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '037')">पदविभागः</button>
                        <button id="anvayasmall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '037')">अन्वयः</button>
                        <button id="pratismall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '037')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '037')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '037')">हिन्द्यर्थः</button>
                        <button id="audiosmall037" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '037')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मातापितृकृताभ्यासो गुणितामेति बालकः । न गर्भच्युतिमात्रेण पुत्रो भवति पण्डितः ॥०.३७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>माता-पितृ-कृत-अभ्यासः गुणिताम् एति बालकः । न गर्भ-च्युति-मात्रेण पुत्रः भवति पण्डितः ॥०.३७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>माता-पितृ-कृत-अभ्यासः बालकः गुणिताम् एति । गर्भ-च्युति-मात्रेण पुत्रः पण्डितः न भवति ॥०.३७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मात्रा च पित्रा च कृतः, कारितः अभ्यासो येनासौ ~ मातापितृ-कृताऽभ्यासः = मातापितृभ्यां कारिताभ्यासः ; बालकः = पुत्रः ; गुणितां = विद्वत्त्वं, गुणवत्त्वञ्च ; एति = प्राप्नोति, लभते ; केवलं गर्भ-च्युति-मात्रेण = जन्मग्रहण-मात्रेणैव ; पुत्रः = बालकः ; पण्डितो न भवति ॥०.३७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>माता पिता च यं बालकं (सद्गुणानां) अभ्यासं कारयन्ति, स एव गुणी भवति। जन्मप्राप्तिमात्रेण न कोऽपि पुत्रः पण्डितः भवति। (अतः शिक्षणमावश्यकम्।) ॥०.३७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>माता पिता के अभ्यास कराने से हरी बालक गुणी होता है । जन्मते ही कोई पण्डित नहीं हो जाता है। अतः बालका को उत्तम शिक्षा देनी चाहिए ॥०.३७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.37.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="038" class="total">
                    <div>
                        <button id="moolamsmall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '038')">मूलम्</button>
                        <button id="padasmall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '038')">पदविभागः</button>
                        <button id="anvayasmall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '038')">अन्वयः</button>
                        <button id="pratismall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '038')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '038')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '038')">हिन्द्यर्थः</button>
                        <button id="audiosmall038" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '038')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>माता शत्रुः पिता वैरी येन बालो न पाठितः । न शोभते सभामध्ये हंसमध्ये बको यथा ॥०.३८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>माता शत्रुः पिता वैरी येन बालः न पाठितः । न शोभते सभा-मध्ये हंस-मध्ये बकः यथा ॥०.३८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>माता शत्रुः पिता वैरी येन बालः न पाठितः । सभा-मध्ये (सः) हंस-मध्ये यथा बकः (तथा) न शोभते ॥०.३८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>माता = जननी ; शत्रुः = अरिः ; पिता = जनकः ; वैरी = रिपुः ; येन = पित्रा ; बालः = पुत्रः ; न पाठितः = अध्ययनं न कारितः, शिक्षा न प्रापयितः ; सभामध्ये = पण्डितानां समवाये, विद्वत्समाजे ; हंसमध्ये बक इव ; न शोभते = न प्रतिष्ठां लभते। 'याभ्या'मिति पाठान्तरम् ॥०.३८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यं बालं माता पिता च न ज्ञानं प्रदापयन्ति, तौ (तस्य) शत्रू इव भवतः । सः विदुषां पुरतः न स्थातुं शक्नोति । हंसानां समूहे बक इव स भवति। यौ पितरौ स्वपुत्रं न शिक्षयन्ति तौ अशिक्षिताय स्वपुत्राय शत्रू भवतः, हंसानां समूहे बकः यथा न प्रकाशते तथैवायमशिक्षितः बालोपि विदुषां समूहे न शोभते, तस्मात् पितृभ्यामवश्यमपत्यानि शिक्षणीयानीति अस्य भावः ॥०.३८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>वे पिता माता शत्रु हैं, जिन्होंने अपने बालक पुत्र को नहीं पढ़ाया । क्यों कि हंसो के बीच में बगुले की तरह वह मूर्ख बालक भी विद्वानों के बीच में कभी शोभा नहीं देता है ॥०.३८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.38.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="039" class="total">
                    <div>
                        <button id="moolamsmall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '039')">मूलम्</button>
                        <button id="padasmall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '039')">पदविभागः</button>
                        <button id="anvayasmall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '039')">अन्वयः</button>
                        <button id="pratismall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '039')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '039')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '039')">हिन्द्यर्थः</button>
                        <button id="audiosmall039" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '039')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>रूपयौवनसम्पन्ना विशालकुलसम्भवाः । विद्याहीना न शोभन्ते निर्गन्धा इव किंशुकाः ॥०.३९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रूप-यौवन-सम्पन्नाः विशाल-कुल-सम्भवाः । विद्याहीनाः न शोभन्ते निर्गन्धाः इव किंशुकाः ॥०.३९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>रूप-यौवन-सम्पन्नाः विशाल-कुल-सम्भवाः (अपि) विद्याहीनाः निर्गन्धाः किंशुकाः इव न शोभन्ते ॥०.३९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>रूप-यौवन-सम्पन्नाः ~ रूपेण = सौन्दर्येण, शरीरकान्त्या च ; यौवनेन = युवत्वकृतेन वपुः ; सम्पन्नाः = शोभिताः अपि ; किञ्च--विशालकुलसम्भवाः = महाकुलप्रसूता अपि ; विद्याहीनाः = मूर्खाः ; निर्गन्धाः = (सुरूपा अपि) गन्धशून्याः, किंशुकाः = पलाशकुसुमानीव, न शोभन्ते = लोके न विराजन्ते ॥०.३९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सुन्दराः, युवकाः, उन्नत-कुले जाताः अपि नराः ज्ञानेन विना, गन्धहीन-किंशुक-पुष्पाणीव न शोभन्ते ॥०.३९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अच्छे कुल में उत्पन्न, सुन्दर, युवा मनुष्य भी विद्याहीन होने से निर्गन्ध पलाश (ढाक) के फूल के समान शोभा नहीं पाते हैं ॥०.३९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.39.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="040" class="total">
                    <div>
                        <button id="moolamsmall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '040')">मूलम्</button>
                        <button id="padasmall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '040')">पदविभागः</button>
                        <button id="anvayasmall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '040')">अन्वयः</button>
                        <button id="pratismall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '040')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '040')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '040')">हिन्द्यर्थः</button>
                        <button id="audiosmall040" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '040')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मूर्खोऽपि शोभते तावत् सभायां वस्त्रवेष्ठितः । तावच्च शोभते मूर्खो यावत्किञ्चिन्न भाषते ॥०.४०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मूर्खः अपि शोभते तावत् सभायां वस्त्रवेष्ठितः । तावत् च शोभते मूर्खः यावत्किञ्चिन्न भाषते ॥०.४०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मूर्खः अपि सभायां वस्त्रवेष्ठितः तावत् शोभते । मूर्खः यावत् किञ्चित् न भाषते तावत् च शोभते ॥०.४०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मूर्खः = मूढबुद्धिः, अल्पधीः, अर्धज्ञानी ; शोभते = साधु दृश्यते ; सभायां = विद्वद्गोष्ठ्याम् ; तावत् = निश्चयेन ; वस्त्रवेष्टितः = महार्ह-पट्ट-वस्त्रावृतः, (दुशाला ओढे हुए) ; भाषते = वदति ॥०.४०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मूढः पुरुषः अपि (सुसज्जीभूय सुन्दर)वस्त्राणि धृत्वा सभायां निश्चयेन शोभनो दृश्यते । यावत्कालं सः किमपि न वदति, तावत् पर्यन्तं सः (पण्डित इव) आदरं प्राप्नोति ॥०.४०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>विद्वानों की सभा में अच्छा कपडा पहन कर कदाचित्मूर्ख भी शोभता है, परन्तु वह तभी तक शोभता है, जब तक वह कुछ बोलता नहीं है । अर्थात् उसके बोलते ही उसकी योग्यता (मूर्खता) मालूम हो जाती है ॥०.४०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.40.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="041" class="total">
                    <div>
                        <button id="moolamsmall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '041')">मूलम्</button>
                        <button id="padasmall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '041')">पदविभागः</button>
                        <button id="anvayasmall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '041')">अन्वयः</button>
                        <button id="pratismall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '041')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '041')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '041')">हिन्द्यर्थः</button>
                        <button id="audiosmall041" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '041')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>काचः काञ्चनसंसर्गाद् धत्ते मारकतीर्द्युतीः । तथा सत्सन्निधानेन मूर्खो याति प्रवीणताम् ॥०.४१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>काचः काञ्चन-संसर्गाद् धत्ते मारकतीः द्युतीः । तथा सत्सन्निधानेन मूर्खः याति प्रवीणताम् ॥०.४१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>काचः काञ्चन-संसर्गाद् मारकतीः द्युतीः धत्ते । तथा मूर्खः सत्सन्निधानेन प्रवीणताम् याति ॥०.४१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>काचः = मृत्तिकाभेदः ; काञ्चनम् = सुवर्णम् ; संसर्गाद् = सम्पर्कात् ; मारकतीं = मरकतमणि-सम्बन्धिनीं, तत्तुल्यतामिति यावत् [मरकतः=पन्ना] ; द्युतीः = प्रकाशान् ; सत्सन्निधानेन = सतां साङ्गत्येन ; प्रवीणतां = कुशलतां, पाण्डित्यञ्च ; याति = लभते ॥०.४१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>काञ्चनस्य सम्पर्केण काचः अपि मरकतमणिरिव कान्तिं प्राप्नोति। तथैव बुद्धिहीनोऽपि सज्जनानां सङ्गतौ कौशल्यं लभते ॥०.४१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि-जैसे काच भी सुवर्ण के सम्बन्ध से मरकत मणि (पन्ना) की सी शोभा को पाता है, इसी प्रकार सज्जनों के संसर्ग से मूर्ख भी चतुर हो जाता है ॥०.४१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.41.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="042" class="total">
                    <div>
                        <button id="moolamsmall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '042')">मूलम्</button>
                        <button id="padasmall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '042')">पदविभागः</button>
                        <button id="anvayasmall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '042')">अन्वयः</button>
                        <button id="pratismall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '042')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '042')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '042')">हिन्द्यर्थः</button>
                        <button id="audiosmall042" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '042')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>हीयते हि मतिस्तात हीनैः सह समागमात् । समैश्च समतामेति विशिष्टैश्च विशिष्टताम् ॥०.४२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>हीयते हि मतिः तात हीनैः सह समागमात् । समैः च समताम् एति विशिष्टैः च विशिष्टताम् ॥०.४२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>तात, हीनैः सह समागमात् मतिः हीयते हि । समैः च समताम् एति । विशिष्टैः च विशिष्टताम् ॥०.४२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>‘ताते’ति सम्बोधनम् ; तात = हे वत्स! ; हीनैः = अधमैः, मूर्खैः ; समागमात् = मित्रत्वात्, साङ्गत्यात् ; मतिः = बुद्धिः ; हीयते = अल्पतामेति, क्षयमेति ; समैः = स्वात्मतुल्यैः, ये समानबुद्धयः भवन्ति तैः सह ; समतां = समान-बौद्धिक-स्थितिं ; विशिष्टैः = स्वस्माद् अधिकैः, ये विलक्षण-बुद्धयः भवन्ति तैः सह ; विशिष्टता= वैदुष्यं, महत्त्वञ्च ॥०.४२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे वत्स, अल्पबुद्धिभिः सहवासेन धीशक्तिः क्षीयते। स्वतुल्यधीभिः सह साङ्गत्येन समा धीस्थितिः भवति। स्वस्मात् विशेषेण अधिकमतिभिः सह सख्यतया नरः स्वयमपि महान् भवति ॥०.४२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>किसी ने कहा भी है कि ‘हे तात, नीचों के सङ्ग-साथ से मनुष्य की बुद्धि छोटी हो जाती है, और अपने बराबर बुद्धिवालों के साथ से बुद्धि साधारण रहती है, और अपने से बद्धि लोगों के सङ्ग से मनुष्य की बुद्धि उत्कृष्ट (उन्नत) होती है ॥०.४२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.42.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="043" class="total">
                    <div>
                        <button id="moolamsmall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '043')">मूलम्</button>
                        <button id="padasmall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '043')">पदविभागः</button>
                        <button id="anvayasmall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '043')">अन्वयः</button>
                        <button id="pratismall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '043')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '043')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '043')">हिन्द्यर्थः</button>
                        <button id="audiosmall043" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '043')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>नाद्रव्ये निहिता काचित् क्रिया फलवती भवेत् । न व्यापारशतेनापि शुकवत् पाठ्यते बकः ॥०.४३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न अद्रव्ये निहिता काचित् क्रिया फलवती भवेत् । न व्यापार-शतेन अपि शुकवत् पाठ्यते बकः ॥०.४३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अद्रव्ये निहिता काचित् क्रिया फलवती न भवेत् । व्यापार-शतेन अपि बकः शुकवत् न पाठ्यते ॥०.४३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>देव = हे राजन् ; अद्रव्ये = अयोग्ये, अपात्रे च ; निहिता = योजिता, स्थापिता च ; क्रिया = संस्कारः, शिक्षा च = शिक्षणं ; फलवती = सफला ; व्यापार-शतेनापि = उपाय-शतेनापि ; बकः = पक्षिविशेषः ; न खलु ; पाठ्यते=पाठयितुं शक्यते ॥०.४३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अपात्रं शिक्षयित्वा संस्कारयितुं कृतानि प्रयतनानि न कदापि सफलानि भवन्ति। बकः शुकवत् भणितुं न पारयति। अतः तं शिक्षयितुं प्रयत्नः व्यर्थो भवति ॥०.४३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अयोग्य अपात्र में कोई भी सुधार सफल नहीं होता है । अनेक उपाय करने पर भी कोई भी बगुले को शुक (सुग्गे) की तरह कभी नहीं पढा सकता है ॥०.४३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.43.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="044" class="total">
                    <div>
                        <button id="moolamsmall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '044')">मूलम्</button>
                        <button id="padasmall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '044')">पदविभागः</button>
                        <button id="anvayasmall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '044')">अन्वयः</button>
                        <button id="pratismall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '044')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '044')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '044')">हिन्द्यर्थः</button>
                        <button id="audiosmall044" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '044')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अस्मिंस्तु निर्गुणं गोत्रे नापत्यमुपजायते । आकरे पद्मरागाणां जन्म काचमणेः कुतः ॥०.४४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अस्मिन् तु निर्गुणं गोत्रे न अपत्यम् उपजायते । आकरे पद्म-राणाणां जन्म काचमणेः कुतः ॥०.४४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अस्मिन् गोत्रे तु निर्गुणम् अपत्यम् न उपजायते । पद्म-रागाणाम् आकरे काचमणेः जन्म कुतः ॥०.४४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अस्मिन् = भवतां प्रसिद्धे ; गोत्रे = वंशे, (अत्र) राजकुले ; निर्गुणं = गुणशून्यम् ; अपत्यं = सन्तानं, पुत्र इति यावत्, तोकं ; न उपजायते = न उत्पद्यते ; यतः ; पद्मरागाणां = तन्नामविशिष्ट-मणयः तेषां ; आकरे = खनौ ; काचमणेः = काचस्य ; जन्म = उत्पत्तिः ; कुतः = कस्माद् हेतोः भवति? नैव संभवतीत्यर्थः ॥०.४४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(सद्गुणविशिष्टे) अस्मिन् राजकुले गुणशून्यं सन्तानं न कदापि सञ्जायते। (अमूल्ये) पद्मरागमणीनाम् उत्पत्तिस्थाने (अयोग्यः) काचमणिः कथमुत्पद्यते ॥०.४४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>परन्तु इस (आपके) वंश में मूर्ख सन्तति हो ही नहीं सकती है । जैसे पद्मरागमणि (लाल' 'चुन्नी') की खान से कभी काच की उत्पत्ति नहीं होती है ॥०.४४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.44.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="045" class="total">
                    <div>
                        <button id="moolamsmall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '045')">मूलम्</button>
                        <button id="padasmall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '045')">पदविभागः</button>
                        <button id="anvayasmall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '045')">अन्वयः</button>
                        <button id="pratismall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '045')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '045')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '045')">हिन्द्यर्थः</button>
                        <button id="audiosmall045" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '045')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>कीटोऽपि सुमनः सङ्गादारोहति सतां शिरः । अश्मापि याति देवत्वं महद्भिः सुप्रतिष्ठितः ॥०.४५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कीटः अपि सुमनः सङ्गाद् आरोहति सतां शिरः । अश्मा अपि याति देवत्वं महद्भिः सुप्रतिष्ठितः ॥०.४५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कीटः अपि सुमनः सङ्गाद् सतां शिरः आरोहति । अश्मा अपि महद्भिः सुप्रतिष्ठितः (भूत्वा) देवत्वं याति ॥०.४५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कीटः = भृङ्गादिः । पामरश्च । सुमनः सङ्गात् = पुष्पसम्बन्धात् । विद्वत्सङ्गाच्च । सतां = सज्जनानां, महताञ्च । शिरः = मस्तकमपि । आरोहति = तत्पूज्यो भवति । अश्मा = पाषाणः । महद्भिः = विद्वद्भिः, श्रेष्ठैश्च । सुप्रतिष्ठितः = स्थापितः ॥०.४५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अस्मिन् पद्ये अल्पवस्तूनां महद्वस्तुसाङ्गत्येन महत्त्वप्राप्तिः उक्ता।) कीटाः पुष्पाणां साङ्गत्येन सज्जनस्य शिरसि न्यस्यते। पाषाणश्च श्रेष्ठैः जनैः मन्दिरादिषु संस्थापितः, प्रतिष्ठितः सन् देवः भूत्वा पूज्यत्वं प्राप्नोति। (अत्र कीटस्य, पाषाणस्य च तुलना पामरजनेन, पुष्पानां, प्रतिष्ठया देवत्वप्राप्तेः च पण्डितजनेन तुलना कृता।) ॥०.४५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>पुष्पों के साथ होने से कीडा भी बड़े लोगों के शिर पर चढ़ जाता है । और बड़े लोगों से आदर प्रतिष्ठा पाकर पत्थर भी देवता बन जाता है ॥०.४५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.45.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="046" class="total">
                    <div>
                        <button id="moolamsmall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '046')">मूलम्</button>
                        <button id="padasmall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '046')">पदविभागः</button>
                        <button id="anvayasmall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '046')">अन्वयः</button>
                        <button id="pratismall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '046')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '046')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '046')">हिन्द्यर्थः</button>
                        <button id="audiosmall046" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '046')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यथोदयगिरेर्द्रव्यं सन्निकर्षेण दीप्यते । तथा सत्सन्निधानेन हीनवर्णोऽपि दीप्यते ॥०.४६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>🌸</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यथा उदयगिरेः द्रव्यं सन्निकर्षेण दीप्यते । तथा सत्सन्निधानेन हीनवर्णः अपि दीप्यते ॥०.४६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उदयगिरेः = उदयपर्वतस्य ; द्रव्यं = पाषाणवृक्षादिकं वस्तुजातमपि ; सन्निकर्षेण = सामीप्यं, सम्पर्कः ; दीप्यते = सूर्यसम्पर्कात् प्रकाशते, शोभते ; हीनवर्णः = बुद्धिविषये नीचः, मूढः ; दीप्तिरहितोऽपि = प्रज्ञादिगुणैः विहीनोऽपि; दीप्यते = संवर्ध्यते ॥०.४६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा सूर्योदयानन्तरम् उदयाचलसमीपे स्थितं सर्वं वस्तु सूर्यप्रकाशसम्पर्केण शोभते, तथैव मूर्खजनः सतां सन्निधौ विवेकशीली भवति। तस्य बुद्धिविकासो जायते ॥०.४६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- जैसे उदयाचल की सभी वस्तु सूर्य के समीप होने से चमकने लगती हैं, उसी तरह सज्जनों के संसर्ग से मूर्ख भी विद्वानों जाते हैं ॥०.४६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.46.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="047" class="total">
                    <div>
                        <button id="moolamsmall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '047')">मूलम्</button>
                        <button id="padasmall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '047')">पदविभागः</button>
                        <button id="anvayasmall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '047')">अन्वयः</button>
                        <button id="pratismall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '047')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '047')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '047')">हिन्द्यर्थः</button>
                        <button id="audiosmall047" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '047')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>गुणा गुणज्ञेषु गुणा भवन्ति ते निर्गुणं प्राप्य भवन्ति दोषाः । आस्वाद्यतोयाः प्रवहन्ति नद्यः समुद्रमासाद्य भवन्त्यपेयाः ॥०.४७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गुणाः गुणज्ञेषु गुणाः भवन्ति ते निर्गुणं प्राप्य भवन्ति दोषाः । आस्वाद्य-तोयाः प्रवहन्ति नद्यः समुद्रम् आसाद्य भवन्ति अपेयाः ॥०.४७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुणाः गुणज्ञेषु गुणाः भवन्ति। ते निर्गुणं प्राप्य दोषाः भवन्ति । नद्यः आस्वाद्य-तोयाः प्रवहन्ति । समुद्रम् आसाद्य अपेयाः भवन्ति ॥०.४७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गुणा इति । गुणाः = दयादाक्षिण्य-सत्कुल-प्रसूतत्वादयः ; गुणज्ञेषु = गुणि-जनसमवधाने, ये गुणं जानन्ति, तेषु ; गुणा भवन्ति = गुणत्वं वहन्ति । ते = गुणाः । निर्गुणं = गुणशून्यम् ; दोषा भवन्ति ; आस्वाद्यं तोयं यासान्ताः ~ आस्वाद्य-तोयाः = सुपेयपानीयाः, मधुरजलाः ; प्रवहन्ति = प्रचरन्ति ; 'प्रभवन्ती'ति पाठेऽपि स एवाऽर्थः ; आसाद्य = प्राप्य ; अपेयाः = क्षारोदकाः ; एवञ्च त्वत्संनिधानेन (भवत्सङ्गेन) कुलीना मत्पुत्रा विद्वांसो भविष्यन्तीत्याशयः ॥०.४७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गुणज्ञा नाम ये गुणं जानन्ति, तेषु गुणाः गुणाः भवन्ति। गुणहीनं प्राप्य ते दोषा भवन्ति। अत्र सादृश्यम् नदीभिः। नद्यः यावत् प्रवहणशीलाः तावत् मधुरजलैः युक्ताः, पानयोग्याः भवन्ति। ताः प्रवाहान्ते समुद्रं यदा प्राप्नुवन्ति तदा पानाय अयोग्यजलयुक्ता सम्पद्यन्ते। [अत्र नदीजलानां सन्दर्भे, पानयोग्यत्वमधिकृत्य समुद्रः क्षारजलत्वात् निर्गुण इति अभिहितः। तावन्मात्रेण अन्यसल्लक्षणानां सन्दर्भे समुद्रस्य गुणहीनत्वं न कीर्तनीयम्।] ॥०.४७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योंकि गुणी मनुष्य के सम्बन्ध से गुणगुण ही रहते है, अर्थात् उनका आदर होता है । पर वे ही गुण-निर्गुण मनुष्य के सम्बन्ध से हो जाते हैं । देखो, नदियों का जल स्वभाव से ही स्वादिष्ट होता है, परन्तु वही जल जब समुद्र में जाकर पड़ता है, तो वह खारा हो जाता है ॥०.४७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-0.47.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="11" class="total">
                    <div>
                        <button id="moolamsmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '11')">मूलम्</button>
                        <button id="padasmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '11')">पदविभागः</button>
                        <button id="anvayasmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '11')">अन्वयः</button>
                        <button id="pratismall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '11')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '11')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '11')">हिन्द्यर्थः</button>
                        <button id="audiosmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '11')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>काव्यशास्त्रविनोदेन कालो गच्छति धीमताम् । व्यसनेन तु मूर्खाणां निद्रया कलहेन वा ॥१.१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>काव्य-शास्त्र-विनोदेन कालः गच्छति धीमताम् । व्यसनेन तु मूर्खाणां निद्रया कलहेन वा ॥१.१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धीमताम् कालः काव्य-शास्त्र-विनोदेन गच्छति । मूर्खाणां तु व्यसनेन, निद्रया कलहेन वा (गच्छति) ॥१.१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>काव्यशास्त्रविनोदेन ~ काव्यञ्च शास्त्रञ्च- काव्यशास्त्रे, ताभ्यां यो विनोदस्तेन ~ यद्वा- काव्यमेव शास्त्रन्तेन विनोद इति विग्रहः = काव्यशास्त्र-पर्यालोचनेनेत्यर्थः ; धीमतां च = विदुषां ; कालः = जीवितसमयः ; गच्छति = सुखं याति ; मूर्खाणान्तु व्यसनेन = स्त्रीद्यूत-मद्यपानादिव्यसनेन ; किञ्च- निद्रया = स्वापेन ; कलहेन = विवादेन च ; कालो गच्छति ॥१.१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विदुषां, विज्ञानां च जीवनसमयः सत्काव्यानां, शास्त्रविज्ञानग्रन्थानां च पठन-चर्चादिना याति। मूढजनानां कालस्तु आत्मनः अवनतिकारकैः दुर्व्यसनैः वा, शयनेन, परस्परं विवादैः वा याति ॥१.१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बुद्धिमान् मनुष्यों का समय काव्यों व शास्त्रों के विचार में ही बीतता है, परन्तु मूर्खों का समय तो व्यसन (बुरे काम) एवं निद्रा तया झगडों में ही बीतता है ॥१.१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.1.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
