                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>असाधना वित्तहीना बुद्धिमन्तः सुहृन्मताः । साधयन्त्याशु कार्याणि काककूर्ममृगाखुवत् ॥१.२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>असाधनाः वित्त-हीनाः बुद्धिमन्तः सुहृन्मताः । साधयन्ति आशु कार्याणि काक-कूर्म-मृग-आखु-वत् ॥१.२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>असाधनाः वित्त-हीनाः बुद्धिमन्तः सुहृन्मताः । काक-कूर्म-मृग-आखु-वत् आशु कार्याणि साधयन्ति ॥१.२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>असाधनाः = उपकरणवर्जिताः ; वित्तहीनाः = धनवर्जिताः ; (अपि-) बुद्धिमन्तः = मनीषिणः ; सुहृत्तमाः = परस्परहितैषिणः, परस्परं मित्रतां गताः सहृदयाः ; आशु = शीघ्रम् । काककूर्ममृगाखुवत् = वायस-कच्छपमूषकवत् ॥१.२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>साधनरहिताः, धनहीनाः चापि धीमन्तः, मित्रतासम्पन्नाः (ये जनाः) ते (आगामिन्यां कथायां) वायस-कच्छपमूषकवत् कार्याणि शीघ्रं साधयन्ति ॥१.२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उपायरहित, धनहीन पर बुद्धिमान् और दृढ मैत्री वाते पुरुष अपने कार्यों को उसी प्रकार शीघ्र सिद्ध कर लेते हैं, जैसे कि उन कौआ, कछुआ, मृग और चूहों ने किया था ॥१.२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.2.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
