                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शोकस्थानसहस्राणि भयस्थानशतानि च । दिवसे दिवसे मूढमाविशन्ति न पण्डितम् ॥१.३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शोक-स्थान-सहस्राणि भय-स्थान-शतानि च । दिवसे दिवसे मूढम् आविशन्ति न पण्डितम् ॥१.३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शोक-स्थान-सहस्राणि भय-स्थान-शतानि च । दिवसे दिवसे मूढम् आविशन्ति। पण्डितम् न (आविशन्ति) ॥१.३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शोक-स्थान-सहस्राणि = सहस्रशः शोककारणानि, शोकावसरा इत्यर्थः ; भयस्थानशतानि = शतशो भयहेतवः ; दिवसे-दिवसे = प्रतिदिनमेव ; मूढं = मूर्खमेव ; आविशन्ति = आश्रयन्ते, व्याकुलं कुर्वन्ति ; परन्तु पण्डितं = विद्वांसन्तु ; न = नैव आविशन्ति ॥१.३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सहस्रशः शोककारणानि शतशो भयहेतवः प्रतिदिनमेव मूर्खम् व्याकुलं कुर्वन्ति ; परन्तु विद्वांसन्तु नैव पीडयन्ति ॥१.३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>🙏</td>
                        </tr>
                    
                    
