                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उत्थायोत्थाय बोद्धव्यं महद्भयमुपस्थितम्।(पाठ. किमद्य सुकृतं कृतम् ।) मरणव्याधिशोकानां किमद्य निपतिष्यति ॥१.४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उत्थाय उत्थाय बोद्धव्यं महद्-भयम् उपस्थितम्। (पाठ. किम् अद्य सुकृतं कृतम्) । मरण-व्याधि-शोकानां किम् अद्य निपतिष्यति ॥१.४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उत्थाय उत्थाय उपस्थितं महद्-भयम् बोद्धव्यं । (पाठ. अद्य किम् सुकृतं कृतम्) । अद्य मरण-व्याधि-शोकानां किम् निपतिष्यति (इति) ॥१.४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्थाय उत्थाय = मुहुः प्रबुध्य ; उपस्थितं = प्राप्तं ; महद्भयं = महाभीतिः ; बोद्धव्यं=ज्ञातव्यम् ; किं ज्ञातव्यमत आह- मरणेति ; मरण-व्याधि-शोकानां = मृत्यु-रोग-मानसिकपीडानां मध्यात् ; निपतिष्यति = आपतिष्यति ॥१.४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जीवैः प्रतिदिनं (प्रातः निद्रातः) समुत्थाय विचारणीयं (स्मर्तव्यम्) । संसारे स्थिताभ्यः पीडाभ्यः का वा अद्य माम् आगत्य पीडयेदिति (सर्वदा सावधानेन भवितव्यम्। विपत्तये सन्नद्धतया स्थातव्यम्) ॥१.४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>संसारी जीवों को प्रतिदिन उठकर विचारना चाहिये और सदा सावधान रहना चाहिए कि आज मृत्यु शोक भय आदि विपत्तियो में से कौन सी विपत्ति आनेवाली है? अर्थात् जाने कब कौन विपत्ति आजाए, अतः बुद्धिमान् मनुष्य को उसके लिए सदा सावधान रहना चाहिए ॥१.४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.4.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
