                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अनिष्टादिष्टलाभेऽपि न गतिर्जायते शुभा । यत्रास्ते विषसंसर्गोऽमृतं तदपि मृत्यवे ॥१.६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अनिष्टाद् इष्टलाभे अपि न गतिः जायते शुभा । यत्र आस्ते विष-संसर्गः अमृतं तद् अपि मृत्यवे ॥१.६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अनिष्टाद् इष्टलाभे अपि शुभा गतिः न जायते । यत्र विष-संसर्गः आस्ते (तत्र) अमृतं, तद् अपि मृत्यवे ॥१.६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अनिष्टाद् = अशुभोपायात्, अयुक्तेन मार्गेण, दुष्टाद्वा पुंसः ; इष्टलाभे अपि = इष्टं वस्तु प्राप्यते, तथापि ; गतिः = परिणतिः, फलं ; शुभा = कल्याणकरी, क्षेमकारी ; यत्रेति । विष-संसर्गः = विषसंपृक्तम्, गरलं ; अमृतं = पीयूषमपि ; मृत्यवे = मरणकारी, मृत्युप्रदं भवतीत्यर्थः ॥१.६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अयुक्तेन मार्गेण इष्टं वस्तु प्राप्यते, तथापि तस्य परिणामः न मङ्गलकारी। यस्मिन् स्थाने गरलेन संयुक्तः, तत्र अमृतमपि प्राणहारकद्रव्यं भवति॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अपने अहित कारक- (शत्रु) से इष्ट वस्तु मिलने पर भी उसका परिणाम अच्छा नहीं होता है । जैसे अमृत में विष का संसर्ग हो तो वह अमृत भी मृत्यु का ही कारण होता है ॥१.६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.6.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="17" class="total">
                    <div>
                        <button id="moolamsmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '17')">मूलम्</button>
                        <button id="padasmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '17')">पदविभागः</button>
                        <button id="anvayasmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '17')">अन्वयः</button>
                        <button id="pratismall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '17')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '17')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '17')">हिन्द्यर्थः</button>
                        <button id="audiosmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '17')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न संशयमनारुह्य नरो भद्राणि पश्यति । संशयं पुनरारुह्य यदि जीवति पश्यति ॥१.७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न संशयम् अनारुह्य नरः भद्राणि पश्यति । संशयं पुनः आरुह्य यदि जीवति पश्यति ॥१.७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नरः संशयम् अनारुह्य भद्राणि न पश्यति । पुनः संशयं आरुह्य यदि जीवति, पश्यति ॥१.७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नेति । नरः = मानवः ; संशयं= सङ्कटं, प्राणसन्देहम्। अनारुह्य = अननुभूय, अनवाप्य च ; भद्राणि = श्रेयांसि, सुखं, धनादिसम्पत्तिञ्चेति यावत् ; पुनः =किन्तु ; संशयं = जीवनशङ्काम् ; जीवति = जीवन्नेव संशयदोलाया यदि उत्तरति तर्हि ; पश्यति = अवश्यं भद्राणि पश्यतीत्यर्थः ॥१.७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मानवः सन्देहम् (प्राणसङ्कटादिकं) अप्राप्य सुखादिकं न लभते। तादृशस्य विपत्तेः प्राप्तेरनन्तरं यदि प्राणैः विहीनो न भवति, तर्हि सुखं भुञ्जते। (कष्टं विना सुखं असम्भवमिति भावः।) ॥१.७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मनुष्य बिना संशय में पड़े कभी लाभ नहीं उठा सकता है, यदि संशय में पद कर भी जीता बच जाता है, तो बह (लाभ का) सुख भोगता है ॥१.७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.7.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="18" class="total">
                    <div>
                        <button id="moolamsmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '18')">मूलम्</button>
                        <button id="padasmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '18')">पदविभागः</button>
                        <button id="anvayasmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '18')">अन्वयः</button>
                        <button id="pratismall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '18')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '18')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '18')">हिन्द्यर्थः</button>
                        <button id="audiosmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '18')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>इज्याध्ययनदानानि तपः सत्यं धृतिः क्षमा । अलोभ इति मार्गोऽयं धर्मस्याष्टविधः स्मृतः ॥१.८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>🌸</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>इज्या-अध्ययन-दानानि तपः सत्यं धृतिः क्षमा । अलोभः इति मार्गः अयं धर्मस्य अष्टविधः स्मृतः ॥१.८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>इज्या = यज्ञः ; अध्ययनं = (गुरुमुखतः उच्चारितस्य पुनः उच्चारणं) पठनं ; दानं = अन्येभ्यः धनादिवस्तुत्यागः ; तपः = धार्मिकफलोद्दिष्टं विधियुक्तकर्म ; सत्यं = यथार्थं, अवितथं ; धृतिः = धैर्यम् ; क्षमा = सहिष्णुता, सहनं ; अलोभः = तृष्णाराहित्यं ; इति ; अयं धर्मस्य = शुभादृष्टस्य ; मार्गः = पन्थाः, धर्मोपार्जने उपाय-भूतः ; अष्टविधः ; स्मृतः = कथितः ॥१.८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धर्मोपार्जने उपायभूताः अष्टौ मार्गाः। ते- यज्ञः, (वेद)पठनं, धनादीनाम् आर्तेभ्यः वितरणं, वैधशारीरक्लेशः, सत्यं, धैर्यं, सहिष्णुता, अतृष्णा चेति ॥१.८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योंकि- धर्म के आठ मार्ग हैं, यज्ञ करना, पढ़ना, दान देना, तपस्या करना, सत्य बोलना, धीरता, क्षमा, और निर्लोभ होना ॥१.८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.8.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="19" class="total">
                    <div>
                        <button id="moolamsmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '19')">मूलम्</button>
                        <button id="padasmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '19')">पदविभागः</button>
                        <button id="anvayasmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '19')">अन्वयः</button>
                        <button id="pratismall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '19')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '19')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '19')">हिन्द्यर्थः</button>
                        <button id="audiosmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '19')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तत्र पूर्वश्चतुर्वर्गो दम्भार्थमपि सेव्यते । उत्तरस्तु चतुर्वर्गो महात्मन्येव तिष्ठति ॥१.९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>🌸</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>तत्र पूर्वः चतुर्वर्गः दम्भार्थम् अपि सेव्यते । उत्तरः तु चतुर्वर्गः महात्मनि एव तिष्ठति ॥१.९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>तत्र = अष्टविधे पूर्वोक्ते धर्ममार्गे ; पूर्वश्चतुर्वर्गः = इज्याध्ययनतपो-दानात्मकः ; दम्भार्थं = लोकसङ्ग्रह-लोकवञ्चनाद्यर्थमपि ; सेव्यते = आश्रीयते ; 'लोकै'रिति शेषः ; उत्तरः चतुर्वर्गः तु = सत्य-धृति-क्षमा-अलोभात्मको धर्ममार्गस्तु महात्मस्वेव सम्भवति, न क्षुद्राशयेषु ॥१.९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(इज्याध्ययनतपोदानाः, सत्यधृतिक्षमालोभाश्च धर्मोपार्जनमार्गाः।) तत्र पूर्वगणं न केवलं धर्माय, अपि तु दम्भप्रदर्शनादि-लौकिकप्रयोजनार्थमपि भजते नरः। अपरगणे स्थिताः गुणास्तु महापुरुषेषु, सन्तजनेषु एव दृश्यन्ते ॥१.९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>इन आठों में से पहले के चारों को (यज्ञ, पढ़ना, दान, तप, इन चारों को) महानताको दिखलाने के लिये पाखण्डी लोग भी कर सकते हैं, परन्तु अन्तिम चार (सत्य, धैर्य, क्षमा, अलोभ-सन्तोष) का अनुष्ठान तो महात्मा लोग ही करते हैं ॥१.९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.9.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="111" class="total">
                    <div>
                        <button id="moolamsmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '111')">मूलम्</button>
                        <button id="padasmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '111')">पदविभागः</button>
                        <button id="anvayasmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '111')">अन्वयः</button>
                        <button id="pratismall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '111')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '111')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '111')">हिन्द्यर्थः</button>
                        <button id="audiosmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '111')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मरुस्थल्यां यथा वृष्टिः क्षुधार्ते भोजनं तथा । दरिद्रे दीयते दानं सफलं पाण्डुनन्दन ॥१.११॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मरु-स्थल्यां यथा वृष्टिः क्षुधा-आर्ते भोजनं तथा । दरिद्रे दीयते दानं सफलं पाण्डु-नन्दन ॥१.११॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पाण्डु-नन्दन, यथा मरु-स्थल्यां वृष्टिः, क्षुधा-आर्ते भोजनं, तथा दरिद्रे (यत्) दानं दीयते (तत्) सफलं (भवति) ॥१.११॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पाण्डुनन्दन = हे युधिष्ठिर! ; मरुस्थल्यां = मरुभूमौ, निर्जलप्रदेशे ; यथा वृष्टिः = यथा वृष्टिः सफला, नितरामुचिता ; क्षुधार्ते = बुभुक्षया पीडिताय ; तथा = तथैव ; दरिद्रे = धनहीनाय ; यद्दानं दीयते तदपि सफलमित्यन्वयः ॥१.११॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे युधिष्ठिर, यथा जलरहितदेशे वर्षणेन वृष्टिः सफला भवति, भोजनेच्छोः अन्नदानेन क्षुधानिवारणेन च अनन्दानं सफलं भवति, तथैव निर्धनाय दत्तं दानं सफलं भवति। (जलं यत्र प्रभूतं तत्र वृष्टये न कोऽपि आर्तः। अन्नं खादित्वा यः तृप्तः तस्य अन्नस्यावश्यकता नास्ति। तथैव धनिकाय धनदानेन न लाभः। यत्र यन्नास्ति, तत्र तद्दातव्यम् इति यावत्।)॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हे युधिष्ठिर! जैसे मरुस्थल (मारवाड़) में वर्षा सफल है और भूखे को भोजन देना सफल है, वैसे दरिद्र को दिया हुआ दान भी सफल होता है ॥१.११॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
