                <div id="112" class="total">
                    <div>
                        <button id="moolamsmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '112')">मूलम्</button>
                        <button id="padasmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '112')">पदविभागः</button>
                        <button id="anvayasmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '112')">अन्वयः</button>
                        <button id="pratismall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '112')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '112')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '112')">हिन्द्यर्थः</button>
                        <button id="audiosmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '112')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>प्राणा यथात्मनोऽभीष्टा भूतानामपि ते तथा । आत्मौपम्येन भूतानां दयां कुर्वन्ति साधवः ॥१.१२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>प्राणाः यथा आत्मनः अभीष्टाः भूतानाम् अपि ते तथा । आत्मा-औपम्येन भूतानां दयां कुर्वन्ति साधवः ॥१.१२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यथा आत्मनः प्राणाः अभीष्टाः ते भूतानाम् अपि तथा । साधवः आत्मा-औपम्येन भूतानां दयां कुर्वन्ति ॥१.१२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आत्मनः = स्वस्य ; अभीष्टाः = प्रियाः ; भूतानां = स्वातिरिक्तानां सर्वेषां जीवानामपि ; ते = प्राणाः ; तथा = तथैव प्रियाः ; अत आत्मौपम्येन = स्वात्मानम् उपमानं कृत्वा ; साधवः = सज्जनाः, दयालवः ; भूतानां = जीवानां, प्राणिनां ; दयां कुर्वन्ति = अनुकम्पां, करुणां, कृपां वा दर्शयन्ति ॥१.१२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा स्वस्य प्राणाः स्वस्य अत्यन्तमिष्टाः भवन्ति, तथैव अन्येषां जीवानामपि ते अभीप्सिता भवन्ति। अतः साधवः अन्यानपि जीवान् आत्मनः समानमेव पश्यन्ति ॥१.१२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और जैसे मनुष्य अपने प्राणों को प्रिय समझता है, वैसे ही दूसरे प्राणियों को भी अपने-अपने प्राण प्यारे हैं । इसलिये महात्मा लोग अपनी ही तरह दूसरों को भी समझ कर सभी जीवों पर समान रूप से ही दया करते हैं ॥१.१२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.12.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="113" class="total">
                    <div>
                        <button id="moolamsmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '113')">मूलम्</button>
                        <button id="padasmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '113')">पदविभागः</button>
                        <button id="anvayasmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '113')">अन्वयः</button>
                        <button id="pratismall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '113')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '113')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '113')">हिन्द्यर्थः</button>
                        <button id="audiosmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '113')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>प्रत्याख्याने च दाने च सुखदुःखे प्रियाप्रिये । आत्मौपम्येन पुरुषः प्रमाणमधिगच्छति ॥१.१३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>प्रत्याख्याने च दाने च सुख-दुःखे प्रिय-अप्रिये । आत्मा-औपम्येन पुरुषः प्रमाणम् अधिगच्छति ॥१.१३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पुरुषः प्रत्याख्याने च दाने च सुख-दुःखे प्रिय-अप्रिये आत्मा-औपम्येन प्रमाणम् अधिगच्छति ॥१.१३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्रत्याख्याने = प्रार्थनाभङ्गे, परतिरस्कारे वा ; सुखे = सुखप्रदाने, दुःखे = क्लेशदाने, दुःखोत्पादने च । प्रिये = इष्टाचरणे, अप्रिये = अनिष्टाचरणे च ; आत्नौपम्येन = आत्मानमेव निदर्शनं कृत्वा ; प्रमाणं = निश्चयम् ; अधिगच्छति = लभते ; ॥१.१३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>प्रत्याख्याने = प्रार्थनाभङ्गे, परतिरस्कारे वा ; सुखे = सुखप्रदाने, दुःखे = क्लेशदाने, दुःखोत्पादने च । प्रिये = इष्टाचरणे, अप्रिये = अनिष्टाचरणे च ; आत्नौपम्येन = आत्मानमेव निदर्शनं कृत्वा ; प्रमाणं = निश्चयम् ; अधिगच्छति = लभते ; ॥१.१३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>प्रत्याख्यान (कोई कुछ कहे तो उसके टाल देना, ना हीं कर देना), दान, सुख और दुःख में अर्थात् किसी को सुखी या दुःखी बनाना, किसी को भला बुरा कहना, इन बातों से लोगों को कितना सुख या दुःख होता है। इसका अनुमान मनुष्य को अपने ऊपर ही करना चाहिए ॥१.१३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.13.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="114" class="total">
                    <div>
                        <button id="moolamsmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '114')">मूलम्</button>
                        <button id="padasmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '114')">पदविभागः</button>
                        <button id="anvayasmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '114')">अन्वयः</button>
                        <button id="pratismall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '114')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '114')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '114')">हिन्द्यर्थः</button>
                        <button id="audiosmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '114')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मातृवत् परदारेषु परद्रव्येषु लोष्टवत् । आत्मवत् सर्वभूतेषु यः पश्यति स पण्डितः ॥१.१४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मातृवत् परदारेषु परद्रव्येषु लोष्टवत् । आत्मवत् सर्वभूतेषु यः पश्यति सः पण्डितः ॥१.१४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>परदारेषु मातृवत्, परद्रव्येषु लोष्टवत्, सर्वभूतेषु आत्मवत् (च) यः पश्यति सः पण्डितः ॥१.१४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>परदारेषु = परकलत्रेषु, परेषां भार्याविषये ; मातृवत् = मातृभावेन यः पश्यति ; लोष्टवत् = मृत्खण्डवत्, पाषाणपिण्डवत् वा ; पश्यतीति शेषः ; पण्डितः = तत्त्वज्ञः ॥१.१४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>परनराणां पत्नीः स्वस्य जननी इति भावनया, परेषां धनानि पाषाणखण्डा इति धिया, सर्वान् प्राणिनः आत्मा इति बुद्ध्या- यः भावयति, सः विद्वान् भवति ॥१.१४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- जो मनुष्य दूसरोंकी स्त्रियों को अपनी माता की तरह समझें, दूसरे के द्रव्य को मिट्टी का ढेला (टुकडा) समझे और प्राणिमात्र को अपनी ही तरह समझे, वही सच्चा पण्डित है ॥१.१४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.14.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="115" class="total">
                    <div>
                        <button id="moolamsmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '115')">मूलम्</button>
                        <button id="padasmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '115')">पदविभागः</button>
                        <button id="anvayasmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '115')">अन्वयः</button>
                        <button id="pratismall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '115')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '115')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '115')">हिन्द्यर्थः</button>
                        <button id="audiosmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '115')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दरिद्रान् भर कौन्तेय मा प्रयच्छेश्वरे धनम् । व्याधितस्यौषधं पथ्यं नीरुजस्य किमौषधैः ॥१.१५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दरिद्रान् भर कौन्तेय मा प्रयच्छ ईश्वरे धनम् । व्याधितस्य औषधं पथ्यं नीरुजस्य किम् औषधैः ॥१.१५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कौन्तेय, दरिद्रान् भर। ईश्वरे धनं मा प्रयच्छ । व्याधितस्य औषधं पथ्यं (भवति)। नीरुजस्य किम् औषधैः (प्रयोजनम्?) ॥१.१५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कौन्तेय = हे कुन्ती-पुत्र, युधिष्ठिर ; दरिद्रान् = धनहीनान् ; भर = पालय ; ईश्वरे = धनिनि, ऐश्वर्यवति ; धनं = वित्तं ; मा प्रयच्छ = मा देहि ;व्याधितस्य = रुग्णस्य, शरीरबाधया पीडितस्य ; पथ्यं = हितकारकम् ; नीरुजस्य = रोगशून्यस्य, स्वस्थस्य तु ; औषधैः = भैषजैः, अगदैः ; किं = किं फलं ; न किमपीत्यर्थः ॥१.१५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे कुन्तीपुत्र, निर्धनान् (धनेन) पोषय। यः पूर्वमेव धनवान्, तस्मै धनं मा देहि। अस्य उदाहरणं दीयते। यथा- यः रोगपीडितः सः औषधेन हितं प्राप्नोति। यः पूर्वमेव स्वस्थः तस्य औषधसेवनं कुतः? ॥१.१५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हे कुन्तीपुत्र युधिष्ठिर! दरिद्रों का ही पालनपोषण करो, धनियों को दान मत दो, क्यों कि रोगी के लिये ही औषध लाभदायक होता है, पर जो नीरोग उनको औषध (दवा) की क्या आवश्यकता है? ॥१.१५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.15.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="116" class="total">
                    <div>
                        <button id="moolamsmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '116')">मूलम्</button>
                        <button id="padasmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '116')">पदविभागः</button>
                        <button id="anvayasmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '116')">अन्वयः</button>
                        <button id="pratismall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '116')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '116')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '116')">हिन्द्यर्थः</button>
                        <button id="audiosmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '116')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दातव्यमिति यद् दानं दीयतेऽनुपकारिणि । देशे काले च पात्रे च तद्दानं सात्त्विकं विदुः ॥१.१६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दातव्यम् इति यद् दानं दीयते अनुपकारिणि । देशे काले च पात्रे च तद् दानं सात्त्विकं विदुः ॥१.१६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् दानं अनुपकारिणि ‘दातव्यम्’ इति देशे काले च पात्रे च दीयते, तद् सात्त्विकं दानं विदुः ॥१.१६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दातव्यमिति = मया अवश्यमिदं कस्मैचन सत्पात्राय देयम् ; इति = इति बुद्ध्या ; दीयते = अर्पयते ; अनुपकारिणि = यस्मिन् पुरुषे आत्मनः लाभप्रत्यपेक्षा नास्ति, यस्मात् न किमपि स्वार्थं न साध्यते ; देशे = तीर्थादौ, सुक्षेत्रेषु ; काले = सूर्येन्दुग्रहणादौ, सत्काले ; पात्रे = योग्ये, सत्पात्रे, विदुषि ; (यद्दानं दीयते) तत् सात्त्विकमित्यन्वयः ॥१.१६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>‘मया अवश्यं कस्मैचन सत्पात्राय धनं देयम्’ इति (निःस्वार्थबुद्ध्या) प्रतिफलानापेक्षया साधुस्थले, साधुकाले, साधुपुरुषाय दत्तं दानं सात्विकं दानमिति व्यपदिश्यते ॥१.१६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>'मुझे यह देना है' इस बुद्धि से जो दान- देश, काल, पात्र समभ कर अनुपकारी (जिससे अपना कुछ लाभ व स्वार्थं न हो) को दिया जाता है, वही सात्त्विक (सच्चा) दान है ॥१.१६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.16.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="117" class="total">
                    <div>
                        <button id="moolamsmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '117')">मूलम्</button>
                        <button id="padasmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '117')">पदविभागः</button>
                        <button id="anvayasmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '117')">अन्वयः</button>
                        <button id="pratismall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '117')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '117')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '117')">हिन्द्यर्थः</button>
                        <button id="audiosmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '117')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न धर्मशास्त्रं पठतीति कारणं न चापि वेदाध्ययनं दुरात्मनः । स्वभाव एवात्र तथातिरिच्यते यथा प्रकृत्या मधुरं गवां पयः ॥१.१७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न धर्मशास्त्रं पठति इति कारणं न च अपि वेद-अध्ययनं दुरात्मनः । स्वभावः एव अत्र तथा अतिरिच्यते यथा प्रकृत्या मधुरं गवां पयः ॥१.१७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धर्मशास्त्रं पठति इति कारणं न ; वेद-अध्ययनं न च अपि (कारणं)। दुरात्मनः स्वभावः एव अत्र- यथा प्रकृत्या मधुरं गवां पयः- तथा अतिरिच्यते ॥१.१७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धर्मशास्त्रं = पुराणस्मृत्यादीनि ; पठति = अध्ययनं करोति ; दुरात्मनः = दुष्टस्वभावस्य ; (स्वभावपरिवर्तने) कारणं = हेतुः ;वेदाध्ययनं = वेदस्य गुरुमुखतः अध्ययनं ; स्वभावः = स्वतःसिद्धः, स्वकीयभावः ; अतिरिच्यते = सर्वोन्नतं, सर्वत्र बलवत् ; गवां पयः = दुग्धं ; प्रकृत्या = संसिद्ध्या ; मधुरं = गुड-इक्ष्वादिस्थः मिष्टस्वादुभावः ॥१.१७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धर्मशास्त्रं पठति, वेदाध्ययनं करोति इति कारणेन (स्वभावः) न परिवर्तते। दुर्जनस्य स्वभावः सर्वस्मात् अतिक्रम्य भवति। धेनूनां दुग्धं स्वभावत- एव मधुरं भवति (तत्र न कोऽपि बाह्यप्रयत्नः आवश्यकः इति यावत्।)☘ [धर्मशास्त्र-पठनं, वेदाध्ययनं वा दुष्टानां खलानां दुरात्मनां स्वभावपरिवर्तने न शक्तं भवति, स्वभावस्य सर्वतो बलवत्त्वात् । अत एव हि कटुकषाय-प्राय-तृणादि-भक्षणेऽपि, दुग्धं स्वभावेनैव मधुरं भवति, एवं- मधुरपयःपानेऽपि भुजङ्गानां स्वभावतो विषमेव भवति,नाऽमृतमिति भावः] ॥१.१७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>धर्मशास्त्र व वेद पढ़ने से ही अथवा कथा वार्त्ता, उपदेश आदि सुनने से ही कोई दुष्ट सज्जन नहीं हो जाता है, किन्तु सज्जन तो स्वभाव ही से सज्जन होते हैं । देखो, गाय का दूध स्वभाव ही से मीठा होता है ॥१.१७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.17.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="118" class="total">
                    <div>
                        <button id="moolamsmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '118')">मूलम्</button>
                        <button id="padasmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '118')">पदविभागः</button>
                        <button id="anvayasmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '118')">अन्वयः</button>
                        <button id="pratismall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '118')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '118')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '118')">हिन्द्यर्थः</button>
                        <button id="audiosmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '118')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अवशेन्द्रियचित्तानां हस्तिस्नानमिव क्रिया । दुर्भगाभरणप्रायो ज्ञानं भारः क्रियां विना ॥१.१८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अवश-इन्द्रिय-चित्तानां हस्ति-स्नानम् इव क्रिया । दुर्भग-आभरण-प्रायः ज्ञानं भारः क्रियां विना ॥१.१८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अवश-इन्द्रिय-चित्तानां क्रिया हस्ति-स्नानम् इव । क्रियां विना ज्ञानं भारः। दुर्भग-आभरण-प्रायः। ॥१.१८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अवशेन्द्रिय-चित्तानां ~ अवशानि इन्द्रियाणि, चित्तं च येषान्ते, तेषाम्-अवशेन्द्रिय-चित्तानाम् = निरवग्रहेन्द्रिय-स्वान्तानां पुंसाम् ; क्रिया = धर्माचरणादिकं कर्म ; हस्तिस्नानम् इव = गजस्नानमिव, निष्फलम् ; दुर्भगाया आभरणानीव- दुर्भगाभरणप्रायः = दुष्ट-दुर्भाग्य-स्त्रीधारित-भूषणवत्, ज्ञानं = विद्या ; क्रियां विना = तद्विहिताचरणं विना, भार एव ॥१.१८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>येषां चित्तं स्वाधीनं नास्ति, तैराचरितं धर्माचरणादिकं कर्म व्यर्थं भवति। यथा- गजाः स्नानं कृत्वा स्नानानन्तरमेव धूलिप्रक्षेपादिना पुनरात्मनो मलिनतामापादयन्ति। अपि च- आचरणं विना शुष्कज्ञानं भारभूतं भवति। यथा- दुर्भाग्यवत्याः स्त्रियः आभरणैः शोभा न वर्धते, केवलं भारवत्त्वमेव तथा ॥१.१८॥ [दुर्भगाधृताभरणैः पत्यादिमनोरञ्जनाऽभावाद् भारवत्तत्सर्वं तस्याः क्लेशप्रदमेव । यथा नानाभरणभूषिताऽपि खलु वन्ध्या, दुष्टा कुरूपा वा स्त्री न शोभते, न वा सा पत्युर्मनः प्रीणाति, एवं ज्ञानवानपि तदुक्ताचारशून्यो नैव शोभते, इत्याशयः । अत्र प्रायश्शब्दो बाहुल्येऽव्ययम्। अकारान्तो वा प्रायशब्दः पुंसि । दुर्भगाया भरणं पालन, तत्तुल्यं निष्फलमिति वाऽर्थः।] ॥१.१८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिन मनुष्यों की इन्द्रियाँ और चित्त वश में नहीं है, उनका सब कार्य हाथी के स्नान की तरह हो निष्फल है। (हाथी स्नान करके भी अपने ऊपर धूल फेंक कर अपने को पुनः मलिन कर लेता है) । और जो लोग अपने ज्ञान का उपयोग नहीं करते, उनका ज्ञान भी दुर्भगा (पतिपरित्यक्ता अथवा विधवा) स्त्री के भूषण की तरह भारमात्र ही है ॥१.१८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.18.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="119" class="total">
                    <div>
                        <button id="moolamsmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '119')">मूलम्</button>
                        <button id="padasmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '119')">पदविभागः</button>
                        <button id="anvayasmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '119')">अन्वयः</button>
                        <button id="pratismall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '119')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '119')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '119')">हिन्द्यर्थः</button>
                        <button id="audiosmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '119')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>नदीनां शस्त्रपाणीनां नखिनां शृङ्गिणां तथा । विश्वासो नैव कर्तव्यः स्त्रीषु राजकुलेषु च ॥१.१९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>नदीनां शस्त्र-पाणीनां नखिनां शृङ्गिणां तथा । विश्वासः न एव कर्तव्यः स्त्रीषु राज-कुलेषु च ॥१.१९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नदीनां शस्त्र-पाणीनां नखिनां शृङ्गिणां तथा स्त्रीषु राज-कुलेषु च विश्वासः न एव कर्तव्यः ॥१.१९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नदीनामिति । नदीनाम् = आपगानाम् ; शस्त्रपाणीनां = गृहीत-शस्त्राणाम् ; नखिनां = नखायुधानां सिंहादीनाम् ; शृङ्गिणां = शृङ्गायुधानां गोवृषभादीनाम् ; स्त्रीषु = युवतिषु ; राजकुलेषु च = राजगृहेषु च, विश्वासः = 'मद्वशगा इमे' इति विसम्भो, नैव कर्त्तव्यः = न विधेय इत्यर्थः ॥१.१९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नदीनां, शस्त्रधारकाणां, नखधारि-क्रूरजन्तूनां, शृङ्गधारि-पशूनां, स्त्रीणां, राजकुलानां च उपरि विश्वासः न करणीयः। [अत्र स्त्रीणां अविश्वासाय परामर्शं दृष्ट्वा स्त्रीवादिभिः अन्यथा न भावनीया। अत्र विष्णुशर्मा राजकुमारेभ्यः पाठनाय राजभिः आचारणयोग्यान् धर्मान् बोधयति। राजकुलेषु राजपुरुषाणां वशीकरणाय शत्रुपक्षिणः नर्तकीणां, सुन्दरस्त्रीणां प्रयोगं कुर्वन्ति (चाणक्यः अर्थशास्त्रे एनं विषयं विशदयति)। अतः तादृग्भिः स्त्रीभिः स्वस्य, देशस्य च रक्षा करणीया, नो चेत् ताः आगत्य, मनः भ्रामयित्वा रक्षणव्यवस्थारहस्यान् ज्ञात्वा शत्रुपक्षिभ्यः तत् सर्वं प्रकाशयेदिति मात्रमेवात्र ग्रहणीयम्। एतत् न सामान्यस्त्री-गृहिण्यादीनां विषये उच्यते।] ॥१.१९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>किसी ने कहा भी है- नदियों का, शस्त्रधारी मनुष्यों का, नख कौर सींग बाले जन्तुओं का, स्त्रियों का और राजकुल का (राजा, रानी, राजपुत्र आदि का-) विश्वास कभी नहीं करना चाहिए ॥१.१९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.19.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="120" class="total">
                    <div>
                        <button id="moolamsmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '120')">मूलम्</button>
                        <button id="padasmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '120')">पदविभागः</button>
                        <button id="anvayasmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '120')">अन्वयः</button>
                        <button id="pratismall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '120')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '120')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '120')">हिन्द्यर्थः</button>
                        <button id="audiosmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '120')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सर्वस्य हि परीक्ष्यन्ते स्वभावो नेतरे गुणाः । अतीत्य हि गुणान् सर्वान् स्वभावो मूर्ध्नि वर्तते ॥१.२०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सर्वस्य हि परीक्ष्यन्ते स्वभावः न इतरे गुणाः । अतीत्य हि गुणान् सर्वान् स्वभावः मूर्ध्नि वर्तते ॥१.२०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सर्वस्य हि स्वभावः (परीक्ष्यते) न इतरे गुणाः परीक्ष्यन्ते । सर्वान् गुणान् अतीत्य हि स्वभावः मूर्ध्नि वर्तते ॥१.२०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सकलस्यापि = गुणिनः, निर्गुणस्य वा, स्वभावाः = प्रकृतिः, संस्कारादयः ; इतरे = विद्वत्त्-औदार्य- कुशलत्वादयः गुणाः ; 'न परीक्ष्यन्ते' इति शेषः ; कुत एतदत आह- अतीत्येति ; सर्वान् गुणान् = सल्लक्षणान् ; अतीत्य = अतिक्रम्य ; स्वभावः = प्रकृतिरेव ;मूर्ध्नि = सर्वेषां गुणानामुपरि, वर्तते = प्रभवतीत्यर्थः ॥१.२०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सर्वेषां मनुष्याणां स्वभावः परीक्ष्यते। इतरे गुणाः न परीक्ष्यन्ते। सर्वान् गुणान् अतिक्रम्य स्वभावः शिरःस्थायी विराजते ॥१.२०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- मनुष्यों के गुणों की ओर ध्यान न देकर उनके स्वभाव की ही परीक्षा करनी चाहिए । क्योंकि गुणों की अपेक्षा स्वभाव ही सबसे ऊपर रहता है। स्वभाव ही सब में प्रधान है ॥१.२०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.20.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="121" class="total">
                    <div>
