                        <button id="padasmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '121')">पदविभागः</button>
                        <button id="anvayasmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '121')">अन्वयः</button>
                        <button id="pratismall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '121')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '121')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '121')">हिन्द्यर्थः</button>
                        <button id="audiosmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '121')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स हि गगनविहारी कल्मषध्वंसकारी दशशतकरधारी ज्योतिषां मध्यचारी । विधुरपि विधियोगाद् ग्रस्यते राहुणासौ लिखितमपि ललाटे प्रोज्झितुं कः समर्थः ॥१.२१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सः हि गगन-विहारी कल्मष-ध्वंस-कारी दश-शतकर-धारी ज्योतिषां मध्यचारी । विधुः अपि विधि-योगाद् ग्रस्यते राहुणा असौ लिखितम् अपि ललाटे प्रोज्झितुं कः समर्थः ॥१.२१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सः (विधुः) हि गगन-विहारी, कल्मष-ध्वंस-कारी, दश-शतकर-धारी, ज्योतिषां मध्यचारी, (अस्ति, तथापि तादृशः) असौ विधुः अपि विधि-योगाद् राहुणा ग्रस्यते । ललाटे लिखितम् अपि प्रोज्झितुं कः समर्थः ॥१.२१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सः = त्रिलोकीप्रसिद्धः ; गगन-विहारी = आकाश-सञ्चारी ; कल्मष-ध्वंस-कारी = अन्धकार-विनाशकः ; दशशत-कर-धारी = सहस्र-किरणः ; ज्योतिषां = ताराणां ; मध्यचारी = मध्यवर्ती ; असौ विधुरपि = चन्द्रोऽपि ; विधियोगात् = दैवविपर्ययात् ; ग्रस्यते = गृह्यते ; राहुणा = ग्रहविशेषेण ; लिखितं = विधात्रा लिखितम् ; ललाटे = फालभागे ; प्रोज्झितुं = त्यक्तुं, परिहर्तुं, पारं गन्तुं ॥१.२१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>चन्द्रः आकाशे विहरति, तमः विनाशयति, अनन्तकिरणान् धरति, ताराणां मध्ये भ्रमति। तथापि सः राहुग्रहेण प्रतिगृह्यते। भाग्यं अतिक्रान्तुं कः वा शक्नोति? ॥१.२१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>चन्द्रः आकाशे विहरति, तमः विनाशयति, अनन्तकिरणान् धरति, ताराणां मध्ये भ्रमति। तथापि सः राहुग्रहेण प्रतिगृह्यते। भाग्यं अतिक्रान्तुं कः वा शक्नोति? ॥१.२१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
