                        <button id="padasmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '122')">पदविभागः</button>
                        <button id="anvayasmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '122')">अन्वयः</button>
                        <button id="pratismall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '122')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '122')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '122')">हिन्द्यर्थः</button>
                        <button id="audiosmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '122')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सुजीर्णमन्नं सुविचक्षणः सुतः सुशासिता स्त्री नृपतिः सुसेवितः । सुचिन्त्य चोक्तं सुविचार्य यत् कृतं सुदीर्घकालेऽपि न याति विक्रियाम् ॥१.२२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुजीर्णम् अन्नं सुविचक्षणः सुतः सुशासिता स्त्री नृपतिः सुसेवितः । सुचिन्त्य च उक्तं सुविचार्य यत् कृतं सुदीर्घ-काले अपि न याति विक्रियाम् ॥१.२२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सुजीर्णम् अन्नं, सुविचक्षणः सुतः, सुशासिता स्त्री, सुसेवितः नृपतिः, सुचिन्त्य च उक्तं, सुविचार्य यत् कृतं, (तत्) सुदीर्घ-काले अपि विक्रियाम् न याति ॥१.२२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सुजीर्णं = सुपक्वम् ; सुविचक्षणः = नितरां शिक्षितो विद्वान् ; सुतः = पुत्रः ; सुशासिता = सुष्ठु आत्मना अनुशासिता, आत्मनः वशे या अस्ति, सा; सुदीर्घकालेऽपि = गतेऽपि बहुतिथे काले ; विक्रियां = विकारम्। न याति = विकृतं न भवति ॥१.२२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>भोजनं सुपक्वं, पुत्रः कार्याकार्यविचारशीलः, आत्मनः अनुशासनेन सन्मार्गगामिनी स्त्री, मन्त्रि-सेनापत्यादिभिः सम्यक् अनुगतः राजा, विचार्य उक्तं वचनं, कृतं कार्यं च एतानि सर्वाणि बहुकालानन्तरमपि दुष्टानि न भवन्ति ॥१.२२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि-भली भाँति पका हुआ अन्न, बुद्धिमान् पुत्र, शिक्षित स्त्री, अच्छी तरह से सेवित राजा, सोच कर कही हुई बात, और विचार कर किया हुआ काम- ये सब कभी बिगड़ते नहीं हैं ॥१.२२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
