                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="123" class="total">
                    <div>
                        <button id="moolamsmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '123')">मूलम्</button>
                        <button id="padasmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '123')">पदविभागः</button>
                        <button id="anvayasmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '123')">अन्वयः</button>
                        <button id="pratismall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '123')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '123')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '123')">हिन्द्यर्थः</button>
                        <button id="audiosmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '123')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वृद्धानां वचनं ग्राह्यमापत्काले ह्युपस्थिते । सर्वत्रैवं विचारे च भोजनेऽप्यप्रवर्तनम्** ॥१.२३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वृद्धनां वचनं ग्राह्यम् आपत्-काले हि उपस्थिते । सर्वत्र एवं विचारे च भोजने अपि अप्रवर्तनम् ॥१.२३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>वृद्धानां वचनं आपत्-काले हि उपस्थिते ग्राह्यम् । सर्वत्र एवं विचारे च भोजने अपि अप्रवर्तनम् ॥१.२३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ग्राह्यं = स्वीकार्यम् ; आपत्काले = विपत्तिसमये ; उपस्थिते = प्राप्ते सति ; सर्वत्र = सर्वेषु कार्येषु ; एवं विचारे = वृद्धवचनानुसारेणैव सुविचार्यैव प्रवृत्तौ तु ; अप्रवर्तनम् = अप्रवृत्तिः स्यादित्यर्थः ; 'विचारेणेति पाठान्तरम् ॥१.२३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदा विपत्तिः सम्भवति, तदा एव ज्येष्ठानाम् उपदेशकथनानुसारम् आचरणीयम्। अन्यथा- ‘यत्रकुत्रचित् तेषाम् उपदेशनेनैव कार्ये प्रवर्ते’ इति विचिन्तनेन भोजनमपि न खादेत् ॥ [**अस्मात् वाक्यात् पूर्वं “कपोतः सदर्पमाह”- इत्यस्ति। दर्पस्यात्र सन्दर्भः। अतः दर्पवन्तः एवं विचिन्तयन्ति इति यावत् ग्राह्यमत्र।] ॥१.२३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>आपत्ति के समय में ही वृद्धों का वचन मानना चाहिये। सब जगह ऐसा विचार करने से तो फिर भोजन में भी प्रवृत्ति नहींहो सकती है ॥१.२३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.23.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="124" class="total">
                    <div>
                        <button id="moolamsmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '124')">मूलम्</button>
                        <button id="padasmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '124')">पदविभागः</button>
                        <button id="anvayasmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '124')">अन्वयः</button>
                        <button id="pratismall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '124')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '124')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '124')">हिन्द्यर्थः</button>
                        <button id="audiosmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '124')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शङ्काभिः सर्वमाक्रान्तमन्नं पानं च भूतले । प्रवृत्तिः कुत्र कर्तव्या जीवितव्यं कथं नु वा ? ॥१.२४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शङ्काभिः सर्वम् आक्रान्तम् अन्नं पानं च भूतले । प्रवृत्तिः कुत्र कर्तव्या जीवितव्यं कथं नु वा ? ॥१.२४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>भूतले सर्वम् अन्नं पानं च शङ्काभिः आक्रान्तम् । कुत्र प्रवृत्तिः कर्तव्या? कथं नु वा जीवितव्यं? ॥१.२४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>भूतले = लोके ; सर्वं = अशेषं ; अन्नं = भक्ष्यम्, भोजनम् ; पानं = पातुं योग्यं पदार्थं जलादिः ; शङ्काभिः = (अत्र भोजन-सम्बन्धि-शङ्काः इति) वात-पित्त-कफादि-जन्य-रोगादि-शङ्काभिः ; आक्रान्तं = व्यापृतं ; कुत्र = कस्मिन् भोज्ये पदार्थे ; प्रवृत्तिः कर्तव्या = (अत्र) खादितव्यम् ; कथं नु = केन प्रकारेण? ; जीवितव्यम् = लोके स्थातव्यम्; ॥१.२४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जगति यत्किञ्चित् खाद्यं, पानयोग्यं च वस्तु वर्तते, तत् समस्तं (वस्तुनः गुण-प्रभावादिषु) नानाविधसन्देहैः आपृतं वर्तते। (अनेन कारणेन) किं खादनीयं, किं न (इति भ्रान्ताः), कथं वा जीवनयात्रां यापयाम इति (विचारयामश्च) ॥१.२४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>इस पृथ्वी तल पर अन्न और पान सन्देहों से भरा है, किस वस्तु में खाने-पीने की इच्छा करे या कैसे जिये ? क्यों कि-संसार में सभी बातें शङ्का से भरी हुई हैं, फिर कहा प्रवृत्ति की जाय और कहाँ प्रवृत्ति न की जाय और किसी प्रकार जीवन निर्वाह किया जाय? ॥१.२४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.24.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="125" class="total">
                    <div>
                        <button id="moolamsmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '125')">मूलम्</button>
                        <button id="padasmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '125')">पदविभागः</button>
                        <button id="anvayasmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '125')">अन्वयः</button>
                        <button id="pratismall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '125')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '125')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '125')">हिन्द्यर्थः</button>
                        <button id="audiosmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '125')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>ईर्ष्यी घृणी त्वसन्तुष्टः क्रोधनो नित्यशङ्कितः । परभाग्योपजीवी च षडेते दुःखभागिनः ॥१.२५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>ईर्ष्यी घृणी तु असन्तुष्टः क्रोधनः नित्य-शङ्कितः । परभाग्य-उपजीवी च षड् एते दुःखभागिनः ॥१.२५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>ईर्ष्यी घृणी असन्तुष्टः क्रोधनः नित्य-शङ्कितः परभाग्य-उपजीवी च-- एते षड् दुःखभागिनः (भवन्ति) ॥१.२५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ईर्ष्यी = ईर्ष्यालुः, परोत्कर्षासहिष्णुः ; घृणी = घृणाशीलः, जुगुप्सा-स्वभावकः ; असन्तुष्टः = सन्तुष्टि-हीनः ; क्रोधनः = कोपस्वभावकः ; नित्यशङ्कितः = यः सर्वदा सर्वत्र शङ्कां करोति ; परभाग्योपजीवी = परान्नभोजी, पराधीनः ; षडेते दुःखभागिनः = एते षट्जनाः सर्वदा दुःखमेव अनुभवन्ति ॥१.२५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>एते षट्-जनाः नित्यं दुःखिता भवन्ति-- १. यः परेषामुत्कर्षं न सहते, अन्यस्य भाग्योदये खिन्नः भवति, २. यः सर्वत्र घृणां प्रदर्शयति, ३. य असन्तुष्टः, कुत्रचित् केनचिदपि सन्तोषं नाननुभवति, ४. यः सदा क्रुद्धः भवति, ५. यः अकारणं, सकारणं वा सर्वत्र सन्देहं करोति, ६. य अन्येषां गृहे तिष्ठति, इतरेषां सम्पदा स्वजीवनं यापयति ॥१.२५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कहा भी है- दूसरों से ईर्ष्या करने वाला, असन्तोषी, क्रोधी, सदा सन्देह करने वाला, दूसरे के आश्रय से जीने वाला, ये छः प्रकार के मनुष्य सदा दुःखी ही रहते हैं ॥१.२५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.25.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="126" class="total">
                    <div>
                        <button id="moolamsmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '126')">मूलम्</button>
                        <button id="padasmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '126')">पदविभागः</button>
                        <button id="anvayasmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '126')">अन्वयः</button>
                        <button id="pratismall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '126')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '126')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '126')">हिन्द्यर्थः</button>
                        <button id="audiosmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '126')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सुमहान्त्यपि शास्त्राणि धारयन्तो बहुश्रुताः । छेत्तारः संशयानां च क्लिश्यन्ते लोभमोहिताः ॥१.२६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुमहान्ति अपि शास्त्राणि धारयन्तः बहुश्रुताः । छेत्तारः संशयानां च क्लिश्यन्ते लोभ-मोहिताः ॥१.२६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>(ये) बहुश्रुताः, सुमहान्ति अपि शास्त्राणि धारयन्तः, संशयानां छेत्तारः च, (ते) लोभ-मोहिताः (सन्तः) क्लिश्यन्ते ॥१.२६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सुमहान्ति शास्त्राणि = सर्व-संशय-उच्छेदकानि, सुगूढ-तत्त्वानि, यानि च पठित्वा उत्कृष्टं ज्ञानं लभ्यते जनः ; धारयन्तः = बुद्ध्या अर्थम् अवबोधितवन्तः ; बहुश्रुताः = व्यवहार-पटवो, नीति-विदश्च, ज्ञानवन्तः ; संशयानां = पर-सन्देहानां ; छेत्तारः = निराकरिष्णवः, ये परिष्कुर्वन्ति ; लोभमोहिताः = लोभात् मोहे पतिताः ; क्लिश्यन्ते = दुःखम् अनुभवन्ति इत्यर्थः ॥१.२६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>उत्कृष्टानि, अत्युत्तमानि च शास्त्राणि अधीतवन्तः, पण्डिताः, ये परेषां स्वेषां च सन्देहानां निराकरणे समर्थाः सन्तः- ते अपि लोभकारणात् मोहिताः भवन्ति। अनेन मोहेन कष्टेषु पतन्ति च [अस्यार्थः- लोभात् जायमानात् मोहात् पतनात् च जागरूकतया भवितव्यमित्येव। शास्त्राध्ययनं त्यक्तव्यमिति न। यदि पण्डिताः एव लोभात् विभ्रमे पतन्ति, तत्र का वा सामान्यानां वार्ता?] ॥१.२६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बड़े बड़े शास्त्रों को जानने वाले, बहुत बातों को जानने वाले, सब प्रकार के भ्रमों को दूर करने वाले लोग भी लोभ मे पड़ कर दुःख भोगते हैं ॥१.२६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.26.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="127" class="total">
                    <div>
                        <button id="moolamsmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '127')">मूलम्</button>
                        <button id="padasmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '127')">पदविभागः</button>
                        <button id="anvayasmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '127')">अन्वयः</button>
                        <button id="pratismall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '127')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '127')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '127')">हिन्द्यर्थः</button>
                        <button id="audiosmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '127')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>बड़े बड़े शास्त्रों को जानने वाले, बहुत बातों को जानने वाले, सब प्रकार के भ्रमों को दूर करने वाले लोग भी लोभ मे पड़ कर दुःख भोगते हैं ॥१.२६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>लोभात् क्रोधः प्रभवति लोभात् कामः प्रजायते । लोभात् मोहः च नाशः च लोभः पापस्य कारणम् ॥१.२७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोभात् क्रोधः प्रभवति। लोभात् कामः प्रजायते । लोभान् मोहः च नाशः च (भवतः)। लोभः पापस्य कारणम् (भवति) ॥१.२७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोभात् = पर-द्रव्ये अभिलाषायाः ; प्रभवति = प्रवर्त्तते, प्रवर्द्धते च ; प्रजायते = उत्पद्यते, प्रवर्द्धते च ; लोभात्- मोहश्च, नाशश्च । 'उपजायते' इति शेषः । अतो लोभः पापस्य कारणमित्यर्थः ॥१.२७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>लोभस्य कारणेन किं किं प्रवर्धते इति उच्यते-- (लोभस्यासम्पूर्तौ) क्रोधः, (लोभस्य सन्तुष्टौ) कामः, मोहश्च जायेते। तेन पापं च प्रभवति। (पापमयं जीवनं भवति।) ॥१.२७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>लोभ ही से क्रोध उत्पन्न होता है, लोभ ही से काम उत्पन्न होता है। और लोभ ही से मोह (अज्ञान) भी उत्पन्न होता है और लोभ ही से मनुष्य का नाश भी होता है, अतः लोभ ही सब पापों का मूल कारण है ॥१.२७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.27.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="128" class="total">
                    <div>
                        <button id="moolamsmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '128')">मूलम्</button>
                        <button id="padasmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '128')">पदविभागः</button>
                        <button id="anvayasmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '128')">अन्वयः</button>
                        <button id="pratismall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '128')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '128')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '128')">हिन्द्यर्थः</button>
                        <button id="audiosmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '128')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>असम्भवं हेममृगस्य जन्म तथापि रामो लुलुभे मृगाय । प्रायः समापन्नविपत्तिकाले धियोऽपि पुंसां मलिना भवन्ति ॥१.२८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>असम्भवं हेममृगस्य जन्म तथापि रामः लुलुभे मृगाय । प्रायः समापन्न-विपत्ति-काले धियः अपि पुंसां मलिनाः भवन्ति ॥१.२८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>हेममृगस्य जन्म असम्भवम्। तथापि रामः मृगाय लुलुभे । प्रायः समापन्न-विपत्ति-काले, पुंसां धियः अपि मलिनाः भवन्ति ॥१.२८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>हेममृगस्य = स्वर्णमृगस्य ; जन्म = उत्पत्तिः ; असम्भवम् = सम्भावनाविषयीभूतमपि न भवति ; तथापि रामः = सकल-ज्ञान-निधिः भगवान् दाशरथिः अपि ; मृगाय = स्वर्ण-मृगम् आदातुं ; लुलुभे = लोभमकरोत् ; प्रायः = बाहुल्येन ; समापन्न-विपत्ति-काले ~ समापन्नाः = सन्निहताः, आपतिताः, या विपदः, तासां कालः = समयः, तस्मिन् ; पुंसां = पुरुषाणां, मनुष्याणां ; धियः अपि = बुद्धयः अपि ; मलिनाः = मलाविलाः, मलेन कुण्ठिताः ; भवन्ति = जायन्ते ; 'इति तर्कयामी'ति शेषः ॥१.२८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>‘स्वर्णः मृगः लोके कुत्रचिदपि न भवितुमर्हति’ इति जानन्नपि साक्षात् पुरुषोत्तमः श्रीरामः अपि (मारीचधृत)काञ्चनं मृगरूपं दृष्ट्वा तं प्राप्तुम् अकामयत। बहुधा एवं भवति- आपत्सु समापन्नेषु जनानां बुद्धयः अपि भ्रान्ताः भवन्ति। (अतः विपत्तौ प्राप्ते सति जागरूकतया भवितव्यम्। यत्र धीरपि प्रमाद्यते, तत्र अन्यचित्तवृत्तीनां किं वा कथनम्? निर्णयकरणसमये अत्यन्तं विचक्षणैः भवितव्यम्- इति तात्पर्यम्। न पुनः श्रीरामस्य विमर्शनमत्रार्थः।) ॥१.२८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सोने के मृग का होना यद्यपि असम्भव है, तथापि भगवान् श्री रामचन्द्रजी महाराज भी सोने के मृग के लोभ में बह गए। ठीक ही है- प्रायः विपत्ति काल सन्निहित होने पर मनुष्यों की बुद्धि भी मलिन हो जाती है ॥१.२८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.28.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="129" class="total">
                    <div>
                        <button id="moolamsmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '129')">मूलम्</button>
                        <button id="padasmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '129')">पदविभागः</button>
                        <button id="anvayasmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '129')">अन्वयः</button>
                        <button id="pratismall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '129')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '129')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '129')">हिन्द्यर्थः</button>
                        <button id="audiosmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '129')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न गणस्याग्रतो गच्छेत् सिद्धे कार्ये समं फलम् । यदि कार्यविपत्तिः स्यान्मुखरस्तत्र हन्यते ॥१.२९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न गणस्य अग्रतः गच्छेत् सिद्धे कार्ये समं फलम् । यदि कार्य-विपत्तिः स्यात् मुखरः तत्र हन्यते ॥१.२९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गणस्य अग्रतः न गच्छेत् । कार्ये सिद्धे (सति) समं फलम् (प्राप्यते) । यदि कार्य-विपत्तिः स्यात्, तत्र मुखरः हन्यते ॥१.२९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गणस्य = सङ्घस्य, समूहस्य, वर्गस्य ; अग्रतः = अग्रे, सर्वस्मात् पुरतः ; कार्ये = कर्त्तव्ये कर्मणि ; सिद्धे = निष्पन्ने सति, सफलत्वे प्राप्तौ सति ; समं = तुल्यं, समानं ; कार्यविपत्तिः = कार्यहानिः, असाफल्यम् ; मुखरः = अग्रणीः, प्रवर्त्तकश्च, नायकः ; हन्यते = वध्यते ; ॥१.२९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>न कदापि समूहे सर्वेभ्यः अग्रे भवितव्यम्। कार्ये सफलत्वं प्राप्ते सति तु (समूहसदस्यानां नायकस्य च) सर्वेषामपि फले समानता भवति। परन्तु कार्यनाशे तु अग्रे विद्यमानस्य नायकस्यैव क्षतिः न तु इतरेषाम्। [अत्र पक्षीणां प्रसङ्गः। ‘कदापि तथा अग्रे मा गच्छतु’ इति न अस्यार्थः। अग्रे गमनस्य परिणामान् मनसि निधाय प्रवर्ततामिति, यदि धैर्यः अस्ति, तथैव गच्छतु इति वा भावना।] ॥१.२९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>किसी कार्य में सबके आगे कभी नहीं होना चाहिये, क्यों कि कार्य की सिद्धि होने पर तो फलमें समान ता हो रहती है, परन्तु यदि दैवात् कार्य में कोई विघ्न हो गया तो पहिले अगुआ ही मारा जाता है ॥१.२९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.29.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="130" class="total">
                    <div>
                        <button id="moolamsmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '130')">मूलम्</button>
                        <button id="padasmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '130')">पदविभागः</button>
                        <button id="anvayasmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '130')">अन्वयः</button>
                        <button id="pratismall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '130')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '130')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '130')">हिन्द्यर्थः</button>
                        <button id="audiosmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '130')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आपदां कथितः पन्था इन्द्रियाणामसंयमः । तज्जयः सम्पदां मार्गो, येनेष्टं तेन गम्यताम् ॥१.३०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आपदां कथितः पन्थाः इन्द्रियाणाम् असंयमः । तत्-जयः सम्पदां मार्गः येन इष्टं तेन गम्यताम् ॥१.३०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>इन्द्रियाणाम् असंयमः आपदां पन्थाः कथितः । तत्-जयः सम्पदां मार्गः येन इष्टं तेन गम्यताम् ॥१.३०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>इन्द्रियाणाम्= चक्षुरादीनाम् ; असंयमः = अनिग्रहः ; आपदां = विपदां, दुःखस्य च ; पन्थाः = मार्गः ; कथितः = (नीतिविद्भिः) प्रोक्तः ; तज्जयः = इन्द्रियाणां जयः, इन्द्रिय-निग्रहश्च ; सम्पदां= सम्पत्तीनां, कल्याणस्य च, ; मार्गः = पन्थाः ; येन = येन पथा ; इष्टम् = अभीष्टसिद्धिः ; तेन गम्यताम् = तदनुस्रियताम् ; यद्वा- येन इष्टं = सुखं भवेत्, तेन = इन्द्रियजयमार्गेण, गम्यतामित्यर्थो बोध्यः ॥१.३०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कर्म-ज्ञानेन्द्रियाणाम् अनियन्त्रणं विपत्तीनां मार्ग इति (बुधैः) कथितः। इन्द्रियाणां जयः तु सम्पत्तीनां मार्गः। येन मार्गेण गन्तुमिच्छसि, तेन गच्छतु। (यदि विपत्तय इष्टाः, तर्हि पूर्वस्मिन् मार्गे गच्छतु। यदि सम्पत्तय इष्टाः तर्हि परस्मिन् मार्गे गच्छतु। परिणामस्तु तव पुरतः वर्तते।) ॥१.३०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कहा भी है- इन्द्रियों को अपने वश में न रखना विपत्ति का मार्ग है । और इन्द्रियों को वश में रखना ही सम्पत्ति का मार्ग है । जिस रास्ते से इच्छा हो, जाओ ॥१.३०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.30.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="131" class="total">
                    <div>
                        <button id="moolamsmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '131')">मूलम्</button>
                        <button id="padasmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '131')">पदविभागः</button>
                        <button id="anvayasmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '131')">अन्वयः</button>
                        <button id="pratismall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '131')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '131')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '131')">हिन्द्यर्थः</button>
                        <button id="audiosmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '131')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आपदामापतन्तीनां हितोऽप्यायाति हेतुताम् । मातृजङ्घा हि वत्सस्य स्तम्भीभवति बन्धने ॥१.३१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आपदामापतन्तीनां हितोऽप्यायाति हेतुताम् । मातृजङ्घा हि वत्सस्य स्तम्भीभवति बन्धने ॥१.३१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आपतन्तीनाम् आपदां हितः अपि हेतुताम् आयाति । मातृजङ्घा हि वत्सस्य बन्धने स्तम्भीभवति ॥१.३१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आपतन्तीनाम् = आगच्छन्तीनाम् ; हितः = हितकारकः, प्रियोऽपि ; हेतुतां = कारणताम् ; आयाति = प्राप्नोति, आगच्छति वा ; हि = यतः ; मातृजङ्घा = मातुः, गोः जङ्घा = पादाग्रभागः, काण्डम् ; वत्सस्य = स्वबाल-वत्सस्य ; स्तम्भी-भवति = गोदोहनकाले तत्र प्रायो वत्सस्य बन्धनाद् वत्सबन्धनस्तम्भतां याति । बन्धनोपकरण-शङ्कुभावं भजतीत्यर्थः ॥१.३१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जीवने या विपत्तयः आगच्छन्ति, तेषां पृष्ठे कारणं हितमपि भवितुमर्हति, अर्थात् हितमपि तत्र विपदि कारणं भवति। अत्रोपन्यासः- गोः दुग्धनिःसारणे वत्सः विघ्नमुत्पादयतीति मत्वा सः धेनोः पादेन रज्ज्वा बध्यते। तदानीं मातुः पादः अपि वत्साय स्तम्भस्य कारणं भवति, गमनरोधनस्य च ॥१.३१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>विपत्ति जब आने वाली होती है, तत्र अपना मित्र भी उस आने वाली आपत्ति का कारण हो जाता है । जैसे बछड़े के बाँधने के लिये कभी कभी (दूध दूहते समय) उसकी माता (गाय) की जङ्घा भी खूँटे (स्तम्भ) का काम देती है ॥१.३१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.31.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="132" class="total">
                    <div>
                        <button id="moolamsmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '132')">मूलम्</button>
                        <button id="padasmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '132')">पदविभागः</button>
                        <button id="anvayasmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '132')">अन्वयः</button>
                        <button id="pratismall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '132')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '132')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '132')">हिन्द्यर्थः</button>
                        <button id="audiosmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '132')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स बन्धुर्यो विपन्नानामापदुद्धरणक्षमः । न तु भीतपरित्राणवस्तूपालम्भपण्डितः ॥१.३२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सः बन्धुः यः विपन्नानाम् आपद्-उद्धरण-क्षमः । न तु भीत-परित्राण-वस्तु-उपालम्भ-पण्डितः ॥१.३२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यो विपन्नानाम् आपद्-उद्धरण-क्षमः सः बन्धुः । भीत-परित्राण-वस्तु-उपालम्भ-पण्डितः न तु ॥१.३२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यो विपन्नानां = विपद्-ग्रस्तानाम् ; आपदुद्धरणे = विपत्तिनिरासे, आपदः अपाकरणे ; क्षमः = शक्तः, स एव बन्धुः = सुबन्धुः ; यस्तु- भीतपरित्राणे = विपन्नस्य रक्षणावसरे, उपालम्भ-पण्डितः = नानाविध-तत्तिरस्कार-वाक्यप्रयोग-विशारदः, यः आक्षेपकर-वाक्यानि, पीडाकर-वचनानि वा वदति, तथा वचने यः कुशलः सः ; न तु = नैव बन्धुः ॥१.३२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः आपदि आपतितायां ततः अस्मान् उद्धर्तुं समर्थः, स एव वास्तवबन्धुः। यः तदकृत्वा पीडाकरवचनैः त्रस्तस्य इतोऽधिक-भयोत्पादने समर्थः, स बन्धुः नास्ति। (आपदि पतितस्य भीतिः वर्धते। तदानीं बन्धुना भयनिष्कासनं कार्यं, न पुनः तद्वर्धक-दुर्वचनप्रयोगः।) ॥१.३२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मित्र वही है जो विपत्ति में पड़े हुए प्राणियों को आपत्ति से छुडाने में समर्थ हो । और जो भयभीत व विपत्तिग्रस्त की रक्षा करने के समय खाली उलहना देने में अपने कर्त्तव्य की समाप्ति समझता है वह मित्र नहीं, किन्तु वह शत्रु है ॥१.३२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.32.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="133" class="total">
                    <div>
                        <button id="moolamsmall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '133')">मूलम्</button>
                        <button id="padasmall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '133')">पदविभागः</button>
                        <button id="anvayasmall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '133')">अन्वयः</button>
                        <button id="pratismall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '133')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '133')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '133')">हिन्द्यर्थः</button>
                        <button id="audiosmall133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '133')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>विपदि धैर्यमथाभ्युदये क्षमा सदसि वाक्पटुता युधि विक्रमः । यशसि चाभिरुचिर्व्यसनं श्रुतौ प्रकृतिसिद्धमिदं हि महात्मनाम् ॥१.३३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विपदि धैर्यम् अथ अभ्युदये क्षमा सदसि वाक्-पटुता युधि विक्रमः । यशसि च अभिरुचिः व्यसनं श्रुतौ प्रकृति-सिद्धम् इदं हि महात्मनाम् ॥१.३३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>महात्मनाम् इदं हि प्रकृति-सिद्धम्-- विपदि धैर्यम्, अथ अभ्युदये क्षमा, सदसि वाक्-पटुता, युधि विक्रमः, यशसि च अभिरुचिः, श्रुतौ व्यसनम् ॥१.३३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>महात्मनां = महापुरुषाणाम् ; इदं प्रकृतिसिद्धं = स्वभाव-सिद्धमेव ; किन्तद् इत्यत आह- विपदीति ; धैर्यं =धैर्यमवलम्ब्य तत्प्रतीकार-चिन्तनम् ; अभ्युदये = सम्पत्तौ ; क्षमा = परानुग्रहः, अभिमानविरहश्च ; सदसि = सभायां वाक्पटुता = वाक्पाटवं, वचनचातुरी ; युधि = युद्धे, विक्रमः = पराक्रमः ; यशसि = कीर्तौ ; इच्छा = अभिलाषः, यशोधनत्वमिति यावत् ; श्रुतौ = शास्त्रे, व्यसनम् = निर्हेतुकोऽनुरागः ॥१.३३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कष्टकाले धीरत्वं, अभिवृद्धौ सहनभावः, सभायां वचनसामर्थ्यं, समराङ्गणे पराक्रमः, कीर्तौ काङ्क्षा, शास्त्राध्ययने निरन्तरपरिश्रमः --एते सर्वे महाजनानां स्वभावलक्षणानि भवन्ति (एतेषां पृथक् शिक्षणस्य अभ्यासस्य वा आवश्यकता नास्ति महात्मनामिति यावत्) ॥१.३३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि- विपत्ति में धीरता, उन्नति होने पर नम्रता, सभा में बोलने की शक्ति, युद्ध में वीरता, कीर्ति की इच्छा और शास्त्रों के अभ्यास में व्यसन, ये सब महात्माओं के स्वभावसिद्ध गुण हैं ॥१.३३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.33.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="134" class="total">
                    <div>
                        <button id="moolamsmall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '134')">मूलम्</button>
                        <button id="padasmall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '134')">पदविभागः</button>
                        <button id="anvayasmall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '134')">अन्वयः</button>
                        <button id="pratismall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '134')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '134')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '134')">हिन्द्यर्थः</button>
                        <button id="audiosmall134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '134')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सम्पदि यस्य न हर्षो विपदि विषादो रणे च भीरुत्वम् । तं भुवनत्रयतिलकं जनयति जननी सुतं विरलम् ॥१.३४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सम्पदि यस्य न हर्षः विपदि विषादः रणे च भीरुत्वम् । तं भुवन-त्रय-तिलकं जनयति जननी सुतं विरलम् ॥१.३४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य सम्पदि न हर्षः, विपदि विषादः (न), रणे च भीरुत्वं (न), तं भुवन-त्रय-तिलकं सुतं जननी विरलं जनयति ॥१.३४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सम्पदि = अर्थाभिवृद्धौ ; हर्षः = प्रमोदः, गर्वश्च ; विपदि = विपत्तौ, कष्टकाले ; विषादः = दुःखं, वैक्लव्यं ; रणे = समरभूमौ ; धीरत्वम् = धैर्यगुणः ; तम् = अनुत्सिक्तम् अकातरं, निर्भयञ्च ; भुवनत्रय-तिलकं = लोकत्रये रत्नतुल्यम् ; जननी = अम्बा ; सुतं = पुत्रं ; विरलं = कञ्चिदेव, स्वल्पमेव ; जनयति = प्रसूते ; ॥१.३४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः जीवने अभिवृद्धिकाले गर्वं न प्राप्नोति, आपत्काले पीडां नानुभवति, युद्धे धैर्यगुणं न मुञ्चति-- तादृशं पुत्रं माता बहु अल्पं प्रसूते (एतादृशानां जननम् अधिकं न भवति। लोके अल्पसङ्ख्याकास्ते।) ॥१.३४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिसको सम्पत्ति में विशेष हर्ष न हो, विपत्ति में विषाद न हो, युद्ध में धीरता हो- ऐसे भुवनत्रय के तिलकस्वरूप पुत्र को विरली ही मातायें उत्पन्न करती हैं ॥१.३४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.34.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="135" class="total">
                    <div>
                        <button id="moolamsmall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '135')">मूलम्</button>
                        <button id="padasmall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '135')">पदविभागः</button>
                        <button id="anvayasmall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '135')">अन्वयः</button>
                        <button id="pratismall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '135')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '135')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '135')">हिन्द्यर्थः</button>
                        <button id="audiosmall135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '135')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>षड्दोषाः पुरुषेणेह हातव्या भूतिमिच्छता । निद्रा तन्द्रा भयं क्रोध आलस्यं दीर्घसूत्रता ॥१.३५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>षड्दोषाः पुरुषेणेह हातव्या भूतिमिच्छता । निद्रा तन्द्रा भयं क्रोध आलस्यं दीर्घसूत्रता ॥१.३५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>भूतिम् इच्छता पुरुषेण इह षड्-दोषाः हातव्याः -- (ते एवं सन्ति) निद्रा, तन्द्रा, भयं, क्रोधः, आलस्यं, दीर्घ-सूत्रता (चेति) ॥१.३५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>षड्-दोषाः = तत्सङ्ख्याविशेषकाः अपाराधाः ; भूतिम् = अष्टैश्वर्यम् ; इच्छता = वाञ्छता ; पुरुषेण ; हातव्याः = परित्याज्याः ; तन्द्रा = प्रमीला, निद्रेव नीरसभावः ; आलस्यं = अलसत्वं ; दीर्घसूत्रता = चिरक्रियता ; 'दीर्घसूत्रश्चिरक्रियः' इत्यमरः ॥१.३५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः अभिवृद्धिम् आकाङ्क्षति, तेन षट् अपराधा न कार्याः- (अधिक)निद्रा, नीरसभावः, भीतिः, कोपः, अलसत्वं, कार्यातिक्षेपः चेति ॥१.३५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>निद्रा (अधिक सोना, तन्द्रा (ऊँघना) डर, क्रोध, आलस्य, दीर्घसूत्रता (थोड़े समय में होने लायक काम को बहुत देर में करना), इन सब दोषों को अपनी उन्नति चाहनेवाले पुरुषों को छोड़ देना चाहिये ॥१.३५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.35.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="136" class="total">
                    <div>
                        <button id="moolamsmall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '136')">मूलम्</button>
                        <button id="padasmall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '136')">पदविभागः</button>
                        <button id="anvayasmall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '136')">अन्वयः</button>
                        <button id="pratismall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '136')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '136')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '136')">हिन्द्यर्थः</button>
                        <button id="audiosmall136" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '136')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अल्पानामपि वस्तूनां संहतिः कार्यसाधिका । तृणैर्गुणत्वमापन्नैर्बध्यन्ते मत्तदन्तिनः ॥१.३६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अल्पानाम् अपि वस्तूनां संहतिः कार्य-साधिका । तृणैः गुणत्वम् आपन्नैः बध्यन्ते मत्त-दन्तिनः ॥१.३६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अल्पानाम् अपि वस्तूनां संहतिः कार्य-साधिका । गुणत्वम् आपन्नैः तृणैः मत्त-दन्तिनः बध्यन्ते ॥१.३६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अल्पानां = स्वल्पानाम्, निर्बलानामपि ; वस्तूनां = द्रव्याणां ; संहतिः = सङ्घः ; कार्यसाधिका = लक्ष्यसिद्धौ सहायिका ; तृणैः = घासैः ; गुणत्वमापन्नैः = संहत्या रज्जुत्वं प्राप्तैः ; मत्तदन्तिनः = मदोन्मत्ता गजेन्द्रा अपि ; बध्यन्ते = बन्धने स्थाप्यन्ते ॥१.३६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अविशेषाणां वस्तूनामपि सङ्घीभवनेन (तेषां ह्रस्वत्वभावः निर्गच्छति, ततश्च) उन्नतं लक्ष्यमपि सुसाध्यं भवति। अत्रोदाहरणम्- मदयुक्ता गजाः (बलवन्तः सन्तः) अपि (अत्यल्पबलयुक्तानां) घासांशानां संयोजनेन या रज्जुः निर्मीयते तया बध्यन्ते ॥१.३६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>छोटी छोटी वस्तु भी एक साथ मिलने पर कार्य साधक हो जाती है । देखो-तृण (घासफूस) भी जब एकत्र होकर रस्सी बन जाते हैं, तब बड़े बड़े हस्तियों को भी बाँध सकते हैं ॥१.३६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.36.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="137" class="total">
                    <div>
                        <button id="moolamsmall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '137')">मूलम्</button>
                        <button id="padasmall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '137')">पदविभागः</button>
                        <button id="anvayasmall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '137')">अन्वयः</button>
                        <button id="pratismall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '137')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '137')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '137')">हिन्द्यर्थः</button>
                        <button id="audiosmall137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '137')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>संहतिः श्रेयसी पुंसां स्वकुलैरल्पकैरपि । तुषेणापि परित्यक्ता न प्ररोहन्ति तण्डुलाः ॥१.३७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>संहतिः श्रेयसी पुंसां स्वकुलैः अल्पकैः अपि । तुषेण अपि परित्यक्ता न प्ररोहन्ति तण्डुलाः ॥१.३७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पुंसां स्वकुलैः अल्पकैः अपि संहतिः श्रेयसी । तुषेण अपि परित्यक्ता तण्डुलाः न प्ररोहन्ति ॥१.३७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>संहतिः = समूहः, सङ्घः ; श्रेयसी = कल्याणप्रदा ; अल्पकैरपि = स्वल्पबलैरपि सह, तुच्छैरपि ; स्वकुलैः = स्ववंश्यैः, तुषेणापि परित्यक्ताः = धान्यत्वचा हीनाः ; तण्डुलाः = धान्यकणाः ; न प्ररोहन्ति = अङ्कुरिता न भवन्ति ॥१.३७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्याणां स्ववंश्य-जनैः सह सङ्घीभावः शुभप्रदः। (सङ्गीभावस्य विरहे का दशा भवतीति उदाहरणमुच्यते) धान्यत्वचा वियुक्तानि तण्डुलबीजानि (पुनः भूम्याम् उप्तानि) न अङ्कुरीभवन्ति। (पुनरुत्पत्तौ असमर्थानि भवन्ति) ॥१.३७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और अपने कुल के छोटे छोटे लोगों की भी संगति अच्छी होती है । देखो, चावल भी अपने छिलके (भूसी) से अलग होने पर उग ही नहीं सकते हैं (अङ्कुरित नहीं हो सकते हैं) ॥१.३७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.37.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="139" class="total">
                    <div>
                        <button id="moolamsmall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '139')">मूलम्</button>
                        <button id="padasmall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '139')">पदविभागः</button>
                        <button id="anvayasmall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '139')">अन्वयः</button>
                        <button id="pratismall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '139')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '139')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '139')">हिन्द्यर्थः</button>
                        <button id="audiosmall139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '139')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>माता मित्रं पिता चेति स्वभावात् त्रितयं हितम् । कार्यकारणतश्चान्ये भवन्ति हितबुद्धयः ॥१.३९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>माता मित्रं पिता च इति स्वभावात् त्रितयं हितम् । कार्य-कारणतः च अन्ये भवन्ति हित-बुद्धयः ॥१.३९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>माता मित्रं पिता च इति स्वभावात् त्रितयं हितम् । अन्ये च कार्य-कारणतः हित-बुद्धयः भवन्ति ॥१.३९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>माता = जननी ; पिता = जनकः ; मित्रं = सुहृत् ; स्वभावात् = प्रकृत्यैव ; त्रितयं = एते त्रयः ; हितं = हितकारकम् ; अन्ये तु = एतत्-त्रितयातिरिक्तास्तु ; कार्यकारणतः = कार्यकारण-प्रसङ्गेनैव ; किमपि कार्यं, कारणं वा उद्दिश्यैव ; हितबुद्धयः = हितकारकाः भवन्ति ॥१.३९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पितरौ, सखा चेति त्रयः प्रकृत्या श्रेयस्कराः भवन्ति। एतान् विहाय अन्यजनाः यं कमपि लाभं मनसि निधाय शुभचिन्तका भवन्ति ॥१.३९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>माता पिता और मित्र ये तीनों स्वभाव ही से हित चाहते हैं, परन्तु दूसरे लोग तो कार्यवश ही हितेषी हुआ करते हैं ॥१.३९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.39.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="140" class="total">
                    <div>
                        <button id="moolamsmall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '140')">मूलम्</button>
                        <button id="padasmall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '140')">पदविभागः</button>
                        <button id="anvayasmall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '140')">अन्वयः</button>
                        <button id="pratismall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '140')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '140')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '140')">हिन्द्यर्थः</button>
                        <button id="audiosmall140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '140')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यस्य मित्रेण सम्भाषो यस्य मित्रेण संस्थितिः । यस्य मित्रेण संलापस्ततो नास्तीह पुण्यवान् ॥१.४०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्य मित्रेण सम्भाषः यस्य मित्रेण संस्थितिः । यस्य मित्रेण संलापः ततः न अस्ति इह पुण्यवान् ॥१.४०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य मित्रेण सम्भाषः, यस्य मित्रेण संस्थितिः, यस्य मित्रेण संलापः (च) ततः पुण्यवान् इह न अस्ति ॥१.४०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य मित्रेण = सुहृदा सह ; सम्भाषः = आलापः ; संस्थितिः = सहावस्थानम्., सहवासः ; संलापः = मुहुर्मुहः कथा, गोष्ठीबन्धः ; ततः = तदपेक्षया ; इह जगति ; पुण्यवान् = सुकृती ॥१.४०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः नित्यं सख्या आलपते, सह तिष्ठति, वार्तालापरतो भवति, ततः भाग्यवान् नरः न भवति अन्यः ॥१.४०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो अपने मित्र के साथ सम्भाषण (मधुर भाषण) करता है और जो अपने मित्र के साथ रहता है और जो अपने मित्र के साथ प्रेम पूर्वक 'वार्तालाप करता है, उससे बढ़कर इस पुण्यवान् संसार में दूसरा कोई नहीं है ॥१.४०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.40.m4a" type="audio/mp4">
