                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="141" class="total">
                    <div>
                        <button id="moolamsmall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '141')">मूलम्</button>
                        <button id="padasmall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '141')">पदविभागः</button>
                        <button id="anvayasmall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '141')">अन्वयः</button>
                        <button id="pratismall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '141')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '141')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '141')">हिन्द्यर्थः</button>
                        <button id="audiosmall141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '141')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यस्माच्च येन च यथा च यदा च यच्च यावच्च यत्र च शुभाशुभमात्मकर्म । तस्माच्च तेन च तथा च तदा च तच्च तावच्च तत्र च विधातृवशादुपैति ॥१.४१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्मात् च येन च यथा च यदा च यत् च यावत् च यत्र च शुभ-अशुभम् आत्मकर्म । तस्मात् च तेन च तथा च तदा च तत् च तावत् च तत्र च विधातृ-वशाद् उपैति ॥१.४१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्मात् च येन च यथा च यदा च यत् च यावत् च यत्र च शुभ-अशुभम् आत्मकर्म । तस्मात् च तेन च तथा च तदा च तत् च तावत् च तत्र च विधातृ-वशाद् उपैति ॥१.४१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्माद्धेतोः, येन-करणेन हस्तादिना, यथा च = येन च प्रकारेण ; यदा च = यस्मिन् काले च, यत्-शुभाशुभशुभम् अशुभं वा ; आत्मकर्म = स्वस्य पापपुण्य-सुखदुःखादिकं ; यावत् = यावन्मितं ; यत्र =यस्मिन्देशे च भावि ; तत् = तस्मात् कारणात् ; तेनैव = उपकरणेन, तथा तेनैव प्रकारेण ; तदा च = तस्मिन्नेव काले च ; तच्च = तत्फलम् ; तावच्च = तावत् प्रमाणमेव ; तत्रैव देशे ; विधातृवशात् = भाग्यवशात् ; उपैति = शुभाशुभमात्मफलं स्वयमेव नरमुपयाति ॥१.४१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जीवः- १. येन कारणेन, २. येनोपायेन, ३. येन विधानेन, ४. यस्मिन् काले, ५. यस्मिन् देशे, ६. यत्स्वरूपकं, ७. यत्प्रमाणकं च, -पापमथवा पुण्यकर्म आचरति, तस्य फलमपि तत्कारणकं, तदुपायकं, तद्विधानकं, तत्कालकं, तद्देशकं, तत्प्रमाणकं, तथैव च भवति ॥१.४१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>पुण्य अथवा पाप कर्म जिस कारण से, जिस उपाय से, जिस प्रकार से, जिस समय मे, जैसा, जितना, जिस स्थान पर करता है, वह प्राणी उसी कारण से, उसी उपाय से, उसी प्रकार से, उसी समय, वैसा ही, उतना ही, उसी स्थान पर, उस पापपुण्य के फल को अवश्य ही (भाग्यवश) पाता है ॥१.४१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.41.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="142" class="total">
                    <div>
