                        <button id="padasmall142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '142')">पदविभागः</button>
                        <button id="anvayasmall142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '142')">अन्वयः</button>
                        <button id="pratismall142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '142')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '142')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '142')">हिन्द्यर्थः</button>
                        <button id="audiosmall142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '142')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>रोगशोकपरीतापबन्धनव्यसनानि च । आत्मापराधवृक्षाणां फलान्येतानि देहिनाम् ॥१.४२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रोग-शोक-परीताप-बन्धन-व्यसनानि च । आत्मा-अपराध-वृक्षाणां फलानि एतानि देहिनाम् ॥१.४२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>एतानि देहिनाम् आत्मा-अपराध-वृक्षाणां फलानि (भवन्ति)-- रोग-शोक-परीताप-बन्धन-व्यसनानि च (इति) ॥१.४२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>देहिनां = शरीरिणाम् ; परीतापः = सन्तापः ; बन्धनं = कारादि-प्राप्तिः ; तान्येव- व्यसनानि = विपत्तयः ; तानि च-- आत्मापराधवृक्षाणां ~आत्मना कृताः अपराधाः, ते एव वृक्षाः तेषाम्-- अपराधाः = पापानि ; वृक्षाणां = स्वकर्म-वृक्षाणां, फलानि = फलभूतान्येव [स्वकृतैरेव पापैर्दुःखानि जनो लभते, नान्यैरिति भावः] ॥१.४२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>आतुरता, हृत्पीडा, पश्चात्तापः, निर्बन्धः, दुःखकालाश्च प्राणिनां स्वयमाचरितानाम् अकार्याणां परिणामत्वेन सम्भवन्ति ॥१.४२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>रोग, शोक, सन्ताप, बन्धन, विपत्ति, ये सब मनुष्य के अपने किए हुए अपराध (पाप) रूपी वृक्ष के ही फल हैं ॥१.४२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.42.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="143" class="total">
                    <div>
                        <button id="moolamsmall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '143')">मूलम्</button>
                        <button id="padasmall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '143')">पदविभागः</button>
                        <button id="anvayasmall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '143')">अन्वयः</button>
                        <button id="pratismall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '143')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '143')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '143')">हिन्द्यर्थः</button>
                        <button id="audiosmall143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '143')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आपदर्थे धनं रक्षेद् दारान् रक्षेद्धनैरपि । आत्मानं सततं रक्षेद्दारैरपि धनैरपि ॥१.४३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आपद्-अर्थे धनं रक्षेद् दारान् रक्षेद् धनैः अपि । आत्मानं सततं रक्षेद् दारैः अपि धनैः अपि ॥१.४३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आपद्-अर्थे धनं रक्षेद् दारान् रक्षेद् धनैः अपि । आत्मानं सततं रक्षेद् दारैः अपि धनैः अपि ॥१.४३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आपदर्थे = आपत्प्रतीकाराय ; रक्षेत् = अर्जयेत्, निभृतं स्थापयेत् ; दारान् = कलत्रम् ; धनैः = धनदानादिभिः ; रक्षेत् = गोपायेत् ; आत्मानं = स्वशरीरन्तु ; दारैरपि = पत्न्यपेक्षयापि ; धनैरपि = धनापेक्षयापि च, तद्व्ययेनापि च ; रक्षेत् = पालयेत् ॥१.४३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कदाचित् भविष्यत्काले विपत्तिस्थितिः सम्भवेदिति धिया किञ्चित् धनम् उपयोगार्थं निकटे स्थापनीयम्। धनस्यापेक्षया पत्न्याः रक्षणं कार्यमथवा समये आपतिते वित्तेन भार्या रक्षणीया। ततश्च यदा आत्मनः विपत्कालः आपतेत्, तदानीं धनपत्न्योरपेक्षया, अथवा भार्यया, धनेन च स्वस्य रक्षणं करणीयम् ॥१.४३ ॥🌹</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>आपत्तिकाल के लिये धन की रक्षा करनी चाहिए, और धन को खर्च कर के भी स्त्री को रक्षा करनी चाहिए, और स्त्री और धन दोनों से भी (उनकी चिन्ता छोडकर, या उनको देकर भी) सदा अपनी रक्षा करनी चाहिए ॥१.४३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.43.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="144" class="total">
                    <div>
                        <button id="moolamsmall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '144')">मूलम्</button>
                        <button id="padasmall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '144')">पदविभागः</button>
                        <button id="anvayasmall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '144')">अन्वयः</button>
                        <button id="pratismall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '144')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '144')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '144')">हिन्द्यर्थः</button>
                        <button id="audiosmall144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '144')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धर्मार्थकाममोक्षाणां प्राणाः संस्थितिहेतवः । तान् निघ्नता किं न हतं रक्षता किं न रक्षितम् ॥१.४४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धर्मार्थ-काम-मोक्षाणां प्राणाः संस्थिति-हेतवः । तान् निघ्नता किं न हतं रक्षता किं न रक्षितम् ॥१.४४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्राणाः धर्मार्थ-काम-मोक्षाणां संस्थिति-हेतवः । तान् निघ्नता किं न हतम् ? रक्षता किं न रक्षितम्? ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्राणाः धर्मार्थ-काम-मोक्षाणां संस्थिति-हेतवः । तान् निघ्नता किं न हतम् ? रक्षता किं न रक्षितम्? ॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(शरीरस्य धारणे ये हेतवः ते) प्राणाः एव धर्मादि-पुरुषार्थ-चतुष्टयस्य संस्थापनेऽपि कारणम्। पुरुषः प्राणान् हत्वा सर्वं हन्ति, प्राणान् ऊत्वा (अव्+त्वा) सर्वम् अवति ॥१.४४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- धर्म, अर्थ, काम, मोक्ष, इन चारों पुरुषार्थों के मूल कारण प्राण ही हैं । अतः जिसने अपने प्राणों का नाश किया उसने किस चीज का नाश नहीं किया? अर्थात् सबका नाश किया । और जिसने उन प्राणों की रक्षा की तो उसने किसकी रक्षा नहीं की? । अर्थात् सबकी रक्षा की ॥१.४४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.44.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="145" class="total">
                    <div>
                        <button id="moolamsmall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '145')">मूलम्</button>
                        <button id="padasmall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '145')">पदविभागः</button>
                        <button id="anvayasmall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '145')">अन्वयः</button>
                        <button id="pratismall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '145')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '145')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '145')">हिन्द्यर्थः</button>
                        <button id="audiosmall145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '145')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धनानि जीवितञ्चैव परार्थे प्राज्ञ उत्सृजेत् । सन्निमित्ते वरं त्यागो विनाशे नियते सति ॥१.४५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धनानि जीवितं च एव परार्थे प्राज्ञः उत्सृजेत् । सन्निमित्ते वरं त्यागः विनाशे नियते सति ॥१.४५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्राज्ञः धनानि जीवितं च एव परार्थे उत्सृजेत् । विनाशे नियते सति सन्निमित्ते त्यागः वरम् ॥१.४५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्राज्ञः = विद्वान् ; जीवितं = प्राणान् ; परार्थे = परोपकाराय ; उत्सृजेत् = दद्यात् ; विनाशे = मरणे ; नियते = निश्चिते सति ; सन्निमित्ते = सत्कार्यसिद्धये, परोपकाराय ; त्यागः = प्राणपरित्यागः ; वरं = किञ्चित् श्रेष्ठः ॥१.४५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>बुधजनः परेषामुपयोगाय वित्तं जीवनं चार्पयति। नाशनमेव यदि (अशाश्वतेऽस्मिन्) लोके नियमः भवति, तर्हि सत्कार्याचरणार्थं धनप्राणयोः उपयोगः एव श्रेष्ठः ॥१.४५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>किसी ने ठीक ही कहा है, कि- विद्वान् लोगों को अपने धन तथा प्राणों को स्वरों के उपकार के लिए समर्पण कर देना चाहिए । क्यों कि जब उन प्राणों का और धन का नाश होना निश्चित ही है, तो उन्हें सदुपयोग में लगा देना ही अच्छा है ॥१.४५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.45.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="147" class="total">
                    <div>
                        <button id="moolamsmall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '147')">मूलम्</button>
                        <button id="padasmall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '147')">पदविभागः</button>
                        <button id="anvayasmall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '147')">अन्वयः</button>
                        <button id="pratismall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '147')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '147')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '147')">हिन्द्यर्थः</button>
                        <button id="audiosmall147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '147')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>विना वर्तनमेवैते न त्यजन्ति ममान्तिकम् । तन्मे प्राणव्ययेनापि जीवयैतान् ममाश्रितान् ॥१.४७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विना वर्तनमेवैते न त्यजन्ति ममान्तिकम् । तन्मे प्राणव्ययेनापि जीवयैतान् ममाश्रितान् ॥१.४७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>एते वर्तनं विना एव न मम अन्तिकं न त्यजन्ति । तत् एतान् मम आश्रितान् मे प्राण-व्ययेन अपि जीवय ॥१.४७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वर्त्तनं = जीविकां, वेतनं ; विनैव = (वेतनादिग्रहणं) विनाऽपि ; मम अन्तिकं = मत्सान्निध्यं ; न त्यजन्ति = न परिहरन्ति ; तत् = तस्मात् ; प्राण-व्ययेनापि = मत्प्राणोपयोगेन अपि ; जीवय = पाशच्छेदेन एनान् परिपालय ॥१.४७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(कपोतानां कथायां मूषकेन कपोत राजा इत्थं वदति-) एतेभ्यः कपोतेभ्यः मासिकभृतिः कापि न दीयते, तथापि एते सदा मम सन्निधावेव वसन्ति, मां न परित्यजन्ति। अतः मम प्राणः अपगच्छेत् तथापि इमान् मम अधीने स्थितान् पूर्वं रक्ष- इति ॥१.४७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- विना किसी प्रकार की जीविका और वेतन के भी ये मेरा साथ नहीं छोडते हैं, इसलिये मेरे प्राणों की पर्वाह न करके भी आप पहिले इन (मेरे आश्रितों) को ही बचाइए ॥१.४७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.47.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="148" class="total">
                    <div>
                        <button id="moolamsmall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '148')">मूलम्</button>
                        <button id="padasmall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '148')">पदविभागः</button>
                        <button id="anvayasmall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '148')">अन्वयः</button>
                        <button id="pratismall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '148')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '148')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '148')">हिन्द्यर्थः</button>
                        <button id="audiosmall148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '148')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मांसमूत्रपुरीषास्थिपूरितेऽस्मिन् कलेवरे । विनश्वरे विहायास्थां यशः पालय मित्र मे ॥१.४८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मांस-मूत्र-पुरीष-अस्थि-पूरिते अस्मिन् कलेवरे । विनश्वरे विहाय आस्थां यशः पालय मित्र मे ॥१.४८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मित्र, अस्मिन् मांस-मूत्र-पुरीष-अस्थि-पूरिते विनश्वरे कलेवरे, आस्थां विहाय मे यशः पालय ॥१.४८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मित्र = हे सुहृत् ; मांसं = पिशितम् ; मूत्रं = मेहनम् ; पुरीषं = विष्ठा ; अस्थि = कीकसम् ; निर्मिते = विरचिते, परिपूर्णे च ; विनश्वरे = विनाशशीले ; कलेवरे = शरीरे ; आस्थां = आलम्बनं, आदरं वा ; मे यशः = मम कीर्तिम् ; पालय = रक्ष ; ॥१.४८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे सखे, कायः विण्मूत्रादिना निर्मितः अशाश्वतः। अतः त्वं (तत् परित्यज्य) मम अपेक्षां विहाय (शाश्वतस्थायिनं) ख्यातिं अव ॥१.४८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- हे मित्र! माँस, मूत्र, विष्ठा, हड्डी आदि से बने हुए मेरे इस नाश-शील शरीर के बचाने की इच्छा को लोक में आप मेरी कीर्ति की ही रक्षा करो ॥१.४८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.48.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="149" class="total">
                    <div>
                        <button id="moolamsmall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '149')">मूलम्</button>
                        <button id="padasmall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '149')">पदविभागः</button>
                        <button id="anvayasmall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '149')">अन्वयः</button>
                        <button id="pratismall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '149')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '149')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '149')">हिन्द्यर्थः</button>
                        <button id="audiosmall149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '149')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यदि नित्यमनित्येन निर्मलं मलवाहिना । यशः कायेन लभ्येत तन्न लब्धं भवेन् नु किम् ॥१.४९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यदि नित्यम् अनित्येन निर्मलं मलवाहिना । यशः कायेन लभ्येत तत् न लब्धं भवेत् नु किम् ॥१.४९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यदि नित्यं, निर्मलं, यशः- अनित्येन, मलवाहिना, कायेन- लभ्येत तत् (तर्हि) न लब्धं किम् नु भवेत् ? ॥१.४९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नित्यं = चिरस्थायि ; निर्मलं = स्वच्छम् ; यशः = कीर्तिः ; अनित्येन = नश्वरेण ; मलवाहिना = मलमूत्रपरिपूर्णेन ; कायेन = शरीरेण ; तत्र 'नु'-इति वितर्के । किं लब्धं न भवेत् = सर्वमेव लब्धं भवेदित्यर्थः ॥१.४९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदि शाश्वती, मलरहिता कीर्तिः, अशाश्वतकेन, दूषितेन देहेन (तन्माध्यमेन) लभ्यते, तर्हि न किमपि अप्राप्तं शिष्यते। (सर्वमेव लब्धमिति यावत्।) ॥१.४९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अनित्य और सूत्र विष्ठा आदि मलों को वहन करने वाले शरीर के बदले में यदि निर्मल और नित्य यश मिले, तो फिर कहो क्या नहीं मिला? । अथपि सब कुछ मिल गया ॥१.४९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.49.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="150" class="total">
                    <div>
                        <button id="moolamsmall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '150')">मूलम्</button>
                        <button id="padasmall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '150')">पदविभागः</button>
                        <button id="anvayasmall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '150')">अन्वयः</button>
                        <button id="pratismall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '150')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '150')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '150')">हिन्द्यर्थः</button>
                        <button id="audiosmall150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '150')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शरीरस्य गुणानां च दूरमत्यन्तमन्तरम् । शरीरं क्षणविध्वंसि कल्पान्तस्थायिनो गुणाः ॥१.५०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शरीरस्य गुणानां च दूरम् अत्यन्तम् अन्तरम् । शरीरं क्षण-विध्वंसि कल्पान्त-स्थायिनः गुणाः ॥१.५०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शरीरस्य गुणानां च अन्तरम् अत्यन्तं दूरम् । शरीरं क्षण-विध्वंसि । गुणाः कल्पान्त-स्थायिनः ॥१.५०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शरीरस्य = देहस्य ; अत्यन्तं दूरं = नितरां विप्रकृष्टम् ; अन्तरं = प्रभेदः ; क्षणविध्वंसि = अचिरविनाशि, क्षणभङ्गुरम् ; गुणाः = दयादाक्षिण्यादयः, यश इति यावत् । कल्पान्तस्थायिनः = प्रलयपर्यन्तस्थायिनः ॥१.५०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>देहस्य गुणानां च मध्ये भेदः महान्। कायः अविलम्बेन विनश्यति। गुणास्तु सृष्टिविलयं यावत् तिष्ठन्ति ॥१.५०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि- शरीर में और गुणों में बहुत बडा भेद है, शरीर तो क्षण ही में नष्ट हो जाता हैं, परन्तु गुण प्रलय काल तक रहते हैं ॥१.५०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.50.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="151" class="total">
                    <div>
                        <button id="moolamsmall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '151')">मूलम्</button>
                        <button id="padasmall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '151')">पदविभागः</button>
                        <button id="anvayasmall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '151')">अन्वयः</button>
                        <button id="pratismall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '151')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '151')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '151')">हिन्द्यर्थः</button>
                        <button id="audiosmall151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '151')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>योऽधिकाद् योजनशतात् पश्यतीहामिषं खगः । स एव प्राप्तकालस्तु पाशबन्धं न पश्यति ॥१.५१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यः अधिकाद् योजन-शतात् पश्यति इह आमिषं खगः । सः एव प्राप्त-कालः तु पाशबन्धं न पश्यति ॥१.५१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः खगः योजन-शतात् अधिकाद् इह आमिषं पश्यति, सः एव प्राप्त-कालः तु पाशबन्धं न पश्यति ॥१.५१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>खगः = गृध्रादिः ; योजनशताद् अपि अधिकात् = शतमपि योजनानां पारे ; आमिषं = स्वभक्ष्यं मांसं ; पश्यति = (अत्र) द्रष्टुं शक्नोति ; स एव = दूरदृष्टिः खगः; प्राप्त-कालः = आसन्नमृत्युः सन् ; पाशबन्धं = जालं ; न पश्यति = नैव लक्षयति ॥१.५१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः पक्षी शताधिकयोजनदूरात् खाद्यपदार्थं मांसं द्रष्टुं शक्नोति, स एव मुत्यौ समीपे स्थिते सति (समीपस्थं) जालं न पश्यति ॥१.५१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि--जो यज्ञ आदि पक्षी, सौ योजन (४०० कोश) से अधिक की दूरी से भी माँस को देख सकता है, वही पक्षी बुरा समय आने पर अपने फँसाने के लिए बिछाये गए जाल को भी नहीं देखता है और उसमें फँसकर अपने प्राण देदेता है ॥१.५१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.51.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="152" class="total">
                    <div>
                        <button id="moolamsmall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '152')">मूलम्</button>
                        <button id="padasmall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '152')">पदविभागः</button>
                        <button id="anvayasmall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '152')">अन्वयः</button>
                        <button id="pratismall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '152')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '152')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '152')">हिन्द्यर्थः</button>
                        <button id="audiosmall152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '152')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शशिदिवाकरयोर्ग्रहपीडनं गजभुजङ्गमयोरपि बन्धनम् । मतिमतां च विलोक्य दरिद्रतां विधिरहो बलवान् इति मे मतिः ॥१.५२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शशि-दिवाकरयोः ग्रहपीडनं गज-भुजङ्गमयोः अपि बन्धनम् । मतिमतां च विलोक्य दरिद्रतां विधिः अहो बलवान् इति मे मतिः ॥१.५२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शशि-दिवाकरयोः ग्रहपीडनं, गज-भुजङ्गमयोः अपि बन्धनम् । मतिमतां च दरिद्रतां विलोक्य “अहो, विधिः बलवान्” इति मे मतिः ॥१.५२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शशिदिवाकरयोः = सूर्यचन्द्रमसोः । ग्रहपीडनं = राहुणा ग्रहणम् ; गजभुजङ्गमयोः = हस्तिसर्पयोः ; बन्धनं = निग्रहं च ; विलोक्य = दृष्ट्वा ; च = पुनः ; मतिमतां = विदुषां ; दरिद्रतां = दारिद्र्यं च ; विलोक्य = दृष्ट्वा ; अहो = इति आश्चर्ये, खेदे वा ; विधिः = दैवं ; बलवान् = अनिवार्यम् इति ; मे = मम ; मतिः = निश्चयः ; 'ग्रहः, सूर्यादौ पूतनादौ च सैंहिकेयोपरागयोरिति मेदिनी ; ॥१.५२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दिनकर-निशाकरयोः (राहु)ग्रहेण ग्रसनं, नागद्वयोः (करिणः, भुजगस्य च ) (व्याधेन) निर्बन्धनं, पण्डितानां धनहीनता च— एतत् त्रितयं दृष्ट्वा (स्थितः अहं) ‘विधिः बलीयः’ इति निश्चिनोमि ॥१.५२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योंकि-- और भी--चन्द्रमा और सूर्य को ग्रहण की पीडा, अर्थात् ग्रहण लगना, हाथों और साँपों का बन्धन,पण्डितों की भी दरिद्रता, इन सब बातों को देखकर मैं तो समझता हूँ कि भाग्य ही सबसे प्रबल है ॥१.५२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.52.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="153" class="total">
                    <div>
                        <button id="moolamsmall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '153')">मूलम्</button>
                        <button id="padasmall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '153')">पदविभागः</button>
                        <button id="anvayasmall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '153')">अन्वयः</button>
                        <button id="pratismall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '153')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '153')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '153')">हिन्द्यर्थः</button>
                        <button id="audiosmall153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '153')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>व्योमैकान्तविहारिणोऽपि विहगाः सम्प्राप्नुवन्त्यापदं  बध्यन्ते निपुणैरगाधसलिलात् मत्स्याः समुद्रादपि । दुर्नीतं किमिहास्ति किं सुचरितं कः स्थानलाभे गुणः कालो हि व्यसनप्रसारितकरो गृह्णाति दूरादपि ॥१.५३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>व्योम-एकान्त-विहारिणः अपि विहगाः सम्प्राप्नुवन्ति आपदं बध्यन्ते निपुणैः अगाध-सलिलात् मत्स्याः समुद्राद् अपि । दुर्नीतं किम् इह अस्ति किं सुचरितं कः स्थानलाभे गुणः कालः हि व्यसन-प्रसारित-करः गृह्णाति दूराद् अपि ॥१.५३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विहगाः व्योम-एकान्त-विहारिणः अपि आपदं सम्प्राप्नुवन्ति । मत्स्याः अगाध-सलिलात् समुद्राद् अपि निपुणैः बध्यन्ते । इह दुर्नीतं किम् अस्ति? किं सुचरितं (अस्ति)? कः स्थानलाभे गुणः (अस्ति)? व्यसन-प्रसारित-करः कालः हि दूराद् अपि गृह्णाति ॥१.५३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विहगाः = पक्षिणः ; व्योमैकान्त-विहारिणः अपि = दूरतर-गगनाङ्गण-विहारिणः अपि ; आपदं = प्राणसङ्कटं, जालबन्धनादि-विपदम् ; सम्प्राप्नुवन्ति = लभन्ते ; निपुणैः = कुशलैः ; अगाध-सलिलात् = अतल-स्पर्शिजल-पूर्यात् ; समुद्रादपि = सागरादपि ; मत्स्याः = मीनाः ; बध्यन्ते = जलात् अपनीय गृह्यन्ते ; लौकैरिति शेषः ; दुर्नीतं = दुश्चरितं ; सुचरितं = शोभनम् आचरणं वा- किम्? । स्थानलाभे = दुर्धर्ष-निरापद-दुरासद-दुर्गम-स्थानलाभे वा ; को गुणः = किं फलम्? ; कालः = मृत्युः ; व्यसन-प्रसारितकरः = विपदवसरे करौ प्रसार्य इव ; दूरादपि = दुर्गमादपि स्थानात् ; गृह्णाति = आदत्ते ॥१.५३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पक्षिणः दूरे गगने डयमाना अपि सङ्कटे पतन्ति । अगाधे वारिनिधौ स्थिता अपि मीनाः धीवरैः प्रसारितैः जालैः निर्बध्यन्ते । इह लोके किं साधु, किमसाधु? अत्यन्तं योग्यस्थानप्राप्त्या किम्? मृत्युः दूरादपि विपत्तिरूपेण आगत्य करौ विस्तीर्य (अस्मान् अवश्यं) धरति ॥१.५३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>आकाश के एकान्त और अत्युच्च प्रदेश में विहार करने वाले पक्षी भी आपत्ति में फँस जाते हैं । चतुर लोग अथाह जल वाले समुद्र से भो मछलियों को पकड़ लेते हैं । इसलिये इस संसार में क्या अच्छा है? और क्या बुरा है? और क्या योग्य स्थान की प्राप्ति में भी लाभ है? अर्थात् कुछ नहीं । क्यों कि कालरूपी शत्रु व्यसन (विपत्ति) रूपी हाथ पसारे बैठा है, और वह मौका पाते ही दूर से भी प्राणियों को पकड़ लेता है ॥१.५३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.53.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="154" class="total">
                    <div>
                        <button id="moolamsmall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '154')">मूलम्</button>
                        <button id="padasmall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '154')">पदविभागः</button>
                        <button id="anvayasmall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '154')">अन्वयः</button>
                        <button id="pratismall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '154')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '154')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '154')">हिन्द्यर्थः</button>
                        <button id="audiosmall154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '154')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यानि कानि च मित्राणि कर्त्तव्यानि शतानि च ।  पश्य मूषिकमिज्रेण कपोता मुक्तवन्धनाः ॥१.५४॥ यानि कानि च मित्राणि कर्त्तव्यानि शतानि च । पश्य, मूषिक-मित्रेण कपोताः मुक्तबन्धनाः ॥१.५४॥ यानि कानि च मित्राणि कर्त्तव्यानि शतानि च, पश्य मूषिक-मित्रेण कपोताः मुक्तबन्धनाः ॥१.५४॥ यानि कानि=निर्बलानि, सबलानि बा, योग्यानि, अयोग्यानि वा । शतानिध असङ्ख्यातानि । (सैकहो) । मुक्तबन्धनाः कृताः ॥१.५४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td></td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td></td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>इसलिए मनुष्य को सभी प्रकार के अपने बहुत से मित्र करने चाहिये । देखो चित्रग्रीव के मित्र चूहेने कधूतरो को बन्धन से क्रुद्धा दिया या ॥१.५४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.54.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="155" class="total">
                    <div>
                        <button id="moolamsmall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '155')">मूलम्</button>
                        <button id="padasmall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '155')">पदविभागः</button>
                        <button id="anvayasmall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '155')">अन्वयः</button>
                        <button id="pratismall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '155')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '155')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '155')">हिन्द्यर्थः</button>
                        <button id="audiosmall155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '155')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यद्येन युज्यते लोके बुधस्तत् तेन योजयेत् । अहमन्नं भवान् भोक्ता कथं प्रीतिर्भविष्यति ॥१.५५॥ भक्ष्यभक्षयोः प्रीतिर्विपत्तेः कारणं मतम् ।</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् येन युज्यते लोके बुधः तत् तेन योजयेत् । अहम् अन्नं भवान् भोक्ता कथं प्रीतिः भविष्यति । भक्ष्य-भक्षयोः प्रीतिः विपत्तेः कारणं मतम् ॥१.५५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोके यद् येन युज्यते, बुधः तत् तेन योजयेत् । अहम् अन्नं (अस्मि), भवान् (तु) भोक्ता (अस्ति), (अतः) कथं प्रीतिः भविष्यति? भक्ष्य-भक्षयोः प्रीतिः विपत्तेः कारणं (इति) मतम् ॥१.५५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोके यद् येन युज्यते, बुधः तत् तेन योजयेत् । अहम् अन्नं (अस्मि), भवान् (तु) भोक्ता (अस्ति), (अतः) कथं प्रीतिः भविष्यति? भक्ष्य-भक्षयोः प्रीतिः विपत्तेः कारणं (इति) मतम् ॥१.५५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अस्मिन् संसारे प्रज्ञावान् योज्यवस्तूनि एव परस्परं योजयति, नान्यानि, विरुद्धानि वा। आवयोः सा स्थितिः नास्ति, यत् साम्यं लेशमपि भवेत्। भवतः अहं आहारोऽस्मि। भवान् मां खादति। कथं साध्यमिति यावत् । अतः आवयोः मिथः स्नेहभावः न युक्तः ॥१.५५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योंकि-पण्डित को चाहिये कि जिसके साथ मेल (मित्रता) हौ सकता है, उसके ही साथ मेल करे । परन्तु मैं तो आपका अन्न (भक्ष्य) हूँ और आप मेरे भक्षक हैं । भला हमारी तुमारी मित्रता कैसे हो सकती है? ॥१.५५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.55.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="158" class="total">
                    <div>
                        <button id="moolamsmall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '158')">मूलम्</button>
                        <button id="padasmall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '158')">पदविभागः</button>
                        <button id="anvayasmall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '158')">अन्वयः</button>
                        <button id="pratismall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '158')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '158')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '158')">हिन्द्यर्थः</button>
                        <button id="audiosmall158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '158')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तावद् भयस्य भेतव्यं यावद् भयमनागतम् । आगतं तु भयं वीक्ष्य नरः कुर्याद् यथोचितम् ॥१.५८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तावद् भयस्य भेतव्यं यावद् भयम् अनागतम् । आगतं तु भयं वीक्ष्य नरः कुर्याद् यथोचितम् ॥१.५८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यावद् भयम् अनागतं, तावद् भयस्य भेतव्यम् । आगतं भयं तु वीक्ष्य नरः यथोचितं कुर्यात् ॥१.५८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>भयस्य = भयजनकस्य चौरव्याघ्रादेः ; भेतव्यं = भीतिः कार्या ; भयं = भयप्रदं चोरव्याघ्रादिकम्, आगतम् = उपस्थितम् ; वीक्ष्य = दृष्ट्वा तु ; यथोचितं = यथायोग्यं तत्प्रतीकारोपायम् ; कुर्यात् = विदधीत ॥१.५८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धैर्यहारकं, भीतिजनकं च यद्यद् कारणं भवति, तस्य आगमनात् पूर्वमेव भीतिर्न कार्या। (तस्मात् प्राक् धैर्यं वोढव्यम् ।) तस्मिन् आगते सति सकृत् परिशील्य यद् योग्यं तत् कर्तव्यम् ॥१.५८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जब तक विपत्ति नहीं आये तभी तक उससे डरना चाहिये। पर यदि विपत्ति आ ही पड़े, तो मनुष्य को निर्भय होकर उसका यथोचित प्रतीकार करना चाहिए ॥१.५८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.58.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="159" class="total">
                    <div>
                        <button id="moolamsmall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '159')">मूलम्</button>
                        <button id="padasmall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '159')">पदविभागः</button>
                        <button id="anvayasmall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '159')">अन्वयः</button>
                        <button id="pratismall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '159')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '159')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '159')">हिन्द्यर्थः</button>
                        <button id="audiosmall159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '159')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>जातिमात्रेण किं कश्चिद् वध्यते पूज्यते क्वचित् । व्यवहारं परिज्ञाय वध्यः पूज्योऽथवा भवेत् ॥१.५९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>जाति-मात्रेण किं कश्चिद् वध्यते पूज्यते क्वचित् । व्यवहारं परिज्ञाय वध्यः पूज्यः अथवा भवेत् ॥१.५९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>जाति-मात्रेण किं कश्चिद् वध्यते पूज्यते क्वचित् । व्यवहारं परिज्ञाय वध्यः पूज्यः अथवा भवेत् ॥१.५९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कश्चिदपि ; क्वचित् = कस्मिंश्चित् स्थलेऽपि ; जातिमात्रेण = 'अयं एवंजातीय' इत्येतावन्मात्रेणैव ; किं वध्यते = किं हन्यते ; किं पूज्यते = किं सत्क्रियते ; नैवेत्यर्थः ; व्यवहारं = तदाचारम् ; परिज्ञाय = दृष्ट्वा, अनुरुध्यैव वध्यः = हन्तव्यः ; पूज्यः = सत्कारयोग्यः ॥१.५९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जन्ममात्रेण प्राप्तेन जीवाकारेण एव कोऽपि सत्क्रियार्हत्वं वा, हन्तव्यत्वं वा न प्राप्नोति । तस्य प्रवृत्त्या ज्ञायते यत् सः व्यापादितव्य उत सत्कारपात्रं वेति ॥१.५९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योंकि-कोई भी व्यक्ति जातिमात्र ही से मारने वा पूजने लायक नहीं होता है, किन्तु उनका व्यवहार देख कर ही उसे मारना या पूजना चाहिए ॥१.५९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.59.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="160" class="total">
                    <div>
                        <button id="moolamsmall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '160')">मूलम्</button>
                        <button id="padasmall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '160')">पदविभागः</button>
                        <button id="anvayasmall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '160')">अन्वयः</button>
                        <button id="pratismall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '160')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '160')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '160')">हिन्द्यर्थः</button>
                        <button id="audiosmall160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '160')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अरावप्युचितं कार्यमातिथ्यं गृहमागते । छेत्तुः पार्श्वगताच्छायां नोपसंहरते द्रुमः ॥१.६०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अरौ अपि उचितं कार्यम् आतिथ्यं गृहम् आगते । छेत्तुः पार्श्वगतात् छायां न उपसंहरते द्रुमः ॥१.६०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अरौ अपि गृहम् आगते (सति) उचितं आतिथ्यं कार्यम् । द्रुमः छेत्तुः अपि पार्श्वगतात् छायां न उपसंहरते ॥१.६०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अराविति । अरौ = शत्रौ-अपि ; गृहमागते सति- उचितं = योग्यम्, आतिथ्यम् = अतिथिसत्कारः ; द्रुमः = वृक्षः ; पार्श्वगतात् = निकटस्थितात् ; छेत्तुः = स्वच्छेदकात्, तक्ष्णः सकाशादपि ; स्वच्छायां नोपसंहरते = न सङ्कोचयति ॥१.६०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(गृहस्थ-धर्मः च एषः–) यदा शत्रुः गृहमागच्छति, तदापि योग्या सत्क्रिया कार्या । (अत्रोपमानम्) यदा (तरुं खण्डशः कर्तुं) छेदकः परितः आगच्छति, तदापि वृक्षः (तं) छायां (प्रददाति), न निवर्तयति ॥१.६०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>शत्रु भी यदि अपने धर पर आ जाए तो उसका भी उचित आतिथ्य सत्कार करना चाहिए । देखो- वृक्ष अपने काटने वाले बढई, सुतार आदि की ओर से भी अपनी सुशीतल छाया को कभी नहीं हटाता है ॥१.६०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.60.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="161" class="total">
                    <div>
                        <button id="moolamsmall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '161')">मूलम्</button>
                        <button id="padasmall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '161')">पदविभागः</button>
                        <button id="anvayasmall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '161')">अन्वयः</button>
                        <button id="pratismall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '161')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '161')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '161')">हिन्द्यर्थः</button>
                        <button id="audiosmall161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '161')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तृणानि भूमिरुदकं वाक् चतुर्थी च सूनृता । एतान्यपि सतां गेहे नोच्छिद्यन्ते कदाचन ॥१.६१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तृणानि भूमिः उदकं वाक् चतुर्थी च सूनृता । एतानि अपि सतां गेहे न उच्छिद्यन्ते कदाचन ॥१.६१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सतां गेहे- तृणानि, भूमिः, उदकं, वाक्, चतुर्थी च सूनृता - एतानि अपि कदाचन न उच्छिद्यन्ते ॥१.६१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>तृणानि = आस्तरणार्थं पलाल-कुशादीनि ; भूमिः = निवास-स्थानम् ; उदकं = पानाद्यर्थे शीतलं पयः ; एतत् त्रितयं ; किञ्च-चतुर्थी- ; सूनृता = प्रिया, सत्या च ; वाक् = वाणी ; ['सूनृतं मङ्गलेऽपि स्यात् प्रियसत्ये वचस्यपी'ति मेदिनी] ; एतानि = चत्वारि ; अपि = तु ; सतां = साधूनां ; गेहे = गृहे ; न उच्छिद्यन्ते कदाचन = न कदाचन विरलीभवन्ति ; सदैव सुलभानि एव इत्याशयः ॥१.६१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सज्जनानां गृहे- (उपवेशनाय, शयनाय च) तृणानि, (वासयोग्या) धरा, (तृषाशान्त्यर्थं) जलं, मधुरा च वाणी- एतानि वस्तूनि कदापि अनुपलब्धतां न यान्ति ॥१.६१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बिछाने के लिए और बैठने के लिए पुआल आदि घास फूस, रहने को स्थान, जल- ये तीन चीज़ और चौथा मीठा वचन, इन चार चीज़ों की कमी तो सज्जनों के घर में कभी भी नहीं होती है । अर्थात् कुछ भी घर में देने को न हो तो भी इन चार वस्तुओं से ही अतिथि का सत्कार करना चाहिये ॥१.६१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.61.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="162" class="total">
                    <div>
                        <button id="moolamsmall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '162')">मूलम्</button>
                        <button id="padasmall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '162')">पदविभागः</button>
                        <button id="anvayasmall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '162')">अन्वयः</button>
                        <button id="pratismall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '162')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '162')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '162')">हिन्द्यर्थः</button>
                        <button id="audiosmall162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '162')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>बालो वा यदि वा वृद्धो युवा वा गृहमागतः । तस्य पूजा विधातव्या सर्वस्याभ्यागतो गुरुः ॥१.६२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>बालः वा यदि वा वृद्धः युवा वा गृहम् आगतः । तस्य पूजा विधातव्या सर्वस्य आभ्यागतः गुरुः ॥१.६२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यदि बालः वा, वृद्धः वा, युवा वा गृहम् आगतः, (तर्हि) तस्य पूजा विधातव्या । आभ्यागतः सर्वस्य गुरुः (वर्तते) ॥१.६२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गृहमागतः = स्वगृह-द्वारि समुपस्थितः, अतिथिः ; तस्य = अतिथेः ; पूजा = सत्क्रिया ; विधातव्या = कर्तव्या ; अभ्यागतः = अन्य-ग्रामादागतः अतिथिः ; गुरुः = पूज्यः ॥१.६२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गेहस्य पुरतः आगतः अतिथिः बालकः, युवा, वृद्धो वा भवतु- तस्य समुचितः सत्कारः कर्तव्यः। अभ्यागतः सर्वेषां (सर्ववर्णाश्रमधर्मिणां) पूज्यः वर्तते ॥१.६२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अतिथि यदि बालक हो या वृद्ध हो या जवान हो, वह यदि अपने घर पर आ जाय, तो उसकी पूजा अवश्य करनी चाहिये। क्यों कि अतिथि सभी का गुरु और पूज्य होता है ॥१.६२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.62.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="163" class="total">
                    <div>
                        <button id="moolamsmall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '163')">मूलम्</button>
                        <button id="padasmall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '163')">पदविभागः</button>
                        <button id="anvayasmall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '163')">अन्वयः</button>
                        <button id="pratismall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '163')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '163')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '163')">हिन्द्यर्थः</button>
                        <button id="audiosmall163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '163')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>निर्गुणेष्वपि सत्त्वेषु दयां कुर्वन्ति साधवः । न हि संहरते ज्योत्स्नां चन्द्रश्चाण्डालवेश्मनः ॥१.६३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>निर्गुणेषु अपि सत्त्वेषु दयां कुर्वन्ति साधवः । न हि संहरते ज्योत्स्नां चन्द्रः चाण्डाल-वेश्मनः ॥१.६३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>साधवः निर्गुणेषु अपि सत्त्वेषु दयां कुर्वन्ति । चन्द्रः ज्योत्स्नां चाण्डाल-वेश्मनः न हि संहरते ॥१.६३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अपरं च– साधवः निर्गुणेषु अपि सत्त्वेषु दयां कुर्वन्ति । चन्द्रः चाण्डाल-वेश्मनः ज्योत्स्नां न हि संहरते ॥१.६३॥ साधवः = सन्तः ; निर्गुणेष्वपि = अयोग्येष्वपि, नीचेष्वपि च ; सत्त्वेषु = भूतेषु ; दयां कुर्वन्ति = करुणां प्रदर्शयन्ति ; हि = यतः ; चन्द्रः = इन्दुः ; चाण्डाल-वेश्मनः = पतितान्तावसायिगेहात्। ज्योत्स्नां = स्वचन्द्रिकां ; न संहरते = न सङ्कोचयति ॥१.६३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सज्जनाः गुणहीनेषु प्राणिषु अपि अनुकम्पां दर्शयन्ति। (अत्र उदाहरणम्-) इन्दुः कौमुदीं (सर्वत्र प्रसारयति) अत्यजगृहेषु अपि (अयोग्यानीति अमत्वा) स्वकान्तिं नोपसंहरति ॥१.६३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>महात्मा लोग गुणहीन (साधारण पामर, तुच्छ) जीवों पर भी सदा दया ही करते हैं । देखो, चन्द्रमा चाण्डाल केघर से भी अपनी किरणों को नहीं हटाता है । अर्थात् चन्द्रमा की शीतल किरण गुणी व निर्गुण सभी के ऊपर समान ही पड़ती हैं ॥१.६३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.63.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="164" class="total">
                    <div>
                        <button id="moolamsmall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '164')">मूलम्</button>
                        <button id="padasmall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '164')">पदविभागः</button>
                        <button id="anvayasmall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '164')">अन्वयः</button>
                        <button id="pratismall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '164')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '164')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '164')">हिन्द्यर्थः</button>
                        <button id="audiosmall164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '164')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अतिथिर्यस्य भग्नाशो गृहात् प्रतिनिवर्तते । स दत्त्वा दुष्कृतं तस्मै पुण्यमादाय गच्छति ॥१.६४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अतिथिः यस्य भग्नाशः गृहात् प्रतिनिवर्तते । सः दत्त्वा दुष्कृतं तस्मै पुण्यम् आदाय गच्छति ॥१.६४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य अतिथिः भग्नाशः (सन्) गृहात् प्रतिनिवर्तते, सः (अतिथिः) तस्मै (गृहस्थाय) दुष्कृतं दत्त्वा, पुण्यम् आदाय (च) गच्छति ॥१.६४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य = पुंसः ; गृहात् = निवासात् ; अतिथिः = अभ्यागतः ; भग्नाशः = निराशः सन् ; प्रतिनिवर्त्तते = पुराङ्मुखो गच्छति ; सः = अतिथिः ; तस्मै = गृहस्वामिने ; दुष्कृतं = स्वपापम् ; दत्त्वा = प्रदाय ; पुण्यं = गृहस्वामिनः पुण्यम् ; आदाय गच्छति = अपहरति, स्वीकृत्य निर्गच्छति ॥१.६४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदि (गृहमागतः) कश्चित् अतिथिः (केनचित्कारणेन) उपहतः सन् निर्गच्छति, तर्हि सः गृहस्थाय पापं दत्त्वा, (गहस्थेनाचरितं) सुकृतं च नीत्वा गच्छति ॥१.६४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिस गृहस्थ के घर से अतिथि निराश होकर लौट जाता है, तो वह अतिथि उस गृहस्थ को अपना पाप देकर और उसका पुण्य लेकर चला जाता है । [अर्थात् अतिथि को निराश करने से बड़ा पाप होता है ॥१.६४ ॥]</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.64.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="165" class="total">
                    <div>
                        <button id="moolamsmall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '165')">मूलम्</button>
                        <button id="padasmall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '165')">पदविभागः</button>
                        <button id="anvayasmall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '165')">अन्वयः</button>
                        <button id="pratismall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '165')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '165')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '165')">हिन्द्यर्थः</button>
                        <button id="audiosmall165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '165')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उत्तमस्यापि वर्णस्य नीचोऽपि गृहमागतः । पूजनीयो यथायोग्यं सर्वदेवमयोऽतिथिः ॥१.६५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उत्तमस्य अपि वर्णस्य नीचः अपि गृहम् आगतः । पूजनीयः यथायोग्यं सर्वदेवमयः अतिथिः ॥१.६५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उत्तमस्य वर्णस्य अपि गृहम् आगतः नीचः अपि यथायोग्यं पूजनीयः । अतिथिः सर्वदेवमयः ॥१.६५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्तमस्यापि वर्णस्य = श्रेष्ठस्यापि ब्राह्मणादेर्वर्णस्य ; गेहे = गृहे ; नीचोऽपि = स्वतो निकृष्टः चाण्डालादिः अपि ; यथायोग्यं = यथोचितम् ; पूजनीयः = पूज्यः ; कुत एतदत आह- सर्वेति । सर्वदेवमयः = सर्वदेवस्वरूपः ॥१.६५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अग्रवर्णस्य कस्यचित् गृहं प्रति इपि (कदाचित्) अन्त्यवर्णः कश्चित् आगच्छति चेत्, सः यथार्हं सत्क्रियापात्रमेव भवति । अभ्यागतस्तु सर्वदेवस्वरूपः ॥१.६५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उत्तम वर्ण (ब्राह्मण आदि) के घर में यदि नीच वर्ण (चाण्डालादिक) भी अतिथि होकर आये तो उसका भी यथायोग्य सत्कार करना चाहिये, क्यों कि अतिथि सब देवताओंका रूप है ॥१.६५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.65.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="168" class="total">
                    <div>
                        <button id="moolamsmall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '168')">मूलम्</button>
                        <button id="padasmall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '168')">पदविभागः</button>
                        <button id="anvayasmall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '168')">अन्वयः</button>
                        <button id="pratismall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '168')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '168')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '168')">हिन्द्यर्थः</button>
                        <button id="audiosmall168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '168')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सर्वहिंसानिवृत्ता ये नराः सर्वसहाश्च ये । सर्वस्याश्रयभूताश्च ते नराः स्वर्गगामिनः ॥१.६८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सर्वहिंसा-निवृत्ताः ये नराः सर्व-सहाः च ये । सर्वस्य आश्रय-भूताः च ते नराः स्वर्ग-गामिनः ॥१.६८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>ये नराः सर्वहिंसा-निवृत्ताः, ये च सर्व-सहाः, (ये) सर्वस्य आश्रय-भूताः च, ते नराः स्वर्ग-गामिनः ॥१.६८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सर्वहिंसा-निवृत्ताः = परपीडाकार्ये ये रताः न भवन्ति ; सर्वसहाः = तितिक्षा-परायणाः ; आश्रयभूताः = सर्वाभयप्रदाः ; स्वर्ग-गामिनः = ये स्वर्गं प्रति गच्छन्ति ॥१.६८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये प्राणिपीडकाः न, ये च सर्वं क्षन्तुमर्हन्ति, ये सर्वेषां शरण्यस्थानं भवन्ति, ते स्वर्गं गच्छन्ति ॥१.६८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो लोग सब प्रकार की जीवहिंसा से निवृत्त हैं, और जो सब कुछ सहन करते हैं, तथा सबको यथाशक्ति आश्रय देते हैं, वे ही लोग स्वर्ग में जाते हैं ॥१.६८ ॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.68.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="169" class="total">
                    <div>
                        <button id="moolamsmall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '169')">मूलम्</button>
                        <button id="padasmall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '169')">पदविभागः</button>
                        <button id="anvayasmall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '169')">अन्वयः</button>
                        <button id="pratismall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '169')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '169')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '169')">हिन्द्यर्थः</button>
                        <button id="audiosmall169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '169')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>एक एव सुहृद्धर्मो निधनेऽप्यनुयाति यः । शरीरेण समं नाशं सर्वमन्यत्तु गच्छति ॥१.६९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>एकः एव सुहृद् धर्मः निधने अपि अनुयाति यः । शरीरेण समं नाशं सर्वम् अन्यत् तु गच्छति ॥१.६९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धर्मः एक एव सुहृद् यः निधने अपि अनुयाति । सर्वम् अन्यत् तु शरीरेण समं नाशं गच्छति ॥१.६९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धर्मः एक एव सुहृद् यः निधने अपि अनुयाति । सर्वम् अन्यत् तु शरीरेण समं नाशं गच्छति ॥१.६९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(नश्वरे अस्मिन् लोके) धर्मः (पुण्यं) मरणेऽपि प्राप्ते जीवेन साकं गच्छति। तद्भिन्नं समस्तं कायनाशं समनन्तरमेव विनश्यति ॥१.६९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और धर्म ही केवल एक ऐसा मित्र है, जो मरने पर भी साथ देता है। और सब सम्पत्ति तो शरीर के साथ ही नष्ट हो जाती है ॥१.६९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.69.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="170" class="total">
                    <div>
                        <button id="moolamsmall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '170')">मूलम्</button>
                        <button id="padasmall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '170')">पदविभागः</button>
                        <button id="anvayasmall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '170')">अन्वयः</button>
                        <button id="pratismall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '170')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '170')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '170')">हिन्द्यर्थः</button>
                        <button id="audiosmall170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '170')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>योऽत्ति यस्य यदा मांसमुभयोः पश्यतान्तरम् । एकस्य क्षणिका प्रीतिरन्यः प्राणैर्विमुच्यते ॥१.७०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यः अत्ति यस्य यदा मांसम् उभयोः पश्यतान्तरम् । एकस्य क्षणिका प्रीतिः अन्यः प्राणैः विमुच्यते ॥१.७०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः यदा यस्य मांसम् अत्ति उभयोः अन्तरं पश्यत । एकस्य क्षणिका प्रीतिः (भवति) । अन्यः प्राणैः विमुच्यते ॥१.७०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यः = पुमान् ; यस्य = मृगादेः ; यदा = यस्मिन् समये ; अत्ति = भक्षयति ; उभयोः = भक्ष्यभक्षकयोः ; अन्तरं = भेदम् ; पश्यत = विलोकयत ; एकस्य = भक्षकस्य पुंसः तु ; क्षणिका = भक्षण-मात्रस्थायिनी एव ; प्रीतिः = तृप्तिः ; परम्- अन्यः = मृगादिः भक्ष्यभूतः पशुस्तु ॥१.७०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कश्चन जीवः यदा अन्यप्राणिनः मांसं खादति, तदा द्वयोः मध्ये भेदः एवमस्ति। यः मांसभुक्, सः तात्कालिकं बुभुक्षाशमनरूपम् आनन्दमनुभवति। किन्तु यं जीवं स भुङ्क्ते, स जीवः प्राणान् त्यजति (मरणं प्राप्नोति इति तस्य सर्वदा नाशः) ॥१.७०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>एक प्राणी जब दूसरे प्राणी का मांस खाता है, तो उस समय उन दोनों का भेद देखिये। एक (खानेवाले) को तो क्षणभर का आनन्द (आस्वाद) मिलता है, परन्तु दूसरा (भक्ष्य प्राणी) सर्वदा के लिये इस संसार से चला जाता है ॥१.७०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.70.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="171" class="total">
                    <div>
                        <button id="moolamsmall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '171')">मूलम्</button>
                        <button id="padasmall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '171')">पदविभागः</button>
                        <button id="anvayasmall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '171')">अन्वयः</button>
                        <button id="pratismall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '171')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '171')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '171')">हिन्द्यर्थः</button>
                        <button id="audiosmall171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '171')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मर्तव्यमिति यद् दुःखं पुरुषस्योपजायते । शक्यते नानुमानेन परेण परिवर्णितुम् ॥१.७१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मर्तव्यम् इति यद्-दुःखं पुरुषस्य उपजायते । शक्यते न अनुमानेन परेण परिवर्णितुम् ॥१.७१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पुरुषस्य यत् मर्तव्यम् इति दुःखम् उपजायते, परेण अनुमानेन परिवर्णितुं न शक्यते ॥१.७१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>'मया मर्त्तव्यमिदानी'मिति ज्ञात्वा, यत् = यादृशं ; दुःखं = मनःक्लेशः ; पुरुषस्य = जन्तोः ; उपजायते = भवति ; तेन = तद्धेतुकेन ; अनुमानेन = अनुमित्या ; परोऽपि = मृगपक्ष्यादिरपि ; शक्यः = योग्यः ; 'मरणाद्यथा मम दुःखं, तथैव परस्यापीति विज्ञाय परोऽपि स्वात्मवदेव रक्षणीय इत्याशयः ॥१.७१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्यस्य या मरणविषया पीडा अनुभूयते, सा (यः तं क्लेशम् अधुना नानुभवति तेन) अन्यजनेन (‘इदमित्थम् एवंरूपेण दुःखं भवती’ति शब्दैः) प्रकटयितुं न शक्या ॥१.७१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>'मुझको मरना होगा' यह सोच कर मरने वाले मनुष्य को जो दुःख होता है, उसको दूसरा मनुष्य केवल अनुमान से वर्णन नहीं कर सकता है ॥१.७१॥   { माम् सः भक्षयिताsमुत्र यस्य मांसम् इह अद्मि अहम् । इति मांसस्य मांसत्वम् प्रवदन्ति मनीषिणः ।। अद्मि - खादामि वह परलोक में मुझे खाएगा जिसका मांस मैं इस लोक में खा रहा हुँ ।बुद्धिमान लोगों का कहना है इसी कारण से मांस को माम् (मुझको) + सः (वह) कहते हैं ।}</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.71.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="172" class="total">
                    <div>
                        <button id="moolamsmall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '172')">मूलम्</button>
                        <button id="padasmall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '172')">पदविभागः</button>
                        <button id="anvayasmall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '172')">अन्वयः</button>
                        <button id="pratismall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '172')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '172')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '172')">हिन्द्यर्थः</button>
                        <button id="audiosmall172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '172')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्वच्छन्दवनजातेन शाकेनापि प्रपूर्यते । अस्य दग्धोदरस्यार्थे कः कुर्यात् पातकं महत् ॥१.७२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्वच्छन्द-वन-जातेन शाकेन अपि प्रपूर्यते । अस्य दग्ध-उदरस्यार्थे कः कुर्यात् पातकं महत् ॥१.७२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>स्वच्छन्द-वन-जातेन शाकेन अपि (उदरं) प्रपूर्यते । (एवं स्थिते) अस्य दग्ध-उदरस्यार्थे कः महत् पातकं कुर्यात्? (न करोतीति भावः) ॥१.७२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्वच्छन्द-वन-जातेन = स्वतन्त्रतया वने उद्भूतेन सुलभेन ; शाकेन = फलमूल-शाकादिना, वृक्षोत्पदनेन ; प्रपूर्यते = यत्परिपूर्णं भवति ; तस्य दग्धोदरस्य = उदरहतकस्य, धिग् अस्य उदरस्य ; अर्थे = निमित्तं ; कः = कः सचेताः पुमान् ; महत् = नितरां गुरु ; पातकं = प्राणिवध-रूपं पापम् ; कुर्यात् = आचरेत् ; (न कश्चिदपि सहृदयः कुर्यादित्यर्थः) ॥१.७२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>स्वयमेव (विना कृषकेण, श्रमेण वा) अरण्ये उत्पन्नेन सस्येन जठरस्य भरणं भवति। (एवं सति) कः (बुद्धिहीनः) कुक्ष्यै (क्षुधापूर्तये जीवहननरूपकं) पापं विदधाति? ॥१.७२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बिना बोये-जोते स्वयं वन में उत्पन्न हुए साग से भी जब यह पेट भरा जा सकता है, तो इस पापी पेट के लिये इतना बड़ा पाप कौन समझदार मनुष्य करेगा? अर्थात् इस पापी पेट के लिए किसी को भी ऐसा जघन्य काम नहीं करना चाहिये। ॥१.७२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.72.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="173" class="total">
                    <div>
                        <button id="moolamsmall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '173')">मूलम्</button>
                        <button id="padasmall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '173')">पदविभागः</button>
                        <button id="anvayasmall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '173')">अन्वयः</button>
                        <button id="pratismall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '173')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '173')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '173')">हिन्द्यर्थः</button>
                        <button id="audiosmall173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '173')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यत्र विद्वज्जनो नास्ति श्लाघ्यस्तत्राल्पधीरपि । निरस्तपादपे देशे एरण्डोऽपि द्रुमायते ॥१.७३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यत्र विद्वज्जनः नास्ति श्लाघ्यः तत्र अल्पधीः अपि । निरस्त-पादपे देशे एरण्डः अपि द्रुमायते ॥१.७३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यत्र विद्वज्जनः नास्ति, तत्र अल्पधीः अपि श्लाघ्यः । निरस्त-पादपे देशे एरण्डः अपि द्रुमायते ॥१.७३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विद्वज्जनः = पण्डितजनः ; श्लाघ्यः = प्रशंसार्हः ; अल्पधीः अपि = मन्दबुद्धियुक्तः, तुच्छमतिः अपि ; निरस्तपादपे = वृक्षशून्ये ; एरण्डः = पञ्चाङ्गुलः ; द्रुमायते = द्रुम इव आचरति, वृक्षशब्दं धत्ते ; एवञ्च भवान् ॥१.७३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्मिन् प्रदेशे बहुश्रुतः नास्ति, तत्र लघुवेत्तापि विख्यायते । (अत्र उदाहरणम्) यत्र वृक्षाः न विद्यन्ते, तत्र एरण्डोऽपि वृक्षत्वं प्राप्नोति ॥१.७३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जहाँ कोई योग्य विद्वान् नहीं है, वहाँ अल्प बुद्धि वाले पुरुष की भी प्रशंसा होती है। जिस जगह वृक्ष नहीं हैं, वहाँ रेंड भी वृक्ष कहा जाता है ॥१.७३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.73.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="174" class="total">
                    <div>
                        <button id="moolamsmall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '174')">मूलम्</button>
                        <button id="padasmall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '174')">पदविभागः</button>
                        <button id="anvayasmall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '174')">अन्वयः</button>
                        <button id="pratismall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '174')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '174')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '174')">हिन्द्यर्थः</button>
                        <button id="audiosmall174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '174')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अयं निजः परो वेति गणना लघुचेतसाम् । उदारचरितानां तु वसुधैव कुटुम्बकम् ॥१.७४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अयं निजः परः वा इति गणना लघु-चेतसाम् । उदार-चरितानां तु वसुधा एव कुटुम्बकम् ॥१.७४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अयं निजः परः वा इति लघु-चेतसां गणना । उदार-चरितानां तु वसुधा एव कुटुम्बकम् ॥१.७४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अयं = अयं जनः ; निजः = आत्मीयः, अयं परः = अयं जनः अपरः, शत्रुर्वा ; इति = इत्येवं ; लघुचेतसां = सङ्कुचित-चित्तानां, तुच्छानां ; गणना = विचारो भवति ; उदार-चरितानां = महानुभावानां, महतान्तु ; वसुधैव = सकलं जगदपि ; कुटुम्बकम् = कुटुम्बतुल्यमेव ; सर्वत्रैव तेषामात्मीयभाव इत्यर्थः ॥१.७४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(मनुष्यान् दृष्ट्वा) एषः मदीयः, एषः इतरः इति अधमानां चिन्तनं भवति। ये उन्नतचेताः तेषां (दृष्टौ) संसारः सर्वः स्वकुलम् इव वर्तते ॥१.७४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>'यह मेरा है', 'यह दूसरा है' यह विचार तो छोटे लोगों का ही होता है । बड़े लोगों का तो संसार ही अपना कुटुम्ब है ॥१.७४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.74.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="175" class="total">
                    <div>
                        <button id="moolamsmall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '175')">मूलम्</button>
                        <button id="padasmall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '175')">पदविभागः</button>
                        <button id="anvayasmall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '175')">अन्वयः</button>
                        <button id="pratismall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '175')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '175')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '175')">हिन्द्यर्थः</button>
                        <button id="audiosmall175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '175')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न कश्चित् कस्यचिन्मित्रं न कश्चित् कस्यचिद् रिपुः । व्यवहारेण मित्राणि जायन्ते रिपवस्तथा ॥१.७५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न कश्चित् कस्यचित् मित्रं न कश्चित् कस्यचिद् रिपुः । व्यवहारेण मित्राणि जायन्ते रिपवः तथा ॥१.७५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कश्चित् कस्यचित् मित्रं न (भवति)। कश्चित् कस्यचिद् रिपुः न (भवति) । व्यवहारेण (एव) मित्राणि रिपवः (वा) तथा जायन्ते ॥१.७५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मित्रं = स्वभावतो मित्रम् ; रिपुः = सहजो शत्रुः ; व्यवहारेण = हित-अहित-आचरणेन, कार्यकारणभावेन च ॥१.७५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कोऽपि कस्यापि सहजमेव सुहृद् वा, अरिर्वा न भवति। (परस्परं) यथा समाचरति, (तस्य फलतः) सौहार्दभावो वा अमित्रभावो वा (तन्मध्ये) समुत्पद्यते ॥१.७५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>स्वभाव से तो न कोई किसी का मित्र है और न कोई किसी का शत्रु ही है । शत्रुता और मित्रता तो व्यवहार (कार्य) से ही होती है ॥१.७५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.75.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="176" class="total">
                    <div>
                        <button id="moolamsmall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '176')">मूलम्</button>
                        <button id="padasmall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '176')">पदविभागः</button>
                        <button id="anvayasmall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '176')">अन्वयः</button>
                        <button id="pratismall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '176')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '176')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '176')">हिन्द्यर्थः</button>
                        <button id="audiosmall176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '176')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आपत्सु मित्रं जानीयाद् रणे शूरं ऋणे शुचिम् । भार्यां क्षीणेषु वित्तेषु व्यसनेषु च बान्धवान् ॥१.७६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आपत्सु मित्रं जानीयाद् रणे शूरं ऋणे शुचिम् । भार्यां क्षीणेषु वित्तेषु व्यसनेषु च बान्धवान् ॥१.७६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मित्रम् आपत्सु जानीयात्। शूरं रणे (जानीयात्)। शुचिम् ऋणे (जानीयात्)। भार्यां क्षीणेषु वित्तेषु (जानीयात्)। बान्धवान् च व्यसनेषु (जानीयात्) ॥१.७६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>जानीयात् = (अत्र) परीक्षेत ; शुचिम् = शुद्धव्यवहारम् ; क्षीणेषु = विनष्टेषु ; वित्तेषु = धनेषु ; व्यसनेषु = विपत्तिषु ; 'जानीया'दिति शेषः ॥१.७६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(कस्य वास्तवं स्वभावं कस्मिन् स्थितौ ज्ञायेत इति उच्यते क्रमेण) सङ्कटे स्थितौ सुहृदं, युद्धकाले वीरं, ऋणप्रसङ्गे (स्वीकारे अथवा प्रत्यर्पणवेलायां) स्पष्टव्यवहारं, धनहानौ पत्नीं, महद्दुःखवेलायां बन्धुजनान् च ज्ञायेत। ॥१.७६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>आपत्ति में-मित्र को, युद्ध में-वीर को, ऋण में-साफ और निष्कपट को, निर्धनता में-स्त्रीको, दुःख पड़ने पर-भाई बन्धुओं को पहचानना चाहिये ॥१.७६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.76.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="177" class="total">
                    <div>
                        <button id="moolamsmall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '177')">मूलम्</button>
                        <button id="padasmall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '177')">पदविभागः</button>
                        <button id="anvayasmall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '177')">अन्वयः</button>
                        <button id="pratismall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '177')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '177')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '177')">हिन्द्यर्थः</button>
                        <button id="audiosmall177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '177')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उत्सवे व्यसने प्राप्ते दुर्भिक्षे शत्रुसङ्कटे । राजद्वारे श्मशाने च यस्तिष्ठति स बान्धवः ॥१.७७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उत्सवे व्यसने प्राप्ते दुर्भिक्षे शत्रु-सङ्कटे । राजद्वारे श्मशाने च यः तिष्ठति सः बान्धवः ॥१.७७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः- उत्सवे, व्यसने प्राप्ते, दुर्भिक्षे, शत्रु-सङ्कटे, राजद्वारे, श्मशाने च- तिष्ठति, सः बान्धवः ॥१.७७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्सवे = विवाहादौ आनन्दसमये ; व्यसने = विपत्तौ ; दुर्भिक्षे = अनावृष्टौ, अन्नकष्टे, अकाले ; राष्ट्रविप्लवे = राज्यभङ्गे, राजपरिवर्तनावसरे ; राजद्वारे = बन्धनागारे, धर्माधिकरणे वा ; श्मशाने = पितृवने, प्रियमरणे ; तिष्ठति = साहय्यमाचरति ॥१.७७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सन्तोषवेलायां, कष्टसमये, अन्नाभावकाले, राज्यसङ्कटे स्थिते, राज्ञः पुरतः, गृहे बन्धुववियोगे-- यः (पार्श्वे) भवति (धैर्यं संवर्धयन्, हितमाचरति) स एव मित्रं, बान्धवो वा ॥१.७७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हर्ष में, शोक में, दुर्भिक्ष पड़ने पर, राज्य क्रान्ति के समय, राज-द्वार (कचहरी) में और श्मशान में जो साथ देता है, वही सच्चा मित्र है ॥१.७७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.77.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="178" class="total">
                    <div>
                        <button id="moolamsmall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '178')">मूलम्</button>
                        <button id="padasmall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '178')">पदविभागः</button>
                        <button id="anvayasmall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '178')">अन्वयः</button>
                        <button id="pratismall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '178')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '178')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '178')">हिन्द्यर्थः</button>
                        <button id="audiosmall178" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '178')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सुहृदां हितकामानां यः शृणोति न भाषितम् । विपत् सन्निहिता तस्य स नरः शत्रुनन्दनः ॥१.७८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुहृदां हित-कामानां यः शृणोति न भाषितम् । विपत् सन्निहिता तस्य सः नरः शत्रु-नन्दनः ॥१.७८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः हित-कामानां सुहृदां भाषितं न शृणोति, तस्य विपत् सन्निहिता (इति ज्ञातव्यम्)। सः नरः शत्रु-नन्दनः ॥१.७८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सुहृदां = मित्राणां ; हितकामानां= हितैषिणाम् ; भाषितम् = उपदेशम् ; विपत् = कष्टं ; सन्निहिता समीपवर्ति ; शत्रुनन्दनः = शत्रुभ्यः हर्षप्रदः (विपन्नं तं दृष्ट्वा शत्रवो नन्दन्तीत्यर्थः) ॥१.७८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शुभचिन्तकानां मित्राणां उक्तीः यः नाकर्णयति, तस्य जीवने दुःखकरसमयः समीपे अस्तीति ज्ञातव्यम्। सः अरीणां मनःसु सन्तोषं जनयति ॥१.७८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो लोग अपने हित चाहने वाले मित्रों का कहना नहीं सुनते हैं, उनके ऊपर विपत्ति अवश्य आती है और वे अपने शत्रुओं के आनन्द के कारण ही होते हैं ॥१.७८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.78.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="179" class="total">
                    <div>
                        <button id="moolamsmall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '179')">मूलम्</button>
                        <button id="padasmall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '179')">पदविभागः</button>
                        <button id="anvayasmall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '179')">अन्वयः</button>
                        <button id="pratismall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '179')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '179')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '179')">हिन्द्यर्थः</button>
                        <button id="audiosmall179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '179')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अपराधो न मेऽस्तीति नैतद् विश्वासकारणम् । विद्यते हि नृशंसेभ्यो भयं गुणवतामपि ॥१.७९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अपराधः न मे अस्ति इति न एतद् विश्वास-कारणम् । विद्यते हि नृशंसेभ्यः भयं गुणवताम् अपि ॥१.७९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>(मम) मे अपराधः नास्ति इति एतद् विश्वास-कारणम् न (अस्ति)। गुणवताम् अपि नृशंसेभ्यः भयं विद्यते हि ॥१.७९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अपराधः = दोषः ; विश्वासकारणम् = आश्वासनस्य आस्पदम् ; नृशंसेभ्यः = क्रूरजनेभ्यः ; गुणवताम् = सज्जनानाम् ॥ </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>स्वस्य दोषाचरणं न विद्यते इति मात्रेण विश्वासः न कर्तव्यः। सद्गुणयुक्तानामपि क्रूरजनेभ्यः भयं विद्यते। (हिंसापराः अकारणमेव सर्वेभ्यः अहितमाचरन्ति। कश्चित् सच्छीलोऽपि भवतु, अपकृतेराचरणं विनापि, नृशंसः तं न त्यजति। अतः सावधानेन भाव्यमिति यावत्।) ॥१.७९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मेरा कोई अपराध नहीं है- यह कोई कारण नहीं है आश्वासन का। गुणवान व्यक्तियों को भी क्रूरजनों से भय होता ही है॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
