                    <div>
                        <button id="moolamsmall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '180')">मूलम्</button>
                        <button id="padasmall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '180')">पदविभागः</button>
                        <button id="anvayasmall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '180')">अन्वयः</button>
                        <button id="pratismall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '180')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '180')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '180')">हिन्द्यर्थः</button>
                        <button id="audiosmall180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '180')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दीपनिर्वाणगन्धं च सुहृद्वाक्यमरुन्धतीम् । न जिघ्रन्ति न शृण्वन्ति न पश्यन्ति गतायुषः ॥१.८०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दीप-निर्वाण-गन्धं च सुहृद्-वाक्यम् अरुन्धतीम् । न जिघ्रन्ति न शृण्वन्ति न पश्यन्ति गत-आयुषः ॥१.८०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दीप-निर्वाण-गन्धं च सुहृद्-वाक्यम् अरुन्धतीम् । न जिघ्रन्ति न शृण्वन्ति न पश्यन्ति गत-आयुषः ॥१.८०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दीप-निर्वाण-गन्धं = निर्गतः दीपः, तस्य सुगन्धं ; सुहृद्-वाक्यम् = मित्राणां, हितकाङ्क्षिणां वचनानि ; अरुन्धतीम् = ताराम् ; न जिघ्रन्ति = घ्रातुं न शक्नुवन्ति ; न शृण्वन्ति = न आकर्णयन्ति ; न पश्यन्ति = न वीक्षन्ते ; गत-आयुषः = येषां आयुः समाप्तम् ॥१.८० ॥ </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>येषां जीवनकालः समाप्तप्रायः, ते विगतस्य दीपस्य गन्धं न जिघ्रन्ति, हितैषिणां वचः न श्रुण्वन्ति, अरुन्धतीतारां न ईक्षन्ते ॥१.८०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिनका आयु क्षीण होगया, वे दीपक के बुझने वाले गन्ध को नहीं सूंघते। हितैषी के बातों को नहीं सुनते। और अरुन्धती नक्षत्र को नहीं देखते ॥१.८०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.80.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="181" class="total">
                    <div>
                        <button id="moolamsmall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '181')">मूलम्</button>
                        <button id="padasmall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '181')">पदविभागः</button>
                        <button id="anvayasmall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '181')">अन्वयः</button>
                        <button id="pratismall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '181')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '181')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '181')">हिन्द्यर्थः</button>
                        <button id="audiosmall181" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '181')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>परोक्षे कार्यहन्तारं प्रत्यक्षे प्रियवादिनम् । वर्जयेत् तादृशं मित्रं विषकुम्भं पयोमुखम् ॥१.८१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>परोक्षे कार्य-हन्तारं प्रत्यक्षे प्रियवादिनम् । वर्जयेत् तादृशं मित्रं विषकुम्भं पयोमुखम् ॥१.८१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>परोक्षे कार्य-हन्तारं, प्रत्यक्षे प्रियवादिनम्- तादृशं विषकुम्भं पयोमुखं मित्रं वर्जयेत् ॥१.८१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>परोक्षे = अन्यत्र स्थिते सति ; कार्य-हन्तारं = कार्यनाशकं ; प्रत्यक्षे = उपस्थितौ ; प्रियवादिनम् = प्रियं वक्ति यः तं ; तादृशं = तद्वन्मित्रं ; विषकुम्भं पयोमुखं = यस्यान्ते विषमस्ति, बहिस्तु पयः दर्श्यते तादृग् घटः, तं ; मित्रं = सुहृदं ; वर्जयेत् = त्यजेत् ॥१.८१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः अनुपस्थितौ सति कार्यविघातं करोति, पुरतः स्थिते सति प्रीतिकराणि वचांसि वदति, तं मित्रं त्यजेत्। सः तत्कुम्भ इव भवति, यत्र अन्तः गरलमस्ति, उपरि दुग्धं दृश्यते ॥१.८१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो पीठ पीछे काम को बिगाड़ता है, और सामने मीठी बातें करता है, ऐसे अन्दर विषभरे, पर बाहर दूध दिखाने वाले घड़े के समान मित्र का त्याग करना चाहिए ॥१.८१॥   </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.81.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="182" class="total">
                    <div>
                        <button id="moolamsmall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '182')">मूलम्</button>
                        <button id="padasmall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '182')">पदविभागः</button>
                        <button id="anvayasmall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '182')">अन्वयः</button>
                        <button id="pratismall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '182')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '182')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '182')">हिन्द्यर्थः</button>
                        <button id="audiosmall182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '182')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>संलापितानां मधुरैर्वचोभिर्मिथ्योपचारैश्च वशीकृतानाम् । आशावतां श्रद्दधतां च लोके किमर्थिनां वञ्चयितव्यमस्ति ॥१.८२॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>संलापितानां मधुरैः वचोभिः मिथ्या-उपचारैः च वशीकृतानाम् । आशावतां श्रद्दधतां च लोके किमर्थिनां वञ्चयितव्यम् अस्ति ॥१.८२॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>संलापितानां मधुरैः वचोभिः मिथ्या-उपचारैः च वशीकृतानाम् । आशावतां श्रद्दधतां च लोके किमर्थिनां वञ्चयितव्यम् अस्ति ॥१.८२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>संलापितानां= विहितालापानाम् (विश्वस्तानामिति यावत्), यैः सह परिचयो जातः तेषां ; किञ्च, मिथ्या = कपटपूर्णैः ; उपचारैः- सेवा-सत्कारादिभिः ; वशीकृतानां = वशे स्थापितानां वा ; आशावताम् = आशा-पाशेन बद्धानां च ; च = किञ्च ; श्रद्धावतां = श्रद्दधतां वा, ये श्रद्धालवः तेषां वा ; अर्थिनां= याचकानां, प्रणयिनां च ; किं वञ्चयितव्यम् = कि वञ्चनीयम्? (अस्ति? इति अवशिष्यते) ; विश्वस्तवञ्चने किं कौशलम् इत्यर्थः ॥१.८२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये परिचिताः, ये च सुवचनैः कपट-सेवाभिः आकृष्टाः, ये लोभपूरिताः, ये श्रद्धावन्तः, ये च भिक्षुकाः-- तान् वञ्चयितुं कः न समर्थः? (यः कोऽपि तत् विनायासं साध्नोतीति, एतादृशाः स्वयमेव वञ्चकानां वशे आपतन्तीति वा भावः) ॥१.८२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मीटी-मीठी बातों से तथा कपटमय सत्कारों से वश में किए गए तथा आशा रखनेवाले श्रद्धालु लोगों व याचकों को ठगना कौन बड़ी बात है? ॥१.८२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.82.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="183" class="total">
                    <div>
                        <button id="moolamsmall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '183')">मूलम्</button>
                        <button id="padasmall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '183')">पदविभागः</button>
                        <button id="anvayasmall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '183')">अन्वयः</button>
                        <button id="pratismall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '183')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '183')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '183')">हिन्द्यर्थः</button>
                        <button id="audiosmall183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '183')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उपकारिणि विश्रब्धे शुद्धमतौ यः समाचरति पापम् । तं जनमसत्यसन्धं भगवति वसुधे कथं वहसि ॥१.८३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उपकारिणि विश्रब्धे शुद्ध-मतौ यः समाचरति पापम् । तं जनम् असत्यसन्धं भगवति वसुधे कथं वहसि ॥१.८३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>भगवति वसुधे, यः उपकारिणि विश्रब्धे शुद्ध-मतौ पापं समाचरति, तम् असत्यसन्धं जनं कथं वहसि ॥१.८३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वसुधे = हे पृथ्वि! ; उपकारिणि = उपकारपरे ; विश्रब्धे = विश्वासमुपगते ; अत एव - शुद्ध-मतौ = सरलाशये, अशङ्किते ; पापं = (अत्र) विश्वासघातेन अनिष्टम् ; असत्यसन्धम् = असत्यप्रतिज्ञं, मिथ्याभाषिणम् ; कथं वहसि = त्वं कथं धारयसि? ॥१.८३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः (अस्मत् प्रति) उपकृतिमाचरति, अस्मासु विश्वसिति, शङ्कां न करोति- तादृशं प्रति यदि कोऽपि कपटम् आचरति, तर्हि हे भूमातः, त्वं तं (विश्वासघातकं) कथं (स्वस्यां) जीवयसि? (त्वया सः न धार्यः इति भावः)। ॥१.८३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो प्राणी-उपकारी, विश्वासी, एवं निष्कपट प्राणी के साथ भी विश्वासघात करता है, उस कपटी झूटे नीच पुरुष को तुम कैसे धारण करती हो? ॥१.८३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.83.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="184" class="total">
                    <div>
                        <button id="moolamsmall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '184')">मूलम्</button>
                        <button id="padasmall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '184')">पदविभागः</button>
                        <button id="anvayasmall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '184')">अन्वयः</button>
                        <button id="pratismall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '184')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '184')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '184')">हिन्द्यर्थः</button>
                        <button id="audiosmall184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '184')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दुर्जनेन समं सख्यं वैरं चापि न कारयेत् । उष्णो दहति चाङ्गारः शीतः कृष्णायते करम् ॥१.८४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दुर्जनेन समं सख्यं वैरं च अपि न कारयेत् । उष्णः दहति च अङ्गारः शीतः कृष्णायते करम् ॥१.८४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनेन समं सख्यं वैरं च अपि न कारयेत् । उष्णः दहति च अङ्गारः शीतः कृष्णायते करम् ॥१.८४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सख्यं = स्नेहं, मैत्रीं ; अङ्गारः = कोकिलः (कोयला) ; उष्णः = प्रदीप्तः सन् ; दहति = अग्नियुक्तं करोति ; शीतः = अनुष्णः कृष्णायते - कृष्णं करोति = मलिनीकुरुते। करं = हस्तम् ॥१.८४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुष्टेन साकं मित्रता वा शत्रुता वा न कार्या। (सः अङ्गारवत् भवति) अङ्गारः यदि तप्तः भवति तर्हि पाणिं तापयति। यदि अनुष्णः भवति तदा हस्तं कालवर्णेन मलिनं करोति॥१.८४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>दुर्जन के साथ मित्रता और प्रीति दोनों ही नहीं करनी चाहिये। क्यों कि -अङ्गार गरम (जलता) हो तो हाथ जलता है, और वही यदि शीतल हो तो हाथ को ही काला कर देता है ॥१.८४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
