                <div id="185" class="total">
                    <div>
                        <button id="moolamsmall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '185')">मूलम्</button>
                        <button id="padasmall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '185')">पदविभागः</button>
                        <button id="anvayasmall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '185')">अन्वयः</button>
                        <button id="pratismall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '185')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '185')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '185')">हिन्द्यर्थः</button>
                        <button id="audiosmall185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '185')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>प्राक् पादयोः पतति खादति पृष्ठमांसं कर्णे कलं किमपि रौति शनैर्विचित्रम् । छिद्रं निरूप्य सहसा प्रविशत्यशङ्कः सर्वं खलस्य चरितं मशकः करोति ॥१.८५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>प्राक् पादयोः पतति खादति पृष्ठ-मांसं कर्णे कलं किम् अपि रौति शनैः विचित्रम् । छिद्रं निरूप्य सहसा प्रविशति अशङ्कः सर्वं खलस्य चरितं मशकः करोति ॥१.८५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्राक् पादयोः पतति खादति पृष्ठ-मांसं कर्णे कलं किम् अपि रौति शनैः विचित्रम् । छिद्रं निरूप्य सहसा प्रविशति अशङ्कः सर्वं खलस्य चरितं मशकः करोति ॥१.८५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्राक् = पूर्वम्। पादयोः पतति = नीचैः गच्छति, (खलपक्षे-) चरणयोः प्रणमति च । पृष्ठमांसं खादति = पृष्ठे दशति, (खलपक्षे-) पृष्ठतो निन्दां करोति च ; कर्णे = श्रवणाङ्गे ; कलं = सुमधुरम् ; विचित्रं = नानाप्रकारम् ; किमपि = अनिर्वचनीयम् ; रौति = कूजति, कथयति च ; छिद्रं = विवरम्, अवसरं च ; निरूप्य = दृष्ट्वा ; अशङ्कः = निर्भयः सन् ; सहसा = सपदि, झटिति, अकस्मात् ; सर्वं = आसमन्तात्, अशेषं ; खलस्य = दुष्टस्य ; मशकः = दंशः ; चरितं = आचरणं ; ॥१.८५॥  </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मशकः पूर्वं चरणयोः दशति। ततः मांसं खादन् इव पृष्ठभागं दशति। (केवलं दंशित्वा न विश्राम्यति) कर्णयोः आगत्य किमपि मधुरं गायन्निव ध्वनिं करोति । ततः तत्र रन्ध्रमस्तीति दृष्ट्वा अन्तः निर्भयं प्रविशति। (खलोऽपि तथैवास्ति।) प्रथमं पादयोः नमस्करोति। ततः पृष्ठतः अस्माभिरविज्ञातम् अस्माकमेव निन्दां करोति। ततश्च अवसरं प्राप्य अन्येषां दोषान् अस्माकं पुरतः कथयति, अस्मासु आक्रमणमपि करोति। ॥१.८५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मच्छर पहले पैर पर गिरता है, फिर पीठ का मांस खाता है, पुनः धीरे-धीरे कान में कुछ गुनगुनाता है, फिर धीरे-धीरे मौका देखकर सहसा निर्भय होकर भीतर प्रवेश कर जाता है। इस प्रकार मच्छर दुर्जनों के सब चरित्रों का अनुकरण करता है । दुष्ट भी- पहले पैर पर गिरता है, फिर परोक्ष में (पीछे से) काम को बिगाड़ता है, फिर कान के पास आकर दूसरों की चुगली करता है, और मौका पाते ही आक्रमण भी करता है ॥१.८५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.85.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
