                        <button id="padasmall186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '186')">पदविभागः</button>
                        <button id="anvayasmall186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '186')">अन्वयः</button>
                        <button id="pratismall186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '186')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '186')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '186')">हिन्द्यर्थः</button>
                        <button id="audiosmall186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '186')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दुर्जनः प्रियवादी च नैतद् विश्वासकारणम् । मधु तिष्ठति जिह्वाग्रे हृदि हालाहलं विषम् ॥१.८६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दुर्जनः प्रियवादी च न एतद् विश्वास-कारणम् । मधु तिष्ठति जिह्व-अग्रे हृदि हालाहलं विषम् ॥१.८६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनः प्रियवादी च- एतद् विश्वास-कारणं न । जिह्वाग्रे मधु तिष्ठति हृदि हालाहलं विषं (तिष्ठति) ॥१.८६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दुर्जनः प्रियवादी च- एतद् विश्वास-कारणं न । जिह्वाग्रे मधु तिष्ठति हृदि हालाहलं विषं (तिष्ठति) ॥१.८६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः दुर्मनाः सन् मधुरालापं करोति तथापि तत्र आश्वासः न विधेयः, यतस्तस्य जिह्वायामेव मधुनः माधर्यं भवति। हृदये तु पुनः गरलमिव अतिभयानकभावना भवति। ॥१.८६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>दुर्जन भी कभी सच्चा प्रियवादी (मीठा बोलनेवाला हितैषी) हो सकता है, यह कभी विश्वास नहीं करना चाहिए, क्यों कि दुर्जन की जिह्वा पर हो मधुरता रहती है, परन्तु हृदय में तो उसके हलाहल विष ही भरा हुआ है ॥१.८६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
