                        <button id="padasmall187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '187')">पदविभागः</button>
                        <button id="anvayasmall187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '187')">अन्वयः</button>
                        <button id="pratismall187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '187')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '187')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '187')">हिन्द्यर्थः</button>
                        <button id="audiosmall187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '187')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>त्रिभिर्वर्षैस्त्रिभिर्मासैस्त्रिभिः पक्षैस्त्रिभिर्दिनैः । अत्युत्कटैः पापपुण्यैरिहैव फलमश्नुते ॥१.८७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>त्रिभिः वर्षैः त्रिभिः मासैः त्रिभिः पक्षैः त्रिभिः दिनैः । अत्युत्कटैः पापपुण्यैः इह एव फलम् अश्नुते ॥१.८७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अत्युत्कटैः पापपुण्यैः त्रिभिः वर्षैः त्रिभिः मासैः त्रिभिः पक्षैः त्रिभिः दिनैः फलम् इह एव अश्नुते ॥१.८७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अत्युत्कटैः = विषमैः ; पापपुण्यै = सत्कर्मभिः दुष्कर्मभिः च ; वर्षैः = वत्सरावधिककालेन ; मासैः = मासावधिककालेन ; पक्षैः = पक्षावधिककालेन ; दिनैः = दिवसैः ; इह एव = अस्मिन्नेव जन्मनि ; अश्नुते = उपभुङक्ते ॥१.८७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अत्युत्कटैः = विषमैः ; पापपुण्यै = सत्कर्मभिः दुष्कर्मभिः च ; वर्षैः = वत्सरावधिककालेन ; मासैः = मासावधिककालेन ; पक्षैः = पक्षावधिककालेन ; दिनैः = दिवसैः ; इह एव = अस्मिन्नेव जन्मनि ; अश्नुते = उपभुङक्ते ॥१.८७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उत्कट पापों व पुण्यों का फल इसी लोक में- तीन वर्ष में, या तीन महीने में, या तीन पक्ष में, या तीन दिन के भीतर ही मनुष्य को मिल जाता है ॥१.८७ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
