                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="189" class="total">
                    <div>
                        <button id="moolamsmall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '189')">मूलम्</button>
                        <button id="padasmall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '189')">पदविभागः</button>
                        <button id="anvayasmall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '189')">अन्वयः</button>
                        <button id="pratismall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '189')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '189')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '189')">हिन्द्यर्थः</button>
                        <button id="audiosmall189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '189')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तिरश्चामपि विश्वासो दृष्टः पुण्यैककर्मणाम् । सतां हि साधुशीलत्वात् स्वभावो न निवर्तते ॥१.८९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तिरश्चाम् अपि विश्वासः दृष्टः पुण्य-एककर्मणाम् । सतां हि साधु-शीलत्वात् स्वभावः न निवर्तते ॥१.८९॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पुण्य-एककर्मणां तिरश्चाम् अपि विश्वासः दृष्टः । सतां स्वभावः साधु-शीलत्वात् न निवर्तते हि ॥१.८९॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>तिरश्चां = पशुपक्ष्यादीनाम् ; विश्वासः = आश्वासः ; दृष्टः = अनुभूतः ; (पुण्यमेकं कर्म येषा तेषां) पुण्यैककर्मणां = पुण्यात्मनां जनानाम् ; साधुशीलत्वात् = शुभाचारत्वात् ; स्वभावः = प्रकृतिः (व्यवहरणाधारभूतः मूलभूतः गुणः) ; साधुता शीलत्वं तस्मात् ; न निवर्तते = (जन्मान्तरेऽपि) न अपयाति ॥१.८९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये पशुपक्षिणः पुण्यवन्तः भवन्ति, तेषु परस्परं विश्वासः दृश्यते । सज्जनाः प्रकृतेः सदाचारित्वं न त्यजन्ति ॥१.८९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>पुण्यात्मा पशुपक्षियों का भी परस्पर में विश्वास देखा गया है, क्यों कि पुण्यवान् सज्जनों का स्वभाव साधुशील (सदाचारी) होने के कारण किसी भी योनि (जन्म) में नहीं बदलता है ॥१.८९॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
