                </div>
                
                
                <div id="190" class="total">
                    <div>
                        <button id="moolamsmall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '190')">मूलम्</button>
                        <button id="padasmall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '190')">पदविभागः</button>
                        <button id="anvayasmall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '190')">अन्वयः</button>
                        <button id="pratismall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '190')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '190')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '190')">हिन्द्यर्थः</button>
                        <button id="audiosmall190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '190')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पुण्यात्मा पशुपक्षियों का भी परस्पर में विश्वास देखा गया है, क्यों कि पुण्यवान् सज्जनों का स्वभाव साधुशील (सदाचारी) होने के कारण किसी भी योनि (जन्म) में नहीं बदलता है ॥१.८९॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>साधोः प्रकोपितस्य अपि मनः न आयाति विक्रियाम् । न हि तापयितुं शक्यं सागर-अम्भः तृण-उल्कया ॥१.९०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्रकोपितस्य साधोः अपि मनः विक्रियाम् न आयाति । सागराम्भः तृणोल्कया हि तापयितुं न शक्यम् ॥१.९०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>साधोः = सज्जनस्य ; प्रकोपितस्य = कोपं प्रापितस्यापि ; मनः = मतिः ; विक्रियां = विकारम् ; न आयाति = न प्राप्नोति गच्छति वा ; हि = यतः ; सागराम्भः = समुद्रजलं ; तृणोल्का = तृणमेव उल्का इव, अग्नियुक्तघासः ; तापयितुं = उष्णीकर्तुं ; न शक्यम् = असाध्यम्; ॥१.९०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>साधोः = सज्जनस्य ; प्रकोपितस्य = कोपं प्रापितस्यापि ; मनः = मतिः ; विक्रियां = विकारम् ; न आयाति = न प्राप्नोति गच्छति वा ; हि = यतः ; सागराम्भः = समुद्रजलं ; तृणोल्का = तृणमेव उल्का इव, अग्नियुक्तघासः ; तापयितुं = उष्णीकर्तुं ; न शक्यम् = असाध्यम्; ॥१.९०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सज्जन का चित्त क्रोध दिलाये जाने पर भी विकार को प्राप्त नहीं होता है । जैसे समुद्र के जल को घास कूस को अग्नि (लुकाटी) से गरम नहीं किया जा सकता है । ॥१.९०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.90.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="192" class="total">
                    <div>
                        <button id="moolamsmall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '192')">मूलम्</button>
                        <button id="padasmall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '192')">पदविभागः</button>
                        <button id="anvayasmall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '192')">अन्वयः</button>
                        <button id="pratismall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '192')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '192')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '192')">हिन्द्यर्थः</button>
                        <button id="audiosmall192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '192')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शत्रुणा न हि सन्दध्यात् सुश्लिष्टेनापि सन्धिना । सुतप्तमपि पानीयं शमयत्येव पावकम् ॥१.९२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शत्रुणा न हि सन्दध्यात् सुश्लिष्टेन अपि सन्धिना । सुतप्तम् अपि पानीयं शमयति एव पावकम् ॥१.९२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शत्रुणा सुश्लिष्टेन अपि सन्धिना न हि सन्दध्यात् । पानीयं सुतप्तम् अपि पावकं शमयति एव ॥१.९२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शत्रुणा सुश्लिष्टेन अपि सन्धिना न हि सन्दध्यात् । पानीयं सुतप्तम् अपि पावकं शमयति एव ॥१.९२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अत्यन्तं दृढबन्धनशीलेन मैत्रिणा अपि अरिणा सह सुहृद्भावः न युक्तः । (अत्र उदाहरणम्) वारि तप्तम् अपि अग्निं निर्वापयति एव। [अत्र अयं भावः- नीरम् अग्नेः शत्रुः भवति। द्वयोः गुणौ विलोमौ। वह्निना युक्तः सन्नेव अम्बु उष्णीभवति। तेनैव तप्तं सदपि तदुदकम् अनलं ज्वलने न सहकरोति अपिच अपाकरोति।]॥१.९२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उत्तम से उत्तम स्नेहभाव के द्वारा भी शत्रु से कभी सन्धि (मेल) नहीं करना चाहिये। क्यों कि यदि पानी गरम होगा तो भी वह अग्नि को तो बुझा ही देता है ॥१.९२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.92.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="193" class="total">
                    <div>
                        <button id="moolamsmall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '193')">मूलम्</button>
                        <button id="padasmall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '193')">पदविभागः</button>
                        <button id="anvayasmall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '193')">अन्वयः</button>
                        <button id="pratismall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '193')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '193')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '193')">हिन्द्यर्थः</button>
                        <button id="audiosmall193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '193')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दुर्जनः परिहर्तव्यो विद्ययालङ्कृतोऽपि सन् ।  मणिना भूषितः सर्पः किमसौ न भयङ्करः ॥१.९३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दुर्जनः परिहर्तव्यः विद्यया अलङ्कृतः अपि सन् । मणिना भूषितः सर्पः किम् असौ न भयङ्करः ॥१.९३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनः विद्यया अलङ्कृतः अपि सन् परिहर्तव्यः । मणिना भूषितः सर्पः असौ किम् न भयङ्करः? ॥१.९३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दुर्जनः = दुष्टः ; विद्यया = ज्ञानेन ; अलङ्कृतः अपि सन् = भूषितः भूत्वा अपि ; परिहर्तव्यः = त्याज्यः ; मणिना = रत्नेन ; भूषितः = अलङ्कृतः ; सर्पः = नागः ; असौ = सः ; किम् न = (प्रश्नः) ; भयङ्करः = भयमुत्पादयति यः ; ॥१.९३॥ </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ज्ञानेन आभूषितोऽपि दुष्टात्मा (दूरेणैव) परित्याज्यः। अत्र उदाहरणम्। भुजङ्गः रत्नेन अलङ्कृतोऽपि (सुन्दरः उपगमने योग्यः न भवति) भयमेवोत्पादयति ॥१.९३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>यदि दुर्जन विद्या से विभूषित भी हो तो भी उससे दूर ही रहना चाहिये । क्यों कि मणि से विभूषित होने पर भी क्या सर्प भयङ्कर नहीं होता है? अवश्य ही भयङ्कर होता है ॥१.९३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.93.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="194" class="total">
                    <div>
                        <button id="moolamsmall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '194')">मूलम्</button>
                        <button id="padasmall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '194')">पदविभागः</button>
                        <button id="anvayasmall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '194')">अन्वयः</button>
                        <button id="pratismall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '194')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '194')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '194')">हिन्द्यर्थः</button>
                        <button id="audiosmall194" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '194')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यदशक्यं न तच्छक्यं यच्छक्यं शक्यमेव तत् । नोदके शकटं याति न च नौर्गच्छति स्थले ॥१.९४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् अशक्यं न तत् शक्यं यत् शक्यं शक्यम् एव तत् । न उदके शकटं याति न च नौः गच्छति स्थले ॥१.९४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् अशक्यं तत् न शक्यम् । यत् शक्यं तत् शक्यम् एव । उदके शकटं न याति । नौः च स्थले न गच्छति ॥१.९४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यत् = यत्कार्यम् ; अशक्यम् = यत् कर्तुम् वयं न समर्थाः ; यत् च शक्यं = यत् कर्तुं वयं प्रभवामः ; तत् शक्यमेव = सम्भवत्येव ; स्वयमेव = अनायासेन एव भवति ; उदके = जले ; शकटं = गन्त्री  (गाडी) ; स्थले = भूमौ ; नौः = नौका ॥१.९४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यत् आचरितुं प्रभवामः, तत् कार्यं सम्पन्नं भवत्येव। यत् आचरितुं न समर्थाः तत् असम्पन्नं भवति । (अस्योदाहर्णम्) वारिणि नौका गन्तुं पारयति, किन्तु स्थलयानं न याति। तथैव भुवि नौः न व्रजति । ॥१.९४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो कार्य नहीं होने लायक है, वह नहीं हो सकता है, और जो होने लायक है, वह सर्वदा हो ही सकता है । जैसे गाड़ी जल में नहीं चल सकती है और भूमि पर नाव नहीं चल सकती है । अर्थात्- जो कार्य होने लायक हो वही करना चाहिए, असम्भव कार्य के लिए प्रयत्न करना मूर्खता है ॥१.९४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.94.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="195" class="total">
                    <div>
                        <button id="moolamsmall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '195')">मूलम्</button>
                        <button id="padasmall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '195')">पदविभागः</button>
                        <button id="anvayasmall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '195')">अन्वयः</button>
                        <button id="pratismall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '195')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '195')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '195')">हिन्द्यर्थः</button>
                        <button id="audiosmall195" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '195')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>महताप्यर्थसारेण यो विश्वसिति शत्रुषु । भार्यासु च विरक्तासु तदन्तं तस्य जीवनम् ॥१.९५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>महता अपि अर्थसारेण यः विश्वसिति शत्रुषु । भार्यासु च विरक्तासु तदन्तं तस्य जीवनम् ॥१.९५॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः महता अपि अर्थसारेण शत्रुषु विश्वसिति, विरक्तासु भार्यासु च तस्य जीवनं तदन्तम् ॥१.९५॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>महता अपि = विपुलेन अपि ; अर्थसारेण = धनादिबलेन समन्वितोऽपीति शेपः ;  यद्वा अर्थसिद्ध्यादिकारणवशेन; यः = यो जनः ; च = पुनः ; विरक्तासु = अननुरक्तासु, परपुरुषरतासु च विश्वसितीति शेपः ; तदन्तं = तद्विश्वासपर्यन्तमेव ; जीवितं = जीवनम् ; केचित्तु- महता अपि अर्थसारेण इत्यस्य गुरुणापि प्रयोजनेन इत्यर्थम् आहुः ॥१.९५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः पुरुषः बृहतः प्रयोजनस्य कारणेनापि अरिषु आश्वासनं करोति, परस्त्रीषु अनुरक्तेः कारणेन आश्वस्तः वा भवति, तस्य जीवनं तावत् पर्यन्तमेव चलति, यावत् सः आश्वासभावः तिष्ठति। विश्वासभावः यदा समाप्तिमेति तदा तस्य जीवनम् अन्तं याति॥१.९५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो पुरुष विशेष लाभवश भी शत्रुओंका, या विरक्त स्त्री (पर-पुरुषानुरागवती) का विश्वास करता है, उस पुरुष के जीवन का अन्त ही समझना चाहिये ॥१.९५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.95.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="196" class="total">
                    <div>
                        <button id="moolamsmall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '196')">मूलम्</button>
                        <button id="padasmall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '196')">पदविभागः</button>
                        <button id="anvayasmall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '196')">अन्वयः</button>
                        <button id="pratismall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '196')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '196')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '196')">हिन्द्यर्थः</button>
                        <button id="audiosmall196" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '196')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मृद्घटवत् सुखभेद्यो दुःसन्धानश्च दुर्जनो भवति । सुजनस्तु कनकघटवद् दुर्भेद्यश्चाशु सन्धेयः ॥१.९६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मृद्घट-वत् सुखभेद्यः दुःसन्धानः च दुर्जनः भवति । सुजनः तु कनक-घटवद् दुर्भेद्यः आशु सन्धेयः ॥१.९६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनः च मृद्घटवत् सुखभेद्यः दुःसन्धानः च भवति । सुजनः तु कनक-घटवद् दुर्भेद्यः आशु सन्धेयः ॥१.९६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मृद्धटवत् = मृत्तिकया निर्मतकुम्भः इव ; सुखभेद्यः = सुकरं भेत्तुं शक्यः ; दुःसन्धानः = पुनर्योजितुम् अशक्यः ;  कनकघटवत् = सुवर्णादिकुम्भवत् ; दुर्भेद्यः = भेत्तुम् असुकरः ; आशु = अनायासेन ; सन्धेयः = योज्यः ॥१.९६॥   </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अयं श्लोकः दुर्जनसज्जनयोः मध्ये भेदं ज्ञापयति) दुर्जनः मृत्तिकाभाण्डः इव अनायासेन भग्नः भवति, नाम क्रोधादिविकारान् प्राप्नोति भवति; पुनः योजितुं कदापि शक्यः न भवति, नाम शान्तः न भवति। किन्तु सज्जनः स्वर्णकलशसदृशः विभक्तुम् अशक्यः, नाम अविकृतः भवति; पुनश्च यदि किञ्चित् भग्नः, तदा विनायासं योजितुं शक्यः, नाम झटिति स्वस्थितिं प्राप्नोति॥१.९६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>दुर्जन प्राणी मिट्टी के घड़े की तरह अनायास ही विकृत हो (फूट-फूट) जाते हैं और उनका पुनः मेल (जोड़ना) कठिनता से होता है । परन्तु सज्जन लोग सुवण के घट की तरह जल्दी बिगड़ते (टूटते) नहीं है, और यदि बिगड़ते भी है, तो शीघ्र ही पुनः ठीक किए (जोड़े) जा सकते हैं ॥१.९६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.96.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="197" class="total">
                    <div>
                        <button id="moolamsmall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '197')">मूलम्</button>
                        <button id="padasmall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '197')">पदविभागः</button>
                        <button id="anvayasmall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '197')">अन्वयः</button>
                        <button id="pratismall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '197')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '197')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '197')">हिन्द्यर्थः</button>
                        <button id="audiosmall197" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '197')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>द्रवत्वात् सर्वलोहानां निमित्तान्मृगपक्षिणाम् । भयाल्लोभाच्च मूर्खाणां सङ्गतं दर्शनात् सताम् ॥१.९७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>द्रवत्वात् सर्व-लोहानां निमित्ताद् मृग-पक्षिणाम् । भयात् लोभात् च मूर्खाणां सङ्गतं दर्शनात् सताम् ॥१.९७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सर्व-लोहानां द्रवत्वात्, मृग-पक्षिणां निमित्ताद्, मूर्खाणां भयात् लोभात् च, सतां सङ्गतं दर्शनात् (भवति)॥१.९७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सर्वलौहानां = सकलधातूनां ; द्रवत्वात् = द्रवभावेन ; मृगपक्षिणां = पशूनां खगानां च ; निमित्तात् = भोजनादिदानात्, कार्यकारण-भावाच्च ; मूर्खाणां = मूढानां ; भयात् = भीतेः ; लोभात् = लौल्यात् ; सतां = सज्जनानां ; दर्शनाद् = प्रेक्षणमात्राद् एव ; सङ्गतं = मैत्री ॥१.९७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>समस्तधातुपदार्थानां विगलनमार्गेण संयुक्तता भवति। पशूनां पक्षिणां च मैत्री केनचिद् हेतुना कल्प्यते। बुद्धिहीनानां साङ्गत्यं भीतेः लोलुपतायाः च कारणात् घटते। सज्जनानां मित्रत्वं केवलं दर्शनमात्रेण जागर्ति॥१.९७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सब धातुओंका परस्पर मेल गलाने से ही होता है, पशुपक्षियों का मेल किसी निमित्त (कारण) से ही होता है, मूर्खों का मेल भय और लोभ से ही होता है, परन्तु सज्जनों का मेल (मैत्री) तो केवल दर्शनमात्र से ही हो जाता है ॥१.९७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.97.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="198" class="total">
                    <div>
                        <button id="moolamsmall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '198')">मूलम्</button>
                        <button id="padasmall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '198')">पदविभागः</button>
                        <button id="anvayasmall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '198')">अन्वयः</button>
                        <button id="pratismall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '198')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '198')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '198')">हिन्द्यर्थः</button>
                        <button id="audiosmall198" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '198')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>नारिकेलसमाकारा दृश्यन्ते हि सुहृज्जनाः । अन्ये बदरिकाकारा बहिरेव मनोहराः ॥१.९८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>नारिकेल-समाकाराः दृश्यन्ते हि सुहृज्जनाः । अन्ये बदरिका-आकाराः बहिः एव मनोहराः ॥१.९८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सुहृज्जनाः नारिकेलसमाकाराः दृश्यन्ते हि । अन्ये बदरिकाकाराः बहिः एव मनोहराः ॥१.९८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नारिकेलसमाकाराः = नारिकेलफलवद्वहिः कठिनाः, अन्तः मृदवः च; दृश्यन्ते = भान्ति ; सुहृज्जनाः = सज्जनाः, सन्तः; अन्ये = सज्जनेतराः, खलाः; बदरिकाकाराः = बदरीफलमिव बाह्ये कोमलाः अभ्यन्तरे कठिनाः च, दुःखदाः; ॥१.९८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नारिकेलफलसदृशाः सुहृदयाः जनाः बाह्यदर्शनाय कठिनाः भवन्ति, परन्तु यथा नारिकेलस्यान्तः जलं वर्तते, तथैव ऐते अन्तः मृदवः भवन्ति। दुष्टजनाः पुनः बदरीफलसन्निभाः भवन्ति- बहिः दर्शनाय सरलाः मृदवश्च। किन्तु अन्तः सर्वं कठोरबीजमेव भवति। ॥१.९८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सज्जन लोग नारियल के फल के समान ऊपर से ही रूखे व कड़े देख पड़ते हैं, परन्तु भीतर उनके मधुरता ही होती है । अर्थात् बाहर से तो वे कठोर मालूम पड़ते हैं, परन्तु भीतर से बड़े ही दयालु होते हैं । पर दूसरे लोग (अर्थात् दुर्जन लोग) बैर के फल की तरह बाहर से ही सुन्दर देख पड़ते हैं, परन्तु भीतर उनके कठोरता (कड़ी गुठली) ही रहती है ॥१.९८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.98.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="199" class="total">
                    <div>
                        <button id="moolamsmall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '199')">मूलम्</button>
                        <button id="padasmall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '199')">पदविभागः</button>
                        <button id="anvayasmall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '199')">अन्वयः</button>
                        <button id="pratismall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '199')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '199')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '199')">हिन्द्यर्थः</button>
                        <button id="audiosmall199" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '199')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्नेहच्छेदेऽपि साधूनां गुणा नायान्ति विक्रियाम् । भङ्गेऽपि हि मृणालानामनुबध्नन्ति तन्तवः ॥१.९९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्नेहच्छेदे अपि साधूनां गुणा न आयान्ति विक्रियाम् । भङ्गे अपि हि मृणालानाम् अनुबध्नन्ति तन्तवः ॥१.९९॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>साधूनां गुणाः स्नेहच्छेदे अपि विक्रियाम् न आयान्ति । मृणालानां भङ्गे अपि तन्तवः अनुबध्नन्ति हि॥१.९९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्नेहच्छेदे = प्रणयभङ्गे ; साधूनां = सज्जनानां ; गुणाः = सरलत्वादयः सद्गुणाः ; विक्रियां = विकारम् ; भङ्गेऽपि = छेदेऽपि ; मृणालानाम् = कमलदण्डानाम् ; तन्तवः = बिससूत्राणि, बिसतन्तवः ; अनुबध्नन्ति = सम्बन्धं न परिहरन्ति ॥१.९९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सत्पुरुषानां मध्ये यदा स्नेहच्छेदः भवति, तदापि तेषां सल्लक्षणानि दूषितानि न भवन्ति। (अत्रोदाहरणम्) कमलनालानि यदा विच्छिद्यन्ते तदापि तेषाम् अन्तःस्थितानि तनूनि सूत्राणि परस्परं बद्धानि एव भवन्ति, बन्धं न त्यजन्ति॥१.९९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और सज्जनों के साथ प्रीति टूट जाने पर भी उनका चित्त विकृत नहीं होता है, किन्तु उनका साधारण सम्बन्ध बना ही रहता है। जैसे मृणालों (कमल की डण्डी) के बीच में से टूट जाने पर भी उनके तन्तु परस्पर में जुड़े ही रहते हैं ॥१.९९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.99.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1100" class="total">
                    <div>
                        <button id="moolamsmall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1100')">मूलम्</button>
                        <button id="padasmall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1100')">पदविभागः</button>
                        <button id="anvayasmall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1100')">अन्वयः</button>
                        <button id="pratismall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1100')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1100')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1100')">हिन्द्यर्थः</button>
                        <button id="audiosmall1100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1100')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शुचित्वं त्यागिता शौर्यं सामान्यं सुखदुःखयोः । दाक्षिण्यं चानुरक्तिश्च सत्यता च सुहृद्गुणाः ॥१.१००॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शुचित्वं त्यागिता शौर्यं सामान्यं सुख-दुःखयोः । दाक्षिण्यं च अनुरक्तिः च सत्यता च सुहृद्गुणाः ॥१.१००॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शुचित्वं, त्यागिता, शौर्यं, सुख-दुःखयोः सामान्यं, दाक्षिण्यम्, अनुरक्तिः, सत्यता च – (एते) सुहृद्गुणाः (सन्ति) ॥१.१००॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शुचित्वं= स्वच्छता ; त्यागिता = औदार्यम् ; शौर्यं = वीरता ; सुखदुःखयोः = सुखे, दुःखे च ; सामान्यं = समता ; दाक्षिण्यं = कुशलता ; अनुरक्तिः = अनुरागभावः ; सत्यता = सत्यवाक्॥१.१००॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>स्वच्छत्वं, उदारत्वं, शूरत्वं, सन्तोषपीडयोः समत्वं, सामर्थ्यम्, अनुरागः, सत्यत्वं – एतानि सर्वाणि मित्रस्य लक्षणानि॥१.१००॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>चित्त शुद्धि, त्याग, वीरता, सुख और दुःख में एक सा भाव, उदारता, प्रेम, सत्य- ये सब मित्र के गुण हैं ॥१.१००॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.100.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1101" class="total">
                    <div>
                        <button id="moolamsmall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1101')">मूलम्</button>
                        <button id="padasmall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1101')">पदविभागः</button>
                        <button id="anvayasmall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1101')">अन्वयः</button>
                        <button id="pratismall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1101')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1101')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1101')">हिन्द्यर्थः</button>
                        <button id="audiosmall1101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1101')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>घर्मार्तं न तथा सुशीतलजलैः स्नानं न मुक्तावली न श्रीखण्डविलेपनं सुखयति प्रत्यङ्गमप्यर्पितम् । प्रीत्यै सज्जनभाषितं प्रभवति प्रायो यथा चेतसः सद्युक्त्या च परिष्कृतं सुकृतिनामाकृष्टिमन्त्रोपमम् ॥१.१०१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>घर्म-आर्तं न तथा सुशीतल-जलैः स्नानं न मुक्तावली न श्रीखण्ड-विलेपनम् सुखयति प्रत्यङ्गम् अपि अर्पितम् । प्रीत्यै सज्जन-भाषितं प्रभवति प्रायः यथा चेतसः सद्युक्त्या च परिष्कृतं सुकृतिनाम् आकृष्टि-मन्त्र-उपमम् ॥१.१०१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>घर्म-आर्तं न तथा सुशीतल-जलैः स्नानं न मुक्तावली न श्रीखण्ड-विलेपनम् सुखयति प्रत्यङ्गम् अपि अर्पितम् । प्रीत्यै सज्जन-भाषितं प्रभवति प्रायः यथा चेतसः सद्युक्त्या च परिष्कृतं सुकृतिनाम् आकृष्टि-मन्त्र-उपमम् ॥१.१०१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>घर्मार्तं = निदाघसन्तप्तं पुमांसं; सुशीतलजैः = शीतनीरैः ; स्नानं = शरीरस्य जलेन शुद्धीकरणं ;  मुक्तावली = मुक्तानां माला ;  प्रत्यङ्गं = प्रत्यवयवम् ; अर्पितं = दत्तं, लेपितं ; श्रीखण्डविलेपनम् = चन्दनस्य लेपनं ; सुखयति = प्रसन्नकरं भवति ; चेतसः = मनसः ; प्रीत्यै = आनन्दाय ; सद्युक्या = शोभनयुक्त्या, कल्पोक्तविधिविधानेन च ; परिष्कृतं = शोभितम् ; आकृष्टिमन्त्रोपमम् = आकर्षणमन्त्रतुल्यम् ; सज्जनभाषितं =सत्पुरुषाणां वचांसि ; प्रभवति = शक्तो भवति ॥१.१०१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>निदाघतप्तं पुरुषं हिमजलैः स्नानं तथा न हर्षयति। मुक्तानां हारं धृत्वा वा, श्रीचन्दनं सर्वेषु अवयवेषु विलेप्य वा सः तादृशं सुखं नानुभवति। सुष्ठु युक्तिभिः अलङ्कृतं, आकर्षणमन्त्रसदृशं सत्पुरुषवचनं श्रुत्वा मनसः अतिशयेन सन्तोषः भवति॥१.१०१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>आकर्षण मन्त्र की तरह मन को खींचने वाली, अच्छी २ युक्तियों से युक्त सज्जनों की वाणी चित्त को जितना आनन्द देती है, उतना सुख घाम से सन्तप्त मनुष्यों को- शीतल जल का स्नान, मोती की माला और शरीर में लगा शुभा चन्दन भी नहीं देता है ॥१.१०१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.101.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1102" class="total">
                    <div>
                        <button id="moolamsmall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1102')">मूलम्</button>
                        <button id="padasmall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1102')">पदविभागः</button>
                        <button id="anvayasmall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1102')">अन्वयः</button>
                        <button id="pratismall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1102')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1102')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1102')">हिन्द्यर्थः</button>
                        <button id="audiosmall1102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1102')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>रहस्यभेदो याच्ञा च नैष्ठुर्यं चलचित्तता । क्रोधो निःसत्यता द्यूतमेतन्मित्रस्य दूषणम् ॥१.१०२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रहस्यभेदः याच्ञा च नैष्ठुर्यं चलचित्तता । क्रोधः निःसत्यता द्यूतम् एतत् मित्रस्य दूषणम् ॥१.१०२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>रहस्यभेदः, याच्ञा च, नैष्ठुर्यं, चलचित्तता, क्रोधः, निःसत्यता, द्यूतम् - एतत् मित्रस्य दूषणम् ॥१.१०२॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>रहस्यभेदः = मित्रस्य अन्तरङ्गविषयाणां बहिः वचनम् ; याच्ञा = द्रव्यादिप्रार्थना ; नैष्टुर्यं = कोठरव्यवहारः; चलचित्तता = अस्थिरत्वम् ; निःसत्यता = मिथ्याभाषित्वम् ; द्यूतम् = अक्षक्रीडा ; मित्रस्य = सुहृदः ; दूषणम् = दोषः, ॥१.१०२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मित्रीभङ्गकारिणः, मित्रे अवगुणाः केचन अत्र उच्यन्ते- १. मित्रस्य रहस्यानाम् उद्घाटनम्, २. वस्तुभ्यः, धनार्थं वा याचनम्, ३. परुषवचांसि, व्यवहारश्च ४. मनसः चाञ्चल्यम्, ५. असत्यभाषणम्, ६. द्यूतम् ॥१.१०२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>गुप्त बातों को प्रगट कर देना, माँगना, निष्ठुरता, चित्त की अस्थिरता, क्रोध, झूठ बोलना, जुआ खेलना ये सब मित्र के दोष हैं ॥१.१०२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.102.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1103" class="total">
                    <div>
                        <button id="moolamsmall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1103')">मूलम्</button>
                        <button id="padasmall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1103')">पदविभागः</button>
                        <button id="anvayasmall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1103')">अन्वयः</button>
                        <button id="pratismall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1103')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1103')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1103')">हिन्द्यर्थः</button>
                        <button id="audiosmall1103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1103')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पटुत्वं सत्यवादित्वं कथायोगेन बुद्ध्यते । अस्तब्धत्वमचापल्यं प्रत्यक्षेनावगम्यते ॥१.१०३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पटुत्वं सत्य-वादित्वं कथा-योगेन बुद्ध्यते । अस्तब्धत्वम् अचापल्यं प्रत्यक्षेन अवगम्यते ॥१.१०३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पटुत्वं सत्य-वादित्वं (च) कथा-योगेन बुद्ध्यते । अस्तब्धत्वम् अचापल्यं प्रत्यक्षेन अवगम्यते ॥१.१०३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पटुत्वं = कुशलत्वम् ; सत्यवादित्वम् = सदा सत्यं वचनं ; कथायोगैन = प्रसङ्गेन ; बुध्यते = सर्वैर्ज्ञातुं शक्यते, मया च ज्ञायते ; अस्तब्धत्वम् = अजडत्वम्, अभीतत्वम् ; अचापल्यं = स्थिरत्वम् ; प्रत्यक्षेण = सावाद्दर्शनेन ; साक्षात् = त्वन्मुखदर्शनादेव च मया ज्ञायते इति भावः ॥१.१०३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्यः समर्थः, सत्यवादी वा अस्ति, न वेति प्रसङ्गात् ज्ञायते। (तदर्थं सन्दर्भादिकस्य आवश्यकता वर्तते।) किन्तु सः जडः नास्ति, चपलः नास्तीति प्रत्यक्षमेव ज्ञायते॥१.१०३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मनुष्य की चतुराई और सचाई तो बात चीत करने से मालूम होती है, पर मनुष्य की नमता और गम्भीरता ता उसे देखने से ही मालूम हो जाती है ॥१.१०३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.103.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1104" class="total">
                    <div>
                        <button id="moolamsmall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1104')">मूलम्</button>
                        <button id="padasmall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1104')">पदविभागः</button>
                        <button id="anvayasmall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1104')">अन्वयः</button>
                        <button id="pratismall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1104')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1104')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1104')">हिन्द्यर्थः</button>
                        <button id="audiosmall1104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1104')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अन्यथैव हि सौहार्दं भवेत् स्वच्छान्तरात्मनः । प्रवर्ततेऽन्यथा वाणी शाठ्योपहतचेतसः ॥१.१०४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अन्यथा एव हि सौहार्दं भवेत् स्वच्छ-अन्तरात्मनः । प्रवर्तते अन्यथा वाणी शाठ्य-उपहत-चेतसः ॥१.१०४॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>स्वच्छ-अन्तरात्मनः सौहार्दम् अन्यथा एव हि भवेत् । शाठ्योपहतचेतसः वाणी अन्यथा प्रवर्तते ॥१.१०४॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्वच्छान्तरात्मनः = शुद्धचेतसः ; अन्यथैव = अन्यप्रकारेण एव ; सौहार्दं = मैत्री ; शाठ्योपहतचेतसः = क्रौर्य-निष्ठुर-चेतसः, शठस्य ; अन्यथैव = अन्यादृशी एव कपटपूर्णा ; वाणी = वाक् ; प्रवर्त्तते = प्रसरति ॥१.१०४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>स्वच्छमनसः सौमनस्यं एकविधं (समं, सद्भावपूर्णं च) भवति। दुष्टमनस्कस्य भाषा अन्यथा (कठिना, परुषा च) भवति ॥१.१०४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>शुद्धहृदय वाले सज्जन की सहृदयता तो कुछ और ही प्रकार की होती है और कुटिल हृदय धूर्त की बोलचाल कुछ और ही तरह की दोती है। अर्थात् सज्जन और दुर्जन का भेद तो बातों से ही मालूम हो जाता है ॥१.१०४॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.104.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1105" class="total">
                    <div>
                        <button id="moolamsmall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1105')">मूलम्</button>
                        <button id="padasmall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1105')">पदविभागः</button>
                        <button id="anvayasmall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1105')">अन्वयः</button>
                        <button id="pratismall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1105')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1105')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1105')">हिन्द्यर्थः</button>
                        <button id="audiosmall1105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1105')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मनस्यन्यद् वचस्यन्यत् कर्मण्यन्यद् दुरात्मनाम् । मनस्येकं वचस्येकं कर्मण्येकं महात्मनाम् ॥१.१०५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मनसि अन्यद् वचसि अन्यत् कर्मणि अन्यद् दुरात्मनाम् । मनसि एकं वचसि एकं कर्मणि एकं महात्मनाम् ॥१.१०५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुरात्मनां मनसि अन्यद्, वचसि अन्यत्, कर्मणि अन्यद् (भवति) । महात्मनां मनसि एकं वचसि एकं कर्मणि एकम् (भवति)॥१.१०५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मनसि = चित्ते ; वचसि = वचने ; कर्मणि = कार्याचरणे ; अन्यत् = यद् दृश्यते तस्मात् भिन्नम् ; दुरात्मनां = पापिनाम् ; महात्मनाम् = सत्पुरुषानाम् ॥१.१०५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुष्टानां मनसि अन्यद् भवति। ते हि अन्यया भाषन्ते । क्रियायाम् अन्यदेव आचरन्ति । महात्मनां तु यदेव मनसि, तदेव तेषां वचसि, तेषां क्रियायां च इत्यर्थः ॥१.१०५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और दुर्जन लोग सोचते कुछ और है, कहते कुछ और है, करते कुछ और है । परन्तु सज्जन लोगों के मन में जो है वहीं वे कहते हैं और वही वे करते भी हैं ॥१.१०५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.105.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1106" class="total">
                    <div>
                        <button id="moolamsmall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1106')">मूलम्</button>
                        <button id="padasmall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1106')">पदविभागः</button>
                        <button id="anvayasmall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1106')">अन्वयः</button>
                        <button id="pratismall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1106')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1106')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1106')">हिन्द्यर्थः</button>
                        <button id="audiosmall1106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1106')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्थानभ्रष्टा न शोभन्ते दन्ताः केशा नखा नराः । इति विज्ञाय मतिमान् स्वस्थानं न परित्यजेत् ॥१.१०६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्थानभ्रष्टाः न शोभन्ते दन्ताः केशाः नखाः नराः । इति विज्ञाय मतिमान् स्वस्थानं न परित्यजेत् ॥१.१०६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दन्ताः केशाः नखाः नराः (च) स्थानभ्रष्टाः न शोभन्ते इति विज्ञाय मतिमान् स्वस्थानं न परित्यजेत् ॥१.१०६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दन्ताः = दशनाः ; केशाः = मूर्धजाः ; नखाः = अङ्गुल्यन्ताः ; नराः = मनुष्याः ; स्थानभ्रष्टाः = स्वस्थानात् चलिताः ; न शोभन्ते = शोभां, श्रियं च न लभन्ते ; इति विज्ञाय = एवं ज्ञात्वा ; मतिमान् = बुद्धिमान् ; स्वस्थानं = वर्तमानां स्वकीयां स्थितिं ; न परित्यजेत् = न मुञ्चेत् ॥१.१०६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>रदाः, शिरोजाः, नखाः, मानवाः च स्वस्मात् स्थिरस्थानात् विचलिताः न शोभन्ते इति ज्ञात्वा विवेकी कदाचित् स्वस्थानं न मुञ्चेत् ॥१.१०६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>दाँत, केश, नख, मनुष्य, ये चारों स्थानभ्रष्ट होने पर शोभते नहीं हैं । ऐसा विचारकर बुद्धिमान् मनुष्य को अपना स्थान कभी नहीं छोडना चाहिये॥१.१०६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.106.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1107" class="total">
                    <div>
                        <button id="moolamsmall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1107')">मूलम्</button>
                        <button id="padasmall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1107')">पदविभागः</button>
                        <button id="anvayasmall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1107')">अन्वयः</button>
                        <button id="pratismall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1107')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1107')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1107')">हिन्द्यर्थः</button>
                        <button id="audiosmall1107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1107')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्थानमुत्सृज्य गच्छन्ति सिंहाः सत्पुरुषा गजाः । तत्रैव निधनं यान्ति काकाः कापुरुषा मृगाः ॥१.१०७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्थानम् उत्सृज्य गच्छन्ति सिंहाः सत्पुरुषा गजाः । तत्र एव निधनं यान्ति काकाः कापुरुषा मृगाः ॥१.१०७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सिंहाः सत्पुरुषा गजाः (च) स्थानम् उत्सृज्य गच्छन्ति । काकाः कापुरुषा मृगाः (च) तत्र एव निधनं यान्ति ॥१.१०७॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सिंहाः = वनराजाः ; सत्पुरुषाः = सज्जनाः ; गजाः = करिणः ; स्थानं = निवासयोग्यं स्वस्थानम् ;  उत्सृज्य = विहाय ; काकाः = वायसाः ; कापुरुषाः = भीरवः ; मृगाः = हरिणाः ; तत्रैव = निवास-अयोग्ये अपि स्थाने ; निधनं यान्ति = मृत्युं प्राप्नुवन्ति ॥१.१०७ ॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(यदा निवासाय अयोग्यं भवति, तदा) प्रकृतं निवासस्थानमपि केचन तत् त्यक्त्वा गच्छन्ति- यथा दन्तिनः, केसरिणः, सन्तः च। (यदा स्वस्य वासस्थानं वस्तुं  न योग्यं, तदापि केचन तत् परित्यज्य न निर्गच्छन्ति, तत्कारणात्) स्वस्थाने मरणमपि प्राप्नुवन्ति- यथा काकाः, धर्यहीनाः, कुरङ्गाः च  ॥१.१०७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि क्यों कि सिंह, सत्पुरुष और हाथी ये तीनों तो अपना अपना स्थान छोडकर जहाँ चाहते हैं, वहीं (अच्छे स्थान में) चले जाते हैं । परन्तु कौवा, कायर मनुष्य और मृग, ये तीनों तो अपने स्थान पर ही पड़े-पड़े मर जाते हैं ॥१.१०७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.107.m4a" type="audio/mp4">
