                <div id="1108" class="total">
                    <div>
                        <button id="moolamsmall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1108')">मूलम्</button>
                        <button id="padasmall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1108')">पदविभागः</button>
                        <button id="anvayasmall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1108')">अन्वयः</button>
                        <button id="pratismall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1108')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1108')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1108')">हिन्द्यर्थः</button>
                        <button id="audiosmall1108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1108')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>को वीरस्य मनस्विनः स्वविषयः को वा विदेशः स्मृतः यं देशं श्रयते तमेव कुरुते बाहुप्रतापार्जितम् । यद्दंष्ट्रानखलाङ्गुलप्रहरणः सिंहो वनं गाहते तस्मिन्नेव हतद्विपेन्द्ररुधिरैस्तृष्णां छिनत्त्यात्मनः ॥१.१०८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः वीरस्य मनस्विनः स्वविषयः कः वा विदेशः स्मृतः यं देशं श्रयते तम् एव कुरुते बाहु-प्रताप-अर्जितम् । यद् दंष्ट्रा-नख-लाङ्गुल-प्रहरणः सिंहः वनं गाहते तस्मिन् एव हत-द्विपेन्द्र-रुधिरैः तृष्णां छिनत्ति आत्मनः ॥१.१०८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मनस्विनः वीरस्य कः स्वविषयः, कः वा विदेशः स्मृतः? (सः) यं देशं श्रयते तम् एव बाहुप्रतापार्जितं कुरुते । यद् दंष्ट्रानख-लाङ्गुलप्रहरणः सिंहः वनं गाहते, तस्मिन् एव (वने) हतद्विपेन्द्ररुधिरैः आत्मनः तृष्णां छिनत्ति ॥१.१०८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वीरस्य = शूरस्य ; मनस्विनः = धीरस्य, गम्भीराशयस्य ; स्वविषयः = (अत्र) स्वदेशः ; विदेशः = स्वदेशात् भिन्नः प्रदेशः ; स्मृतः = भावितः ; श्रयते = आश्रयते ; बाहुप्रतापार्जितम् ~ बाह्वोः-प्रतापेन अर्जितम् = भुजयोः बलेन स्वाधीनं कृतम् ; दंष्ट्रानखलाङ्गुलप्रहरणः ~ दंष्ट्राः नखाः पुच्छं च आयुधाः यस्य ; सिंहः = केसरी ; वनं = अरण्यं ; गाहते = प्रविशति ; तस्मिन्नेव = (अत्र) वने ; हतद्विपेन्द्ररुधिरैः ~ हतः द्विपेन्द्रः, तस्य रुधिराणि, तैः = व्यापादितः गजेन्द्रः तस्य रक्तैः, आत्मनः = स्वीयं ; तृष्णां = पिपासाम् अथवा बुभुक्षाम् ; छिनत्ति = अपनयति ॥१.१०८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धैर्यशालिनः विक्रान्तस्य चिन्तने स्वदेशः कः, विदेशः कः? (कोपि भेदो न। सः सर्वत्र एकथैव तिष्ठति) यत्रापि (गच्छेत्) निवसेत्, तत्र स्वभुदोर्बलेन स्वायत्तं करोति। (अत्र उदाहरणम्) यथा सिंहः दशनरूपैः नखरूपैः, पुच्छरूपेण च आयुधैः युक्तः इव कानने निवसति, तत्रैव गजान् हत्वा तेषां शोणितेन स्वस्य बुभुक्षादिकं निवारयति। (अस्यार्थः- सिंहः स्वस्य वनं वा अपरं वनं वेति न चिन्तयति। यत्र निवासाय याति तत्रैव स्वस्याहारम् अन्विष्यति, तेन जीवति च।) ॥१.१०८॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी-वीर एवं मनस्वी पुरुष के लिये कौन अपना देश है कौन-कौन विदेश है? वह तो जिस देश में जाता है, उसी को अपने बाहुबल से अपना कर लेता है । जैसे (दाँत, नख, और पूंछ ही आयुध जिसके हैं, ऐसा वीर) सिंह जिस वन में जाता है, उसी वन में हाथियों को मारकर, उनके रुधिर से हो अपनी प्यास बुझाता है॥१.१०८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.108.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1109" class="total">
                    <div>
                        <button id="moolamsmall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1109')">मूलम्</button>
                        <button id="padasmall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1109')">पदविभागः</button>
                        <button id="anvayasmall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1109')">अन्वयः</button>
                        <button id="pratismall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1109')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1109')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1109')">हिन्द्यर्थः</button>
                        <button id="audiosmall1109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1109')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>चलत्येकेन पादेन तिष्ठत्येकेन बुद्धिमान् । नासमीक्ष्य परं स्थानं पूर्वमायतनं त्यजेत् ॥१.१०९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मित्र, क्व गन्तव्यम् ? तथा च उक्तम्– चलति एकेन पादेन तिष्ठति एकेन बुद्धिमान् । न असमीक्ष्य परं स्थानं पूर्वम् आयतनं त्यजेत् ॥१.१०९॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मित्र, क्व गन्तव्यम् ? तथा च उक्तम्– बुद्धिमान् एकेन पादेन चलति एकेन तिष्ठति । परं स्थानं असमीक्ष्य पूर्वम् आयतनं न त्यजेत् ॥१.१०९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>बुद्धिमान् = विवेकी ; एकेन पादेन चलति = किञ्चित् अग्रे सरति ; एकेन तिष्ठति = किञ्चित् तत्रैव स्थित्वा ईक्षते ; परं = वर्तमानात् अन्यत् ; स्थानं = प्रदेशं ; असमीक्ष्य = सम्यक् अदृष्ट्वा ; पूर्वम् = वर्तमाने स्थितं ; आयतनं = स्थानम् न त्यजेत् = न मुञ्चेत् ॥१.१०९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मतिमान् मनुष्यः सः पदमेकमग्रे न्यस्यति, पुनः अन्यत् पदं न सारयति, तत्रैव तिष्ठति। अस्य स्थानस्य त्यागात् पूर्वं यत्र गन्तव्यं तत्र समीचीनत्वं परीक्षितव्यम्। अपरीक्ष्य अधुना यदस्ति तत् विमुच्य न यातव्यम्। (विवेकशीलः अविलोक्य अविचार्य वा कार्यं न करोतीति भावः) ॥१.१०९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बुद्धिमान् मनुष्य वही है, जो एक पैर से चलता है, अर्थात् एक पैर वह आगे रखता है, और एक पैर पूर्व स्थान पर ही रखे (जमाए) रहता है । इसलिए दूसरे स्थान को पहिले से निर्धारित किये बिना ही पहले स्थान को नहीं छोड़ना चाहिये॥१.१०९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.109.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1110" class="total">
                    <div>
                        <button id="moolamsmall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1110')">मूलम्</button>
                        <button id="padasmall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1110')">पदविभागः</button>
                        <button id="anvayasmall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1110')">अन्वयः</button>
                        <button id="pratismall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1110')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1110')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1110')">हिन्द्यर्थः</button>
                        <button id="audiosmall1110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1110')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>परोपदेशे पाण्डित्यं सर्वेषां सुकरं नृणाम् । धर्मे स्वीयमनुष्ठानं कस्यचित् तु महात्मनः ॥१.११०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>परोपदेशे पाण्डित्यं सर्वेषां सुकरं नृणाम् । धर्मे स्वीयम् अनुष्ठानं कस्यचित् तु महात्मनः ॥१.११०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>परोपदेशे पाण्डित्यं सर्वेषां नृणां सुकरम् । धर्मे स्वीयम् अनुष्ठानं तु कस्यचित् महात्मनः ॥१.११०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>परोपदेशे = परशिक्षणे ; पाण्डित्यं = नैपुण्यं, विद्वत्त्वम् ; सर्वेषां नृणां = समेषां मनुष्याणां ; सुकरम् = सुलभम् ; धर्मे = कर्तव्यपालने ; स्वीयं = स्वकीयम् ; अनुष्ठानं = आचरणम् ; महात्मनः = महापुरुषस्य ॥१.११०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अन्येषाम् उपबोधने सामान्याः सर्वे कुशलिनः । किन्तु स्वयमेव आचरणीयस्य अनुपालनं केचन उत्तमाः एव कर्तुं पारयन्ति॥१.११०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि- धर्म के विषय में दूसरे को उपदेश देने के लिये पण्डिताई दिख-लाना तो सभी के लिए सहज है, परन्तु धर्म का स्वयं आचरण तो बिरले ही महात्मा लोग किया करते हैं ॥१.११०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.110.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1111" class="total">
                    <div>
                        <button id="moolamsmall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1111')">मूलम्</button>
                        <button id="padasmall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1111')">पदविभागः</button>
                        <button id="anvayasmall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1111')">अन्वयः</button>
                        <button id="pratismall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1111')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1111')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1111')">हिन्द्यर्थः</button>
                        <button id="audiosmall1111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1111')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यस्मिन् देशे न सम्मानो न वृत्तिर्न च बान्धवः । न च विद्यागमः कश्चित् तं देशं परिवर्जयेत् ॥१.१११॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्मिन् देशे न सम्मानः न वृत्तिः न च बान्धवः । न च विद्या-आगमः कश्चित् तं देशं परिवर्जयेत् ॥१.१११॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्मिन् देशे सम्मानः न, वृत्तिः न, बान्धवः च न, विद्या-आगमः च न कश्चित् (वर्तेत), तं देशं परिवर्जयेत् ॥१.१११॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सम्मानः = सत्कारः ; वृत्तिः = जीविका ; बान्धवाः = ज्ञातिनः, परिचिताः, मित्राणि वा ; विद्यागमः = विद्यालाभः ; परिवर्जयेत् = विमुञ्चेत् ॥१.१११॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यत्र स्वस्मै आदरभावः न वर्तते, वित्ताय कार्यनियोगः नास्ति, बन्धुजनाः न सन्ति, ज्ञानलाभः न विद्येत तस्मिन् प्रदेशविशेषे कदापि न वस्तव्यम्। त्यक्त्वा गन्तव्यम् ॥१.१११॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिस देश में सम्मान न हो, कोई जीविका न हो, कोई मित्र न हो, और न किसी प्रकार की विद्या की प्राप्ति ही हो, उस देश को छोड़ देना चाहिये, उसमें कभी नहीं रहना चाहिये ॥१.१११॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.111.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1112" class="total">
                    <div>
                        <button id="moolamsmall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1112')">मूलम्</button>
                        <button id="padasmall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1112')">पदविभागः</button>
                        <button id="anvayasmall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1112')">अन्वयः</button>
                        <button id="pratismall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1112')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1112')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1112')">हिन्द्यर्थः</button>
                        <button id="audiosmall1112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1112')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>जिस देश में सम्मान न हो, कोई जीविका न हो, कोई मित्र न हो, और न किसी प्रकार की विद्या की प्राप्ति ही हो, उस देश को छोड़ देना चाहिये, उसमें कभी नहीं रहना चाहिये ॥१.१११॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धनिकः श्रोत्रियः राजा नदी वैद्यः तु पञ्चमः । पञ्च यत्र न विद्यन्ते तत्र वासं न कारयेत् ॥१.११२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धनिकः, श्रोत्रियः, राजा, नदी, पञ्चमः तु वैद्यः – (एते) पञ्च यत्र न विद्यन्ते तत्र वासं न कारयेत् ॥१.११२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धनिकः = ऋणादिदाता श्रेष्ठी ; श्रोत्रियः = वेदपारगः ; राजा = परिपालकः ; नदी = नीरस्थानं, जलाशयः वा ; वैद्यः = चिकित्सकः ; पञ्च = एते पञ्च ; वासं = संस्थितिम् ॥१.११२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्मिन् प्रदेशविशेषे एते उच्यमानाः पञ्च न वर्तन्ते, तस्मिन् देशे केनापि निवासः न कार्यः । ते पञ्च सन्ति- धनवान्, पुरोहितः, पालयिता, नदी सरः वा, रोगहारकश्च ॥१.११२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>यस्मिन् प्रदेशविशेषे एते उच्यमानाः पञ्च न वर्तन्ते, तस्मिन् देशे केनापि निवासः न कार्यः । ते पञ्च सन्ति- धनवान्, पुरोहितः, पालयिता, नदी सरः वा, रोगहारकश्च ॥१.११२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.112.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1113" class="total">
                    <div>
                        <button id="moolamsmall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1113')">मूलम्</button>
                        <button id="padasmall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1113')">पदविभागः</button>
                        <button id="anvayasmall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1113')">अन्वयः</button>
                        <button id="pratismall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1113')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1113')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1113')">हिन्द्यर्थः</button>
                        <button id="audiosmall1113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1113')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>लोकयात्रा भयं लज्जा दाक्षिण्यं त्यागशीलता । पञ्च यत्र न विद्यन्ते न कुर्यात् तत्र संस्थितिम् ॥१.११३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>लोकयात्रा भयं लज्जा दाक्षिण्यं त्याग-शीलता । पञ्च यत्र न विद्यन्ते न कुर्यात् तत्र संस्थितिम् ॥१.११३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोकयात्रा, भयं, लज्जा, दाक्षिण्यं, त्याग-शीलता (च इति) पञ्च यत्र न विद्यन्ते तत्र संस्थितिं न कुर्यात् ॥१.११३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोकयात्रा = जीवनोपायः ; भयं = राज-लोक-धर्म-भयम् ; लज्जा = लोके पापमाचरामः तेन जनाः निन्देयुः इति भीतिपूर्वका व्रीडा ; दाक्षिण्यं = अनुकूलता ; त्यागशीलता = निःस्वार्थबुद्धिः ; संस्थितिं = वासम् ॥१.११३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्मिन् प्रदेशे एते पञ्च न वर्तन्ते, तत्र निवासः न कार्यः- जीविकायाः मार्गः, असाध्वाचरणेन भीतिः, लोकतः ह्री, कार्यानुकूलता, स्वार्थराहित्यं च ॥१.११३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और जिस देश में जीविका का साधन, लोकभय, लोकलज्जा, सरलता, त्याग, (उदारता) ये पाँच बातें न हों, वहाँ कभी नहीं रहना चाहिए ॥१.११३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.113.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1114" class="total">
                    <div>
                        <button id="moolamsmall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1114')">मूलम्</button>
                        <button id="padasmall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1114')">पदविभागः</button>
                        <button id="anvayasmall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1114')">अन्वयः</button>
                        <button id="pratismall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1114')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1114')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1114')">हिन्द्यर्थः</button>
                        <button id="audiosmall1114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1114')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तत्र मित्र ! न वस्तव्यं यत्र नास्ति चतुष्टयम् । ऋणदाता च वैद्यश्च श्रोत्रियः सजला नदी ॥१.११४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तत्र मित्र ! न वस्तव्यं यत्र नास्ति चतुष्टयम् । ऋणदाता च वैद्यश्च श्रोत्रियः सजला नदी ॥१.११४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मित्र ! यत्र चतुष्टयं नास्ति तत्र न वस्तव्यम् - ऋणदाता च वैद्यः च श्रोत्रियः सजला नदी ॥१.११४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मित्र = हे सुहृत् ; न वस्तव्यं = निवासः न कार्यः ; चतुष्टयम् = चत्वारः ; ऋणदाता = यः धनं ददाति उपयोगाय, पुनः प्रत्यर्पणाय ; वैद्यः = चिकित्सकः ; श्रोत्रियः = वेदपारगः ब्राह्मणः, सजला नदी = जलपूर्णा नदी ॥१.११४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे सुहृत्, यत्र एते चत्वारः न भवन्ति, तत्र वासः न कार्यः- ऋणं ददाति यः, रोगनिवारकः, वेदज्ञः, जलयुक्ता नदी च ॥१.११४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हे मित्र- जहाँ ऋणदाता धनी, वैद्य, श्रोत्रिय (वैदिक विद्वान्) और जल से पूर्ण नदी, ये चार चीज़े नहीं हों, वहाँ कभी नहीं रहना चाहिए ॥१.११४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.114.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1115" class="total">
                    <div>
                        <button id="moolamsmall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1115')">मूलम्</button>
                        <button id="padasmall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1115')">पदविभागः</button>
                        <button id="anvayasmall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1115')">अन्वयः</button>
                        <button id="pratismall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1115')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1115')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1115')">हिन्द्यर्थः</button>
                        <button id="audiosmall1115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1115')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>बालो वा यदि वा वृद्धो युवा वा गृहमागतः । तस्य पूजा विधातव्या सर्वत्राभ्यागतो गुरुः ॥१.११५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>बालः वा यदि वा वृद्धः युवा वा गृहम् आगतः । तस्य पूजा विधातव्या सर्वत्र अभ्यागतः गुरुः ॥१.११५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गृहम् आगतः यदि बालः वा, वृद्धः वा, युवा वा, तस्य पूजा विधातव्या। अभ्यागतः सर्वत्र गुरुः ॥१.११५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गृहम् = निवासस्थानम् ; आगतः = आयातः ; यदि = चेत् ; बालः = अल्वयस्कः ; वृद्धः = अधिकायुः ; युवा = युवकः ; पूजा = स्वागतसत्कारपूर्वक-वस्तुप्रदानादिभिः युक्तः समुचितव्यवहारः ; विधातव्या = कर्तव्या ; अभ्यागतः = विशेषेण गृहमागतः ; सर्वत्र = यत्र क्वचिदपि ; गुरुः = पूज्यः, सद्व्यवहारार्हः ॥१.११५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गेहमागतः यः कोपि भवतु सः सत्कारार्हः एव। तस्य आदरः एव विहितव्यः। यतो हि सः सर्वेषां गौरवयोग्यो भवति॥१.११५॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बालक, या वृद्ध, या जवान कोई भी हो, वह यदि अपने घर पर आजाये तो उसका भोजन आदि से सत्कार और अतिथिपूजन अवश्य करना चाहिए, क्योंकि- अतिथि सबका पूज्य है ॥१.११५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.115.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1116" class="total">
                    <div>
                        <button id="moolamsmall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1116')">मूलम्</button>
                        <button id="padasmall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1116')">पदविभागः</button>
                        <button id="anvayasmall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1116')">अन्वयः</button>
                        <button id="pratismall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1116')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1116')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1116')">हिन्द्यर्थः</button>
                        <button id="audiosmall1116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1116')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>गुरुरग्निर्द्विजातीनां वर्णानां ब्राह्मणो गुरुः । पतिरेको गुरुः स्त्रीणां सर्वत्राभ्यागतो गुरुः ॥१.११६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गुरुः अग्निः द्विजातीनां वर्णानां ब्राह्मणः गुरुः । पतिः एकः गुरुः स्त्रीणां सर्वत्र अभ्यागतः गुरुः ॥१.११६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुरुः अग्निः द्विजातीनां वर्णानां ब्राह्मणः गुरुः । पतिः एकः गुरुः स्त्रीणां सर्वत्र अभ्यागतः गुरुः ॥१.११६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>द्विजातीनां = ब्राह्मणादीनां त्रैवर्णिकानाम् ; अग्निः = वैश्वानरः ; गुरुः पूज्यः ; वर्णानां = ब्राह्मणादीनां चतुर्णा वर्णानां ; गुरुः = श्रेष्ठः ; एकः = केवलः, नान्यः ; स्त्रीणां = पत्नीसम्बन्धेन नारीणां ; सर्वस्य = सर्वस्यापि लोकस्य ; अभ्यागतः = आह्वानेन गृहमागतः ; गुरुः = सत्कारार्हः॥१.११६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कस्य कस्य कः कः पूज्यः इति कीर्तयति- चतुर्षु वर्षेणु प्रथमत्रयेभ्यः अग्निः आराध्यः। सर्ववर्णास्थेभ्यः ब्राह्मणः सत्क्रियार्हः। स्त्रीणां कृते पतिः एव गुरुः। समस्तलोकाय अतिथिः पूज्यः भवति॥१.११६॥   </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अग्नि- द्विजाति (ब्राह्मण, क्षत्रिय, वैश्य इन तीनों) का गुरु (पूज्य) हैं । वर्णों (ब्राह्मण क्षत्रिय, वैश्य, शूद्र इन चारों को, ब्राह्मण गुरु हैं । स्त्री का पति ही गुरु है और अभ्यागत (अतिथि) सभी का गुरु है ॥१.११६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.116.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1117" class="total">
                    <div>
                        <button id="moolamsmall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1117')">मूलम्</button>
                        <button id="padasmall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1117')">पदविभागः</button>
                        <button id="anvayasmall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1117')">अन्वयः</button>
                        <button id="pratismall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1117')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1117')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1117')">हिन्द्यर्थः</button>
                        <button id="audiosmall1117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1117')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उत्तमस्यापि वर्णस्य नीचोऽपि गृहमागतः । पूजनीयो यथायोग्यं सर्वदेवमयोऽतिथिः ॥१.११७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उत्तमस्य अपि वर्णस्य नीचः अपि गृहम् आगतः । पूजनीयः यथायोग्यं सर्व-देवमयः अतिथिः ॥१.११७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उत्तमस्य अपि वर्णस्य नीचः अपि गृहम् आगतः । पूजनीयः यथायोग्यं सर्व-देवमयः अतिथिः ॥१.११७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्तमस्य वर्णस्य = ब्राह्मण-क्षत्रियादेः अपि ; नीचोऽपि = शूद्रादिरपि ; गृहम् = स्वनिवासम् ; आगतः = मेलनाय समागतः ; पूजनीयः = सत्कारयोग्यः ; यतायोग्यं = यावच्छक्ति ; सर्वदेवमयः = सकलदेवस्वरूपः ; सः = अतिथिः ॥१.११७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>उत्तमस्य वर्णस्य = ब्राह्मण-क्षत्रियादेः अपि ; नीचोऽपि = शूद्रादिरपि ; गृहम् = स्वनिवासम् ; आगतः = मेलनाय समागतः ; पूजनीयः = सत्कारयोग्यः ; यतायोग्यं = यावच्छक्ति ; सर्वदेवमयः = सकलदेवस्वरूपः ; सः = अतिथिः ॥१.११७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और उत्तम वर्ण (ब्राह्मण आदि) के घर पर यदि अपने से नीच (क्षत्रिय वैश्य या शूद्र आदि) भी कोई आवे तो भी उसकी भी यथायोग्य पूजा करनी चाहिए, क्यों कि अतिथि में सब देवताओं का निवास रहता है ॥१.११७ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.117.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1118" class="total">
                    <div>
                        <button id="moolamsmall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1118')">मूलम्</button>
                        <button id="padasmall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1118')">पदविभागः</button>
                        <button id="anvayasmall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1118')">अन्वयः</button>
                        <button id="pratismall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1118')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1118')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1118')">हिन्द्यर्थः</button>
                        <button id="audiosmall1118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1118')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मुखं प्रसन्नं विमला च दृष्टिः कथानुरागो मधुरा च वाणी । स्नेहोऽधिकः सम्भ्रमदर्शनं च सदानुरक्तस्य जनस्य लक्ष्म ॥१.११८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मुखं प्रसन्नं विमला च दृष्टिः कथानुरागः मधुरा च वाणी । स्नेहः अधिकः सम्भ्रम-दर्शनं च सदा अनुरक्तस्य जनस्य लक्ष्म ॥१.११८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सदा अनुरक्तस्य जनस्य लक्ष्म (इत्थं भवति)- प्रसन्नं मुखं, विमला च दृष्टिः, कथानुरागः, मधुरा च वाणी, अधिकः स्नेहः, सम्भ्रम-दर्शनं च ॥१.११८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मुखं = वदनं ; प्रसन्नं = सन्तुष्टियुक्तं ; विमला = स्वच्छा, रागशून्या ; दृष्टिः = दर्शनम् ; कथानुरागः = वार्ताश्रवणादरः ; मधुरा वाणी = श्रवणानन्दकरी वाक् ; स्नेहः = सुहृद्भावः ; सम्भ्रमर्दनं = आगमने सत्कारादिषु च त्वरादर्शनम् ; सदा = नित्यं ; अनुरक्तस्य = प्रीतिभावयुक्तस्य ; लक्ष्म = लक्षणम् ॥१.११८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः सदा अनुरागयुक्तः भवति तस्य लक्षणानि उच्यन्ते- तद्वदनम् आनन्दितं, दृष्टिः स्वच्छा च भवति । तस्मिन् सुहृदः वार्तां श्रोतुम् उत्साहः दृश्यते । तस्य वाक् मधुरा । अधिकं सुहृद्भावं च दर्शयति । मित्रे आगते सति सानन्दाश्चर्यं दर्शयति ॥१.११८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>प्रसन्न मुख, विमल नेत्र, बातों में प्रेम, मधुर वाणी, अधिक स्नेह, आने पर संभ्रम से (हडबडाकर, उत्सुकतापूर्वक) देखना- ये सब अनुरक्त मनुष्यों के लक्षण हैं ॥१.११८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.118.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1119" class="total">
                    <div>
                        <button id="moolamsmall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1119')">मूलम्</button>
                        <button id="padasmall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1119')">पदविभागः</button>
                        <button id="anvayasmall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1119')">अन्वयः</button>
                        <button id="pratismall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1119')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1119')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1119')">हिन्द्यर्थः</button>
                        <button id="audiosmall1119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1119')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अदृष्टिदानं कृतपूर्वनाशनम् अमाननं दुश्चरितानुकीर्तनम् । कथाप्रसङ्गेन च नामविस्मृति- र्विरक्तभावस्य जनस्य लक्षणम् ॥१.११९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अदृष्टिदानं कृतपूर्व-नाशनम् अमाननं दुश्चरित-अनुकीर्तनम् । कथा-प्रसङ्गेन च नाम-विस्मृतिः विरक्त-भावस्य जनस्य लक्षणम् ॥१.११९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विरक्त-भावस्य जनस्य लक्षणम्- अदृष्टिदानं, कृतपूर्व-नाशनम्, अमाननं, दुश्चरित-अनुकीर्तनम्, कथा-प्रसङ्गेन च नाम-विस्मृतिः (इति)॥१.११९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अदृष्टिदानम् = अविलोकनम् ; कृतपूर्वनाशनम् = पूर्वोपकारादि-अचिन्तनम् ; अमाननम् = तिरस्कारः, सत्काराभावश्च ; दुश्चरितानुकीर्तनम् = दोषवर्णनम् ; कथाप्रसङ्गेन = कथावसरेणापि ; नामविस्मृतिः = नाम-अस्मरणम् ; विरक्तभातस्य = विरक्तस्य ; जनस्य = मनुष्यस्य ; लक्षणम् = सङ्केतः॥१.११९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः पूर्वानुरागी, अधुना रागरहितः विरक्तश्च सञ्जातः तस्य लक्षणानि एवं सन्ति- सः सहृदं न पश्यति । पूर्वकृतं सर्वं विस्मरति । मित्रं पराभवति । आचरितानां दोषानां वर्णनं करोति । वार्ताप्रसङ्गे नाम अपि विस्मरति ॥१.११९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>असन्तुष्ट होकर देखना, पूर्वकृत कार्यों (उपकारों) को भूल जाना, सत्कार न करना, दोषों को प्रकट करना, अक्सर (मौके) पर नाम तक भी भूल जाना, वे सब विरक्त मनुष्य के लक्षण है ॥१.११९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.119.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1120" class="total">
                    <div>
                        <button id="moolamsmall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1120')">मूलम्</button>
                        <button id="padasmall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1120')">पदविभागः</button>
                        <button id="anvayasmall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1120')">अन्वयः</button>
                        <button id="pratismall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1120')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1120')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1120')">हिन्द्यर्थः</button>
                        <button id="audiosmall1120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1120')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अकस्माद्युवती वृद्धं केशेष्वाकृष्य चुम्बति । पतिं निर्दयमालिङ्ग्य हेतुरत्र भविष्यति ॥१.१२०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अकस्माद् युवती वृद्धं केशेषु आकृष्य चुम्बति । पतिं निर्दयम् आलिङ्ग्य हेतुः अत्र भविष्यति' ॥१.१२०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>युवती अकस्माद् वृद्धं पतिं निर्दयम् आलिङ्ग्य केशेषु आकृष्य चुम्बति, अत्र हेतुः भविष्यति' ॥१.१२०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अकस्माद् = हेतुना विना, विनापि हेतोः ; युवती = तरुणी ; वृद्धं = जराजीर्णम् ; केशेषु = मूर्धजेषु ; आकृष्य = बलात् समीपमाहूय ; पतिम् = स्वामिनम् ; निर्दयम् = बलवत् ; आलिङ्ग्य = आश्लिष्य ; चुम्बति = मुखम् ओष्ठैः स्पृशति ; हेतुः = किमपि कारणम् ॥१.१२०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदि काचित् प्राप्तयौवना अकारणं स्थविरं भर्तारं बलेन निकटमाहूय परिष्वङ्गसहितं मुखसंयोगं करोति, तत्र अवश्यं किमपि कारणम् अवश्यं भविष्यति ॥१.१२०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>वृद्धपति की जवान (युवती) स्त्री सहसा अपने वृद्धपति के केशों को पकड़कर उसका गाढ़ आलिङ्गन कर उसके मुख का चुम्बन करती है, तो उसमें ज़रूर कुछ कारण होगा ॥१.१२० ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.120.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1121" class="total">
                    <div>
                        <button id="moolamsmall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1121')">मूलम्</button>
                        <button id="padasmall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1121')">पदविभागः</button>
                        <button id="anvayasmall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1121')">अन्वयः</button>
                        <button id="pratismall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1121')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1121')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1121')">हिन्द्यर्थः</button>
                        <button id="audiosmall1121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1121')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शशिनीव हिमार्तानां घर्मार्तानां रवाविव । मनो न रमते स्त्रीणां जराजीर्णेन्द्रिये पतौ ॥१.१२१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शशिनी इव हिमार्तानां घर्मार्तानां रवौ इव । मनः न रमते स्त्रीणां जरा-जीर्णेन्द्रिये पतौ ॥१.१२१॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शशिनी इव हिमार्तानां घर्मार्तानां रवौ इव स्त्रीणां मनः जरा-जीर्णेन्द्रिये पतौ न रमते ॥१.१२१॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>हिमार्तानाम्= शीतपीडितानाम् ; शशिनि = चन्द्रे ; इव = वत् ; घर्मार्तानां = ग्रीष्मोपतापतप्तानाम् ; रवौ = सूर्ये ; स्त्रीणां = नारीणां ; मनः = चित्तं ;  जराजीर्णेन्द्रिये = जरया विकले इन्द्रियग्रामे ; पतौ = भर्तरि (छान्दसोऽयं प्रयोगः, पत्यौ इत्युचितम्) ; 'धवे' इति पाठान्तरम् ; न रमते = आनन्दितं न भवति ॥१.१२१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शैत्येन पीडितानां यथा चन्द्रमसि आसक्तिः न भवति, आतपेन तप्तानाम् आदित्ये चेतः न भवति, तथैव यस्य इन्द्रियाणि जीर्णानि तादृशि वृद्धे पत्यौ नारीणां मनः रतं न भवति ॥१.१२१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हिम (बर्फ़ जाड़ा) से पीडित प्राणी को चन्द्रमा अच्छा नहीं लगता है, धूप से पीडित मनुष्य को सूर्य अच्छा नहीं लगता है, वैसे ही जिस की सभी इन्द्रियों जीर्ण हो गयी हो ऐसा वृद्धपति युवति स्त्रियों को कभी अच्छा नहीं लगता है ॥१.१२१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.121.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1122" class="total">
                    <div>
                        <button id="moolamsmall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1122')">मूलम्</button>
                        <button id="padasmall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1122')">पदविभागः</button>
                        <button id="anvayasmall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1122')">अन्वयः</button>
                        <button id="pratismall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1122')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1122')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1122')">हिन्द्यर्थः</button>
                        <button id="audiosmall1122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1122')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पलितेषु हि दृष्टेषु पुंसः का नाम कामिता । भैषज्यमिव मन्यन्ते यदन्यमनसः स्त्रियः ॥१.१२२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पलितेषु हि दृष्टेषु पुंसः का नाम कामिता! । भैषज्यम् इव मन्यन्ते यद् अन्य-मनसः स्त्रियः ॥१.१२२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पुंसः (केशेषु) पलितेषु हि दृष्टेषु का नाम कामिता! यद् अन्य-मनसः स्त्रियः भैषज्यम् इव मन्यन्ते ॥१.१२२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पलितेषु = शुक्लेषु केशेषु, केशशौक्ल्ये ; दृष्टेषु = जातेषु ; का नाम = का खलु ; कामिता = कामोपभोगपरायणता ; सा नैवोचिता इत्यर्थः ; यत् = यस्मात् ; अन्यमनसः = विरक्ताः, अन्यासक्ता वा ; स्त्रियः = कामिन्यः ; भैषज्यम् इव = कटुकौषधम् इव ; मन्यन्ते = भावयन्ति, ॥१.१२२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्यस्य मूर्धजाः यदा शुक्लवर्णं प्राप्ताः, तदा का वार्ता कामभावस्य? नार्यः तादृशं पतिं परिहार्यं मन्यन्ते, अनिच्छया च तं सेवन्ते ॥१.१२२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और जब पुरुष के सब बाल पक गये हों तो फिर कहो उसकी कामुकता कैसी ? अर्थात् वृद्धावस्था में कामोपभोग की इच्छा व्यर्थ है । क्यों कि- वृद्ध पुरुष की स्त्री दूसरे से आसक्त हो जाती हैं और वह अपने उस वृद्ध पति को औषध (दवा) की तरह ही कडुआ समझती है ॥१.१२२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.122.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1123" class="total">
                    <div>
                        <button id="moolamsmall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1123')">मूलम्</button>
                        <button id="padasmall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1123')">पदविभागः</button>
                        <button id="anvayasmall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1123')">अन्वयः</button>
                        <button id="pratismall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1123')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1123')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1123')">हिन्द्यर्थः</button>
                        <button id="audiosmall1123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1123')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धनाशा जीविताशा च गुर्वी प्राणभृतां सदा । वृद्धस्य तरुणी भार्या प्राणेभ्योऽपि गरीयसी ॥१.१२३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धनाशा जीविताशा च गुर्वी प्राणभृतां सदा । वृद्धस्य तरुणी भार्या प्राणेभ्यः अपि गरीयसी ॥१.१२३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्राणभृतां सदा धनाशा जीविताशा च गुर्वी । तरुणी भार्या वृद्धस्य प्राणेभ्यः अपि गरीयसी ॥१.१२३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यद्यपि- प्राणभृतां = प्राणिनां ; धनाशा = वित्ते इच्छा ; जीविताशा = जीवनयापने आकाङ्क्षा ; सदा = तर्वदा ; गुर्वी = महती, अधिका भवति ; तथापि- वृद्धस्य = जराजीर्णस्य ; तरुणी भार्या = यौवनवती पत्नी ; तु तस्य प्राणेभ्योऽपि = प्राणानाम् अपेक्षया अपि ; गरीयसी = नितरां गुर्वी भवति ; ॥१.१२३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यद्यपि- जीवानां द्रविणाकाङ्क्षा, आयुषि कामना च प्रबला भवति, तथापि- गतयौवनस्य प्राणेभ्यः अपि अधिका युवती कान्ता भाति ॥१.१२३॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि- सभी प्राणियों को धन की आशा और जीवन की आशा (लालसा) स्वभावतः अधिक होती है । परन्तु वृद्ध पुरुष को तो अपनी युवती स्त्री अपने प्राणों से भी अधिक प्यारी होती है ॥ १.१२३ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.123.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1124" class="total">
                    <div>
                        <button id="moolamsmall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1124')">मूलम्</button>
                        <button id="padasmall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1124')">पदविभागः</button>
                        <button id="anvayasmall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1124')">अन्वयः</button>
                        <button id="pratismall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1124')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1124')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1124')">हिन्द्यर्थः</button>
                        <button id="audiosmall1124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1124')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>क्यों कि- सभी प्राणियों को धन की आशा और जीवन की आशा (लालसा) स्वभावतः अधिक होती है । परन्तु वृद्ध पुरुष को तो अपनी युवती स्त्री अपने प्राणों से भी अधिक प्यारी होती है ॥ १.१२३ ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न उपभोक्तुं न च त्यक्तुं शक्रोति विषयान् जरी । अस्थि निर्दशनः श्वेव जिह्वया लेढि केवलम् ॥१.१२४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>जरी विषयान् न उपभोक्तुं (शक्नोति) न च त्यक्तुं शक्रोति । निर्दशनः श्वेव केवलम् अस्थि जिह्वया लेढि ॥१.१२४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>जरी = जराजीर्णो वृद्धः ; विषयान् = कान्तासुखादीन् ; उपभोक्तुम् = सुखं प्राप्तुं, आनन्दितुम् ; त्यक्तुं = परित्यक्तुं ; शक्नोति = पारयति ; निर्दशनः = दन्तविकलः ; श्वा इव = कुक्कुरवत् ; अस्थि = कीकशम् ; केवलं लेढि = जिह्वया केवलम् आस्वादयति एव ॥१.१२४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जर्जरः नरः उपभोगवस्तूनि न च आनन्दितुं न वा हातुं पारयति। (अत्रोदाहरणम्) दन्तै विहीनः शुनकः कर्करं केवलं लिह्यति (दष्टुं न शक्नोति)॥१.१२४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और वृद्ध मनुष्य न तो विषयों (स्त्री आदि) को भोग ही सकता है, और न उन्हें छोड़ ही सकता किन्तु जिस प्रकार दन्तहीन कुत्ता हड्डी को केवल जीभसे चाटता रहता है, किन्तु उसे चबा नहीं सकता है, वही दशा उस वृद्ध मनुप्य की भी होती है ॥१.१२४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.124.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1125" class="total">
                    <div>
                        <button id="moolamsmall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1125')">मूलम्</button>
                        <button id="padasmall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1125')">पदविभागः</button>
                        <button id="anvayasmall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1125')">अन्वयः</button>
                        <button id="pratismall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1125')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1125')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1125')">हिन्द्यर्थः</button>
                        <button id="audiosmall1125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1125')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्वातन्त्र्यं पितृमन्दिरे निवसतिर्यात्रोत्सवे सङ्गति- र्गोष्ठी पूरुषसन्निधावनियमो, वासो विदेशे तथा । संसर्गः सह पुंश्चलीभिरसकृद्वृत्तेर्निजायाः क्षतिः, पत्युर्वार्द्धकमीषितं प्रवसनं नाशस्य हेतुः स्त्रियाः॥१.१२५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्वातन्त्र्यं पितृमन्दिरे निवसतिः यात्रोत्सवे सङ्गति-गोष्ठी पूरुषसन्निधौ अनियमः, वासः विदेशे तथा । संसर्गः सह पुंश्चलीभिः असकृद् वृत्तेः निजायाः क्षतिः, पत्युः वार्द्धकम् ईर्षितं, प्रवसनं, नाशस्य हेतुः स्त्रियाः॥१.१२५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>स्वातन्त्र्यं, पितृमन्दिरे निवसतिः, यात्रोत्सवे सङ्गतिः, गोष्ठी, पूरुषसन्निधौ अनियमः, विदेशे वासः तथा, पुंश्चलीभिः सह असकृत् संसर्गः, निजायाः वृत्तेः क्षतिः, पत्युः वार्द्धकम् ईर्षितं, प्रवसनं- स्त्रियाः नाशस्य हेतुः ॥१.१२५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्वातन्त्र्यमिति । स्वातन्त्र्यं = स्वतन्त्रता ; पितृमन्दिरे = जनकस्य गेहे ; निवसतिः = निवासः ; यात्रोत्सवे, यात्रा = ग्रामान्तरादि-गमनम्, उत्सवे = विवाहादौ ; सङ्गतिः = जनैः सह गमनम्, जनसंसर्गः ; यद्वा यात्रोत्सवे = जनमेलापके, देवयात्रादौ, विवाहादौ च, सङ्गतिः = मुहुर्यानमित्यर्थः ; पुरुषसन्निधौ = पुरुषाणां सविधे ; गोष्ठी = आसनबन्धः वार्तालापः च ;  अनियमः = निरोधाभावः ; विदेशे वासः = परदेशे निवासः ; पत्युरात्मनश्चेति शेषः । पुंश्चलीभिः = दुष्टस्त्रीभिः, कुलटाभिः ; असकृत् = मुहुर्मुहुः ; संसर्गः = सम्पर्कः ; निजायाः = आत्मनः ; वृत्तेः = जीविकायाः ; क्षतिः = अभावः, विनाशश्च ; वार्धक्यं = पत्युः वृद्धावस्था ; ईर्षितं = पत्युरीर्ष्यालुत्वम्, स्वस्य वा ; प्रवसनं = पत्युर्विदेशे प्रवासः ; (पाठ. प्रहसनं = अकारणं हसणं च) स्त्रीणां = नारीणां ; नाशस्य = पतनस्य, शीलखण्डनस्य ; हेतुः = हेतवः ॥१.१२५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>योषितां शीलविनाशे हेतवः उच्यन्ते- नियन्त्रणराहित्यं, जन्मदस्य सदने (दीर्घकालं यावत्) वासः, अत्र तत्र प्रदेशान्तर-विहरणं, उत्सवमेलनादिषु (सुदीर्घकालं यावत्) विचरणं, वृथासँल्लापवर्गेषु गमनं, पुरुषैः सह समीपवर्तनं, नियमराहित्यं, विदेशवासः, दुश्चरिताभिः वनिताभिः सह मित्रता, स्वस्याः पत्युः वा जीविकायाः अभावः, भर्तुः वृद्धत्वं, धवस्य ईर्ष्यालुत्वं, स्वस्याः पत्युः वा अधिककालं यावत् देशान्तरवासः च ॥१.१२५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि- स्वतन्त्रता, पिता के घर (पीहर में) रहना, यात्रा (देवता आदि के दर्शनों के मेले एवं विवाह उत्सव इत्यादि में लोगों से मित्रता, पुरुषों के साथ में बिना रोक टोक बैठना और उनसे गप लड़ाना, किसी की रोक टोक का न रहना, विदेश में रहना, व्यभिचारिणी स्त्रियों का साथ होना, जीविका (खाने-पीने) का अभाव, पति का वृद्ध होना, पति का इर्षालु होना, और पति का परदेश में रहना,-ये सब स्त्रियों के बिगड़ने के कारण हैं ॥१.१२५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.125.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1126" class="total">
                    <div>
                        <button id="moolamsmall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1126')">मूलम्</button>
                        <button id="padasmall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1126')">पदविभागः</button>
                        <button id="anvayasmall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1126')">अन्वयः</button>
                        <button id="pratismall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1126')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1126')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1126')">हिन्द्यर्थः</button>
                        <button id="audiosmall1126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1126')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पानं दुर्जनसंसर्गः पत्या च विरहोऽटनम् । स्वप्नश्चान्यगृहे वासो नारीणां दूषणानि षट् ॥१.१२६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पानं दुर्जन-संसर्गः, पत्या च विरहः अटनम् । स्वन्नश्चा अन्यगृहे वासः, नारीणां दूषणानि षट् ॥१.१२६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नारीणां दूषणानि षट् – पानं, दुर्जनसंसर्गः, पत्या च विरहः, अटनम्, अन्यगृहे स्वप्नः वासः च ॥१.१२६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नारीणां = स्त्रीणां ; दूषणानि = दुष्टलक्षणानि ; पानं = मद्यपानम् ; दुर्जनसंसर्गः = दुष्टैः जनैः सह मित्रता ; पत्या = भर्त्रा ; विरहः = कोपात् दूरे वासः ; अटनं = भ्रमणम् ; अन्यगृहे = बन्धुमित्राणां, अज्ञातानां वा गेहे ; स्वप्नः = शयनम् ; ॥१.१२६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अत्र योषितां दुर्लक्षणानि उक्तानि- मधुपानं, दुर्जनसम्पर्कः, भर्तुः दूरे स्थितिः, वृथा विचरणं, परेषां गृहेषु निद्राकरणं, दीर्घवासः चेति ॥१.१२६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- शराब पीना, दुष्टों का साथ, पति का विरह, इधर उधर घूमना, दूसरे के धर में रहना या सोना, अकारण हँसना, हँसी-ठट्ठा ये छः कारण स्त्रियों के दूषित होने (बिगड़ने) के होते हैं ॥१.१२६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.126.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1127" class="total">
                    <div>
                        <button id="moolamsmall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1127')">मूलम्</button>
                        <button id="padasmall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1127')">पदविभागः</button>
                        <button id="anvayasmall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1127')">अन्वयः</button>
                        <button id="pratismall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1127')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1127')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1127')">हिन्द्यर्थः</button>
                        <button id="audiosmall1127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1127')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्थानं नास्ति क्षणो नास्ति नास्ति प्रार्थयिता तेन नारद नारीणां सतीत्वमुपजायते ॥१.१२७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्थानं नास्ति, क्षणः नास्ति, नास्ति प्रार्थयिता तेन नारद! नारीणां सतीत्वम् उपजायते॥१.१२७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नारद! स्थानं नास्ति, क्षणः नास्ति, प्रार्थयिता नास्ति। तेन नारीणां सतीत्वम् उपजायते॥१.१२७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्थानम् = व्यभिचाराय एकान्तस्थानमित्यर्थः ; क्षणः = अवसरः ; प्रार्थयिता = कामयिता, कामी, यः व्यभिचरितुमिच्छेत्, शीलखण्डनाय लोभादिप्रदर्शनेनोत्तेजकः ; हे नारदेति सम्बोधनपदम् ; तेन = तेनैव, नान्यथा इत्यर्थः ॥१.१२७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे नारद, आस्पदराहित्यम्, अवसराभावः, कामिनः अनुपलब्धिरेव स्त्रियः साध्वीत्वे कारणानि भवन्ति (स्थानादिकानामभावात् एव स्त्रीणां सतीत्वं तिष्ठति)॥१.१२७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>हे नारद! स्त्रियाँ पतिव्रता तभी तक रह सकती हैं, जब तक या तो उनके लिए व्यभिचारका कोई स्थान ही नहीं हो, या समय (व्यभिचार के लिये मौका) ही न मिले, या उनके चाहने वाला कोई पुरुष ही न हो ॥१.१२७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.127.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1128" class="total">
                    <div>
                        <button id="moolamsmall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1128')">मूलम्</button>
                        <button id="padasmall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1128')">पदविभागः</button>
                        <button id="anvayasmall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1128')">अन्वयः</button>
                        <button id="pratismall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1128')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1128')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1128')">हिन्द्यर्थः</button>
                        <button id="audiosmall1128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1128')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न स्त्रीणामप्रियः कश्चित्प्रियो वापि न विद्यते । गावस्तृणमिवारण्ये प्रार्थयन्ति नवं नवम् ॥१.१२८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न स्त्रीणाम् अप्रियः कश्चित् प्रियः वा अपि न विद्यते । गावः तृणम् इव अरण्ये प्रार्थयन्ति नवं नवम् ॥१.१२८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कश्चित् स्त्रीणाम् अप्रियः प्रियः वा अपि न विद्यते । गावः अरण्ये नवं नवं तृणं प्रार्थयन्ति इव (ताः अपि)॥१.१२८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्त्रीणां = नारीणां ; प्रियः = हृदयसमीपवर्ती ; अप्रियः = इष्टाभावपात्रम् ; कश्चित् न विद्यते = कोपि न अस्ति ;  अरण्ये = वने ; गावः = धेनवः ; नवं नवं = प्रत्यहं नूतनं नूतनं ; तृणम् = हरितम् ; इव = वत् ; प्रार्थयन्ति = इच्छन्ति ॥१.१२८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नारीणां इष्टः, इष्टरहितः वा कोपि न भवति। (अत्रोदाहरणम्) धेनवः वने नवं नवं त्रिणम् अभिलषन्ति, (तथैव वनिताः अपि नूतनं पुरुषम् काङ्क्षन्ति)॥१.१२८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी- स्त्रियों का न तो कोई प्रिय है और न उनका कोई अप्रिय ही है । किन्तु जैसे गाय वन में नया नया तृण (घास) ढूँढती रहती हैं, (वैसे ही स्त्रियां भी नये नये पुरुषों को खोजा करती हैं) ॥१.१२८ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.128.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1129" class="total">
                    <div>
                        <button id="moolamsmall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1129')">मूलम्</button>
                        <button id="padasmall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1129')">पदविभागः</button>
                        <button id="anvayasmall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1129')">अन्वयः</button>
                        <button id="pratismall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1129')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1129')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1129')">हिन्द्यर्थः</button>
                        <button id="audiosmall1129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1129')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>घृतकुम्भसमा नारी तप्ताङ्गारसमः पुमान्। तस्माद् घृतञ्च वह्निञ्च नैकत्र स्थापयेद्बुधः ॥१.१२९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>घृतकुम्भसमा नारी, तप्त-अङ्गार-समः पुमान्। तस्मात् घृतञ्च वह्निं च, न एकत्र स्थापयेद् बुधः ॥१.१२९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नारी घृतकुम्भसमा, पुमान् तप्ताङ्गारसमः । तस्मात् बुधः घृतं च वह्निं च, एकत्र न स्थापयेत् ॥१.१२९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>घृतकुम्भसमा = घृतपूर्णघटतुल्या ; नारी = स्त्री ; तप्ताङ्गारसमः =ज्वलद्-अङ्गार-तुल्यः ; पुमान् = पुरुषः ; तस्माद् = तेन कारणेन ; घृतञ्च = आज्यं च ; वह्निञ्च = अग्निं च ; नैकत्र = एकस्मिन् स्थान् न ; स्थापयेद् = न्यस्येत् ; बुधः= बुद्धिमान् ;॥१.१२९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>वनिता सर्पिःसदृशा। नरः तु उष्ण-अङ्गारतुल्यः। अतः द्वावपि एकत्र न स्थापनीयौ।  ॥१.१२९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और स्त्री- घी से भरे घड़े के समान है, पुरुष-जलते हुए अङ्गार (अग्नि) है समान है, इस लिए बुद्धिमान् पुरुष को चाहिये कि घृत और अग्नि को एक साथ कभी न रखे ॥१.१२९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.129.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1130" class="total">
                    <div>
                        <button id="moolamsmall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1130')">मूलम्</button>
                        <button id="padasmall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1130')">पदविभागः</button>
                        <button id="anvayasmall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1130')">अन्वयः</button>
                        <button id="pratismall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1130')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1130')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1130')">हिन्द्यर्थः</button>
                        <button id="audiosmall1130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1130')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मात्रा, स्वस्रा, दुहित्रा वा न विविक्तासनो भवेत्। बलवानिन्द्रियग्रामो महान्तमपि कर्षति ॥१.१३०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मात्रा, स्वस्रा, दुहित्रा वा न विविक्ता आसनः भवेत्। बलवान् इन्द्रिय-ग्रामः महान्तम् अपि कर्षति ॥१.१३०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मात्रा, स्वस्रा, दुहित्रा वा न विविक्ता आसनः भवेत्। बलवान् इन्द्रिय-ग्रामः महान्तम् अपि कर्षति ॥१.१३०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मात्रा = जनन्या ; स्वस्रा = भगिन्या ; दुहित्रा = पुत्र्या ; विविक्तासनः = निर्जनप्रदेशस्थितः, एकान्त-स्थितः ; बलवान् = शक्तिशाली, अनियतः ; इन्द्रियग्रामः = इन्द्रियाणां समूहः ; महान्तम् अपि = सद्गुणयुक्तम्, सच्छीलम् अपि ; कर्षति = बलवत् समीपं नयति, अत्र- पापे नियोजयति ॥१.१३०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जनयित्र्या, सोदर्या, आत्मजायाः च सह एकाकी न तिष्ठेत्। अवशः महापुरुषमपि हृषीकाणां वर्गः महात्मानम् अपि प्रलोभे पातयति ॥१.१३०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>बुद्धिमान् पुरुष को अपनी माता, बहन तथा अपनी लड़की के साथ भी कभी भी एकान्त में नहीं बैठना चाहिये, क्यों कि इन्द्रियों बड़ी प्रबल हैं, ये (इन्द्रियाँ) विद्वान् को भी अपने वश में कर ले सकती है ॥१.१३०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.130.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1131" class="total">
                    <div>
                        <button id="moolamsmall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1131')">मूलम्</button>
                        <button id="padasmall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1131')">पदविभागः</button>
                        <button id="anvayasmall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1131')">अन्वयः</button>
                        <button id="pratismall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1131')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1131')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1131')">हिन्द्यर्थः</button>
                        <button id="audiosmall1131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1131')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न लज्जा न विनीतत्वं न दाक्षिण्यं न भीरुता। प्रार्थनाभाव एवैकं सतीत्वे कारणं स्त्रियाः ॥१.१३१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न लज्जा, न विनीतत्वं, न दाक्षिण्यं न भीरुता। प्रार्थना-अभावः एव एकं सतीत्वे कारणं स्त्रियाः ॥१.१३१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>न लज्जा, न विनीतत्वं, न दाक्षिण्यं न भीरुता (वा नास्ति कारणम्)। प्रार्थनाभावः एव एकं स्त्रियाः सतीत्वे कारणम् ॥१.१३१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>न लज्जा, न विनीतत्वं, न दाक्षिण्यं न भीरुता (वा नास्ति कारणम्)। प्रार्थनाभावः एव एकं स्त्रियाः सतीत्वे कारणम् ॥१.१३१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नारी साध्वी भवतीति अत्र कारणं – लज्जा, विनयभावः, सरलता, भीतिः वा न। तत्र कामुकः कोपि आगत्य सङ्गमेच्छा न व्यनक्ति इत्येव हेतुः तत्र ॥१.१३१॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और स्त्री के सती होने का कारणा तो लज्जा है, न नम्रता है, न दान-शीलता है, और न डर ही है, किन्तु इसमें यदि कोई कारण है, तो वह केवल प्रार्थना करने वाले पुरुष का पास में नहीं होना ही है ॥१.१३१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.131.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1132" class="total">
                    <div>
                        <button id="moolamsmall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1132')">मूलम्</button>
                        <button id="padasmall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1132')">पदविभागः</button>
                        <button id="anvayasmall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1132')">अन्वयः</button>
                        <button id="pratismall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1132')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1132')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1132')">हिन्द्यर्थः</button>
                        <button id="audiosmall1132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1132')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पिता रक्षति कौमारे भर्ता रक्षति यौवने। पुत्रश्च स्थाविरे भावे न स्त्री स्वातन्त्र्यमर्हति ॥१.१३२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पिता रक्षति कौमारे, भर्त्ता रक्षति यौवने। पुत्रः च स्थाविरे भावे, न स्त्री स्वातन्त्र्यम् अर्हति ॥१.१३२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पिता कौमारे रक्षति, भर्त्ता यौवने रक्षति । पुत्रः च स्थाविरे भावे (रक्षति), स्त्री स्वातन्त्र्यं न अर्हति ॥१.१३२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पिता = जनकः ; कौमारे = बाल्ये ; भर्ता = पतिः ; यौवने = युवावस्थायाम् ; स्थाविरे भावे = वृद्धावस्थायाम् ; रक्षति = संरक्षणं करोति ; अतः- स्त्री = नारी ; कदापि स्वातन्त्र्यं = स्वाधीनतां ; न अर्हति = नैव अर्हति ॥१.१३२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>वनिता यदा कुमारी तदा जन्मदः संरक्षति। यदा सा युवती तदा धवः रक्षणं निर्वहति। सा जराजीर्णा भवति तदा आत्मजः तां पश्यति। सा स्वतन्त्रा न तिष्ठेत्॥१.१३२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और बाल्यावस्था में स्त्री की रक्षा पिता को करनी चाहिए जवानी में पति को रक्षा करनी चाहिये । और वृद्धावस्था में पुत्र की उनकी रक्षा करना चाहिये। इस प्रकार स्वयं को कभी स्वतन्त्र नहीं छोडना चाहिये ॥१.१३२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.132.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1133" class="total">
                    <div>
                        <button id="moolamsmall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1133')">मूलम्</button>
                        <button id="padasmall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1133')">पदविभागः</button>
                        <button id="anvayasmall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1133')">अन्वयः</button>
                        <button id="pratismall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1133')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1133')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1133')">हिन्द्यर्थः</button>
                        <button id="audiosmall1133" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1133')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्त्रियो हि चपला नित्यं देवानामपि विश्रुतम्। ताश्चापि रक्षिता येषां ते नराः सुखभागिनः ॥१.१३३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्त्रियः हि चपलाः नित्यं देवानामपि विश्रुतम् । ताः च अपि रक्षिता येषां ते नराः सुखभागिनः ॥१.१३३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>देवानामपि स्त्रियः हि नित्यं चपलाः (इति) विश्रुतम् । येषां ताः च अपि रक्षिता ते नराः सुखभागिनः ॥१.१३३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>(न केवलं मानुषाणामेव, किन्तर्हि) देवानाम् अपि स्त्रियः = लक्ष्मी-प्रभृतयः स्त्रियः ; चपलाः = चञ्चलाः ; इति  विश्रुतं = पुराणादौ प्रसिद्धमेव ; ताः = प्रकृति-चपलाः स्त्रियः ; येषां = अन्येषां पुसां, यैर्वा पुरुषैः ; रक्षिताः = सुरक्षिताः, शीले स्थापिताः ; ते एव नराः सुखभागिनः = लोके सुखिनः ॥१.१३३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>देवतानामपि नार्यः नित्यं चञ्चलाः इति प्रसिद्धमेव। तादृश्यपि नार्यः येषां पुरुषाणां सुरक्षिताः सन्ति, एते सुखिनः सन्ति॥१.१३३॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योकि- स्त्रियाँ सदा चञ्चल हैं- यह बात लक्ष्मी आदिके विषय में देवताओं में भी प्रसिद्ध है । अतः जिन पुरुषों की स्त्रियां सुशील व सुरक्षित हैं, वे ही मनुष्य संसार में सुखी हैं ॥१.१३३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.133.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1134" class="total">
                    <div>
                        <button id="moolamsmall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1134')">मूलम्</button>
                        <button id="padasmall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1134')">पदविभागः</button>
                        <button id="anvayasmall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1134')">अन्वयः</button>
                        <button id="pratismall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1134')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1134')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1134')">हिन्द्यर्थः</button>
                        <button id="audiosmall1134" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1134')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उशना वेद यच्छास्त्रं यच्च वेद बृहस्पतिः । स्वभावेनैव तच्छास्त्रं स्त्रीबुद्धौ सुप्रतिष्ठितम् ॥१.१३४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उशना वेद यत्-शास्त्रं यत् च वेद बृहस्पतिः । स्वभावेन एव तत् शास्त्रं स्त्रीबुद्धौ सुप्रतिष्ठितम् ॥१.१३४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यत्-शास्त्रम् उशना वेद यत् च बृहस्पतिः वेद, तत् शास्त्रं स्त्रीबुद्धौ स्वभावेन एव सुप्रतिष्ठितम् ॥१.१३४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उशनाः = शुक्राचार्यः ; यच्छास्त्रं = यत् नीतिशास्त्रादिकम् ; वेद = अध्ययनादिना वेत्ति ; बृहस्पतिः = देवगुरुः ; वेद = अधीत्य ज्ञातवान् ; तत्-शास्त्रसारं ; स्वभावेनैव = प्रकृत्यैव ; स्त्रीबुद्धौ = नारीणां मतौ ; सुप्रतिष्ठितम् = सम्यक् उपस्थितम् ; ननु शिक्षणादेः तत्र न आवश्यकतेति भावः ॥१.१३४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दैत्यगुरुः देवगुरुश्च यत् शास्त्रादिकं जानाति, तत् सर्वं सहजमेव नारीणां बुद्धिषु पूर्वमेव सुस्थितम् (अध्ययनादिकस्य आवश्यकता नास्तीति यावत्) ॥१.१३४॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कहा भी है- शुक्राचार्य और बृहस्पति भी जिन शास्त्रों को अपने गुरु से पढकर ही जानसके हैं, वे सब शास्त्र स्त्रियों की बुद्धि में स्वभाव से ही रहते हैं ॥१.१३४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.134.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1135" class="total">
                    <div>
                        <button id="moolamsmall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1135')">मूलम्</button>
                        <button id="padasmall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1135')">पदविभागः</button>
                        <button id="anvayasmall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1135')">अन्वयः</button>
                        <button id="pratismall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1135')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1135')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1135')">हिन्द्यर्थः</button>
                        <button id="audiosmall1135" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1135')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धनवान् बलवाँल्लोके सर्वः सर्वत्र सर्वदा । प्रभुत्वं धनमूलं हि राज्ञामप्युपजायते ॥१.१३५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धनवान् बलवान् लोके सर्वः सर्वत्र सर्वदा । प्रभुत्वं धनमूलं हि राज्ञाम् अपि उपजायते ॥१.१३५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोके सर्वः सर्वत्र सर्वदा धनवान् बलवान् । राज्ञाम् अपि प्रभुत्वं धनमूलं हि उपजायते ॥१.१३५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धनवान् = वित्तयुक्तः ; बलवान् = बलसम्पन्नः ; राज्ञामपि = महाराजानमपि ; प्रभुत्वं = राजत्वं ; धनमूलमेव = धनेनैव, धन-हेतुकमेव ; उपजायते = भवति ॥१.१३५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>लोके सर्वस्थानेषु सर्वकालेषु धनसम्पन्नः एव बलयुक्तः भवति । राजानः अपि धनकारणेनैव सर्वशासकाः जायन्ते ॥१.१३५॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्योकि- संसार में सभी जगह, सदा ही, धनी लोग ही बलवान् गिने जाते हैं । राजा लोग भी धन ही के कारण सबके स्वामी बने रहते हैं ॥१.१३५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.135.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1137" class="total">
                    <div>
                        <button id="moolamsmall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1137')">मूलम्</button>
                        <button id="padasmall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1137')">पदविभागः</button>
                        <button id="anvayasmall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1137')">अन्वयः</button>
                        <button id="pratismall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1137')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1137')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1137')">हिन्द्यर्थः</button>
                        <button id="audiosmall1137" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1137')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अर्थेन तु विहीनस्य पुरुषस्याल्पमेधसः । क्रियाः सर्वा विनश्यन्ति ग्रीष्मे कुसरितो यथा ॥१.१३७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अर्थेन तु विहीनस्य पुरुषस्य अल्प-मेधसः । क्रियाः सर्वा विनश्यन्ति ग्रीष्मे कुसरितः यथा ॥१.१३७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अर्थेन तु विहीनस्य पुरुषस्य अल्प-मेधसः । क्रियाः सर्वा विनश्यन्ति ग्रीष्मे कुसरितः यथा ॥१.१३७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अर्थेन = धनेन ; विहीनस्य = रहितस्य ; अल्पमेधसः = स्वल्पमतेः ; सर्वाः क्रियाः = सर्वाणि कर्माणि ; विनश्यन्ति = हीयन्ते ; ग्रीष्मे = आतपकाले ; कुसरितः = स्वल्पजला नद्यः ; ॥१.१३७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा अधिके आतपे अल्पनीरयुक्ताः नद्यः शुष्यन्ति, तथैव बुद्धिहीनस्य धनहीनस्य प्रयतनानि सर्वाणि व्यर्थानि भवन्ति॥१.१३७॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>धनहीन (दरिद्र) हो जाने से अल्पबुद्वि वाले भाग्यहीन मनुष्य के सभी काम उसी प्रकार बिगड़े जाते हैं, जैसे गरमी में सब छोटी छोटी नदियाँ सूख जाती है ॥१.१३७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.137.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1138" class="total">
                    <div>
                        <button id="moolamsmall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1138')">मूलम्</button>
                        <button id="padasmall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1138')">पदविभागः</button>
                        <button id="anvayasmall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1138')">अन्वयः</button>
                        <button id="pratismall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1138')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1138')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1138')">हिन्द्यर्थः</button>
                        <button id="audiosmall1138" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1138')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यस्यार्थास्तस्य मित्राणि यस्यार्थास्तस्य बान्धवाः । यस्यार्थाः स पुमान् लोके यस्यार्थाः स हि पण्डितः ॥१.१३८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्य अर्थाः तस्य मित्राणि यस्य अर्थाः तस्य बान्धवाः । यस्य अर्थाः सः पुमान् लोके यस्य अर्थाः सः हि पण्डितः ॥१.१३८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य अर्थाः तस्य मित्राणि यस्य अर्थाः तस्य बान्धवाः । यस्य अर्थाः सः पुमान् लोके यस्य अर्थाः सः हि पण्डितः ॥१.१३८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य = पुंसः ; अर्थाः = धनानि सन्ति ; तस्य = तस्य एव ; मित्राणि = सुहृदः भवन्ति ; बान्धवाः = सम्बन्धिनः ; पुमान् = पुरुषश्रेष्ठः ; लोके  विश्वे ; पण्डितः = विद्वान् ॥१.१३८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य = पुंसः ; अर्थाः = धनानि सन्ति ; तस्य = तस्य एव ; मित्राणि = सुहृदः भवन्ति ; बान्धवाः = सम्बन्धिनः ; पुमान् = पुरुषश्रेष्ठः ; लोके  विश्वे ; पण्डितः = विद्वान् ॥१.१३८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिसके पास धन है, उसीके सब लोग मित्र हैं, उसी के भाह बन्धु है, वह श्रेष्ठ पुरुष है और वही सच्चा पण्डित है ॥१.१३८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.138.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1139" class="total">
                    <div>
                        <button id="moolamsmall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1139')">मूलम्</button>
                        <button id="padasmall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1139')">पदविभागः</button>
                        <button id="anvayasmall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1139')">अन्वयः</button>
                        <button id="pratismall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1139')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1139')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1139')">हिन्द्यर्थः</button>
                        <button id="audiosmall1139" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1139')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अपुत्रस्य गृहं शून्यं सन्मित्ररहितस्य च । मूर्खस्य च दिशः शून्याः सर्वशून्या दरिद्रता ॥१.१३९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अपुत्रस्य गृहं शून्यं सन्मित्र-रहितस्य च । मूर्खस्य च दिशः शून्याः सर्वशून्या दरिद्रता ॥१.१३९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अपुत्रस्य सन्मित्र-रहितस्य च गृहं शून्यम् । मूर्खस्य च दिशः शून्याः । दरिद्रता सर्वशून्या ॥१.१३९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अपुत्रस्य = पुत्ररहितस्य पुंसः ; गृहं = गेहं ; शून्यं = रिक्तम् इव भवति ; सन्मित्ररहितस्य च = श्रेष्ठमित्रविरहितस्यापि च ; मूर्खस्य = अविवेकिनः ;  दिशः = दिक्प्रदेशाः शून्याः, क्वचिदपि स गन्तुमशक्तः, मूर्खत्वात् ; दरिद्रता = धनहीनत्वं ; सर्वशून्या = दरिद्रस्य सर्वमेव शून्यमित्यर्थः ॥१.१३९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य पुत्रः नास्ति, तस्य वेश्म सत्सु सर्वेष्वपि अन्येषु सर्वरहितमिव । सुहृदेन विनापि गृहं रिक्तमिव । विवेकहीनस्य आशाः सर्वाः प्रयोजनहीनाः । वित्तहीनता तु सर्वविधशून्यत्वस्य आस्पदम्॥१.१३९॥ </td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और भी-जिसको लडका नहीं है उसका, तथा जिसके सच्चा मित्र नहीं है उसका तो घर ही सूना है । और मूर्ख के लिए सब दिशायें ही सूनी हैं । (सभी देश शून्यवत् है, परन्तु दरिद्र के लिये तो सभी कुछ सूना है, अर्थात् दरिद्र के इसलिये सब कुछ सूने की तरह ही है ॥१.१३९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.139.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1140" class="total">
                    <div>
                        <button id="moolamsmall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1140')">मूलम्</button>
                        <button id="padasmall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1140')">पदविभागः</button>
                        <button id="anvayasmall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1140')">अन्वयः</button>
                        <button id="pratismall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1140')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1140')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1140')">हिन्द्यर्थः</button>
                        <button id="audiosmall1140" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1140')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दारिद्र्यान्मरणाद् वापि दारिद्र्यमवरं स्मृतम् । अल्पक्लेशेन मरणं दारिद्र्यमतिदुःसहम् ॥१.१४०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दारिद्र्यान् मरणाद् वा अपि दारिद्र्यम् अवरं स्मृतम् । अल्प-क्लेशेन मरणं दारिद्र्यम् अतिदुःसहम् ॥१.१४०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दारिद्र्यान् मरणाद् वा अपि दारिद्र्यम् अवरं स्मृतम् । मरणम् अल्प-क्लेशेन, दारिद्र्यम् अतिदुःसहम् ॥१.१४०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दारिद्र्यात् = धनहीनत्वात् ; मरणात् = मृत्योः ; अवरं = निकृष्टम् ; स्मृतम् = उक्तम्, ज्ञायेत ; अल्पक्लेशेन = क्षणमात्र-स्थायिना दुःखेन ;  दारिद्र्यं = दारिद्र्योत्थितं दुखन्तु ; अतिदुःसहम् = नितरां सोढुमशक्यम् ; ॥१.१४०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अत्र वित्तहीनतायाः मृत्योः च तुलना कृता । द्वयोः वित्तहीनता निकृष्टतरास्ति तस्याः अतिदुस्तरत्वात् । प्राणहरणम् अत्यल्पकष्टप्रदम्, दारिद्र्यदुःखं तु आजीवनपीडाकरम्॥१.१४०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>दरिद्रता और मरना इन दोनों में से मरना ही अच्छा है, क्यों कि मरने में तो थोड़ी देर ही क्लेश है, पर दरिद्रता में तो सदा कष्ट ही कष्ट है ॥१.१४०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.140.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1141" class="total">
                    <div>
                        <button id="moolamsmall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1141')">मूलम्</button>
                        <button id="padasmall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1141')">पदविभागः</button>
                        <button id="anvayasmall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1141')">अन्वयः</button>
                        <button id="pratismall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1141')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1141')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1141')">हिन्द्यर्थः</button>
                        <button id="audiosmall1141" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1141')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तानीन्द्रियाण्यविकलानि तदेव नाम सा बुद्धिरप्रतिहता वचनं तदेव । अर्थोष्मणा विरहितः पुरुषः स एव अन्यः क्षणेन भवतीति विचित्रमेतत् ॥१.१४१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तानि इन्द्रियाणि अविकलानि तद् एव नाम सा बुद्धिः अप्रतिहता वचनं तद् एव । अर्थ-ऊष्मणा विरहितः पुरुषः सः एव अन्यः क्षणेन भवति इति विचित्रम् एतत् ॥१.१४१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>तानि अविकलानि इन्द्रियाणि । तद् एव नाम । सा अप्रतिहता बुद्धिः । तद् एव वचनम् । सः एव अर्थोष्मणा विरहितः पुरुषः । अन्यः क्षणेन भवति- इति एतत् विचित्रम् ॥१.१४१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>तानि = यानि पूर्वम् आसन् तानि एव ; अविकलानि = दोषैः अनुपहतानि ; इन्द्रियाणि = चक्षुरादीनि (अप्रकटानि अवयवान्तरिक-संवेदकानि) ; तदेव = यद्धन-सत्त्वसमये आसीत्, तदेव च ; नाम = नामधेयम् ; अप्रतिहता = अकुण्ठिता सा निर्मला एव ; बुद्धिः = मतिः ; तदेव वचनं= वाक्यम् ; अर्थोष्मणा = वित्तागमनेन जनितः अहङ्कारतापः ; स एव = यो धनसत्त्वसमये आसीत्स एवास्ति ; अन्यः = अन्य इव, धनापगमेन प्रभावशून्यः ; इत्येतत् = अयं विषयः ; विचित्रम् = आश्चर्यजनकम् ॥१.१४१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धनं यदा अस्ति, तदा यानि अकुण्ठितानि इन्द्रियाणि, नाम, अविहता बुद्धिः, उक्तयः- सर्वाः समानाः धनापगमे अपि सन्ति । मनुष्यः अपि स एवास्ति । किन्तु लोके वित्तहीनस्य स्थितिः सपदि एव पूर्वस्याः धनवत्त्वस्थितेः नितान्तं विरुद्धा घटते इति विचित्रम्॥१.१४१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>यद्यपि दरिद्र होने पर भी पुरुष की वे ही अविकृत इन्द्रियाँ रहती है, वही नाम है, वही पहिले की तरह ही अल्प बुद्धि है, वही वाणी है, परन्तु जब उसमें धन की गर्मी नहीं रहती है, तो क्षण भर में ही उसकी दशा बदल जाती है, यह कैसी विचित्र और आश्चर्य की बात है ॥१.१४१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.141.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1142" class="total">
                    <div>
                        <button id="moolamsmall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1142')">मूलम्</button>
                        <button id="padasmall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1142')">पदविभागः</button>
                        <button id="anvayasmall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1142')">अन्वयः</button>
                        <button id="pratismall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1142')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1142')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1142')">हिन्द्यर्थः</button>
                        <button id="audiosmall1142" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1142')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अर्थनाशं मनस्तापं गहे दुश्चरितानि च । वञ्चनं चापमानं च मतिमान्न प्रकाशयेत् ॥१.१४२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अर्थनाशं मनस्तापं गहे दुश्चरितानि च । वञ्चनं, च अपमानं च, मतिमान्न प्रकाशयेत् ॥१.१४२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मतिमान् अर्थनाशं, मनस्तापं, गहे दुश्चरितानि च, वञ्चनं, च अपमानं च- न प्रकाशयेत् ॥१.१४२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अर्थनाशं = धननाशम् ; मनस्तापं = मानसं क्लेशम् ; गृहे = गृहे भवानि ; दुश्चरितानि = दुराचररगानि, व्यभिचारादीनि ; वञ्चनं = दुष्टैः छलः ; अपमानं = तिरस्कारञ्च ; मतिमान् = बुद्धिमान् ; न प्रकाशयेत् = कस्याप्यग्रे न प्रकटीकुर्यात् ॥१.१४२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विवेकशीलः कदापि एतान् स्वदोषान् बहिः न प्रकटयेत्- धनापगमं, मनसि पीडां, गेहे घटमानानि दुर्घटनानि, छलं, पराभवं च॥१.१४२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि- बुद्धिमान् मनुष्य,- अपने धनको नाश, अपने मन को सताप घरकी बुराई, ठगा जाना और अपने अपमान को किसी के सामने प्रकाशित न करे ॥१.१४२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.142.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1143" class="total">
                    <div>
                        <button id="moolamsmall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1143')">मूलम्</button>
                        <button id="padasmall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1143')">पदविभागः</button>
                        <button id="anvayasmall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1143')">अन्वयः</button>
                        <button id="pratismall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1143')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1143')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1143')">हिन्द्यर्थः</button>
                        <button id="audiosmall1143" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1143')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>आयुर्वित्तं गृहच्छिद्रं मन्त्रमैथुनभेषजम् । तपो दानापमानञ्च नव गोप्यानि यत्नतः ॥१.१४३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आयुः वित्तं, गृहच्छिद्रं, मन्त्रमैथुनभेषजं, तपः, दानापमानं च नव गोप्यानि यत्नतः ॥१.१४३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यत्नतः गोप्यानि नव – आयुः, वित्तं, गृहच्छिद्रं, मन्त्रमैथुनभेषजं, तपो, दानापमानं च ॥१.१४३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आयुः = जीवितकालः ; वित्तं = धनम् ; गृहच्छिद्रं = गृहे भवानि दुश्चरितानि ;  मन्त्रमैथुनभेषजम् = मन्त्रसुरतभेषजानि ; तपः = व्रतपूर्वकप्रयत्नः, दीक्षा ; दानम् = धनादीनां समर्पणम् ; अपमानञ्चेति = पराभवः च इति ; नव गोप्यानि = रहसि स्थाप्यानि, न प्रकाशनीयानि ॥१.१४३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(मनुष्येन कतिपय विषयाः न प्रकटनीयाः, क्वचिदपि कस्यचित् अपि पुरतः न वक्तव्याः । ते) प्रयत्नपूर्वकं गोप्यविषयाः नव सन्ति- वयः, वेतनं, गेहे दोषाः, मन्त्रदीक्षादिकं, रतिसुखप्रस्तावः, औषधं, तपस्या, वित्ताद्यर्पणं चेति ॥१.१४३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>आयु, धन, गृह का कलंक, मन्त्र, मैथुन, औषध, तप, दान और अपमान, इन नौ बातों को सदा बहुत सावधानी से छिपाना चाहिए ॥१.१४३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.143.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1144" class="total">
                    <div>
                        <button id="moolamsmall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1144')">मूलम्</button>
                        <button id="padasmall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1144')">पदविभागः</button>
                        <button id="anvayasmall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1144')">अन्वयः</button>
                        <button id="pratismall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1144')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1144')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1144')">हिन्द्यर्थः</button>
                        <button id="audiosmall1144" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1144')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अत्यन्तविमुखे दैवे व्यर्थे यत्ने च पौरुषे । मनस्विनो दरिद्रस्य वनादन्यत् कुतः सुखम् ॥१.१४४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अत्यन्त-विमुखे दैवे व्यर्थे यत्ने च पौरुषे । मनस्विनः दरिद्रस्य वनाद् अन्यत् कुतः सुखम् ॥१.१४४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दैवे अत्यन्तविमुखे (सति) यत्ने पौरुषे च व्यर्थे (सति) मनस्विनः दरिद्रस्य वनाद् अन्यत् कुतः सुखम् ॥१.१४४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दैवे = अदृष्टे ; अत्यन्तं विमुखे = नितरां प्रतिकूले सति ; यत्ने = प्रयत्ने च ; पौरुषे = बले च ; व्यर्थे = व्यर्थतां गते सति ; मनस्विनः = मानधनस्य, उन्नतचित्तस्य ; दरिद्रस्य = धनहीनस्य ; वनाद् अन्यत् = स्वदेशं विहाय वनगमनं विना ; कुतः सुखं = क्व सुखं स्यात् ॥१.१४४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदा भाग्यं विमुखं, यदा आत्मबलः, प्रयत्नश्च व्यर्थतां यातः- तदानीम् उत्तममनसः वित्तहीनस्य वनं विहाय क्व सुखम्? नैव कुत्रापि सुखमित्यर्थः ॥१.१४४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जब विधाता प्रतिकूल हो और जब सब यत्न भी निष्फल हो जाए, तो निर्धन मनस्वी मनुष्य के लिये वन को छोड़कर और काहाँ सुख हो सकता है ? अर्थात् इसे देश छोड़कर अन्यत्र कहीं वनमें चला जाना चाहिए ॥१.१४८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.144.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1145" class="total">
                    <div>
                        <button id="moolamsmall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1145')">मूलम्</button>
                        <button id="padasmall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1145')">पदविभागः</button>
                        <button id="anvayasmall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1145')">अन्वयः</button>
                        <button id="pratismall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1145')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1145')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1145')">हिन्द्यर्थः</button>
                        <button id="audiosmall1145" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1145')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>मनस्वी म्रियते कामं कार्पण्यं न तु गच्छति । अपि निर्वाणमायाति नानलो याति शीतताम् ॥१.१४५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मनस्वी म्रियते कामं कार्पण्यं न तु गच्छति । अपि निर्वाणम् आयाति न अनलः याति शीतताम् ॥१.१४५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मनस्वी म्रियते कामं कार्पण्यं न तु गच्छति । अपि निर्वाणम् आयाति न अनलः याति शीतताम् ॥१.१४५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मनस्वी = उन्नतचेतः ; कामं = इच्छया ; म्रियते=स्वप्राणान् जहाति ; कार्पण्यं = दैन्यम् ; गच्छति, आयाति, याति = स्थितिं प्राप्नोति ; निर्वाणं = शान्तिम् ; शीततां = शैत्यम् ; अनलः = वह्निः ॥१.१४५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मानधनी नरः इच्छापूर्वकं मरणं प्राप्नोति किन्तु दीनस्थितिं न आप्नोति । (अस्योदाहरणम्) अनलः अन्ततो गत्वा उपशाम्यति किन्तु शीतो न भवति॥१.१४५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>मानधनी नरः इच्छापूर्वकं मरणं प्राप्नोति किन्तु दीनस्थितिं न आप्नोति । (अस्योदाहरणम्) अनलः अन्ततो गत्वा उपशाम्यति किन्तु शीतो न भवति॥१.१४५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.145.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1146" class="total">
                    <div>
                        <button id="moolamsmall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1146')">मूलम्</button>
                        <button id="padasmall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1146')">पदविभागः</button>
                        <button id="anvayasmall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1146')">अन्वयः</button>
                        <button id="pratismall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1146')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1146')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1146')">हिन्द्यर्थः</button>
                        <button id="audiosmall1146" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1146')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>कुसुमस्तबकस्येव द्वे वृत्ती तु मनस्विनः । सर्वेषां मूर्ध्नि वा तिष्ठेद् विशीर्येत वनेऽथवा ॥१.१४६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कुसुमस्तबकस्य इव द्वे वृत्ती तु मनस्विनः । सर्वेषां मूर्ध्नि वा तिष्ठेद् विशीर्येत वने अथवा ॥१.१४६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कुसुमस्तबकस्य इव द्वे वृत्ती तु मनस्विनः । सर्वेषां मूर्ध्नि वा तिष्ठेद् विशीर्येत वने अथवा ॥१.१४६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कुसुमस्तबकस्य इव=पुष्पगुच्छकस्य इव ; वृत्ती = व्यवस्थिती ; मनस्विनः = मानधनिनः ; मूर्ध्नि = शिरसि ; विशीर्येत = म्लायेत् ; वने = अरण्ये ;  ॥१.१४६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पुष्पमालेव उत्तममनस्काः द्वौ मार्गौ एव सरन्ति। सा यद्वा जनानां शिरसि तिष्ठति, नो चेत् वने म्लानीभवति । (तथैव मानिनः सर्वेषां हृदये स्थिताः नो चेत् जनसमाजात् बहिरेव भवन्ति)॥१.१४६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>फूल के गुच्छे की तरह मनस्वी मनुष्य की भी दो ही वृत्तियाँ होती हैं। या तो वह सब के (शिर के) ऊपर ही रहता है, अथवा वह वन में ही पड़ा-पड़ा नष्ट हो जाता है ॥१.१४६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.146.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1147" class="total">
                    <div>
                        <button id="moolamsmall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1147')">मूलम्</button>
                        <button id="padasmall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1147')">पदविभागः</button>
                        <button id="anvayasmall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1147')">अन्वयः</button>
                        <button id="pratismall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1147')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1147')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1147')">हिन्द्यर्थः</button>
                        <button id="audiosmall1147" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1147')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वरं विभवहीनेन प्राणैः सन्तर्पितोऽनलः । नोपचारपरिभ्रष्टः कृपणः प्रार्थितो जनः ॥१.१४७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरं विभव-हीनेन प्राणैः सन्तर्पितः अनलः । न उपचार-परिभ्रष्टः कृपणः प्रार्थितः जनः ॥१.१४७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विभवहीनेन प्राणैः सन्तर्पितः अनलः वरम्।  उपचारपरिभ्रष्टः कृपणः प्रार्थितः जनः (इति) न (वरम्) ॥१.१४७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वरम् = श्रेष्ठम् ; विभवहीनेन = धनरहितेन पुंसा ; अनलः = वह्निः ; प्राणैः = जीवितेन ; सन्तर्पितः = तृप्तिं कारितः, वह्वौ शरीरं हुतं चेत् ; वरं = किञ्चित् श्रेष्ठम् ; उपचारपरिभ्रष्ठः = सत्कारवर्जितः ; कृपणो जनः = कदर्यः ;  प्रार्थितः=याचितः ; ॥१.१४७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अस्मिन् श्लोके निर्धनस्य मनुष्यस्य दुःस्थितिः वर्ण्यते-) सद्भावनारहितस्य परमलुब्धस्य पुरतः गत्वा याचनात् वरमिदं यत् धनहीनः वह्नौ स्वस्य शरीरं त्यजेत् ॥१.१४७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>दरिद्र मनुष्य अपने प्राण को अग्नि में समर्पण कर दे, तो वह बहुत अच्छा है। परन्तु विचार शून्य कृपण मनुष्यों से प्रार्थना करना (उनसे भिक्षा माँगना) यह तो अच्छा नहीं हैं ॥१.१४७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.147.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1148" class="total">
                    <div>
                        <button id="moolamsmall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1148')">मूलम्</button>
                        <button id="padasmall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1148')">पदविभागः</button>
                        <button id="anvayasmall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1148')">अन्वयः</button>
                        <button id="pratismall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1148')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1148')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1148')">हिन्द्यर्थः</button>
                        <button id="audiosmall1148" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1148')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दारिद्र्याद्ध्रियमेति ह्रीपरिगतः सत्त्वात् परिभ्रश्यते निःसत्त्वः परिभूयते परिभवान्निर्वेदमापद्यते । निर्विण्णः शुचमेति शोकनिहतो बुद्ध्या परित्यज्यते निर्बुद्धिः क्षयमेत्यहो निधनता सर्वापदामास्पदम् ॥१.१४८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दारिद्र्याद् ह्रियम् एति ह्रीपरिगतः सत्त्वात् परिभ्रश्यते निःसत्त्वः परिभूयते परिभवान् निर्वेदम् आपद्यते । निर्विण्णः शुचम् एति शोक-निहतः बुद्ध्या परित्यज्यते निर्बुद्धिः क्षयम् एति अहो निधनता सर्व-आपदाम् आस्पदम् ॥१.१४८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दारिद्र्याद् ह्रियम् एति । ह्रीपरिगतः सत्त्वात् परिभ्रश्यते । निःसत्त्वः परिभूयते । परिभवान् निर्वेदम् आपद्यते । निर्विण्णः शुचम् एति । शोकनिहतः बुद्ध्या परित्यज्यते । निर्बुद्धिः क्षयम् एति । अहो निधनता सर्वापदाम् आस्पदम् ॥१.१४८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दारिद्र्याद् = निर्धनत्वात् । ह्रियं = लज्जाम्। ह्रीपरिगतः = लज्जितः ; सत्त्वात् = शक्त्या, बलात्, ओजसः, पौरुषात्, धैर्याच्च ; परिभ्रश्यते = तेजसा विहीनो भवति ; निस्सत्त्वः = शक्तिहीनः ; परिभूयते = तिरस्क्रियते ; निर्वेदं = ग्लानिम्. मनस्तापञ्च ; आपद्यते = स्थितिं प्राप्नोति ; निर्विण्णः = खिन्नः ; शुचं= शोकम् ; एति = गच्छति ; शोकनिहतः = व्याकुलः ; बुद्ध्या = मत्या ; परित्यज्यते = त्यक्तो भवति ; निर्बुद्धिः = बुद्धिहीनः ; क्षयं = विनाशम् ; निधनता = निर्धनता, दरिद्रता ; सर्वापदां = सकलविपत्तीनाम् ; आस्पदं = स्थानम्, कारणञ्च ॥१.१४८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अस्मिन् पद्ये दरिद्रतायाः नरः परम्पराशृङ्खलया कां स्थितिम् आप्नोतीति दर्शयति) निर्धनः जनः लज्जामनुभवति, ततः कान्तिहीनः, ततः पराभवभाक् च भवति। तेन खेदं, ततश्च शोकं, पुनः बुद्धिहीनतां च समाप्नोति। अहो, वित्तहीनः सर्वदा आपद्भिः एव परिवृत्तो भवति ॥१.१४८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>(अस्मिन् पद्ये दरिद्रतायाः नरः परम्पराशृङ्खलया कां स्थितिम् आप्नोतीति दर्शयति) निर्धनः जनः लज्जामनुभवति, ततः कान्तिहीनः, ततः पराभवभाक् च भवति। तेन खेदं, ततश्च शोकं, पुनः बुद्धिहीनतां च समाप्नोति। अहो, वित्तहीनः सर्वदा आपद्भिः एव परिवृत्तो भवति ॥१.१४८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
