                <div id="1149" class="total">
                    <div>
                        <button id="moolamsmall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1149')">मूलम्</button>
                        <button id="padasmall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1149')">पदविभागः</button>
                        <button id="anvayasmall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1149')">अन्वयः</button>
                        <button id="pratismall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1149')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1149')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1149')">हिन्द्यर्थः</button>
                        <button id="audiosmall1149" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1149')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वरं मौनं कार्यं न च वचनमुक्तं यदनृतं वरं क्लैब्यं पुंसां न च परकलत्राभिगमनम् । वरं प्राणत्यागो न च पिशुनवाक्येष्वभिरुचि-र्वरं भिक्षाशित्वं न च परधनास्वादनसुखम् ॥१.१४९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरं मौनं कार्यं न च वचनम् उक्तं यद् अनृतं वरं क्लैब्यं पुंसां न च पर-कलत्र-अभिगमनम् । वरं प्राण-त्यागः न च पिशुन-वाक्येषु अभिरुचिः वरं भिक्षाशित्वं न च परधन-आस्वादन-सुखम् ॥१.१४९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मौनं कार्यं वरं, यद् अनृतं (तद्) वचनम् उक्तं न च। पुंसां क्लैब्यं वरं, पर-कलत्र-अभिगमनं न च । प्राण-त्यागः वरं, पिशुन-वाक्येषु अभिरुचिः न च । भिक्षाशित्वं वरं, परधन-आस्वादन-सुखं न च ॥१.१४९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वरं = उत्तमम् ; मौनं कार्यं = तूष्णीभावस्य आचरणम् ; वचनं = वाणी ; अनृतं = मिथ्या ; क्लैब्यं = नपुंसकता ; परकलत्राभिगमनम् = परदाराणां प्रति असाधुवाञ्छा, तदाचरणं च ; प्राणत्यागः = जीवनस्य समापनम् ; पिशुनवाक्येषु = अनुपस्थितौ निन्दासु, दुर्जनखलवचनेषु ; अभिरुचिः=आदरः ; भिक्षाशित्वं = भिक्षाभोजनस्वीकारः ; परधनास्वादनसुखम् = परेषां धनस्य उपभोगे लम्पटता ॥१.१४९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अस्मिन् पद्ये श्रेष्ठाचारस्य कीर्तनं, तदितरस्य गर्हिताचरणस्य निन्दा च कृता ।) असत्यवचनात् न किमपि उक्तमेव साध्वाचारः । अन्येषां पत्नीषु आसक्तेः नपुंसकत्वमेव उत्तमम् । कस्यचित् अनुपस्थितौ दुर्वचनानां प्रयोगात् मृत्युरेव आचरणीयः । अन्येषां धनमुपयुज्य उपभोगेच्छया भिक्षाटनं साधुकार्यम्  ॥१.१४९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>चुप रहना कहीं अच्छा है, परन्तु मू बोलना अच्छा नहीं।  नपुंसकता अच्छा है, परन्तु परस्त्रीगमन अच्छा नहीं । मर जाना अच्छा है परन्तु दुष्ट व निन्दक के वचन में विश्वास करना अच्छा नहीं । भिक्षा माँगकर खाना अच्छा है, परन्तु क्रूर के धन पर आनन्द (मौज) करना कभी अच्छा नहीं है ॥१.१४९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.149.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1150" class="total">
                    <div>
                        <button id="moolamsmall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1150')">मूलम्</button>
                        <button id="padasmall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1150')">पदविभागः</button>
                        <button id="anvayasmall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1150')">अन्वयः</button>
                        <button id="pratismall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1150')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1150')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1150')">हिन्द्यर्थः</button>
                        <button id="audiosmall1150" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1150')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वरं शून्या शाला न च खलु वरो दुष्टवृषभो वरं वेश्या पत्नी न पुनरविनीता कुलवधूः । वरं वासोऽरण्ये न पुनरविवेकाधिपपुरे वरं प्राणत्यागो न पुनरधमानामुपगमः ॥१.१५०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरं शून्या शाला न च खलु वरः दुष्ट-वृषभः वरं वेश्या पत्नी न पुनः अविनीता कुलवधूः ।वरं वासः अरण्ये न पुनः अविवेक-अधिप-पुरे वरं प्राण-त्यागः न पुनः अधमानाम् उपगमः ॥१.१५०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शून्या शाला वरं, दुष्ट-वृषभः न च खलु वरः । वेश्या पत्नी वरं, अविनीता कुलवधूः न पुनः । अरण्ये वासः वरं, अविवेक-अधिप-पुरे न पुनः । प्राण-त्यागः वरं, अधमानाम् उपगमः न पुनः ॥१.१५०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वरम् = श्रेष्ठ इत्यर्थः ; शाला = गोशाला, गृहं च ; वृषभः = गौः ; वासः = जीवनयापनाय निवासः ; अरण्ये = वने ;  अविनीता = अविनम्रा ; अविवेकाधिपपुरे = विवेकशून्यः यः नरपतिः तस्य नगर्याम् ; उपगमः = याच्ञा ; अधमानां = नीचानाम् ॥१.१५०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>वरम् = श्रेष्ठ इत्यर्थः ; शाला = गोशाला, गृहं च ; वृषभः = गौः ; वासः = जीवनयापनाय निवासः ; अरण्ये = वने ;  अविनीता = अविनम्रा ; अविवेकाधिपपुरे = विवेकशून्यः यः नरपतिः तस्य नगर्याम् ; उपगमः = याच्ञा ; अधमानां = नीचानाम् ॥१.१५०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>गोशाला का सूना रहना अच्छा है, परन्तु उनमें दुष्ट बैल रखना अच्छा नहीं है । वेश्या को पत्नी रूप से रख लेना अच्छा है, परन्तु कुलीन स्त्री यदि दुश्चरित्रा हो, तो वह अच्छा नहीं । वन में रहना अच्छा है, परन्तु अविवेकी राजा के राज्य में रहना अच्छा नहीं । प्राण का त्याग कर देना कहीं अच्छा है, परन्तु नीचो, की सेवा और उनका संग-साथ कभी अच्छा नहीं है ॥१.१५०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.150.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1151" class="total">
                    <div>
                        <button id="moolamsmall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1151')">मूलम्</button>
                        <button id="padasmall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1151')">पदविभागः</button>
                        <button id="anvayasmall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1151')">अन्वयः</button>
                        <button id="pratismall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1151')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1151')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1151')">हिन्द्यर्थः</button>
                        <button id="audiosmall1151" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1151')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सेवेव मानमखिलं ज्योत्स्नेव तमो जरेव लावण्यम् । हरिहरकथेव दुरितं गुणशतमप्यर्थिता हरति ॥१.१५१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सेवा इव मानम् अखिलं ज्योत्स्ना इव तमः जरा इव लावण्यम् । हरिहर-कथा इव दुरितं गुण-शतम् अपि अर्थिता हरति ॥१.१५१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सेवा अखिलं मानम् इव, ज्योत्स्ना तमः इव, जरा लावण्यम् इव, हरिहरकथा दुरितम् इव- अर्थिता गुणशतम् अपि हरति ॥१.१५१॥ 🌼</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सेवा = भृत्यकार्यम् ; मानम् = आत्मगौरवभावः ; अखिलं = सर्वम् ; हरति = न्यूनीकरोति ; जोत्स्ना = चन्द्रकान्तिः ; तमः = अन्धकारम् ; हरति = नाशयति ; जरा = वृद्धावस्था ; लावण्यं = सौन्दर्यम् ; हरति = अल्पीकरोति; हरिहरकथा = भगवत्कीर्तनम् ; दुरितं = पापं ; हरति = अपाकरोति ; अर्थिता = याच्ञा ; गुणशतम् अपि = अनुन्तान् अपि गुणान् ; हरति = विलोपयति ; ॥१.१५१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सेवनं पूर्णं स्वाभिमानं लोपयति । चन्द्रिका तिमिरस्य अन्तं करोति । वार्धक्यं सुन्दरतां तनूकरोति । ईश्वरप्रसङ्गश्रवणं, चिन्तनं च अघं विनाशयति । तथैव याचना निखलान् अपि सद्गुणान् विलोपयति ॥१.१५१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जैसे दूसरे की सेवा मान को, प्रकाश अन्धकार को, वृद्धता सौन्दर्य को और भगवत्कथा पाप को हरण करती है, वैसे ही याचना (माँगना) भी मनुष्यों के सभी गुणों को हर लेती है, (वह सभी गुणों का नाश कर देती है) ॥१.१५१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.151.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
