                            <td>सेवा = भृत्यकार्यम् ; मानम् = आत्मगौरवभावः ; अखिलं = सर्वम् ; हरति = न्यूनीकरोति ; जोत्स्ना = चन्द्रकान्तिः ; तमः = अन्धकारम् ; हरति = नाशयति ; जरा = वृद्धावस्था ; लावण्यं = सौन्दर्यम् ; हरति = अल्पीकरोति; हरिहरकथा = भगवत्कीर्तनम् ; दुरितं = पापं ; हरति = अपाकरोति ; अर्थिता = याच्ञा ; गुणशतम् अपि = अनुन्तान् अपि गुणान् ; हरति = विलोपयति ; ॥१.१५१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सेवनं पूर्णं स्वाभिमानं लोपयति । चन्द्रिका तिमिरस्य अन्तं करोति । वार्धक्यं सुन्दरतां तनूकरोति । ईश्वरप्रसङ्गश्रवणं, चिन्तनं च अघं विनाशयति । तथैव याचना निखलान् अपि सद्गुणान् विलोपयति ॥१.१५१॥</td>
