                <div id="1152" class="total">
                    <div>
                        <button id="moolamsmall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1152')">मूलम्</button>
                        <button id="padasmall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1152')">पदविभागः</button>
                        <button id="anvayasmall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1152')">अन्वयः</button>
                        <button id="pratismall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1152')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1152')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1152')">हिन्द्यर्थः</button>
                        <button id="audiosmall1152" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1152')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पल्लवग्राहि पाण्डित्यं क्रयक्रीतञ्च मैथुनम्। भोजनञ्च पराधीनं तिस्रः पुंसां विडम्बनाः ॥१.१५२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पल्लव-ग्राहि पाण्डित्यं, क्रयक्रीतं च मैथुनम्। भोजनं च पराधीनं, तिस्रः पुंसां विडम्बनाः ॥१.१५२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पाण्डित्यं पल्लवग्राहि, मैथुनं च क्रयक्रीतं, भोजनं च पराधीनं- तिस्रः पुंसां विडम्बनाः ॥१.१५२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पल्लवग्राहि = अंशमात्रेण गृहीतम्, नानाशास्त्रेभ्यः कियतः अपि अंशस्य विशकलितस्य ग्रहणेन समुद्धतम् ; क्रयक्रीतं = वेश्यादितो भाटकेन लब्धम् ; मैथुनं = सुरतम् ; भोजनम् = अन्नग्रहणम् ; पराधीनं = स्ववशात् बहिः ; पुंसां = मनुष्याणाम् ; विडम्बनाः = कदर्थनानि, उपहासायैव ॥१.१५२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अत्र विडम्बनाजनकविषयाः त्रयः उक्ताः) अपूर्णा विद्वत्ता लेशमात्रं ज्ञानं वा, (वाराङ्गनायै पण्यस्त्रियै वा) धनं दत्त्वा उपभुक्तं रतिसुखं, अन्येभ्यः करणीयम् अशनं च प्रतारणकराः विषयाः एते त्रयः॥१.१५२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि-पल्लवग्राही पाण्डित्य-(थोडा थोडा सब कुछ पढ़ना, परन्तु किसी विषय को पूरा पूरा न जानना), द्रव्य देकर मैथुन करना, दूसरे के अधीन होकर पेट पालना (भोजन करना) ये तीनों बातें तो अत्यन्त कष्ट देने बाली और उपहासास्पद ही हैं, अर्थात् निस्सार (व्यर्थ) ही है ॥१.१५२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.152.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1153" class="total">
                    <div>
                        <button id="moolamsmall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1153')">मूलम्</button>
                        <button id="padasmall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1153')">पदविभागः</button>
                        <button id="anvayasmall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1153')">अन्वयः</button>
                        <button id="pratismall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1153')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1153')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1153')">हिन्द्यर्थः</button>
                        <button id="audiosmall1153" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1153')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>रोगी चिरप्रवासी परान्नभोजी परावसथशायी । यज्जीवति तन्मरणं यन्मरणं सोऽस्य विश्रामः ॥१.१५३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रोगी चिर-प्रवासी पर-अन्न-भोजी पर-आवसथ-शायी । यत् जीवति तत् मरणं यत् मरणं सः अस्य विश्रामः ॥१.१५३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>रोगी चिरप्रवासी परान्नभोजी परावसथशायी । यत् जीवति तत् मरणं यत् मरणं सः अस्य विश्रामः ॥१.१५३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>रोगी = आतुरः ; चिरप्रवासी = अधिकसमयं यावत् अन्यदेशो यः निवसति ; परान्नभोजी = अन्येषां गृहे यः भोजनं गृह्णाति ; परावसथशायी = परगृहे यः शेते ; यज्जीवति तन्मरणं = तस्य जीवनं मरणतुल्यम् ; यन्मरणं सोऽस्य विश्रामः = मरणञ्च तस्य क्लेशनिर्मोक्षः ॥१.१५३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>[एतेषां चतुर्णां स्थितिः मृत्युतुल्या भवति इति उच्यते] रोगग्रस्तः, अधिककालं यावत् विदेशनिवासी, यः परेषाम् अन्नं खादति, परगृहे यः निद्राति- एतेषां जीवनं मृत्युतुल्यम्। मृत्युं प्राप्नुवन्ति, तेनैव समस्याविरामः भवति ॥१.१५३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>रोगी, सदा परदेश रहने वाले दूसरे का अन्न खाने वाले, और दूसरे के घर में रहनेवाले-पुरुष का जीवन तो मरने के तुल्य है, और उसका मरना उसके लिए विश्राम के ही समान है। अर्थात् जीने से उसका मरना ही अच्छा है ॥१.१५३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.153.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1154" class="total">
                    <div>
                        <button id="moolamsmall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1154')">मूलम्</button>
                        <button id="padasmall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1154')">पदविभागः</button>
                        <button id="anvayasmall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1154')">अन्वयः</button>
                        <button id="pratismall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1154')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1154')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1154')">हिन्द्यर्थः</button>
                        <button id="audiosmall1154" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1154')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>लोभेन बुद्धिश्चलति लोभो जनयते तृषाम् । तृषार्तो दुःखमाप्नोति परत्रेह च मानवः ॥१.१५४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>लोभेन बुद्धिः चलति लोभः जनयते तृषाम् । तृषार्तः दुःखम् आप्नोति परत्र इह च मानवः ॥१.१५४॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोभेन बुद्धिः चलति । लोभः तृषां जनयते । तृषार्तः मानवः परत्र इह च दुःखम् आप्नोति ॥१.१५४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोभेन = अत्याकाङ्क्षया ; बुद्धिः चलति = मतिः नश्यति ; तृषाम् = तृष्णाम् ; तृषार्तः = तृष्णया आर्दितः, धनादितृष्णया आकुलः ; मानवः = मनुष्यः ; परत्र = परलोके ; इह = अस्मिन्लोके ; दुःखम् आप्नोति = पीडाम् अनुभवति ; ॥१.१५४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(लोभात् काः हानयः भवन्तीति उच्यते-) अतिस्पृहया मतिभ्रमः भवति । अत्यभिलाषेण अतिलिप्सा जायते । तृष्णायुक्तः इहलोके परलोके च खेदमनुभवति । ॥१.१५४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>लोभ से मनुष्य की बुद्धि चञ्चल हो जाती है, और लोभ से मनुष्य को तृष्णा उत्पन्न होती है और तृष्णा से ही मनुष्य इस लोक में तथा परलोक में भी दुःख पाता है ॥१.१५४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.154.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1155" class="total">
                    <div>
                        <button id="moolamsmall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1155')">मूलम्</button>
                        <button id="padasmall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1155')">पदविभागः</button>
                        <button id="anvayasmall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1155')">अन्वयः</button>
                        <button id="pratismall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1155')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1155')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1155')">हिन्द्यर्थः</button>
                        <button id="audiosmall1155" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1155')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धनलुब्धो ह्यसन्तुष्टोऽनियतात्माजितेन्द्रियः । सर्वा एवापदस्तस्य यस्य तुष्टं न मानसम् ॥१.१५५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धनलुब्धः हि असन्तुष्टः अनियतात्मा अजितेन्द्रियः । सर्वाः एव आपदः तस्य यस्य तुष्टं न मानसम् ॥१.१५५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धनलुब्धः हि असन्तुष्टः अनियतात्मा अजितेन्द्रियः सर्वाः एव आपदः तस्य यस्य मानसं तुष्टं न (भवति) ॥१.१५५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धनलुब्धः = वित्ते दत्तैकचित्तः, धनलोभाक्रान्तः ; हि = निश्चयेन ; असन्तुष्टः = सन्तोषरहितः ; अनियतात्मा = यः स्ववशे नास्ति, चञ्चलमानसः ; अजितेन्द्रियः = इन्द्रियाणि यस्य स्वामिनः भवन्ति ; सर्वाः एव आपदः = समस्तविधाः विपत्तयः ; मानसं तुष्टं न = अन्तः सन्तुष्टिः नास्ति ॥१.१५५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः वित्तसक्तः, सन्तोषहीनः, अवशात्मा, अवशेन्द्रियः अथवा , नियमनरहितः, अतुष्टमनाः भवति- तस्य सर्वाः विपत्तयः भवन्ति ॥१.१५५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो मनुष्य धन का लोभी, असंतोषी, चञ्चल चित्तवाला, इन्द्रियों के वश में रहनेवाला है, तथा जिसका मन सन्तुष्ट नहीं है, ऐसे मनुष्य को सब प्रकार की आपत्तियों आकर घेर लेती हैं ॥१.१५५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.155.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1156" class="total">
                    <div>
                        <button id="moolamsmall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1156')">मूलम्</button>
                        <button id="padasmall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1156')">पदविभागः</button>
                        <button id="anvayasmall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1156')">अन्वयः</button>
                        <button id="pratismall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1156')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1156')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1156')">हिन्द्यर्थः</button>
                        <button id="audiosmall1156" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1156')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सर्वाः सम्पत्तयस्तस्य सन्तुष्टं यस्य मानसम् । उपानद्गूढपादस्य ननु चर्मावृतेव भूः ॥१.१५६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सर्वाः सम्पत्तयः तस्य सन्तुष्टं यस्य मानसम् । उपानद्-गूढ-पादस्य ननु चर्म-आवृता इव भूः ॥१.१५६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य मानसं सन्तुष्टं तस्य सर्वाः सम्पत्तयः (भवन्ति) । (अत्रोदहरणम्) ननु उपानद्गूढपादस्य भूः चर्मावृता इव ॥१.१५६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य मानसं सन्तुष्टं तस्य सर्वाः सम्पत्तयः (भवन्ति) । (अत्रोदहरणम्) ननु उपानद्गूढपादस्य भूः चर्मावृता इव ॥१.१५६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य मनः सन्तृप्तं भवति, तस्य सविधे सर्वविधसम्पदाः भवन्ति। यस्य पादयोः पादरक्षे भवतः, तस्मै भूमिः चर्मणा आवृता इव निष्कण्टका भवति॥१.१५६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिसका मन सन्तुष्ट है, उसके पास सब सम्पत्ति है । जैसे जिस मनुष्य के पैर में जूता है, उसके लिये मानो सब पृथ्वी ही चर्म से अच्छा दिए है ॥१.१५६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.156.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1157" class="total">
                    <div>
                        <button id="moolamsmall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1157')">मूलम्</button>
                        <button id="padasmall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1157')">पदविभागः</button>
                        <button id="anvayasmall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1157')">अन्वयः</button>
                        <button id="pratismall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1157')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1157')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1157')">हिन्द्यर्थः</button>
                        <button id="audiosmall1157" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1157')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सन्तोषामृततृप्तानां यत् सुखं शान्तचेतसाम् । कुतस्तद्धनलुब्धानामितश्चेतश्च धावताम् ॥१.१५७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सन्तोष-अमृत-तृप्तानां यत् सुखं शान्त-चेतसाम् । कुतः तद्धन-लुब्धानामितश्चेतश्च धावताम् ॥१.१५७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सन्तोषामृततृप्तानां शान्तचेतसां यत् सुखं तत् कुतः धनलुब्धानाम् इतश्च इतश्च धावताम् ?॥१.१५७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सन्तोषामृततृप्तानां ~ सन्तोषः एव अमृतं, तेन तृप्तानाम् इत्यर्थः = आनन्दभावेन सन्तुष्टानाम् ; शान्तचेतसां = प्रशान्तं चित्तं येषां तेषां ; सुखं = धनलुब्धानाम् = वित्तेन आकृष्टानां ; इतश्च इतश्च धावताम् = दिशं विना धावन्ति ये तेषां॥१.१५७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये सन्तोषकारणात् तृप्तिभावयुक्ताः, येषां मनांसि शान्तानि भवन्ति, ते नन्दन्ति। तादृशं नन्दनं द्रविणलोलुपानां, दिशाहीनं गच्छतां न भवति ॥१.१५७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सन्तोषरूपी अमृत से तृप्त एवं शान्त चित्तवालों को जो सुख है, वह सुख धन के लोभ से इधर-उधर दौड़ने वाला को कहाँ से हो सकता है? ॥१.१५७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.157.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1158" class="total">
                    <div>
                        <button id="moolamsmall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1158')">मूलम्</button>
                        <button id="padasmall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1158')">पदविभागः</button>
                        <button id="anvayasmall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1158')">अन्वयः</button>
                        <button id="pratismall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1158')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1158')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1158')">हिन्द्यर्थः</button>
                        <button id="audiosmall1158" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1158')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>तेनाधीतं श्रुतं तेन तेन सर्वमनुष्ठितम् । येनाशाः पृष्ठतः कृत्वा नैराश्यमवलम्बितम् ॥१.१५८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तेन अधीतं श्रुतं तेन तेन सर्वम् अनुष्ठितम् । येन आशाः पृष्ठतः कृत्वा नैराश्यम् अवलम्बितम् ॥१.१५८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>येन आशाः पृष्ठतः कृत्वा नैराश्यम् अवलम्बितं, तेन अधीतम्, तेन श्रुतम्, तेन सर्वम् अनुष्ठितम् ॥१.१५८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अधीतम् = अध्ययनं कृतम्, शास्त्रं पठितम् ; श्रुतम् = गुरुमुखतः आकर्णितम् ; अनुष्ठितम् = सर्वं यज्ञादिकं शुभं कर्म कृतम् ; नैराश्यं = लोभाभावः, सन्तोषः ; अवलम्बितम् = स्वस्मिन् विहितम् ॥१.१५८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः अतितृष्णां त्यक्त्वा मनसि सन्तुष्टिं गतवान्, स एव अधीती, बहुश्रुतः, आचारवान् च ॥१.१५८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिसने आशा को लात मार कर नैराश्य (निराशा) का ही अवलम्बन किया है, उसीने सब शास्त्रों को ठीक २ पढा है, और उसी ने शास्त्रों को ठीक२ सुना है और उसी ने सब कुछ कर्त्तव्य कार्य किया है ॥१.१५८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.158.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1159" class="total">
                    <div>
                        <button id="moolamsmall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1159')">मूलम्</button>
                        <button id="padasmall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1159')">पदविभागः</button>
                        <button id="anvayasmall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1159')">अन्वयः</button>
                        <button id="pratismall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1159')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1159')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1159')">हिन्द्यर्थः</button>
                        <button id="audiosmall1159" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1159')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>असेवितेश्वरद्वारमदृष्टविरहव्यथम् । अनुक्तक्लीबवचनं धन्यं कस्यापि जीवनम् ॥१.१५९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>असेवित-ईश्वर-द्वारम् अदृष्ट-विरह-व्यथम् । अनुक्त-क्लीब-वचनं धन्यं कस्य अपि जीवनम् ॥१.१५९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>असेवितेश्वरद्वारम् अदृष्टविरहव्यथम् । अनुक्त-क्लीब-वचनं धन्यं कस्य अपि जीवनम् ॥१.१५९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>(जीवनम् इत्यस्य विशेषणानि सर्वाणि पदानि) असेवितेश्वरद्वारम् ~ न सेवितं ईश्वरस्य द्वारं यस्मिन् जीवने = राजादिधनिगृहद्वारं न सेवितम् यस्मिन् जीवने; अदृष्टविरहव्यथम् ~ अदृष्टा विरहव्यथा यस्मिन् तत् तादृक् = प्रियविरहं न अनुभूतं यस्मिन् जीवने ; अनुक्तक्लीबवचनम् ~ नोक्तं क्वीबवचनं यस्मिन् जीवने = दीनवाक्यं मुखात् न निःसृतं ; जीवनम् = जीवितम् ; कस्यापि = सन्तुष्टस्य, विरक्तस्य च ; धन्यम् = सम्पन्नम् ॥१.१५९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः राज्ञां, धनिकानां वा गृहेषु सेवां न कृतवान्, यः कस्यचित् इष्टजनस्य अभावजनितां पीडां न अनुभूतवान्, यः कस्यचित् पुरतः गत्वा दीनभावं न व्यञ्जयति, तादृशस्य पुरुषस्य जीवनं सम्पन्नम् अस्ति॥१.१५९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>यः राज्ञां, धनिकानां वा गृहेषु सेवां न कृतवान्, यः कस्यचित् इष्टजनस्य अभावजनितां पीडां न अनुभूतवान्, यः कस्यचित् पुरतः गत्वा दीनभावं न व्यञ्जयति, तादृशस्य पुरुषस्य जीवनं सम्पन्नम् अस्ति॥१.१५९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.159.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1160" class="total">
                    <div>
                        <button id="moolamsmall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1160')">मूलम्</button>
                        <button id="padasmall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1160')">पदविभागः</button>
                        <button id="anvayasmall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1160')">अन्वयः</button>
                        <button id="pratismall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1160')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1160')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1160')">हिन्द्यर्थः</button>
                        <button id="audiosmall1160" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1160')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न योजनशतं दूरं वाह्यमानस्य तृष्णया । सन्तुष्टस्य करप्राप्तेऽप्यर्थे भवति नादरः ॥१.१६०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न योजन-शतं दूरं वाह्यमानस्य तृष्णया । सन्तुष्टस्य करप्राप्ते अपि अर्थे भवति न आदरः ॥१.१६०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>न योजन-शतं दूरं वाह्यमानस्य तृष्णया । सन्तुष्टस्य करप्राप्ते अपि अर्थे भवति न आदरः ॥१.१६०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>तृष्णया = आशया ; वाह्यमानस्य = प्रेर्यमाणस्य ; योजनशतमपि न दूरम् = शतं योजनेषु अपि समीपभावः एव ; सन्तुष्टस्य तु = तृप्तिंगतस्य ; करप्राप्ते = हस्तगतेऽपि ; अर्थे = धने, वस्तुनि वा ; न आदरो = उन्नतभावः न भवतीत्यर्थः ॥१.१६०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः अतिलोभात् पीडितः सः शतयोजनस्थानमपि अल्पं मन्यते। यः सन्तृप्तिवान् भवति सः करमितेन धनेनापि महद्भावम् आवहति ॥१.१६०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो मनुष्य तृष्णा के वश में हो रहा है, उसके लिये तो १०० सौ योजन (चार सौ कोश) भी दूर नहीं है, पर जो प्राणी सन्तुष्ट है, उसको तो हाथ में आए हुए धन पर भी आदर नहीं होता है, किन्तु उसमें भी उसे उपेक्षा ही होती है ॥१.१६०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.160.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1161" class="total">
                    <div>
                        <button id="moolamsmall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1161')">मूलम्</button>
                        <button id="padasmall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1161')">पदविभागः</button>
                        <button id="anvayasmall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1161')">अन्वयः</button>
                        <button id="pratismall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1161')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1161')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1161')">हिन्द्यर्थः</button>
                        <button id="audiosmall1161" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1161')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>को धर्मो भूतदया किं सौख्यं नित्यमरोगिता जगति । कः स्नेहः सद्भावः किं पाण्डित्यं परिच्छेदः ॥१.१६१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः धर्मः भूत-दया किं सौख्यं नित्यम् अरोगिता जगति । कः स्नेहः सद्भावः किं पाण्डित्यं परिच्छेदः ॥१.१६१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कः धर्मः? भूत-दया। किं सौख्यं? जगति नित्यम् अरोगिता । कः स्नेहः? सद्भावः। किं पाण्डित्यं? परिच्छेदः ॥१.१६१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कः धर्मः = किं कर्तव्यम् इति ; भूतदया = जीवेषु अनुकम्पा ; सौख्यम् = सुखम् ; नित्यम् अरोगिता = सदा आरोग्यं ; जगति = लोके ; स्नेहः = मित्रत्वम् ; सद्भावः = सहृदयभावः ; पाण्डित्यं = विद्वत्ता ; परिच्छेदः = विभागोपभागपूर्वकं ज्ञानं, सदसद्विवेको वा ॥१.१६१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>प्राणिकोटिषु दाक्षिण्यभावः एव धर्मः। लोके सदा स्वस्थता एव सुखम्। सौजन्यभावः एव मित्रत्वम्। विभज्य सदसतोः सूक्ष्मं ज्ञानम् एव विज्ञता भवति ॥१.१६१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>धर्म क्या है ? प्राणियों पर दया । संसार में सुख क्या है ? नीरोग रहना । स्नेह क्या है ? सद्भाव अनुराग, प्रेम । पाण्डित्य क्या है? सत् असत् का विवेक । अर्थात्- उचित अनुचित का ठीक ठीक समझना ॥१.१६१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.161.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1162" class="total">
                    <div>
                        <button id="moolamsmall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1162')">मूलम्</button>
                        <button id="padasmall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1162')">पदविभागः</button>
                        <button id="anvayasmall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1162')">अन्वयः</button>
                        <button id="pratismall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1162')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1162')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1162')">हिन्द्यर्थः</button>
                        <button id="audiosmall1162" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1162')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>परिच्छेदो हि पाण्डित्यं यदापन्ना विपत्तयः । अपरिच्छेदकर्तॄणां विपदः स्युः पदे पदे ॥१.१६२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>परिच्छेदः हि पाण्डित्यं यद्-आपन्ना विपत्तयः । अपरिच्छेद-कर्तॄणां विपदः स्युः पदे पदे ॥१.१६२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पाण्डित्यं (तु) यदापन्ना विपत्तयः परिच्छेदः हि । अपरिच्छेदकर्तॄणां पदे पदे विपदः स्युः ॥१.१६२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>परिच्छेदः = सदसतोः सम्यक् ज्ञानं, विचारः ; पाण्डित्यं = विद्वत्ता, कौशलम् ; आपन्नाः = प्राप्ताः । अपरिच्छेदकर्तॄणाम् = अविचार्य कार्यमाचरताम्, अविवेकिनाम् = असन्तुष्टानां वा ॥१.१६२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदा  आपत्तयः आपतन्ति, तदानीं विचार्य कार्यकरणं विज्ञत्वमिति जानीयात्। ये विचारशीलाः न, तेषां तु मुहुर्मुहुः विपत्तयः भवन्ति  ॥१.१६२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>विपत्ति आने पर, विचार कर कार्य करना ही पाण्डित्य (बुद्धिमत्ता) है। विना विचारे काम करने वाले प्राणियों पर तो पद-पद में विपत्तियाँ आती है ॥१.१६२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.162.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1163" class="total">
                    <div>
                        <button id="moolamsmall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1163')">मूलम्</button>
                        <button id="padasmall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1163')">पदविभागः</button>
                        <button id="anvayasmall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1163')">अन्वयः</button>
                        <button id="pratismall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1163')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1163')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1163')">हिन्द्यर्थः</button>
                        <button id="audiosmall1163" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1163')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>त्यजेदेकं कुलस्यार्थे ग्रामस्यार्थे कुलं त्यजेत् । ग्रामं जनपदस्यार्थे स्वात्मार्थे पृथिवीं त्यजेत् ॥१.१६३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>त्यजेद् एकं कुलस्य-अर्थे ग्रामस्य-अर्थे कुलं त्यजेत् । ग्रामं जनपदस्य-अर्थे स्वात्मा-अर्थे पृथिवीं त्यजेत् ॥१.१६३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>त्यजेद् एकं कुलस्य-अर्थे ग्रामस्य-अर्थे कुलं त्यजेत् । ग्रामं जनपदस्य-अर्थे स्वात्मा-अर्थे पृथिवीं त्यजेत् ॥१.१६३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>एकम् = एकं जनम् ; कुलं = कुटुम्बम्, बन्धुबान्धवानां समूहम् अपि ; ग्रामस्य अर्थे= ग्रामवासि-सकल-जनोपकाराय ; जनपदस्य = विषयस्य, ग्रामाणां समूहस्य ; अर्थे = लाभाय ; स्वात्मार्थे = स्वात्मलाभाय तु ; पृथिवीं = सकलं राज्य-धन-पुत्रादिकम् अपि ; ॥१.१६३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>बृहत्प्रयोजनाय तदपेक्षया अल्पं वस्तु त्यजेत् इति सूचयति- कुटुम्बहिताय एकः जनः परिहर्तव्यः। ग्रामश्रेयसे एकः कुटुम्बः त्याज्यः। जनावासानां समूहलाभाय ग्रामः एकः विहातव्यः। आत्मनः निःश्रेयसे तु समस्तं त्यक्तव्यम्। (यत्र आत्मनः सुखं स्यात् तत्रैव गच्छेदिति भावः) ॥१.१६३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कुल के लिए एक को, गाँव भर के लिए कुल को, देश के लिये गाँव को, और अपने लाभ के लिये सम्पूर्ण पृथ्वी को भी लोह देना चाहिये ॥१.१६३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.163.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1164" class="total">
                    <div>
                        <button id="moolamsmall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1164')">मूलम्</button>
                        <button id="padasmall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1164')">पदविभागः</button>
                        <button id="anvayasmall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1164')">अन्वयः</button>
                        <button id="pratismall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1164')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1164')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1164')">हिन्द्यर्थः</button>
                        <button id="audiosmall1164" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1164')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>पानीयं वा निरायासं स्वाद्वन्नं वा भयोत्तरम् । विचार्य खलु पश्यामि तत् सुखं यत्र निर्वृतिः ॥१.१६४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पानीयं वा निरायासं स्वादु अन्नं वा भय-उत्तरम् । विचार्य खलु पश्यामि तत् सुखं यत्र निर्वृतिः ॥१.१६४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पानीयं वा निरायासं स्वादु अन्नं वा भय-उत्तरम् । विचार्य खलु पश्यामि तत् सुखं यत्र निर्वृतिः ॥१.१६४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>निरायासं = प्रयत्नं विनापि ; पानीयं = निर्झरादिजलम् ; भयोत्तरं = भयसङ्कुलं ; स्वादु = मधुरम् ; अन्नं =  भक्ष्यभोज्यादिकम् ; विचार्य =  पश्यामि = अवधारयामि ; यत्र = यस्मिन् ; निर्वृतिः = मनसः शान्तिः, सन्तोषश्च, ॥१.१६४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>द्वयोः वस्तुनोः कतरत् श्रेयः? विना श्रमं जलं, भयपूर्वकं खाद्यं - तत् उभयोर्मध्ये चेतव्यम् अस्ति। अत्र आत्मनः प्रश्ने त्वयमेव उत्तरमाह- विचार्य इति । यत् सन्तोषदायकं तदेव सुखं प्राप्तव्यं, नान्यदिति भावः ॥१.१६४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>यदि अनायास जल भी मिल जाय, और यदि नाना क्लेशों से स्वादु मिष्ट अन्न भी मिले, जिसमें अनेक कष्ट होने की सम्भावना होती, इन दोनों में मैं तो पहिले में ही सुख सभझता हूँ। क्यों कि सुख वही है, जिस में चित्त को शान्ति हो –अर्थात् स्वावधीन जल का मिलना- कष्टलभ्य स्वाहु अन्नसे अधिक अच्छा है ॥१.१६४॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.164.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1165" class="total">
                    <div>
                        <button id="moolamsmall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1165')">मूलम्</button>
                        <button id="padasmall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1165')">पदविभागः</button>
                        <button id="anvayasmall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1165')">अन्वयः</button>
                        <button id="pratismall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1165')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1165')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1165')">हिन्द्यर्थः</button>
                        <button id="audiosmall1165" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1165')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>वरं वनं व्याघ्रगजेन्द्रसेवितं द्रुमालयं पत्रफलाम्बुभक्षितम् । तृणानि शय्या वसनं च वल्कलं न बन्धुमध्ये धनहीनजीवनम् ॥१.१६५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरं वनं व्याघ्र-गजेन्द्र-सेवितं द्रुमालयं पत्र-फल-अम्बु-भक्षितम् । तृणानि शय्या वसनं च वल्कलं न बन्धु-मध्ये धन-हीन-जीवनम् ॥१.१६५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>व्याघ्र-गजेन्द्र-सेवितं वनं वरम्। पत्र-फल-अम्बु-भक्षितं (वरं), द्रुमालयं (वरम्)। तृणानि शय्या (वरं), वसनं च वल्कलं (वरम्)। बन्धु-मध्ये धन-हीन-जीवनं (तु) न (वरम्) ॥१.१६५॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>व्याघ्रगजेन्द्रसेवितं = सिंहादिश्वापद-गजादिवन्यजन्तु-सङ्कुलं ; द्रुमालयं ~ द्रुभा एव आलया यत्र तत् = वृक्षादिनिर्मितम् आवासम् ; पक्वकलाम्बुभोजनं ~ पक्वानि फलानि,अम्बु च भोजनं यत्र तत् = पक्ववन्यफलजलभोजनं ; वनं = वनवासः, वरं = श्रेष्ठम् ; तत्र यानं श्रेष्ठं, परन्तु बन्धुमध्ये धनहीनजीवनम् = निर्धनजनजीवनम् ॥१.१६५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>क्रूरजन्तूनां निवासः आवासो भवतु, वृक्षाणाम् अधः एव गृहं भवतु, पर्णानि, सस्यानि, सरसाम् अम्बु च भक्ष्यं भवतु। यत्र हि वने तृणान्येव शय्यास्थानीयानि, वल्कलमेव च परिधानवस्त्राणि तादृशमपि भवतु तदुचितमेव। किन्तु स्वकीयबान्धवानां मध्ये धनहीनेन न भवितव्यम्, तन्नोचितमित्यर्थः ॥१.१६५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>व्याघ्र और हाथियों से भरे हुए वन में वृक्षों के नीचे ठहरना कहीं अच्छा है, तथा पके हुए फलों से तथा जल से भी निर्वाह करना अच्छा है, तृण की शय्या और पहनने को वल्कल हो तो भी अच्छा है, परन्तु अपने बन्धुओं के बीच में दुरिद्र होकर रहना कभी अच्छा नहीं है ॥१.१६५ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
