                    <div>
                        <button id="moolamsmall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1166')">मूलम्</button>
                        <button id="padasmall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1166')">पदविभागः</button>
                        <button id="anvayasmall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1166')">अन्वयः</button>
                        <button id="pratismall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1166')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1166')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1166')">हिन्द्यर्थः</button>
                        <button id="audiosmall1166" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1166')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>संसारविषवृक्षस्य द्वे एव रसवत् फले । काव्यामृतरसास्वादः सङ्गमः सज्जनैः सह ॥१.१६६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>संसार-विष-वृक्षस्य द्वे एव रसवत् फले । काव्य-अमृत-रस-आस्वादः सङ्गमः सज्जनैः सह ॥१.१६६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>संसार-विष-वृक्षस्य द्वे एव रसवत् फले । काव्य-अमृत-रस-आस्वादः सङ्गमः सज्जनैः सह ॥१.१६६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>संसारविषवृक्षस्य = संसारः एव विषवृक्षरूपः, तस्य ; रसवत्फले=रसवती, रसयुक्ते फले ; काव्यामृतरसास्वादः = काव्यरूपस्य अमृतरसस्य आस्वादः (इत्येकं फलम्) ; सुजनैः सह = सज्जनैः साकं ; सङ्गमः = समागमः (इत्यपरं फलम्) ॥१.१६६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विश्वेस्मिन् द्वे एव उपयुक्तवस्तुनी- एतदेव वृक्षोपमया उक्तम्। संसारस्य तरुणा उपयुक्तवस्तुनोः फलाभ्यां च तुलना कृता। ते द्वे फले स्तः- कविकर्मणां रसपानं, साधुजनैः सहवासः च। ॥१.१६६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>संसार रूपी विष वृक्ष के दो ही रसयुक्त (मीठे) फल हैं, एक तो अमृततुल्य काव्यों का रसास्वाद, द्यौ- दूसरा सजनों की संगति ॥१.१६६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.166.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1167" class="total">
                    <div>
                        <button id="moolamsmall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1167')">मूलम्</button>
                        <button id="padasmall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1167')">पदविभागः</button>
                        <button id="anvayasmall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1167')">अन्वयः</button>
                        <button id="pratismall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1167')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1167')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1167')">हिन्द्यर्थः</button>
                        <button id="audiosmall1167" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1167')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अर्थाः पादरजोपमा गिरिनदीवेगोपमं यौवनम् आयुष्यं जलबिन्दुलोलचपलं फेनोपमं जीवनम् । धर्मं यो न करोति निश्चलमतिः स्वर्गार्गलोद्घाटनं पश्चात्तापयुतो जरापरिगतः शोकाग्निना दह्यते ॥१.१६७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मन्थर उवाच– अर्थाः पाद-रज-उपमा गिरि-नदी-वेग-उपमं यौवनम् आयुष्यं जल-बिन्दु-लोल-चपलं फेन-उपमं जीवनम् । धर्मं यः न करोति निश्चलमतिः स्वर्ग-अर्गल-उद्घाटनं पश्चात्-तापहतः जरा-परिणतः शोक-अग्निना दह्यते ॥१.१६७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पादरजोपमाः अर्थाः। गिरिनदीवेगोपमं यौवनम्। जलबिन्दुलोलचपलम् आयुष्यम्। जीवनं फेनोपमम् । यो निश्चलमतिः स्वर्गार्गलोद्घाटनं धर्मं न करोति, (सः) पश्चात्तापहतः जरापरिणतः शोकाग्निना दह्यते ॥१.१६७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अर्थाः = धनानि ; पादरजोपमाः = चरणधूलितुल्याः; गिरिनदीवेगोपमं = पर्वतसरितः प्रवाहजववत् ; यौवनम् = युवदशा ; आयुष्यं = जीवितकालः ; जललोलबिन्दुचपलम् = चञ्चलवारिबिन्दुवत् अचिरविनाशि ; फेनोपमं = जलबुद्बुदोपमम् ; जीवितम् = ; स्वर्गार्गलोद्घाटनं स्वर्गस्य या अर्गला = कपाटविष्कन्धः ; तस्याः उद्धाटनम् = निराकरणक्षमम् ; धर्मं यो न करोति = कर्तव्यं न आचरति ; सः जरापरिगतः = वृद्धः सन् ; पश्चात्तापयुतः = पश्चात्तापसन्तप्तः, पश्चात्, नाम अन्ते, तापयुतः = सन्तप्तमानस इत्यर्थः ; शोकाग्निना = शोकवह्निना ; दह्यते = अनिशं ज्वलति ॥१.१६७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अस्मिन् पद्ये कतिपयलौकिकविषयानाम् अस्थिरता उक्ता। धनं पदयोः धूलिरिव। युवावस्था शैलापगस्य रयः इव पूर्वमधिकं पश्चात् अल्पीयं च।  जीवनकालावधिः बुद्बुदप्रायः। जीवितं फेनमिव अस्थिरम्। यः मूर्खः नाकलोकस्य कवाटोद्घाटनकरं धर्माचरणं न करोति, सः काले अतीतौ जीर्णवयस्कः सन् दुःखपीडितो भवति॥१.१६७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>धन तो पैर की धूलि के समान है, और यौवन भी पर्वतीय नदी के वेग के समान हो क्षणभङ्गुर है, और आयु जल के चञ्चल बिन्दुओं के समान है, जीवन भी फेनबुद्बुद के ही तुल्य है । इसलिये जो निन्दित बुद्धिवाला मनुष्य स्वर्ग के कपाट की अर्गला (आगल) का उद्धाटन करने वाले धर्म का सेवन नहीं करता है, वह पीछे वृद्धावस्था में सन्तापरूपी अग्नि से जलता रहता है॥१.१६७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.167.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1168" class="total">
