                        <button id="moolamsmall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1168')">मूलम्</button>
                        <button id="padasmall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1168')">पदविभागः</button>
                        <button id="anvayasmall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1168')">अन्वयः</button>
                        <button id="pratismall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1168')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1168')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1168')">हिन्द्यर्थः</button>
                        <button id="audiosmall1168" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1168')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उपार्जितानां वित्तानां त्याग एव हि रक्षणम् । तडागोदरसंस्थानां परीवाह इवाम्भसाम् ॥१.१६८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उपार्जितानां वित्तानां त्यागः एव हि रक्षणम् । तडाग-उदर-संस्थानां परीवाह इवाम्भसाम् ॥१.१६८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उपार्जितानां वित्तानां त्यागः एव हि रक्षणम् । तडाग-उदर-संस्थानां अम्भसां परीवाहः (एव रक्षणं तथा) इव  ॥१.१६८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उपार्जितानाम् = सङ्गृहीतानाम् ; वित्तानां = धनानां ; त्यागः = दानम् ; रक्षणम् = रक्षा ; तडागोदरसंस्थानां = सरःमध्यस्थितानाम् ; अम्भसां = जलानाम्। परीवाहः = ततो निष्कासनमेव, (क्षेत्रादौ योजनमेव च) ; रक्षणमित्यर्थः ॥१.१६८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सञ्चितस्य धनस्य दानरूपव्ययः एव तस्य रक्षणं भवति। (अत्र उदाहरणं वदति) सरसि स्थितं जलं क्षेत्रादिभ्यः सस्यवर्धनार्थं दीयते इत्येव तस्य रक्षणं (अन्यथा प्रयोजनराहित्यमेव जलस्य) यथा भवति तथेदमपि॥१.१६८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अर्जन (पैदा) किये हुए धन को (सत्पात्र में) देना ही उसकी रक्षा है । जैसे तालाब के भीतर के बढ़े हुए जल को (खेती आदि के लिये) निकाल देने से ही उसके जल की शुद्धि होती है ॥१.१६८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.168.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1169" class="total">
                    <div>
                        <button id="moolamsmall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1169')">मूलम्</button>
                        <button id="padasmall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1169')">पदविभागः</button>
                        <button id="anvayasmall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1169')">अन्वयः</button>
                        <button id="pratismall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1169')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1169')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1169')">हिन्द्यर्थः</button>
                        <button id="audiosmall1169" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1169')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अर्जन (पैदा) किये हुए धन को (सत्पात्र में) देना ही उसकी रक्षा है । जैसे तालाब के भीतर के बढ़े हुए जल को (खेती आदि के लिये) निकाल देने से ही उसके जल की शुद्धि होती है ॥१.१६८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् अधोऽधः क्षितौ वित्तं निचखान मितम्पचः । तद् अधः निलयं गन्तुं चक्रे पन्थानम् अग्रतः ॥१.१६९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् अधोऽधः क्षितौ वित्तं निचखान मितम्पचः । तद् अधः निलयं गन्तुं चक्रे पन्थानम् अग्रतः ॥१.१६९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>क्षितौ = पृथिव्याम् ; मितम्पचः = कदर्यः ; वित्तं= धनम् ; अधोधः = भूम्याः अन्तः ; वित्तं = धनं ; निचखान = निखातवान् ( गाढ़ता हुआ) ; तत् निखननम् ; अधः = नीचैः ; निलयं = स्थानं, नरकमिति यावत्। अधोनिलयं=पातालभिति वा ; गन्तुं चक्रे = प्राप्तुम् उद्यतः ; पन्थानं = मार्गं ; अग्रतः = भविष्यत्काले॥१.१६९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धनसञ्चयिता तस्य रक्षणार्थं भूमौ यावत् अन्तः खननं कृत्वा तत् गूहयति, तथा काले प्राप्ते सः नरकलोकेषु तावत् अन्तः गमनाय मार्गं संसिद्धयति ॥१.१६९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिस कृपण ने अपने धन को पृथ्वी के भीतर गाड़ दिया है, उसने पहले से ही मानो अपने लिये नीचे (नरक में) जाने के लिये मार्ग (सीढी) ही बनाया है ॥१.१६९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.169.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1170" class="total">
                    <div>
                        <button id="moolamsmall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1170')">मूलम्</button>
                        <button id="padasmall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1170')">पदविभागः</button>
                        <button id="anvayasmall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1170')">अन्वयः</button>
                        <button id="pratismall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1170')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1170')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1170')">हिन्द्यर्थः</button>
                        <button id="audiosmall1170" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1170')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>निजसौख्यं निरुन्धानो यो धनार्जनमिच्छति । परार्थभारवाहीव स क्लेशस्यैव भाजनम् ॥१.१७०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>निज-सौख्यं निरुन्धानः यः धनार्जनम् इच्छति । परार्थ-भार-वाही इव सः क्लेशस्य एव भाजनम् ॥१.१७०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः निज-सौख्यं निरुन्धानः धनार्जनम् इच्छति, सः परार्थ-भार-वाही इव क्लेशस्य एव भाजनम् (भवति) ॥१.१७०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्वसुखं = आत्मनः आनन्दं ; निरुन्धानः = अपवार्य, परित्यज्यापि ; यः = यः धनलुब्धः ; धनार्जनम् = केवलं धनमेव अर्जयितुमिच्छति ; सः = तादृशः ; परार्थम् = अन्यार्थम् ; भारवाही इव = भारवाहक इव ; क्लेशस्य = कष्टस्य ; भाजनम् = पात्रम् ॥१.१७०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>स्वस्य सुखम् अविगणय्य यः केवलं वित्तार्जने दत्तचित्तः, सः परेषां प्रयोजनार्थं भारान् वहन्निव केवलं क्लेशमेव लभते, न सुखम्। (यतो हि तस्य मरणं पश्चात् अन्ये तद्धनं स्वीकुर्वन्ति।) ॥१.१७०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो प्राणी अपने को कष्ट में डाल कर धन का उपार्जन करता है, वह दूसरे के बोझ को ढोने वाले कुली की तरह केवल दुःख ही का पात्र है, अर्थात् वह केवल दुःख ही पाता है- सुख नहीं ॥१.१७०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.170.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1171" class="total">
                    <div>
                        <button id="moolamsmall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1171')">मूलम्</button>
                        <button id="padasmall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1171')">पदविभागः</button>
                        <button id="anvayasmall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1171')">अन्वयः</button>
                        <button id="pratismall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1171')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1171')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1171')">हिन्द्यर्थः</button>
                        <button id="audiosmall1171" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1171')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दानोपभोगहीनेन धनेन धनिनो यदि । भवामः किं न तेनैव धनेन धनिनो वयम् ॥१.१७१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दान-उपभोग-हीनेन धनेन धनिनः यदि । भवामः किं न तेन एव धनेन धनिनः वयम् ॥१.१७१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यदि दानोपभोगहीनेन धनेन (केपि) धनिनो (भवितुमर्हन्ति), किं न तेनैव धनेन वयम् (अपि) धनिनो भवामः ?॥१.१७१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दानोपभोगहीनेन = दानेन उपभोगेन च शून्येन (धनेन) भूमौ स्थापितेन धनेन ; यदि = चेत् ; (कदर्याः) धनिनः = वित्तवन्तः (भवन्ति) ; (तर्हि) तेनैव = भूमिस्थितेन तेषां धनेन ; वयम् = उदासीनाः अपि ; धनिनः = धनाधिकारिणः (कुतो न भवामः?) ॥१.१७१॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विना दानं कृत्वा, विना च स्वस्य सुखाय उपयुज्य (केवलधनसञ्चयेन) यदि कोपि धनवानिति यशः प्राप्नोति, तर्हि तेनैव धनेन वयं (धनेन असम्बद्धाः अपि) धनवन्तः एवेति गण्येम। दानोपभोगशून्यतस्योभयत्र तुल्यत्वादिरयाशयः ॥१.१७१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जिस धन का उपभोग नहीं, किया गया और जो न दिया गया, उस धन से यदि प्राणी अपने को धनी समभता है, तो पृथ्वी के भीतर गड़े हुए उस धन से का हम लोग भी धनी नहीं कहा सकते हैं, अर्थात् अवश्य कहा सकते है ॥१.१७१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.171.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1172" class="total">
                    <div>
                        <button id="moolamsmall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1172')">मूलम्</button>
                        <button id="padasmall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1172')">पदविभागः</button>
                        <button id="anvayasmall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1172')">अन्वयः</button>
                        <button id="pratismall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1172')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1172')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1172')">हिन्द्यर्थः</button>
                        <button id="audiosmall1172" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1172')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दानोपभोगहीनाश्च दिवसा यान्ति यस्य वै । स कमकारभस्त्रेव श्वसन्नपि न जीवति ॥१.१७२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दानोपभोगहीनाश्च दिवसा यान्ति यस्य वै । स कमकारभस्त्रेव श्वसन्नपि न जीवति ॥१.१७२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य वै दानोपभोगहीनाः च दिवसाः यान्ति, सः कमकारभस्त्र इव श्वसन्नपि न जीवति ॥१.१७२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य = यस्य पुंसः ; दानोपभोगहीनाश्च = परेभ्यः अदत्त्वा, स्वयमपि अनुपयुज्य ; दिवसाः = दिनानि ; यान्ति = गच्छन्ति ; सः = तादृशः लोभी ; कर्मकारभस्त्रेव = लोहकारभस्त्रेव (भस्त्रः = अग्निदीपकचर्म्मनिर्म्मितयन्त्रविशेषः।) ; श्वसन्नपि = वायुं शरीरान्तः स्वीकुर्वन् मुञ्चन्नपि ; न जीवति = मृतकः एव॥१.१७२ ॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य कदर्यस्य दिनानि धन्य वितरणेन विना, आत्मनः सन्तोषायापि नोपयुज्य यान्ति, सः प्राणैः संयुक्तोपि सन् मृतकतुल्य एव ॥१.१७२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और जिस मनुष्य के दिन दान और उपभोग के बिना निष्फल ही बीतते जाते हैं, वह मनुष्य लोहार की भाथी की तरह साँस लेता हुआ भी मरे हुए के समान ही है ॥१.१७२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.172.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1173" class="total">
                    <div>
                        <button id="moolamsmall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1173')">मूलम्</button>
                        <button id="padasmall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1173')">पदविभागः</button>
                        <button id="anvayasmall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1173')">अन्वयः</button>
                        <button id="pratismall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1173')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1173')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1173')">हिन्द्यर्थः</button>
                        <button id="audiosmall1173" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1173')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>धनेन किं यो न ददाति नाश्नुते बलेन किं यश्च रिपून् न बाधते । श्रुतेन किं यो न च धर्ममाचरेत् किमात्मना यो न जितेन्द्रियो भवेत् ॥१.१७३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धनेन किं यः न ददाति न अश्नुते बलेन किं यः च रिपून् न बाधते । श्रुतेन किं यः न च धर्मम् आचरेत् किम् आत्मना यः न जितेन्द्रियः भवेत् ॥१.१७३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः न ददाति न अश्नुते, (तस्य) धनेन किम्? यः च रिपून् न बाधते (तस्य) बलेन किम्? यः न च धर्मम् आचरेत्, (तस्य) श्रुतेन किम्? यः न जितेन्द्रियः भवेत् (तेन) आत्मना किम् ?॥१.१७३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धनेन = वित्तेन ; किं = कि फलम् ? यो = यः पुरुषः ; न ददाति = न अर्पयति ; न अश्नुते = न उपभुङ्क्ते ; बलेन = शरीरस्य शक्त्या ; रिपून= शत्रून् ; न बाधते = न उन्मूलयति ; श्रुतेन = शास्त्रेण ; आत्मना = शरीरेण, जीवनेन जितेन्द्रियः = आत्मनियतः ॥१.१७३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः पुमान् (धनवान् सन्नपि) न अन्यस्मै ददाति, न हि स्वयं उपभुङ्क्ते, तस्य धनेन किं प्रयोजनम्? यः (बलवानपि सन्), शत्रून् न नियन्त्यति, तस्य पुंसो शक्त्या को लाभः? यः (ज्ञानी सन्नपि) स्वयं धर्मं न आचरति, तस्य ज्ञानेन कः अर्थः? यः (शरीरधारी सन्नपि प्राणी) आत्मजित् नास्ति, तस्य शरीरेण किं प्रयोजनम्? ॥१.१७३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उस धन से क्या लाभ है, जिस धन से दान न दिया जाय । और उस बल से भी क्या लाभ है, जिससे शत्रुओं को न दबा सके। और शास्त्र को सुनने से भी क्या लाभ है, यदि तदनुसार धर्म का आचरण न किया जाय । और उसके आत्मा (शरीर) से भी क्या लाभ है, जो जितेन्द्रिय न हो ॥१.१७३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.173.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1174" class="total">
                    <div>
                        <button id="moolamsmall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1174')">मूलम्</button>
                        <button id="padasmall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1174')">पदविभागः</button>
                        <button id="anvayasmall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1174')">अन्वयः</button>
                        <button id="pratismall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1174')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1174')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1174')">हिन्द्यर्थः</button>
                        <button id="audiosmall1174" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1174')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>असम्भोगेन सामान्यं कृपणस्य धनं परैः । अस्येदमिति सम्बन्धो हानौ दुःखेन गम्यते ॥१.१७४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>असम्भोगेन सामान्यं कृपणस्य धनं परैः । अस्य इदम् इति सम्बन्धः हानौ दुःखेन गम्यते ॥१.१५४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कृपणस्य धनम् असम्भोगेन परैः सामान्यम् । हानौ (सति) दुःखेन ‘अस्य इदम्’ इति सम्बन्धः गम्यते ॥१.१७४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>असम्भोगन = अनुपभोगेन ; परैः सामान्यं = परधनतुल्यमेव ; परन्तु अस्य = कदयस्य, इदं = धनम्, इति ; सम्बन्धो = सम्बन्धानुभवस्तु ; हान्या = तस्य धनस्य नाशे सति ; दुःखेन = कदर्यदुःखेनैव ; गम्यते = अनुमीयते ॥१.१७४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>उपभोगम् अकृत्वा धनलुब्धस्य धनं परेषां धनतुल्यमेव। धने विगते यदा स दुःखम् अऩुभवति, तावता ज्ञायते यत् इदं धनं तस्य इति ॥१.१७४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कृपण का धन उसके काम में नहीं आने से दूसरे के धन के बराबर ही है । 'परन्तु वह धन इस कृपण का हैं, यह बात तो केवल इतने से ही मालूम होती है, कि उस धन के नष्ट होने पर वह दुःखी होकर रोता है ॥१.१७४ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.174.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1175" class="total">
                    <div>
                        <button id="moolamsmall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1175')">मूलम्</button>
                        <button id="padasmall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1175')">पदविभागः</button>
                        <button id="anvayasmall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1175')">अन्वयः</button>
                        <button id="pratismall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1175')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1175')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1175')">हिन्द्यर्थः</button>
                        <button id="audiosmall1175" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1175')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न देवाय न विप्राय न बन्धुभ्यो न चात्मने । कृपणस्य धनं याति वह्नितस्करपार्थिवैः ॥१.१७५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न देवाय न विप्राय न बन्धुभ्यः न च आत्मने । कृपणस्य धनं याति वह्नि-तस्कर-पार्थिवैः ॥१.१७५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>देवाय न (याति), विप्राय न (याति), बन्धुभ्यः न (याति), आत्मने च न (याति)। कृपणस्य धनं तु वह्नि-तस्कर-पार्थिवैः याति॥१.१७५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कृपणस्य = लोभिनः ; धनं = सम्पत् ; न देवाय = न देवपूजादौ उपयुज्यते ; न बन्धुभ्यो = बान्धवेभ्यः अपि न ; न विप्राय = न तेन ब्राह्मणाय दीयते ; वह्नितस्करपार्थिवैः ~ वह्निः = अग्निः, तस्कराः = चौराः, पार्थिवः = राजा – एतैः ; याति = नश्यति ; ॥१.१७५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धनलुब्धः कस्मै अपि धनम् अदत्त्वा स्वस्मै एव निक्षिपति। पूजादिभ्यः, दानादिभ्यः वा, परेषां साहाय्यककार्येभ्यो वा वित्तं नोपयुङ्क्ते। (अन्ते तस्य मृत्योः परं) सर्वं धनं अग्नौ दग्ध्वा नश्यति, अथवा चोराः चोरयन्ति, नो चेत् राजानः स्वीकुर्वन्ति।॥१.१७५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>कृपण का धन न देवता के काम (यज्ञ आदि) में आता है, और न ब्राह्मणों के काम में आता है, और न वह बन्धुओं के ही काम मे आता है, न अपने ही काम में आता है, किन्तु वह धन या तो अग्नि में जल जाता है, या उसे चोर ही चुरा लेते हैं, या उसे राजा ही हर (छीन) लेता है ॥१.१७५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.175.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1176" class="total">
                    <div>
                        <button id="moolamsmall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1176')">मूलम्</button>
                        <button id="padasmall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1176')">पदविभागः</button>
                        <button id="anvayasmall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1176')">अन्वयः</button>
                        <button id="pratismall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1176')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1176')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1176')">हिन्द्यर्थः</button>
                        <button id="audiosmall1176" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1176')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दानं भोगो, नाशस्तिस्रो गतयो भवन्ति वित्तस्य । यो न ददाति न भुङ्क्ते तस्य तृतीया गतिर्भवति ॥१.१७६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दानं भोगः नाशः तिस्रः गतयः भवन्ति वित्तस्य । यः न ददाति न भुङ्क्ते तस्य तृतीया गतिः भवति ॥१.१७६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>वित्तस्य तिस्रः गतयः भवन्ति- दानं भोगः नाशः (च) । यः न ददाति, न भुङ्क्ते, तस्य (धनस्य) तृतीया गतिः भवति ॥१.१७६॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दानं = परेभ्यः त्यागः ; भोगः = स्वस्य सुखाय विनिभोगः ; नाशः = क्षयः ; गतयः = परिणामाः ; वित्तस्य = धनस्य ; ददाति = यच्छति ; भुङ्क्ते = स्वस्मै विनियुज्यते ; तृतीया गतिः = (अत्र) नाशः ; भवति = घटते ॥१.१७६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>परेभ्यः उपयोगः, स्वस्य सुखाय व्ययः, अपक्षयः च धनस्य परिणामाः त्रयः भवन्ति। यः वित्तम् अन्येभ्यः न यच्छति, स्वार्थाय नोपयुङ्क्ते वा, तस्य धनस्य पूर्णक्षयः एव भवति॥१.१७६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>धन की तीन तरह की गति होती है- १. दान, २. भोग और ३. नाश । परन्तु जो कंजूस मनुष्य न देता है। न खाता है और उसके धन की तीसरी ही गति (नाश) होती है। अर्थात् उसका वह धन नष्ट ही हो जाता है ॥१.१७६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.176.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1177" class="total">
                    <div>
                        <button id="moolamsmall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1177')">मूलम्</button>
                        <button id="padasmall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1177')">पदविभागः</button>
                        <button id="anvayasmall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1177')">अन्वयः</button>
                        <button id="pratismall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1177')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1177')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1177')">हिन्द्यर्थः</button>
                        <button id="audiosmall1177" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1177')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>दानं प्रियवाक्सहितं ज्ञानमगर्वं क्षमान्वितं शौर्यम् । वित्तं त्यागनियुक्तं दुर्लभमेतच्चतुष्टयं लोके ॥१.१७७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दानं प्रियवाक्-सहितं ज्ञानम् अगर्वं क्षमा-अन्वितं शौर्यम् । वित्तं त्यागनियुक्तं दुर्लभमेत् चतुष्टयं लोके ॥१.१७७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्रियवाक्-सहितं दानम्, अगर्वं ज्ञानं, क्षमान्वितं शौर्यं, त्यागनियुक्तं वित्तं – एतत् चतुष्टयं लोके दुर्लभम् ॥१.१७७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दानं = त्यागः ; प्रियवाक्-सहितं = मनःसुखकरवचनान्वितम् ; ज्ञानं = अवगतिः ; अगर्वं = गर्वरहितं, अभिमानशून्यम् ; क्षमान्वितम् = सहनभावयुक्तं ; शौर्यं = वीरत्वं ; वित्तं = धनं ; त्यागनियुक्तं = दानप्रयुक्तम्, दानान्वितं वा ; दुर्लभं = अप्राप्यं ; एतत् चतुष्टयं = एते चत्वारः ; लोके = संसारे ॥१.१७७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मृदुवचनैः सहितं धनवस्त्वादिनां दानं, दम्भरहितं ज्ञानं, शूरत्वभावः अकोपसहितः, दानसहितं धनं च इह संसारे दुष्प्राप्यमेव॥१.१७७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>प्रियवचन पूर्वक दान, विना गर्व का ज्ञान, क्षमा युक्त शूरवीरता, धन होने पर दान देना, ये चारों बातें संसार में बड़ी दुर्लभ हैं ॥१.१७७ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.177.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1179" class="total">
                    <div>
                        <button id="moolamsmall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1179')">मूलम्</button>
                        <button id="padasmall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1179')">पदविभागः</button>
                        <button id="anvayasmall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1179')">अन्वयः</button>
                        <button id="pratismall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1179')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1179')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1179')">हिन्द्यर्थः</button>
                        <button id="audiosmall1179" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1179')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>जलमग्निर्विषं शस्त्रं क्षुद् व्याधिः पतनं गिरेः । निमित्तं किञ्चिदासाद्य देही प्राणैर्विमुच्यते ॥१.१७९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>जलम् अग्निः विषं शस्रं क्षुद् व्याधिः पतनं गिरेः । निमित्तं किञ्चिद् आसाद्य देही प्राणैः विमुच्यते ॥१.१७९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>जलम् अग्निः विषं शस्रं क्षुद् व्याधिः गिरेः पतनं - देही किञ्चिद् निमित्तम् आसाद्य प्राणैः विमुच्यते ॥१.१७९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>जलम् = नीरं ; अग्निः =तेजः ; विषं = गरलं ; शस्त्रं = आयुधम् ; क्षुद् = क्षुधा ; व्याधिः = रोगः ; गिरेः = पर्वतादेः ; आसाद्य = लब्ध्वा ; देही = शरीरी ; प्राणैर्वियुज्यते = म्रियते ॥१.१७९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शरीरी यं कमपि हेतुम् आधृत्य मरणं प्राप्नोति। तानि निमित्तानि एवं भवन्ति- वारि, अनलः, क्ष्वेलं, प्रहरणं, अन्नार्तता, अस्वस्थता, पर्वतादिभ्यः अधःपातः च ॥१.१७९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जल, अग्नि, विष, शस्त्र, भूख, रोग, पर्वत आदिसे गिरना आदि, इनमें से किसी भो निमित्तसे प्राणी अपने प्राणों को छोड़ता (अर्थात् मरता) है ॥१.१७९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.179.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1180" class="total">
                    <div>
                        <button id="moolamsmall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1180')">मूलम्</button>
                        <button id="padasmall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1180')">पदविभागः</button>
                        <button id="anvayasmall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1180')">अन्वयः</button>
                        <button id="pratismall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1180')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1180')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1180')">हिन्द्यर्थः</button>
                        <button id="audiosmall1180" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1180')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>अचिन्तितानि दुःखानि यथैवायान्ति देहिनाम् । सुखान्यपि तथा मन्ये दैवमत्रातिरिच्यते ॥१.१८०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अचिन्तितानि दुःखानि यथा एव आयान्ति देहिनाम् । सुखानि अपि तथा मन्ये दैवम् अत्र अतिरिच्यते ॥१.१८०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>देहिनां दुःखानि अचिन्तितानि यथा एव आयान्ति तथा सुखानि अपि (इति) मन्ये। अत्र दैवम् अतिरिच्यते ॥१.१८०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अविचारितानि ; दुःखानि = क्लेशाः ; देहिनाम् = जीविनाम् ; सुखानि = उपभोगानि ; तथा अचिन्तितान्येव आयान्ति ; दैवं = भाग्यम् ; अतिरिच्यते = पृथग्भवति ; तद्धि नात्र हेतुः । विशिष्यते इति वा ॥१.१८०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>प्राणिनां पीडाः यथा अतर्कितानि एव आपतन्ति, तथैव सन्तोषकराणि अपि (अविमृष्टानि एव उपयान्ति)। भाग्यम् एव अत्र सर्वोपरि भवति ॥१.१८०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जैसे प्राणियों के ऊपर दुःख बिना सूचना के ही एकाएक आया करते हैं, उसी प्रकार सुख भी अनायास ही आते हैं । इसमें केवल भाग्य ही प्रधान है ॥१.१८०॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.180.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1182" class="total">
                    <div>
                        <button id="moolamsmall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1182')">मूलम्</button>
                        <button id="padasmall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1182')">पदविभागः</button>
                        <button id="anvayasmall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1182')">अन्वयः</button>
                        <button id="pratismall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1182')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1182')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1182')">हिन्द्यर्थः</button>
                        <button id="audiosmall1182" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1182')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यद् ददाति यदश्नाति तदेव धनिनो धनम् । अन्ये मृतस्य क्रीडन्ति दारैरपि धनैरपि ॥१.१८२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् ददाति यद् अश्नाति तद् एव धनिनः धनम् । अन्ये मृतस्य क्रीडन्ति दारैः अपि धनैः अपि ॥१.१८२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् ददाति यद् अश्नाति तद् एव धनिनः धनम् । अन्ये मृतस्य दारैः अपि धनैः अपि क्रीडन्ति ॥१.१८२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यत् = यद्धनम् ; अश्राति = उपभुङक्ते ; धनिनः = वित्तवतां ; धनम् = सम्पत् ; अन्ये = अन्यबान्धवाः, जामातृ-भ्रात्रादयः ; मृतस्य = विगतप्राणिनः ; दारैः = पत्नीभिः ; धनैः = वित्तैः ; क्रीडन्ति = दुरुपयोगं कुर्वन्ति ॥१.१८२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>वित्तवान् जीवितः सन् यत् वित्तम् अन्येभ्यः धर्मकार्याय ददाति, येन धनेन स्वयं नन्दति, उपभुङ्क्ते, तदेव तस्य स्वकीयम्। तस्य मृत्योः पश्चात् अन्ये सम्बन्धिनः तस्य दारधनादिकम् उपभुञ्जते। (अतः अधिकसञ्चयेन न कोपि लाभः इति भावः) ॥१.१८२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो धनी अपने धन को किसी को देता है और उसका उपभोग करता है, वही उसका धन है । मरने पर तो उसके धन और स्त्री आदि से दूसरे ही लोग आनन्द करेंगे ॥१.१८२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.182.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1183" class="total">
                    <div>
                        <button id="moolamsmall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1183')">मूलम्</button>
                        <button id="padasmall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1183')">पदविभागः</button>
                        <button id="anvayasmall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1183')">अन्वयः</button>
                        <button id="pratismall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1183')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1183')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1183')">हिन्द्यर्थः</button>
                        <button id="audiosmall1183" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1183')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>यद् ददासि विशिष्टेभ्यो यच्चाश्नासि दिने दिने । तत् ते वित्तमहं मन्ये शेषं कस्यापि रक्षसि ॥१.१८३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् ददासि विशिष्टेभ्यः यत् च अश्नासि दिने दिने । तत् ते वित्तम् अहं मन्ये शेषं कस्य अपि रक्षसि ॥१.१८३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् विशिष्टेभ्यः ददासि, यत् च दिने दिने अश्नासि । तत् ते वित्तम् । शेषं कस्य अपि रक्षसि (इति) अहं मन्ये ॥१.१८३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धनादिकं ; ददासि = वितरणं करोषि ; विशिष्टेभ्यः = महद्भ्यः, सत्पात्रेभ्यः ; यत् च अश्नासि = यत् खादसि, उपभुङ्क्षे ; दिने दिने = सदा ; तत् = तत् सर्वं ; ते = तव ; वित्तम् = धनं ; मन्ये = चिन्तये ; शेषं = अवशिष्टं धनम् ; कस्यापि = कस्यापि उत्तराधिकारिणः कृते ; रक्षसि = सञ्चिनोषि ॥१.१८३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्यः यावत् धनं सत्पात्रेभ्यः ददाति, स्वयम् अऩुभवति, तावत् धनं तस्य स्वकीयं भवति। अवशिष्टं तस्य मृत्योः पश्चात् पुत्रादयः स्वीकरिष्यन्ति। अतः तत् तस्य नास्ति, केवलं तेभ्यः रक्षतीव भाति॥१.१८३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जो धन सत्पात्र में दिया जाता है, या जिसका नित्य उपभोग किया जाता है, वही धन तुम्हारा है, बाकी धन तो किसी दूसरे का है, तुम तो उसके केवल रखवाले मात्र ही हो ॥१.१८३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.183.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1184" class="total">
                    <div>
                        <button id="moolamsmall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1184')">मूलम्</button>
                        <button id="padasmall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1184')">पदविभागः</button>
                        <button id="anvayasmall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1184')">अन्वयः</button>
                        <button id="pratismall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1184')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1184')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1184')">हिन्द्यर्थः</button>
                        <button id="audiosmall1184" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1184')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>नाप्राप्यमभिवाञ्छन्ति नष्टं नेच्छन्ति शोचितुम् । आपत्स्वपि न मुह्यन्ति नराः पण्डितबुद्धयः ॥१.१८४॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न अप्राप्यम् अभिवाञ्छन्ति नष्टं न इच्छन्ति शोचितुम् । आपत्सु अपि न मुह्यन्ति नराः पण्डित-बुद्धयः ॥१.१८४॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पण्डितबुद्धयः नराः अप्राप्यं न अभिवाञ्छन्ति। नष्टं शोचितुं न इच्छन्ति । आपत्सु अपि न मुह्यन्ति। ॥१.१८४॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अप्राप्यम् = अलभ्यं ; न अभिवाच्छन्ति = न काङ्क्षन्ति ; नष्टं = गतं ; शोचितुम् = दुःखेन चिन्तयितुं ; नेच्छन्ति = न वाञ्छन्ति ; आपत्सु अपि = विपत्तिषु अपि ; न मुह्यन्ति = मोहं न प्राप्नुवन्ति ; नराः = मनुष्याः ; पण्डितबुद्धयः = निश्चितबुद्धयः ॥१.१८४॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>बुद्धिमन्तः मानवाः यत् न लभ्यते तन्नेच्छन्ति। यत् विनष्टतां गच्छति तन्न अभिलषन्ति। कष्टकालेषु अपि दुःखात् न भ्राम्यन्ति। ॥१.१८४॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>विद्वान् लोग अप्राप्य वस्तु को नहीं चाहते हैं और नष्ट वस्तु के लिये शोक भी नहीं करते हैं, तथा आपत्ति में घबड़ाते भी नहीं हैं ॥१.१८४ ॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
