                <div id="1185" class="total">
                    <div>
                        <button id="moolamsmall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1185')">मूलम्</button>
                        <button id="padasmall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1185')">पदविभागः</button>
                        <button id="anvayasmall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1185')">अन्वयः</button>
                        <button id="pratismall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1185')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1185')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1185')">हिन्द्यर्थः</button>
                        <button id="audiosmall1185" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1185')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>शास्त्राण्यधीत्यापि भवन्ति मूर्खा यस्तु क्रियावान् पुरुषः स विद्वान् । सुचिन्तितं चौषधमातुराणां न नाममात्रेण करोत्यरोगम् ॥१.१८५॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शास्त्राणि अधीत्य अपि भवन्ति मूर्खाः यस्तु क्रियावान् पुरुषः सः विद्वान् । सुचिन्तितं च औषधम् आतुराणां न नाम-मात्रेण करोति अरोगम् ॥१.१८५॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शास्त्राणि अधीत्य अपि मूर्खाः भवन्ति। यः पुरुषः तु क्रियावान् सः विद्वान् (भवति)। औषधं सुचिन्तितं च आतुराणां नाम-मात्रेण अरोगं न करोति ॥१.१८५॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शास्त्राणि = अध्येयानि ; अधीत्य अपि = ज्ञानं प्राप्य अपि ; मूर्खाः = कुण्ठितबुद्धयः ; क्रियावान् = कर्मसु कुशलः ; पुरुषः = नरः ; विद्वान् = विज्ञः ; सुचिन्तितं = सुविचार्य, रोगानुसारेण कल्पितमपि ; औषधं = अगदं ; आतुराणां = अस्वस्थानां ; नाममात्रेण = केवलम् औषधस्य नामकीर्तनमात्रेण ; अरोगं = नीरोगं, स्वास्थ्यं वा ॥१.१८५॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जनाः शास्त्राणि पठित्वापि अर्धज्ञाः एव भवन्ति। यः कार्यनिर्वहणे कुशलः सः एव वस्तुतः ज्ञाता। अस्योदाहरणमेवम्- यदि कश्चन रोगेन पीडितः भवति, तदा औषधस्य नामोच्चारणेन चिन्तनेन वा तस्य रोगापगमः न भवति। भैषजं वस्तुरूपेण स्वीकर्तव्यमेव भवति।॥१.१८५॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>क्यों कि बहुत से लोग शास्त्रों को पढकर भी मूर्ख ही रह जाते हैं, किन्तु जो कार्यों को करने में कुशल हैं, वे ही सच्चे विद्वान् हैं । क्यों कि- अच्छी तरह विचार कर निश्चित की हुई ओषधि भी केवल नाम लेने मात्र से ही मनुष्य को नीरोग नहीं कर देती हैं किन्तु उसका सेवन करने से ही लाभ होता है ॥१.१८५॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.185.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1186" class="total">
                    <div>
                        <button id="moolamsmall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1186')">मूलम्</button>
                        <button id="padasmall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1186')">पदविभागः</button>
                        <button id="anvayasmall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1186')">अन्वयः</button>
                        <button id="pratismall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1186')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1186')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1186')">हिन्द्यर्थः</button>
                        <button id="audiosmall1186" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1186')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>न स्वल्पमप्यध्यवसायभीरोः करोति विज्ञानविधिर्गुणं हि । अन्धस्य किं हस्ततलस्थितोऽपि प्रकाशयत्यर्थमिह प्रदीपः ॥१.१८६॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न स्वल्पम् अपि अध्यवसाय-भीरोः करोति विज्ञान-विधिः गुणं हि । अन्धस्य किं हस्त-तल-स्थितः अपि प्रकाशयति अर्थम् इह प्रदीपः ॥१.१८६॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विज्ञान-विधिः अध्यवसाय-भीरोः न स्वल्पम् अपि गुणं करोति हि । हस्ततलस्थितः अपि अन्धस्य प्रदीपः अर्थम् इह किं प्रकाशयति ॥१.१८६॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अध्यवसायभीरोः = पराक्रमविकलस्य, अलसस्य च ; विज्ञानविधिं = शास्त्रकला-कौशलम् ; विधि = क्रमः ; स्वल्पम् = न्यूनम् ; गुणं करोति = लाभं विदधाति ; अन्धस्य = नेत्रहीनस्य ; हस्ततलस्थितोपि = कराग्रे सन्नपि ; प्रकाशयति = दर्शनयोग्यं कारयति ; अर्थं = वस्तुजातं घटादिकम् ; प्रदीपः = दीपज्योतिः॥१.१८६॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः परिश्रमं न करोति तस्य शास्त्रक्रमः किञ्चिदपि लाभं न कल्पयति । अत्रोदाहरणम्- अदृक् नरः स्वस्य करे दीपं धृत्वापि किमपि वस्तुजालं द्रष्टुं न पारयति। दीपः तस्य लाभाय न।  ॥१.१८६॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उत्साहहीन व परिश्रम न करने वाले मनुष्य को शास्त्रविधि (शास्त्रीय ज्ञान) भी कुछ लाभ नहीं पहुँचाता है । जैसे अन्धे मनुष्य के हाथ पर रक्खा हुआ दीपक भी उसे घट पट आदि पदार्थों को नहीं दिखला सकता है ॥१.१८६॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.186.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1187" class="total">
                    <div>
                        <button id="moolamsmall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1187')">मूलम्</button>
                        <button id="padasmall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1187')">पदविभागः</button>
                        <button id="anvayasmall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1187')">अन्वयः</button>
                        <button id="pratismall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1187')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1187')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1187')">हिन्द्यर्थः</button>
                        <button id="audiosmall1187" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1187')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>राजा कुलवधूर्विप्रा मन्त्रिणश्च पयोधराः । स्थानभ्रष्टा न शोभन्ते दन्ताः केशा नखा नराः ॥१.१८७॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>राजा कुलवधूः विप्राः मन्त्रिणः च पयोधराः । स्थानभ्रष्टाः न शोभन्ते दन्ताः केशाः नखाः नराः ॥१.१८७॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>राजा कुलवधूः विप्राः मन्त्रिणः च पयोधराः दन्ताः केशाः नखाः नराः- स्थानभ्रष्टाः न शोभन्ते ॥१.१८७॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>राजा = नृपः ; कुलवधूः = सत्कुलस्त्री ; विप्राः = द्विजाः ; मन्त्रिणः = अमात्याः ; पयोधराः = स्त्रीस्तनाः ; स्थानभ्रष्टाः = स्खलिताः ; न शोभन्ते = असुन्दराणि भवन्ति ; दन्ताः = दशनाः ; केशाः = मूर्धजाः ; नखाः = कररुहः ; नराः = मनुष्याः ॥१.१८७॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नृपः, कुलाङ्गना, ब्राह्मणाः, सचिवाः, वक्षोजाः, रदनाः, शिरोजाः, पाणिजाः, मानवाः च- स्वस्मात् स्थानात् पतिताः आकर्षकाः न भवन्ति ॥१.१८७॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>'राजा, कुलीन स्त्री, ब्राह्मण, मन्त्री, स्त्रियों के स्तन, दाँत, केश, नख और मनुष्य- ये सब अपने स्थान से गिर जाने पर शोभा नहीं देते हैं ॥१.१८७॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.187.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1188" class="total">
                    <div>
                        <button id="moolamsmall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1188')">मूलम्</button>
                        <button id="padasmall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1188')">पदविभागः</button>
                        <button id="anvayasmall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1188')">अन्वयः</button>
                        <button id="pratismall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1188')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1188')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1188')">हिन्द्यर्थः</button>
                        <button id="audiosmall1188" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1188')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्थानभ्रष्टा न शोभन्ते दन्ता केशा नखा नराः। इति विज्ञाय मतिमान् स्वस्थानं न परित्यजेत् ॥१.१८८॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्थानभ्रष्टा न शोभन्ते दन्ता केशा नखा नराः। इति विज्ञाय मतिमान् स्वस्थानं न परित्यजेत् ॥१.१८८॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दन्ताः, केशाः, नखा, नराः स्थानभ्रष्टाः (सन्तः) न शोभन्ते -इति विज्ञाय मतिमान् स्वस्थानं न परित्यजेत् ॥१.१८८॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दन्ताः = रदनाः ; केशाः = शिरोजाः ; नखाः = अङ्गुलिजाः ; नराः = मानवाः ; स्थानभ्रष्टाः (सन्तः) = स्खलित्वा ; न शोभन्ते = पात्रत्वादिकं लुप्यते ; इति = एवं ; विज्ञाय = ज्ञात्वा ; मतिमान् = बुद्धिमान् ; स्वस्थानं = युक्तं स्थानं ; न परित्यजेत् = तस्मात् न विरमेत् ॥१.१८८॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>रदनाः, शिरोजाः, पाणिजाः, मानवाः च- युक्तस्थानात् स्खलिताः अपकर्षकाः भवन्ति इति ज्ञात्वा विवेकी आत्मनः युक्तं स्थानं न मुञ्चति ॥१.१८८॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>अपने स्थान से भ्रष्ट हुए- दाँत, केश, नख और पुरुष- ये सुशोभित नहीं होते हैं । इसलिए बुद्धिमान् मनुष्य को चाहिए कि वह अपने स्थान को कभी न छोडे ॥१.१८८॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.188.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1189" class="total">
                    <div>
                        <button id="moolamsmall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1189')">मूलम्</button>
                        <button id="padasmall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1189')">पदविभागः</button>
                        <button id="anvayasmall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1189')">अन्वयः</button>
                        <button id="pratismall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1189')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1189')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1189')">हिन्द्यर्थः</button>
                        <button id="audiosmall1189" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1189')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>स्थानमुत्सज्य गच्छन्ति सिंहाः सत्पुरुषा गजाः । तत्रैव निधनं यान्ति काकाः कापुरुषा मृगाः ॥१.१८९॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>स्थानम् उत्सज्य गच्छन्ति सिंहाः सत्पुरुषा गजाः । तत्र एव निधनं यान्ति काकाः कापुरुषाः मृगाः ॥१.१८९॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सिंहाः, सत्पुरुषाः, गजाः (च) स्थानम् उत्सज्य गच्छन्ति । काकाः कापुरुषाः मृगाः (च) तत्र एव निधनं यान्ति ॥१.१८९॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सिंहाः = मृगेन्द्राः ; सत्पुरुषाः = सज्जनाः ; गजाः = करिणः ; स्थानम् = वासस्थलम् ; उत्सज्य = त्यक्त्वा ; गच्छन्ति = अन्यत्र यान्ति ; काकाः = वायसाः ; कापुरुषाः = भीरवः ; मृगाः = हरिणाः ; तत्रैव = दुर्भिक्षे, दुःखप्रदेऽपि देशे ; निधनं यान्ति = म्रियन्ते ॥१.१८९॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>स्वस्थले कष्टकाले समायाते कतिपयजीवाः यथा- केसरिणः, दन्तिनः, साधवः च, स्वनिवासस्थानात् अन्यप्रदेशं गत्वा जीवन्ति। अन्ये महत्कष्टमपि सहमानाः तस्मिन्नेव स्थले मरणं प्राप्नुवन्ति ॥१.१८९॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>सिंह, गुणी पुरुष, हाथी- ये अपने स्थानों को छोड़कर भी अन्यत्र जाकर प्रतिष्ठा प्राप्त करते हैं । परन्तु कौवा, कापुरुष, हरिण एक जगह रहकर ही जन्म बिता देते हैं और वहीं मर भी जाते हैं ॥१.१८९॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.189.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1190" class="total">
                    <div>
                        <button id="moolamsmall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1190')">मूलम्</button>
                        <button id="padasmall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1190')">पदविभागः</button>
                        <button id="anvayasmall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1190')">अन्वयः</button>
                        <button id="pratismall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1190')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1190')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1190')">हिन्द्यर्थः</button>
                        <button id="audiosmall1190" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1190')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>को वीरस्य मनस्विनः स्वविषयः को वा विदेशस्तथा यं देशं श्रयते तमेव कुरुते बाहुप्रतापार्जितम्। यद्दंष्ट्रानखलाङ्गुलप्रहरणः सिंहो वनं गाहते तस्मिन्नेव हतद्विपेन्द्ररुधिरैस्तृष्णां छिनत्त्वात्मनः ॥१.१९०॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः वीरस्य मनस्विनः स्वविषयः कः वा विदेशः तथा, यं देशं श्रयते तम् एव कुरुते बाहु-प्रताप-अर्जितम्। यत् दंष्ट्रा-नख-लाङ्गुल-प्रहरणः सिंहः वनं गाहते, तस्मिन् एव हत-द्विपेन्द्र-रुधिरैः तृष्णां छिनत्तु आत्मनः ॥१.१९०॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मनस्विनः वीरस्य स्वविषयः कः, तथा विदेशः कः वा? यं देशं श्रयते तम् एव बाहुप्रतापार्जितं कुरुते । दंष्ट्रानखलाङ्गुलप्रहरणः सिंहः यत् वनं गाहते, तस्मिन् एव हतद्विपेन्द्ररुधिरैः आत्मनः तृष्णां छिनत्तु ॥१.१९०॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मनस्विनः = धीराः ; वीरस्य = शूरस्य ; स्वविषयः = स्वकीयं वस्तु ;  विदेशः = अन्यदेशः ; देशं = प्रदेशं ; श्रयते = वासाय इच्छति ; बाहुप्रतापार्जितं = विक्रमेण स्वायत्तीकृतं ; दंष्ट्रानखलाङ्गुलप्रहरणः = यः सिंहः दशनैः पाणिजैः, लाङ्गलेन च प्रहरति ; वनं = अरण्यं ; गाहते = प्रविशति ; हत-द्विपेन्द्र-रुधिरैः = मारितस्य गजस्य रक्तेन ; आत्मनः = स्वस्य ; तृष्णां = पिपासां ; छिनत्तु = नाशयतु (नाम उपशामयतु) ॥१.१९०॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>वीरपुरुषस्य स्वपरभेदो न भवति। ‘मम देशोयं अन्यः न मम’ इत्यादिकं तस्य मनसि न भवति। यत्र सः आश्रयते तमेव प्रदेशं स्वकीयं मत्त्वा स्वविक्रमेण अर्जित्वा जीवति। अस्योदाहरणं – सिंहः नवमपि वनं गच्छेत् तत्र सः  नखदन्तादिकेन स्वाङ्गानां बलेन गजान् हत्वा रुधिरं पीत्वा स्वस्य तृषार्ततां शामयति॥१.१९०॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और उत्साही वीरपुरुष के लिए स्वदेश और परदेश क्या है। वह तो जहाँ भी जाता है, उसी जगह को अपने बाहुवल से अपने अधीन कर लेता है । क्यों कि दाँत, नख, पोंछ ही जिसके साधन (शस्त्र) हैं, ऐसा सिंह-जिस वन में जाता है, उसी में हाथियों का शिकार कर के ही अपनी क्षुधा शान्त करता है ॥१.१९०॥ </td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.190.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1191" class="total">
                    <div>
                        <button id="moolamsmall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1191')">मूलम्</button>
                        <button id="padasmall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1191')">पदविभागः</button>
                        <button id="anvayasmall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1191')">अन्वयः</button>
                        <button id="pratismall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1191')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1191')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1191')">हिन्द्यर्थः</button>
                        <button id="audiosmall1191" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1191')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>निपानमिव मण्डूकाः सरः पूर्णमिवाण्डजाः । सोद्योगं नरमायान्ति विवशाः सर्वसम्पदः ॥१.१९१॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>निपानम् इव मण्डूकाः सरः पूर्णम् इव अण्डजाः । स-उद्योगं नरम् आयान्ति विवशाः सर्व-सम्पदः ॥१.१९१॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मण्डूकाः निपानम् इव, पूर्णं सरः अण्डजाः इव, सोद्योगं नरं विवशाः सर्वसम्पदः आयान्ति ॥१.१९१॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मण्डूकाः = भेकाः ; निपानम् = उपकूपजलाशयम् ; सरः = ह्रदं; अण्डजाः = हंसकारण्डकादयः पक्षिणः ; सोद्योगं = उद्योगिनम्, प्रयत्नशीलं ; विवशाः = आकृष्टाः इव, स्वयमेव ; सर्वसम्पदः = समस्तभाग्यानि ॥१.१९१॥ ('आहावस्तु निपानं स्यादुपकूपजलाशये इत्यमरः</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा दर्दुराः जलाशयं प्रति यान्ति, विहगाः सम्भृतं सरोवरं प्राप्नुवन्ति, तथैव वशबाह्याः इव समस्तसम्पदः क्रियाशीलं नरं स्वयमेव उपयान्ति ॥१.१९१॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>और- जिस प्रकार कुए के पास के छोटे-छोटे जलाशयों (खेल, कोठों) में मेढक स्वयं चले आते हैं, और पूर्ण सरोवरों में पक्षी भी स्वयं चले आते हैं, उसी प्रकार उद्योगी पुरुष के पास भी सब प्रकार की सम्पत्तियाँ स्वयं ही चली आती हैं ॥१.१९१॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.191.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1192" class="total">
                    <div>
                        <button id="moolamsmall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1192')">मूलम्</button>
                        <button id="padasmall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '1192')">पदविभागः</button>
                        <button id="anvayasmall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '1192')">अन्वयः</button>
                        <button id="pratismall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '1192')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '1192')">तात्पर्यम्</button>
                        <button id="hindyarthamsmall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('hindyartham', '1192')">हिन्द्यर्थः</button>
                        <button id="audiosmall1192" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('audio', '1192')">उच्चारणम्</button>
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>सुखमापतितं सेव्यं दुःखमापतितं तथा । चक्रवत् परिवर्तन्ते दुःखानि च सुखानि च ॥१.१९२॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुखम् आपतितं सेव्यं दुःखम् आपतितं तथा । चक्रवत् परिवर्तन्ते दुःखानि च सुखानि च ॥१.१९२॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आपतितं सुखं सेव्यम्। आपतितं दुःखं तथा (एव सेव्यम्) । दुःखानि च सुखानि च चक्रवत् परिवर्तन्ते ॥१.१९२॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सुखम् = सन्तोषकरं ; आपतितं = आगतम् ; दुःखम् = पीडाकरं ; परिवर्तन्ते = आगच्छन्ति ; तथा = समानमेव ; सेव्यम् = उपभोग्यं ; यतः- चक्रवत् = रथाङ्गमिव ; परवर्तन्ते = परिणामं यान्ति ; (आयान्ति, यान्ति च) ॥१.१९२॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जीवनमार्गे आयात् मोदकरं वा कष्टकरं वा समानम् उपभोग्यम्। यतो हि आमोदं तद्विपरीतं वा पूर्वपरत्वेन वृत्ताकारं भ्रमन्ति ॥१.१९२॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>जब सुख आवे तो उसको भी भोगना चाहिये, और वैसे ही दुःख भी जब आ पड़े तो उसको भी सहना चाहिये । क्योंकि सुख और दुःख तो चक्र (पहिए) की तरह घूमा करते हैं । अर्थात् स्वयं ही आते-जाते रहते हैं ॥१.१९२॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
                            <td style="width: 90px">उच्चारणम् </td>
                            <td style="vertical-align:bottom">
                                <audio controls>
                                    <source src="audio/hitopadesa/Hito-Sh-1.192.m4a" type="audio/mp4">
                                    Your browser does not support the audio element.
                                </audio>
                            </td>
                        </tr>
                            
                    </table>
                </div>
                
                
                <div id="1193" class="total">
                    <div>
                        <button id="moolamsmall1193" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '1193')">मूलम्</button>
