                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम्: </td>
                            <td>उत्साहसम्पन्नमदीर्घसूत्रं क्रियाविधिज्ञं व्यसनेष्वसक्तम् । शूरं कृतज्ञं दृढसौहृदं च लक्ष्मीः स्वयं वाञ्छति वासहेतोः ॥१.१९३॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उत्साह-सम्पन्नम् अदीर्घ-सूत्रं क्रिया-विधिज्ञं व्यसनेषु असक्तम् । शूरं कृतज्ञं दृढ-सौहृदं च लक्ष्मीः स्वयं वाञ्छति वास-हेतोः ॥१.१९३॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उत्साहसम्पन्नम्, अदीर्घसूत्रं, क्रियाविधिज्ञं, व्यसनेषु असक्तं, शूरं, कृतज्ञं, दृढसौहृदं च, लक्ष्मीः स्वयं वाञ्छति वासहेतोः ॥१.१९३॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्साहसम्पन्नम् = उद्यमपरिपूर्णम् ; अदीर्घसूत्रम् = अचिरक्रियम् ; क्रियाविधिज्ञं = कार्यविधानकुशलम् ; व्यसनेषु = द्यूतमद्यपानादि-दुष्टकार्येषु ; असक्तम् = अप्रवृत्तं ; शूरं = धैर्यशीलं ; दृढसौहृदं = स्थिरानुरागं, स्थिरसङ्कल्पं वा ; लक्ष्मीः = धनं ; वासहेतोः = निवासाय ; स्वयं = आत्मवशेन ; वाञ्छति = काङ्क्षति, उपगच्छति ॥१.१९३॥</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>एतादृशः पुरुषः अनायासं सम्पन्नतापात्रं भवति- यः उत्साहपूर्णः, द्रुतक्रियाशीलः, कार्यविधेः ज्ञाता, दुर्व्यापारेषु अनासक्तः, धीरः, यः कृतं जानाति, घनिष्ठसुहृद्भावसम्पन्नः च ॥१.१९३॥</td>
                        </tr>
                        <tr class="hindyartham">
                            <td style="width: 90px">हिन्द्यर्थः </td>
                            <td>उत्साही, आलस्य रहित, कार्य करने के उपायों को जाननेवाला, विषयों में अनासक्त, वीर और कृतज्ञ, तथा जिसकी मित्रता दृढ है- ऐसे मनुष्य के पास रहने की इच्छा से लक्ष्मी स्वयं ही आती है ॥१.१९३॥</td>
                        </tr>
                    
                    
                        <tr class="audio">
