<script>
    $("#intromore").hide();
    $("#less1").hide();

    $("#more1").click(function(){
        $("#intromore").slideDown(2000);
        $("#more1").hide();
        $("#less1").show();
    });

    $("#less1").click(function(){
        $("#intromore").hide();
        $("#more1").show();
        $("#less1").hide();
        $("html, body").animate({
            'scrollTop':   $('#pageTopDiv').offset().top
        }, 200);

    });

    function toggleSection(whichclass){
        //Also toggle the small buttons on the top of each section
        var s = whichclass +'small';
        $('[id^='+s+']').toggleClass("inactivemini mini-btn");

        var appClasses = document.getElementsByClassName(whichclass);

        for (var i = 0; i < appClasses.length; i ++) {
            if(appClasses[i].style.display === 'none'){
                appClasses[i].style.display = '';
            }
            else{
                appClasses[i].style.display = 'none';
            }
        }
    }

    $(document).ready(function () {
        $("#moolam,#pada,#anvaya,#prati,#taatparyam,#hindyartham,#audio").click(function() {
                $(this).toggleClass("inactive lang-btn");
                toggleSection(this.id);
            });
    })

    function toggleOneSloka(name, number){
        $.customToggle(name, number);        
    }
    $.customToggle = function(name, number) {
        console.log(name);
        console.log(number);
            $('#'+number +' .'+name).toggle();
            $('#'+name+'small'+number).toggleClass("inactivemini mini-btn");
         };

</script>

    
